import java.util.Scanner

import scala.collection.mutable.{Map => MMap}

object Main extends App {
  val sc = new Scanner(System.in)
  val (n, k, l) = (sc.nextInt, sc.nextInt, sc.nextInt)

  val roads = Seq.fill(k)((sc.nextInt, sc.nextInt))
  val rails = Seq.fill(l)((sc.nextInt, sc.nextInt))

  val road_connected_cities: MMap[Int, Set[Int]] = MMap()
  val rail_connected_cities: MMap[Int, Set[Int]] = MMap()

  Range(1, n + 1).foreach { x =>
    road_connected_cities.put(x, Set(x))
    rail_connected_cities.put(x, Set(x))
  }

  roads.foreach { case (p, q) =>
    val x = road_connected_cities(p) ++ road_connected_cities(q)
    x.foreach {
      road_connected_cities.put(_, x)
    }
  }

  rails.foreach { case (r, s) =>
    val x = rail_connected_cities(r) ++ rail_connected_cities(s)
    x.foreach {
      rail_connected_cities.put(_, x)
    }
  }

  val ans = Range(1, n + 1).toList.map(x => (road_connected_cities(x) intersect rail_connected_cities(x)).size).mkString(" ")

  println(ans)
}

#include <cstdio>
#include <cstdint>
#include <vector>
#include <algorithm>
#include <map>

class union_find {
  std::vector<intmax_t> tree;

public:
  union_find(size_t n): tree(n, -1) {}

  size_t find(size_t v) {
    if (tree[v] < 0)
      return v;

    return (tree[v] = find(tree[v]));
  }

  bool unite(size_t u, size_t v) {
    u = find(u);
    v = find(v);
    if (u == v)
      return false;

    if (-tree[u] >= -tree[v])
      std::swap(u, v);

    tree[v] += tree[u];
    tree[u] = v;
    return true;
  }

  bool connected(size_t u, size_t v) {
    return (find(u) == find(v));
  }

  size_t size(size_t v) {
    return -tree[find(v)];
  }
};

int main() {
  size_t N, K, L;
  scanf("%zu %zu %zu", &N, &K, &L);

  union_find uf1(N);
  for (size_t i = 0; i < K; ++i) {
    size_t p, q;
    scanf("%zu %zu", &p, &q);
    --p;
    --q;
    uf1.unite(p, q);
  }

  union_find uf2(N);
  for (size_t i = 0; i < L; ++i) {
    size_t r, s;
    scanf("%zu %zu", &r, &s);
    --r;
    --s;
    uf2.unite(r, s);
  }

  std::map<std::pair<size_t, size_t>, int> res;
  for (size_t i = 0; i < N; ++i)
    ++res[{uf1.find(i), uf2.find(i)}];

  for (size_t i = 0; i < N; ++i)
    printf("%d%c", res[{uf1.find(i), uf2.find(i)}], i+1<N? ' ':'\n');
}

