    A.merge(X,Y);
  }
  for(int I=0;I<L;I++){
    int X,Y;cin>>X>>Y;X--;Y--;
    B.merge(X,Y);
  }
  for(int X=0;X<N;X++){
    int M=0;
    for(int Y=0;Y<N;Y++){
      if(X==Y)continue;
      if(A.issame(X,Y)&&B.issame(X,Y))M++;
    }
    cout<<M<<endl;
  }
}

