void patrol(ll root, ll node, unordered_map<ll, vector<ll> >& graph, ll* link, vector<bool>& used) {
    used[node] = true;
    link[node] = root;

    for (auto next : graph[node]) {
        if (!used[next]) {
            patrol(root, next, graph, link, used);
        }
    }
}

