struct dset{
	vector<int> parent, rank;
	dset(){}
	dset(int n) {parent.resize(n, -1), rank.resize(n, 1);}
	int find(int x){return ((parent[x]==-1)?x:(parent[x]=find(parent[x])));}
	void join(int a, int b){
		a = find(a), b = find(b);
		if (a != b){
			if (rank[a]<rank[b]) swap(a, b);
			rank[a]+=rank[b];
			parent[b] = a;
		}
	}
};


int n, k, l, x, y;


int main(){
	scanf("%d %d %d", &n, &k, &l);
	dset road(n), rail(n);
	for(int i = 0; i<k; i++){
		scanf("%d %d", &x, &y);
		road.join(x-1, y-1);
	}
