struct UnionFind {
    vector<int> par;
    UnionFind(int n) : par(n, -1) { }

    bool unite(int x, int y) {
        x = root(x); y = root(y);
        if(x==y)return false;
        if(par[y]<par[x])swap(x,y);
        par[x]+=par[y];par[y]=x;
        return true;
    }

    bool same(int x, int y) {
        return root(x) == root(y);
    }

    int size(int x) {
        return -par[root(x)];
    }
    int root(int x) {
        return par[x] < 0 ? x : par[x] = root(par[x]);
    }
};

