int getpar(int city, int k) {
    if (par[k][par[k][city]] == par[k][city]) return par[k][city];
    else return par[k][city] = getpar(par[k][city],k);
}

void merge(int c1, int c2, int k) {
    c1 = getpar(c1,k), c2 = getpar(c2,k);
    if (c1 == c2) return;
    if (c1>c2) swap(c1,c2);
    par[k][c2] = c1;
}

int main() {
	ios_base::sync_with_stdio(0);cin.tie(0);
	int N,K,L; cin >> N >> K >> L;
	FOR(i,1,N+1) par[0][i] = par[1][i] = i;
	F0R(i,K) {
	    int p,q; cin >> p >> q;
	    merge(p,q,0);
	}
	F0R(i,L) {
	    int r,s; cin >> r >> s;
	    merge(r,s,1);
	}
	FOR(i,1,N+1) done[mp(getpar(i,0),getpar(i,1))]++;
	FOR(i,1,N+1) cout << done[mp(getpar(i,0),getpar(i,1))] << "\n";
}

