const int MAX = 100000;
int n, k, l, p[MAX], q[MAX], r[MAX], s[MAX];

class UnionFind {
public:
	UnionFind(int size);
	int unite(int v, int w);
	int find(int v);
	int get_size_eq(int v);
	int get_size_part();
	virtual ~UnionFind();

private:
	int *parent;
	int *size_eq;
	int size_part;
};

UnionFind::UnionFind(int size) {
	parent = new int[size];
	size_eq = new int[size];
	for(int i = 0; i < size; i++) { parent[i] = -1; size_eq[i] = 1; }
	size_part = size;
}

int UnionFind::unite(int v, int w) {
	int fv = find(v);
	int fw = find(w);
	if(fv == fw) { return fv; }

	size_part--;
	int &sv = size_eq[fv];
	int &sw = size_eq[fw];

	if(sv < sw) {
		parent[fv] = fw;
		sw += sv;
		return fw;
	} else {
		parent[fw] = fv;
		sv += sw;
		return fv;
	}
}

int UnionFind::find(int v) {
	if(parent[v] == -1) { return v; }
	return parent[v] = find( parent[v] );
}

int UnionFind::get_size_eq(int v) {
	return size_eq[ find(v) ];
}

int UnionFind::get_size_part() {
	return size_part;
}

UnionFind::~UnionFind() {
	delete[] parent;
	delete[] size_eq;
}


