using namespace std;

const int N = 2e5;
int par[N];
int par2[N];
vector<int> items[N];

void init() {
    for (int i = 0; i < N; i++) {
        par[i] = i;
        par2[i] = i;
    }
}

int find(int x) {
    if (x == par[x]) {
        return x;
    }
    return par[x] = find(par[x]);
}

void unite(int x, int y) {
    par[find(x)] = find(y);
}

int find2(int x) {
    if (x == par2[x]) {
        return x;
    }
    return par2[x] = find2(par2[x]);
}

void unite2(int x, int y) {
    x = find2(x);
    y = find2(y);
    if (x == y) {
        return;
    }
    if (items[x].size() < items[y].size()) {
        swap(x, y);
    }
    for (int e : items[y]) {
        items[x].push_back(e);
    }
    par2[y] = x;
}

int main() {
    int n, K, L;
    cin >> n >> K >> L;

    init();

    for (int i = 0; i < K; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        u--; v--;
        unite(u, v);
    }

    for (int i = 0; i < N; i++) {
        items[i].push_back(find(i));
    }

    for (int i = 0; i < L; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        u--; v--;
        unite2(u, v);
    }

    for (int i = 0; i < N; i++) {
        sort(items[i].begin(), items[i].end());
    }

    for (int i = 0; i < n; i++) {
        int u = find2(i);
        int s = upper_bound(items[u].begin(), items[u].end(), find(i)) - lower_bound(items[u].begin(), items[u].end(), find(i));
        printf("%d ", s);
    }
}

