class UF {
    public:
    int par[300000]={};
    UF(int n) {
        for(int i=0; i<n; i++)
            par[i] = i;
    }
    int find(int x) {
        if(par[x] == x) return x;
        return par[x] = find(par[x]);
    }
    void unite(int x, int y) {
        x = find(x), y = find(y);
        par[x] = y;
    }
};

