void dfs(int v, int was[], int c[], vector<int> a[], vector<int> g[], int num) {
    c[v] = num;
    a[num].push_back(v);
    was[v] = true;
    for (auto& to : g[v]) {
        if (!was[to]) dfs(to, was, c, a, g, num);
    }
