#define REP(i, n) for(int i = 0; i < n; i++)

struct UnionFind {
    vector<int> par;

    UnionFind(int n) : par(n) {
        REP(i, n) par[i] = i;
    }

    int root(int x) {
        if (x == par[x]) return x;
        else return par[x] = root(par[x]);
    }

    void unite(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y) return;
        if (x < y) swap(x, y);
        par[x] = y;
    }

    bool same(int x, int y) {
        return root(x) == root(y);
    }
};

