struct UF {
    vector<int> par, rk, sz;

    UF(int _n) {
        par.resize(_n + 1), rk.assign(_n + 1, 0), sz.assign(_n + 1, 1);
        for (int i = 0; i <= _n; ++i) {
            par[i] = i;
        }
    }

    int find(int x) {
        if (x != par[x]) par[x] = find(par[x]);
        return par[x];
    }

    bool same(int x, int y) {
        return find(x) == find(y);
    }

    bool unite(int x, int y) {
        x = find(x), y = find(y);
        if (x == y) return false;
        if (rk[x] < rk[y]) par[x] = y, sz[y] += sz[x];
        else {
            par[y] = x, sz[x] += sz[y];
            if (rk[x] == rk[y]) rk[x]++;
        }
        return true;
    }

	int size(int x) {
		x = find(x);
		return sz[x];
	}
};

