    uf1.unite(p,q);
  }
  REP(i,L) {
    int r,s; cin>>r>>s; r--,s--;
    uf2.unite(r,s);
  }
  REP(i,N) {
    mp1.emplace(uf1.root(i), i);
    mp2.emplace(uf2.root(i), i);
  }
  REP(i,N) {
    int cnt=0;
    auto p1 = mp1.equal_range(uf1.root(i));
    auto p2 = mp2.equal_range(uf2.root(i));
    auto it1 = p1.first;
    auto it2 = p2.first;
    while (it1!=p1.second && it2!=p2.second) {
      int s = it1->second;
      int t = it2->second;
      if (s==t) cnt++, it2++;
      if (s<t)  it1++;
      if (s>t)  it2++;
    }
    cout << cnt << " ";
  }
  cout << endl;
}

