  vector<int> u;
  vector<int> r;
  UF(int n) {
    for (int i=0; i<n; i++) {
      u.push_back(i);
      r.push_back(1);
    }
  }

  int find(int x) {
    if (u[x] == x) return x;
    return u[x] = find(u[x]);
  }

  void unite(int x, int y) {
    x = find(x), y = find(y);
    if (x == y) return;
    u[y] = x;
    r[x] += r[y];
    r[y] = 0;
  }

  bool same(int x, int y) {
    return find(x) == find(y);
  }

  int count(int x) {
    return r[find(x)];
  }
};

int N, K, L;
int main() {
  cin >> N >> K >> L;
  UF x(N), y(N);
  for (int i=0; i<K; i++) {
    int a, b;
    cin >> a >> b;
    x.unite(a-1, b-1);
  }
  for (int i=0; i<L; i++) {
    int a, b;
    cin >> a >> b;
    if (x.same(a-1, b-1)) {
      y.unite(a-1, b-1);
    }
  }
  for (int i=0; i<N; i++) {
    cout << y.count(i) << (i==N-1?"\n":" ");
  }
  return 0;
}

#include <bits/stdc++.h>

using namespace std;

int par[200001], Rank[200001];

void init(int n) {
  for (int i = 0; i < n; i++) {
    par[i] = i;
    Rank[i] = 1;
  }
}

int find(int x) {
  if (par[x] == x) return x;
  return par[x] = find(par[x]);
}

void unite(int x, int y) {
  x = find(x);
  y = find(y);
  if (x == y) return;
  if (Rank[x] < Rank[y]) {
    par[x] = y;
  } else {
    par[y] = x;
    if (Rank[x] == Rank[y]) Rank[x]++;
  }
}

int main(void) {
  int n, K, L;
  cin >> n >> K >> L;

  init(n);
  for (int i = 0; i < K; i++) {
    int p, q;
    cin >> p >> q;
    p--, q--;
    unite(p, q);
  }

  vector<int> ans(n, 1);
  for (int i = 0; i < L; i++) {
    int r, s;
    cin >> r >> s;
    r--, s--;

    if (find(r) == find(s)) {
      ans[r]++, ans[s]++;
    }
  }

  for (int i = 0; i < n; i++) {
    if (i) cout << " ";
    cout << ans[i];
  }
  cout << endl;

  return 0;
}

