using namespace std;

const int MAXN = 200001;
int road[MAXN], railway[MAXN];

int father(int fa[], int p) {
    if (fa[p] == p) { return p; }
    fa[p] = father(fa, fa[p]);
    return fa[p];
}

int main() {
    int n, k, l;
    scanf("%d%d%d", &n, &k, &l);
    for (int i = 1; i <= n; i++) {
        road[i] = railway[i] = i;
    }
    while (k--) {
        int p, q;
        scanf("%d%d", &p, &q);
        road[father(road, p)] = father(road, q);
    }
    while (l--) {
        int p, q;
        scanf("%d%d", &p, &q);
        railway[father(railway, p)] = father(railway, q);
    }
    map<long long, int> result;
    for (int i = 1; i <= n; i++) {
        road[i] = father(road, i);
        railway[i] = father(railway, i);
        result[(long long)road[i] * (long long)(n + 1) + (long long)railway[i]]++;
    }
    for (int i = 1; i <= n; i++) {
        cout << result[(long long)road[i] * (long long)(n + 1) + (long long)railway[i]] << ((i != n) ? " " : "\n");
    }
    return 0;
}

