            patrol(i, road, road_used);
            for (ll j = 1; j <= N; j++) {
                if (!old[j] && road_used[j]) {
                    road_set[i].push_back(j);
                }
            }
            for (auto j : road_set[i]) {
                road_set[j] = road_set[i];
            }
        }

        if (!line_used[i]) {
            auto old = line_used;
            patrol(i, line, line_used);
            for (ll j = 1; j <= N; j++) {
                if (!old[j] && line_used[j]) {
                    line_set[i].push_back(j);
                }
            }
            for (auto j : line_set[i]) {
                line_set[j] = line_set[i];
            }
        }
    }

    for (ll i = 1; i <= N; i++) {
        sort(road_set[i].begin(), road_set[i].end());
        sort(line_set[i].begin(), line_set[i].end());

        vector<ll> ans;
        set_intersection(road_set[i].begin(), road_set[i].end(), line_set[i].begin(), line_set[i].end(), back_inserter(ans));

        cout << ans.size() << " \n"[i == N];
    }

    return 0;
}

