const int N = 2 * 100 * 1000 + 2;
long long n, k, l, dpL[N], dpR[N], visK[N], visL[N];
vector <int> adjK[N], adjL[N], moaL[N], moaK[N];

void dfsK(int u, int num) {
	visK[u] = num;
	moaK[num].push_back(u);
	for (int v: adjK[u])
		if (visK[v] == 0)
			dfsK(v, num);
}

void dfsL(int u, int num) {
	visL[u] = num;
	moaL[num].push_back(u);
	for (int v: adjL[u])
		if (visL[v] == 0)
			dfsL(v, num);
}

void readInput() {
	cin >> n >> k >> l;
	for (int i = 0, u, v; i < k; i++) {
		cin >> u >> v;
		adjK[u].push_back(v);
		adjK[v].push_back(u);
	}
	for (int i = 0, u, v; i < l; i++) {
		cin >> u >> v;
		adjL[u].push_back(v);
		adjL[v].push_back(u);
	}
}

void moalefeK() {
	for (int i = 1, num = 1; i <= n; i++)
		if (visK[i] == 0)
			dfsK(i, num), num++;
	for (int i = 1; moaK[i].size() != 0; i++)
		sort(moaK[i].begin(), moaK[i].end());
}

void moalefeL() {
	for (int i = 1, num = 1; i <= n; i++)
		if (visL[i] == 0)
			dfsL(i, num), num++;
	for (int i = 1; moaL[i].size() != 0; i++)
		sort(moaL[i].begin(), moaL[i].end());
}

bool bs(int x, int p) {
	int it = lower_bound(moaL[p].begin(), moaL[p].end(), x) - moaL[p].begin();
	return (x == moaL[p][it] && it < moaL[p].size());
}

void updateDpL() {
	for (int i = 1; i <= n; i++) {
		int postK = visK[i], postL = visL[i];
		int tmp = -1;
		for (int j = 0; moaK[postK][j] < i; j++) 
			if (bs(moaK[postK][j], postL) == true)
				tmp = moaK[postK][j];
		tmp == -1? dpL[i] = 1: dpL[i] = dpL[tmp] + 1;
	}
}

void updateDpR() {
	for (int i = n; i >= 1; i--) {
		int postK = visK[i], postL = visL[i];
		int tmp = -1;
		for (int j = moaK[postK].size() - 1; moaK[postK][j] > i; j--) 
			if (bs(moaK[postK][j], postL) == true)
				tmp = moaK[postK][j];
		tmp == -1? dpR[i] = 1: dpR[i] = dpR[tmp] + 1;
	}
}

void writeOutput() {
	for (int i = 1; i <= n; i++)
		cout << dpR[i] + dpL[i] - 1 << ' ';
}

void runProgram() {
	readInput();
	moalefeK();
	moalefeL();
	updateDpL();
	updateDpR();
	writeOutput();
}

int main() {
	ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);
	runProgram();
}

