// n要素で初期化
void init(int n){
    FOR(i,0,2){
      par[i].resize(n);rnk[i].resize(n);
      FOR(j, 0, n){par[i][j] = j;rnk[i][j] = 0;}
    }
}
//木の根を求める
int find(int i, int x){
    if(par[i][x] == x) return x;
    else return par[i][x] = find(par[i][x]);
}
//xとyの属する集合を併合
void unite(int i, int x, int y){
    x = find(x);y = find(y);
    if(x == y) return;
    if(rnk[i][x] < rnk[i][y]) par[i][x] = y;
    else{par[i][y] = x;if(rnk[i][x] == rnk[i][y]) rnk[i][x]++;}
    return;
}
bool isSame(int x, int y){return find(x) == find(y);}

