struct UnionFind {
  vector<int> par, rank;

  UnionFind(int size){
    par.resize(size);
    rank.resize(size);
    rep(i,size){
      par[i] = i;
      rank[i] = 0;
    }    
  }

  int find(int x){
    if(par[x] == x) return x;
    else return par[x] = find(par[x]);
  }

  void unite(int x, int y){
    x = find(x);
    y = find(y);
    if(x == y) return;

    if(rank[x] < rank[y]){
      par[x] = y;
    }else{
      par[y] = x;
      if(rank[x] == rank[y]) rank[x]++;
    }
  }

  bool same(int x, int y){
    return find(x) == find(y);
  }

  void print(){
    cout << "i :\t";
    rep(i, par.size()) cout << i << "\t";
    cout << endl;
    cout << "par :\t";
    rep(i, par.size()) cout << par[i] << "\t";
    cout << endl;
    cout << "rank :\t";
    rep(i, par.size()) cout << rank[i] << "\t";
    cout << endl;
  }
};

