const int MAX_N = 200000;
const int MAX_K = 100000;
const int MAX_L = 100000;

int par[2][MAX_N];
int depth[2][MAX_N];

void init(int n, int type) {
  for (int i=0; i<n; i++) {
    par[type][i] = i;
    depth[type][i] = 0;
  }
}

int find_parent(int x, int type) {
  if (par[type][x] == x) {
    return x;
  } else {
    return par[type][x] = find_parent(par[type][x], type);
  }
}

void unite(int x, int y, int type) {
  x = find_parent(x, type);
  y = find_parent(y, type);
  if (x == y) return;

  if (depth[type][x] < depth[type][y]) {
    par[type][x] = y;
  } else {
    par[type][y] = x;
    if (depth[type][x] == depth[type][y]) depth[type][x]++;
  }
}

int main() {
  int N, K, L, p, q, r, s;
  int type;
  cin >> N >> K >> L;
  type = 0;
  init(N, type);
  for (int i=0; i<K; i++) {
    cin >> p >> q; p--; q--;
    unite(p, q, type);
  }
  type = 1;
  init(N, type);
  for (int i=0; i<L; i++) {
    cin >> r >> s; r--; s--;
    unite(r, s, type);
  }

  map<pair<int, int>, int> ans;
  for (int i=0; i<N; i++) {
