			func(s, i, ++cnt);
		}
	}

	for (int i = 0; i < n; ++i) {
		if (ans[i] != 0) continue;
		int a = grp[0][i], b = grp[1][i];
		int cnt = 0;
		for (int j = i; j < n; ++j) {
			if (grp[0][j] == a && grp[1][j] == b) ++cnt;
		}
		for (int j = i; j < n; ++j) {
			if (grp[0][j] == a && grp[1][j] == b) ans[j] = cnt;
		}
	}
	for (int i = 0; i < n; ++i) {
		if (i > 0) cout << " ";
		cout << ans[i];
	}
	cout << endl;
	return 0;
}

