void solve() {
    i64 N; RD(N);
    i64 K; RD(K);
    i64 L; RD(L);

    UnionFind uf1(N);
    REP(_, K) {
        i64 p,q; RD(p); RD(q); --p; --q;  // 0-based
        uf1.unite(p,q);
    }

    UnionFind uf2(N);
    REP(_, L) {
        i64 r,s; RD(r); RD(s); --r; --s;  // 0-based
        uf2.unite(r,s);
    }

    HashMap<pair<i64,i64>,i64> cnts;
    REP(i, N) {
        i64 r1 = uf1.root(i);
        i64 r2 = uf2.root(i);
        ++cnts[PAIR(r1,r2)];
    }

    vector<i64> ans(N);
    REP(i, N) {
        i64 r1 = uf1.root(i);
        i64 r2 = uf2.root(i);
        ans[i] = cnts[PAIR(r1,r2)];
    }

    PRINTLN(ans);
}

signed main() {


    solve();

    EXIT();
}

