    }

    for (int i : rep(0, n1)) {
        sort(s1[i]);
    }

    for (int i : rep(0, n2)) {
        sort(s2[i]);
    }

    map<pair<int, int>, int> m;

    vector<int> ans;

    for (int i : rep(0, n)) {
        int c1 = col[0][i];
        int c2 = col[1][i];

        if (m.count({c1, c2})) {
            ans.push_back(m[{c1, c2}]);
        } else {
            int res = 0;
            if (s1[c1].size() < s2[c2].size()) {
                for (int x : s1[c1]) {
                    res += binary_search(s2[c2], x);
                }
            } else {
                for (int x : s2[c2]) {
                    res += binary_search(s1[c1], x);
                }
            }

            m[{c1, c2}] = res;
            ans.push_back(res);
        }
    }

    vout(ans, n);
}

