/* constant */

const int MAX_N = 200000;

/* typedef */

typedef pair<int,int> pii;
typedef map<pii,int> mpii;

struct UFT {
  int links[MAX_N], ranks[MAX_N], sizes[MAX_N];
  UFT() {}

  void clear(int n) {
    for (int i = 0; i < n; i++) links[i] = i, ranks[i] = sizes[i] = 1;
  }

  int root(int i) {
    int i0 = i;
    while (links[i0] != i0) i0 = links[i0];
    return (links[i] = i0);
  }

  int rank(int i) { return ranks[root(i)]; }
  int size(int i) { return sizes[root(i)]; }
  bool same(int i, int j) { return root(i) == root(j); }

  int merge(int i0, int i1) {
    int r0 = root(i0), r1 = root(i1), mr;
    if (r0 == r1) return r0;
    if (ranks[r0] == ranks[r1]) {
      links[r1] = r0;
      sizes[r0] += sizes[r1];
      ranks[r0]++;
      mr = r0;
    }
    else if (ranks[r0] > ranks[r1]) {
      links[r1] = r0;
      sizes[r0] += sizes[r1];
      mr = r0;
    }
    else {
      links[r0] = r1;
      sizes[r1] += sizes[r0];
      mr = r1;
    }
    return mr;
  }
};

/* global variables */

UFT uft0, uft1;
mpii cs;

/* subroutines */

/* main */

int main() {
  int n, k, l;
  cin >> n >> k >> l;

  uft0.clear(n);
  uft1.clear(n);

  for (int i = 0; i < k; i++) {
    int ai, bi;
    cin >> ai >> bi;
    ai--, bi--;
    if (! uft0.same(ai, bi)) uft0.merge(ai, bi);
  }
  for (int i = 0; i < l; i++) {
    int ai, bi;
    cin >> ai >> bi;
    ai--, bi--;
    if (! uft1.same(ai, bi)) uft1.merge(ai, bi);
  }

  for (int i = 0; i < n; i++) {
    int r0 = uft0.root(i);
    int r1 = uft1.root(i);
    cs[pii(r0, r1)]++;
  }

  for (int i = 0; i < n; i++) {
    if (i) putchar(' ');
    int r0 = uft0.root(i);
    int r1 = uft1.root(i);
    printf("%d", cs[pii(r0, r1)]);
  }
  putchar('\n');

  return 0;
}

