    rep(i,0,n){
        m[make_pair(uf.find(i), uf2.find(i))]++;
    }
    rep(i,0,n)cout << m[make_pair(uf.find(i), uf2.find(i))]<< " ";
    cout << endl;
  	return 0;
}

