using ll = long long;
using ld = long double;

const ll mod = 1e9 + 7;
const ld PI = acos(-1.0);

struct DSU {
	using T = int;
	vector<T> parent;
	vector<T> size;
	T numComponents = 0;
	DSU(T n = 0) {
		if(n >= 0)
			init(n);
	}
	void init(T n = 0) {
		parent.resize(n);
		size.assign(n, 1);
		numComponents = n;
		for (T i = 0; i < n; i++)
			parent[i] = i;
	}
	T getParent(T x) {
		return (x == parent[x]) ? x : parent[x] = getParent(parent[x]);
	}
	bool merge(T x, T y) {
		x = getParent(x);
		y = getParent(y);
		if (x == y) {
			return false;
		} 
		if (size[x] < size[y]) {
			swap(x, y);
		}
		parent[y] = x;
		size[x] += size[y];
		numComponents--;
		return true;
	}
};

void Solve() {
	int n, k, l;
	cin >> n >> k >> l;
	DSU road(n), railway(n);
	for(int i = 0; i < k; i ++) {
		int a, b;
		cin >> a >> b;
		a --; b --;
		road.merge(a, b);
	}
	for(int i = 0; i < l; i ++) {
		int a, b;
		cin >> a >> b;
		a --; b --;
		if(road.getParent(a) == road.getParent(b)) {
			railway.merge(a, b);
		}
	}
	for(int i = 0; i < n; i ++) {
		cout << railway.size[railway.getParent(i)] << " ";
	}
	cout << endl;
}

