struct UFNode
{
    UFNode *parent;
    int rank;
    UFNode(){
        parent=this;
        rank=0;
    }
};

typedef pair<UFNode*, UFNode*> P;

UFNode* find(UFNode *n)
{
    if(n->parent==n) return n;
    else return n->parent=find(n->parent);
}

void unite(UFNode *a,UFNode *b)
{
    UFNode *x=find(a),*y=find(b);
    if(x==y) return;
    if(x->rank < y->rank) x->parent=y;
    else{
        y->parent=x;
        if(x->rank == y->rank) x->rank++;
    }
}

