struct vert{
	int key;
	int prev;
};

void gpaphColoring(std::vector<int> &coloredNode, std::vector<std::vector<int>> graph){
	int color= 0;	
	for(int i=0; i<coloredNode.size(); i++){
		if(coloredNode[i]>= 0)
			continue;

		std::stack<int> path;
		std::stack<vert> dfs;
		dfs.push({i, -1});

		while(!dfs.empty()){
			int cur= dfs.top().key;
			dfs.pop();	

			coloredNode[cur]= color;
			path.push(cur);

			bool isLeaf= true;
			for(int i=0; i<graph[cur].size(); i++){
				int dst= graph[cur][i];
				if(coloredNode[dst]<0){
					dfs.push({dst, cur});
					isLeaf= false;
				}
			}

			if(isLeaf){
				while(!dfs.empty()){
					if(dfs.top().prev==path.top())
						break;
					else
						path.pop();
				}
			}
		}
		color++;	
	}

}

