class UnionFind
{
public:
	UnionFind() {};
	void init(int n)
	{
		max = n;
		par.resize(max);
		rank.resize(max);
		for (int i = 0; i < max; ++i)
		{
			par[i] = i;
			rank[i] = 0;
		}
	}
	int find(int x)
	{
		if (par[x] == x)return x;
		return par[x] = find(par[x]);
	}
	bool same(int x, int y)
	{
		return find(x) == find(y);
	}
	void unit(int x, int y)
	{
		x = find(x);
		y = find(y);
		if (x == y)return;

		if (rank[x] < rank[y])
		{
			par[x] = y;
		}
		else
		{
			par[y] = x;
			if (rank[x] == rank[y])
			{
				rank[x]++;
			}
		}
	}

private:
	std::vector<int> par;
	std::vector<int> rank;
	int max;
};

