void dfsG(Graph &G, int s, int mark){
    if(checkG[s] != -1) return;
    checkG[s] = mark;
    for (int i=0;i<G[s].size();i++){
        if(checkG[G[s][i]] == -1){
            dfsG(G, G[s][i], mark);
        }
    }
}

void dfsH(Graph &H, int s, int mark){
    if(checkH[s] != -1) return;
    checkH[s] = mark;
    for (int i=0;i<H[s].size();i++){
        if(checkH[H[s][i]] == -1 && checkG[H[s][i]] == checkG[mark]){
            dfsH(H, H[s][i], mark);
        }
    }
}

void Connectivity(Graph &G, Graph &H){
    int N = G.size();
    for(int i=0;i<N;i++){
        checkG[i] = -1;
        checkH[i] = -1;
    }
    for (int i=0;i<N;i++){
        dfsG(G, i, i);
    }
    for(int i=0;i<N;i++){
        dfsH(H, i, i);
    }
    int count[N] = {};
    for(int i=0;i<N;i++){
        count[checkH[i]]++;
    }
    for (int i=0;i<N;i++){
        cout << count[checkH[i]] << endl;
    }
}

