/*--------------------template--------------------*/

class UF
{
  public:
    vi rank, data;
    UF() {}
    UF(ll size)
    {
        rank.resize(size, 0);
        data.resize(size, 0);
        REP(i, size)
        {
            init(i);
        }
    }
    void init(ll x)
    {
        data[x] = x;
        rank[x] = 0;
    }

    bool same(ll x, ll y)
    {
        return root(x) == root(y);
    }

    void unite(ll x, ll y)
    {
        link(root(x), root(y));
    }

    void link(ll x, ll y)
    {
        if (rank[x] > rank[y])
        {
            data[y] = x;
        }
        else
        {
            data[x] = y;
            if (rank[x] == rank[y])
            {
                rank[y]++;
            }
        }
    }
    // xの根を探す。同じ集合なら同じ根が帰る, O(A^-1)
    ll root(ll x)
    {
        return (x == data[x] ? data[x] : data[x] = root(data[x]));
    }

    // 分離されている集合の数を返す, O(n)
    ll getSetNum(){
        map<ll, ll> c;
        REP(i,data.size()) {
            c[root(i)]++;
        }
        return c.size();
    }

    // 頂点vと連結な集合を返す, O(n)
    vi getContainingSet(int v)
    {
        vi ret;
        REP(i,data.size()) {
            if(root(i)==root(v)){
                ret.push_back(i);
            }
        }
        return ret;
    }
};

