      p[i]--; q[i]--;
   }
   REP(i, 0, L) {
      cin >> r[i] >> s[i];
      r[i]--; s[i]--;
   }

   UnionFind uni0(N), uni1(N);
   REP(i, 0, K) {
      uni0.unite(p[i], q[i]);
   }
   REP(i, 0, L) {
      uni1.unite(r[i], s[i]);
   }

   map<P, int> count;
   REP(i, 0, N) {
      count[MP(uni0.find(i), uni1.find(i))]++;
   }

   REP(i, 0, N) {
      cout << count[MP(uni0.find(i), uni1.find(i))] << endl;
   }

   return 0;
}

