int parent[2][MAX_N+1], depth[MAX_N+1];

int root(int a, int t){
  if(a==parent[t][a])return a;
  return parent[t][a]=root(parent[t][a], t);
}

void unite(int a, int b, int t){
  a=root(a, t);
  b=root(b, t);
  if(depth[a]>depth[b]){
    parent[t][b]=a;
  }else if(depth[b]>depth[a]){
    parent[t][a]=b;
  }else{
    parent[t][a]=b;
    depth[b]++;
  }
}

