const int MAX_N = 200000;
struct UnionFind{
    int par[MAX_N];
    int cnt[MAX_N];
    void init(int n){
        for(int i = 0;i < n;i++){
            par[i] = i;
            cnt[i] = 1;
        }
    }
    int root(int x){
        if(par[x] == x)return x;
        else return par[x] = root(par[x]);
    }
    bool same(int x,int y){
        return root(x) == root(y);
    }
    void unite(int x,int y){
        x = root(x);
        y = root(y);
        if(x == y)return;
        par[y] = x;
        cnt[x] += cnt[y];
    }
    int getcnt(int x){
        return cnt[root(x)];
    }
};
