class UnionFind{
public:
  vector<int> uni;
  UnionFind(int s) : uni(s, -1) {}

  int root(int a){
    if(uni[a] < 0) return a;
    return uni[a] = root(uni[a]);
  }

  bool connect(int a, int b){
    a = root(a);
    b = root(b);
    if(a == b) return false;
    if(uni[a] > uni[b]) swap(a, b);
    uni[a] = uni[a] + uni[b];
    uni[b] = a;
    return true;
  }

  bool isConnect(int a, int b){
    return root(a) == root(b);
  }

  int size(int a){
    return -uni[root(a)];
  }
};

int main() {
  int N, K, L;
  cin >> N >> K >> L;
  UnionFind uf(N);
  rep(i, 0, K) {
    int p, q;
    cin >> p >> q;
    p--, q--;
    uf.connect(p, q);
  }
  UnionFind uf2(N);
  rep(i, 0, L) {
    int p, q;
    cin >> p >> q;
    p--, q--;
    if(uf.isConnect(p, q)) uf2.connect(p, q);
  }
  rep(i, 0, N) cout << uf2.size(i) << " ";
  cout << endl;
  return 0;
}

