    cin>>p>>q;
    u1.unite(p,q);
  }
  for(i=0;i<l;i++){
    cin>>p>>q;
    if(u1.same(p,q)) u2.unite(p,q);
  }
  for(i=1;i<=n;i++) cout << u2.r[u2.find(i)] << " \n"[i==n];
  return 0;
}

