using namespace std;
typedef long long ll;
typedef pair<int, int> Pr;

struct edge{
	int to, cost;
};

int N, K, L;
vector<edge> G1[200010], G2[200010];
int d1[200010],d2[200010];
int ans[200010];

const int INF = 1000000009;

void dijkstra1(int s) {
	priority_queue<Pr, vector<Pr>, greater<Pr>> q;
	fill(d1, d1 + N, INF);
	d1[s] = 0;
	q.push(Pr(0, s));

	while (!q.empty()) {
		Pr p = q.top(); q.pop();
		int v = p.second;
		if (d1[v] < p.first)continue;
		for (int i = 0; i < G1[v].size(); i++) {
			edge e = G1[v][i];
			if (d1[e.to] > d1[v] + e.cost) {
				d1[e.to] = d1[v] + e.cost;
				q.push(Pr(d1[e.to], e.to));
			}
		}
	}
}

void dijkstra2(int s) {
	priority_queue<Pr, vector<Pr>, greater<Pr>> q;
	fill(d2, d2 + N, INF);
	d2[s] = 0;
	q.push(Pr(0, s));

	while (!q.empty()) {
		Pr p = q.top(); q.pop();
		int v = p.second;
		if (d2[v] < p.first)continue;
		for (int i = 0; i < G2[v].size(); i++) {
			edge e = G2[v][i];
			if (d2[e.to] > d2[v] + e.cost) {
				d2[e.to] = d2[v] + e.cost;
				q.push(Pr(d2[e.to], e.to));
			}
		}
	}
}

int main()
{
	cin >> N >> K >> L;
	for (int i = 0; i < K; i++) {
		int p, q;
		cin >> p >> q;
		p--, q--;
		G1[p].push_back({q,1});
		G1[q].push_back({p,1 });
	}

	for (int i = 0; i < L; i++) {
		int s, r;
		cin >> s >> r;
		s--, r--;
		G2[s].push_back({r,1});
		G2[r].push_back({s,1 });
	}

	for (int i = 0; i < N; i++) {
		dijkstra1(i);
		dijkstra2(i);
		ans[i]++;
		for (int j = i + 1; j < N; j++) {
			if (d1[j] != INF && d2[j] != INF)
				ans[j]++, ans[i]++;
		}
	}

	for (int i = 0; i < N; i++)
		cout << ans[i];
	cout << endl;
	return 0;
}

