void bfs(int t) {
	ccnt = 0;
	comp[t] = vector<int>(N, -1);
	for(int i = 0; i < N; i++) {
		if(comp[t][i] != -1) continue;
		queue<int> q;
		q.push(i);
		comp[t][i] = ccnt;
		while(!q.empty()) {
			int u = q.front(); q.pop();

			for(int i = 0; i < adj[t][u].size(); i++) {
				int v = adj[t][u][i];
				if(comp[t][v] == -1) {
					q.push(v);
					comp[t][v] = ccnt;
				}
			}
		}
		ccnt++;
	}
}

