class UFT {
  int *par;
  int *rank;

public:

  UFT(const size_t N): par(new int [N]), rank(new int [N]) {
    std::iota(par, par + N, 0);
    std::fill(rank, rank + N, 0);
  }

  ~UFT() { delete [] par; delete [] rank; }

  int find(int x) { return par[x] == x ? x : par[x] = find(par[x]); }
  bool same(int x, int y) { return find(x) == find(y); }

  void unite(int x, int y) {
    x = find(x);
    y = find(y);
    if (x == y) return;

    if (rank[x] < rank[y]) {
      par[x] = y;
    } else {
      par[y] = x;
      if (rank[x] == rank[y])
        ++rank[x];
    }
  }

};

int main(int argc, char *argv[]) {
  int N, K, L;
  cin >> N >> K >> L;
  UFT ufroad(N + 1);

  for (int i = 0; i < K; ++i) {
    int p, q;
    cin >> p >> q;
    ufroad.unite(p, q);
  }

  int cnts[N + 1];
  fill(cnts, cnts + N + 1, 1);
  for (int i = 0; i < L; ++i) {
    int r, s;
    cin >> r >> s;
    int same = ufroad.same(r, s);
    cnts[r] += same;
    cnts[s] += same;
  }

  for (int i = 1; i < N + 1; ++i) {
    cout << cnts[i] << (i == N ? "\n" : " ");
  }

  return 0;
}

