class union_find
{
public:
	int *par;
	int *rank;

	union_find(int n) {
		par = new int[n];
		rank = new int[n];
		for (int i = 0; i < n; i++) {
			par[i] = i;
			rank[i] = 0;
		}
	}

	int root(int a) {
		if (par[a] == a) {
			return a;
		}
		else {
			return root(par[a]);
		}
	}

	bool same(int a, int b) {
		return root(a) == root(b);
	}

	void uni(int a, int b) {
		a = root(a);
		b = root(b);
		if (a == b) {
			return;
		}
		if (rank[a] < rank[b]) {
			par[a] = b;
		}
		else {
			par[b] = a;
			if (rank[a] == rank[b]) {
				rank[a]++;
			}
		}
	}
};

