    vector<int> ans(N, 1);
    REP(i, L) {
        int r, s;
        cin >> r >> s;
        r--;
        s--;
        if (uf.same(r, s)) {
            ans[r]++;
            ans[s]++;
        }
    }

    REP(i, ans.size()) {
        cout << ans[i] << " ";
    }
    cout << endl;

    return 0;
}

