#define FOR(i, n) for(int i = 0; i < (n); i++)
#define MEM(a, x) memset(a, x, sizeof(a))
#define ALL(a) a.begin(), a.end()
#define UNIQUE(a) a.erase(unique(ALL(a)), a.end())
typedef long long ll;

int par[200005], ran[200005], par2[200005], ran2[200005];
int n, k, l;

void init(int n, bool road) {
	if (road) {
		FOR(i, n) {
			par[i] = i;
			ran[i] = 0;
		}
	}
	else {
		FOR(i, n) {
			par2[i] = i;
			ran2[i] = 0;
		}
	}
}

int find(int x, bool road) {
	if (road) {
		if (par[x] == x) return x;
		else return par[x] = find(par[x], true);
	}
	else {
		if (par2[x] == x) return x;
		else return par2[x] = find(par2[x], false);
	}

}

void unite(int x, int y, bool road) {
	if (road) {
		x = find(x, true);
		y = find(y, true);
		if (x == y) return;
		if (ran[x] < ran[y]) par[x] = y;
		else {
			par[y] = x;
			if (ran[x] == ran[y]) ran[x]++;
		}
	}
	else {
		x = find(x, false);
		y = find(y, false);
		if (x == y) return;
		if (ran2[x] < ran2[y]) par2[x] = y;
		else {
			par2[y] = x;
			if (ran2[x] == ran2[y]) ran2[x]++;
		}
	}
}

bool same(int x, int y, bool road) {
	if (road) return find(x, true) == find(y, true);
	else return find(x, false) == find(y, false);
}

int main(int argc, char const *argv[]) {
	ios_base::sync_with_stdio(false);
	cin >> n >> k >> l;
	init(n, true);
	FOR(i, k) {
		int p, q;
		cin >> p >> q;
		p--;
		q--;
		unite(p, q, true);
	}
	init(n, false);
	FOR(i, l) {
		int r, s;
		cin >> r >> s;
		r--;
		s--;
		unite(r, s, false);
	}
	map<pair<int, int>, int> mp;
	FOR(i, n) {
		mp[make_pair(find(i, true), find(i, false))]++;
	}
	FOR(i, n) {
		cout << mp[make_pair(find(i, true), find(i, false))];
		if (i < n-1) cout << " ";
		else cout << endl;
	}
	return 0;
}

