int rank2[MAX_N];


// ｎ要素で初期化
void init(){
  for(int i=0;i<n;i++){
    par1[i]=par2[i]=i;
    rank1[i]=rank2[i]=0;
  }
}

// 木の根を求める
int find(int x, bool flag){
  if(flag){
    if (par1[x] == x){
      return x;
    }else{
      return par1[x] = find(par1[x],flag);
    }
  }else{
    if(par2[x]==x){
      return x;
    }else{
      return par2[x]=find(par2[x],flag);
    }
  }
}

// ｘとｙの属する集合を併合
void unite(int x, int y, bool flag){
  x = find(x,flag);
  y = find(y,flag);
  if (x == y) return;
  if(flag){
    if (rank1[x] < rank1[y]){
      par1[x] = y;
    }else{
      par1[y] = x;
      if (rank1[x] == rank1[y]) rank1[x]++;
    }
  }else{
    if(rank2[x]<rank2[y]){
      par2[x]=y;
    }else{
      par2[y]=x;
      if(rank2[x]==rank2[y]) rank2[x]++;
    }
  }
}

// ｘとｙが同じ集合に属するかどうか
bool same(int x, int y, bool flag){
  return find(x,flag) == find(y,flag);
}


