const int MaxN = 2e5+3;
int n,k,l;
struct DSU{
	int fa[MaxN],rank[MaxN];
	DSU() { for (int i=1;i<MaxN;++i) fa[i]=i,rank[i]=1; }
	int getfa(int x) {return (fa[x]==x) ? x : (fa[x]=getfa(fa[x]));}
	inline void uni(int a,int b) {
		a=getfa(a),b=getfa(b);
		if (a!=b) {
			if (rank[a]<rank[b]) {
				fa[a]=b;
				rank[b]+=rank[a];
			} else {
				fa[b]=a;
				rank[a]+=rank[b];
			}
		}
	}
}road,railway;
typedef pair<int,int> PII;
map<PII,int> mp;
