		road.uni(p,q);
	}
	for (int i=1;i<=l;++i) {
		int r,s;
		scanf("%d%d",&r,&s);
		railway.uni(r,s);
	}
	for (int i=1;i<=n;++i) {
		int x=road.getfa(i),y=railway.getfa(i);
		PII t=make_pair(x,y);
		if (!mp.count(t)) mp[t]=0;
		mp[t]++;
	}
	for (int i=1;i<=n;++i) {
		int x=road.getfa(i),y=railway.getfa(i);
		printf("%d ",mp[PII(x,y)]);
	}
	return 0;
}

