struct UF {
  std::vector<int> par, rank;
  UF(int n) : par(n), rank(n, 0) {
    for (size_t i = 0; i < n; ++i) par[i] = i;
  }

  int root(int x) {
    return (par[x] == x) ? x : par[x] = root(par[x]);
  }

  void unite(int x, int y) {
    x = root(x); y = root(y);

    if (x == y) return;

    if (rank[x] < rank[y]) {
      par[x] = y;
    } else {
      par[y] = x;
      if (rank[x] == rank[y]) rank[x]++;
    }
  }

  bool same(int x, int y) {
    return root(x) == root(y);
  }
};

