void init(int n){
	for(int i = 0;i < n;i++){
		par[i] = i;
		arank[i] = 0;
	}
}

int find(int x){
	if(par[x] == x) return x;
	else return par[x] = find(par[x]);
}

void unite(int x,int y){
	x = find(x);
	y = find(y);
	if(x == y) return;
	if(arank[x] < arank[y]){
		par[x] = y;
	}else{
		par[y] = x;
		if(arank[x] == arank[y]) arank[x]++;
	}
}

bool same(int x,int y){
	return find(x) == find(y);
}

int main(){
	int n,k,l;
	long long int res[200000];
	cin >> n >> k >> l;
	init(n * 2);
	for(int i = 0;i < n;i++) {
		res[i] = 1;
		unite(i,i + n);
	}
	for(int i = 0;i < k;i++){
		int a,b;
		cin >> a >> b;
		a--;
		b--;
		unite(a,b);
	}
	for(int i = 0;i < l;i++){
		int a,b;
		cin >> a >> b;
		a--;
		b--;
		if(same(a + n,b + n)){
			res[a]++;
			res[b]++;
		}
		else unite(a + n,b + n);
	}
	cout << res[0];
	for(int i = 1;i < n;i++){
		cout << " " << res[i];
	}
	cout << endl;
	return 0;
}

