using namespace std;
const int maxn=2e5+1212;

int n,m1,m2;
int edgenum,Time,scccnt,stacknum;
bool isstack[maxn],vis[maxn];
int head[maxn],Next[maxn],b[maxn],V[maxn];
int num[maxn];
vector <int> human;
void init()
{
    memset(num,0,sizeof(num));
    memset(head,-1,sizeof(head));
}
void add(int u,int v)
{
    V[++edgenum]=v;
    Next[edgenum]=head[u];
    head[u]=edgenum;
}


void DFS(int u)
{
    human.push_back(u);
    vis[u]=true;
    for(int i=head[u];i!=-1;i=Next[i])
    {
        int v=V[i];
        if(b[v]==b[u]&&vis[v]==false) DFS(v);
    }
}

int f(int x)
{
    if(b[x]==x) return x;
    else return b[x]=f(b[x]);
}
int main()
{
    int u,v;
    while(scanf("%d %d %d",&n,&m1,&m2)!=EOF)
    {
        init();
        for(int i=1;i<=n;i++) b[i]=i;
        for(int i=1;i<=m1;i++)
        {
            scanf("%d %d",&u,&v);
            add(u,v);
            int t1=f(u),t2=f(v);
            b[t2]=t1;
        }
        for(int i=1;i<=n;i++) b[i]=f(b[i]);
        memset(vis,false,sizeof(vis));
        memset(head,-1,sizeof(head));
        edgenum=0;
        for(int i=1;i<=m2;i++)
        {
            scanf("%d %d",&u,&v);
            add(u,v);
            add(v,u);
        }
        for(int i=1;i<=n;i++)
        {
            if(vis[i]==false)
            {
                DFS(i);
                for(int j=0;j<(int)human.size();j++)
                {
                    int pos=human[j];
                    num[pos]=num[pos]+human.size();
                }
                human.clear();
            }
        }
        for(int i=1;i<=n;i++)
        {
            if(i==n) printf("%d\n",num[i]);
            else printf("%d ",num[i]);
        }
    }
    return 0;
}

