vector<vector<ll>> adj1;
vector<vector<ll>> adj2;
void dfs(ll pos,vector<ll>& con,vector<bool>& used) {
	REP(i,adj1[pos].size()) {
		if(!used[adj1[pos][i]]) {
			used[adj1[pos][i]]=true;
			con.pb(adj1[pos][i]);
			dfs(adj1[pos][i],con,used);
		}
	}
}
void dfs2(ll pos,vector<ll>& con,vector<bool>& used,set<ll>& s) {
	REP(i,adj2[pos].size()) {
		if(s.count(adj2[pos][i])!=0&&!used[adj2[pos][i]]) {
			used[adj2[pos][i]]=true;
			con.pb(adj2[pos][i]);
			dfs2(adj2[pos][i],con,used,s);
		}
	}
}

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	ll n,k,l;
	cin>>n>>k>>l;
	adj1.resize(n);
	adj2.resize(n);
	REP(i,k) {
		ll p,q;
		cin>>p>>q;
		p--;
		q--;
		adj1[p].pb(q);
		adj1[q].pb(p);
	}
	REP(i,l) {
		ll r,s;
		cin>>r>>s;
		r--;
		s--;
		adj2[r].pb(s);
		adj2[s].pb(r);
	}
	vector<bool> used1(n,false);
	vector<ll> ret(n);
	REP(i,n) {
		if(!used1[i]) {
			vector<ll> con;
			vector<bool> used2(n,false);
			con.pb(i);
			used2[i]=true;
			dfs(i,con,used2);
			map<ll,bool> s;
			REP(j,con.size()) {
				used1[con[j]]=true;
				s[con[j]]=false;
			}
			set<ll> ss;
			REP(j,con.size()) {
				ss.insert(con[j]);
			}
			REP(j,con.size()) {
				if(!s[con[j]]) {
					vector<ll> con2;
					vector<bool> used3(n,false);
					con2.pb(con[j]);
					used3[con[j]]=true;
					dfs2(con[j],con2,used3,ss);
					REP(k,con2.size()) {
						s[con2[k]]=true;
						ret[con2[k]]=(ll)con2.size();
					}
				}
			}
		}
	}
	DUMP(n,ret);
}

