/* Coding Space*/
class UF{
public:
  vi value;
  vi over; // When over < 0, 'over' keep number of node(using negative number). -1 means this tree is a node.
  int root(int index){
    int t = index;
    stack<int> stack_i;
    while(over[t] >= 0){
      stack_i.push(t);
      t = over[t];
    }
    while(!stack_i.empty()){
      int i = stack_i.top(); stack_i.pop();
      over[i] = t;
    }// reconnect
    return t;
  }
  void merge(int a,int b){
    if(this->root(a) == this->root(b)) return;
    over[root(a)] += over[root(b)]; // over have a number of nodes.
    over[root(b)] = root(a);
  }
  int NumNode(int a){
    return -over[root(a)];
  }
  UF(int Nodes){
    value.resize(Nodes);
    over.resize(Nodes);
    rep(i,Nodes)
      over[i] = -1;
  }
};
typedef tuple<int,int> tii;
int main(){
  UF road(2*100001);
  UF train(2*100001);
  int n,k,l; cin >> n >> k >> l;
  rep(i,k){
    int a,b; cin >> a >> b;a--,b--;
    road.merge(a,b);
  }
  rep(i,l){
    int a,b; cin >> a >> b;a--,b--;
    train.merge(a,b);
  }
  map<tii,int> m;
  rep(i,n){
    m[tii{road.root(i),train.root(i)}]++;
  }
  rep(i,n){
    cout << m[tii{road.root(i),train.root(i)}] << (i==n-1?"\n":" ");
  }
}

