struct UnionFind {
private:
    const int n;
    int __size;
    vector<int> uf;
public:
    // 初期化 UnionFind uni(n) のように宣言すれば良い
    UnionFind(int _n) : n(_n), __size(_n), uf(_n, -1) {}
    // find (木の根を求める)
    int find(int x) {return (uf[x] < 0) ? x : uf[x] = find(uf[x]);}
    // x と y が同じ集合に属するかどうか
    bool same(int x, int y) {return find(x) == find(y);}
    // x が属する集合の要素数
    int size(int x) {return -uf[find(x)];}
    // 集合はいくつあるか
    int size()      {return __size;}
    // x と y の属する集合を併合
    void unite(int x, int y) {
        x = find(x); y = find(y);
        if(x == y) return;
        __size--;
        if(uf[y] < uf[x]) swap(x, y);
        uf[x] += uf[y]; uf[y] = x;
    }
};

signed main() {
    int n, k, l; cin >> n >> k >> l;
    UnionFind uf1(n), uf2(n);
    rep(i,0,k) {
        int p, q; cin >> p >> q;
        p--; q--;
        uf1.unite(p, q);
    }
    rep(i,0,l) {
        int r, s; cin >> r >> s;
        r--; s--;
        uf2.unite(r, s);
    }

    map<pii, int> m;
    rep(i,0,n) {
        int f1 = uf1.find(i);
        int f2 = uf2.find(i);
        pii temp = pii(f1, f2);
        if(!m.count(temp)) m[temp] = 1;
        else m[temp] += 1;
    }

    rep(i,0,n) {
        int f1 = uf1.find(i);
        int f2 = uf2.find(i);
        int ret = m[ pii(f1, f2) ];
        if(i == 0) printf("%lld", ret);
        else printf(" %lld", ret);
    }
    cout << endl;
    return 0;
}

