const int maxn = 62, mlg = 18, rt = 1<<10, mod = 1e9 + 7;
struct dsu {
	vi p, r;
	vector<vi> col;
	dsu(int n) {
		p.resize(n+1);
		iota(all(p), 0);
		r.resize(n+1,1);
		col.resize(n+1);
	}
	int par(int v) {
		return v^p[v] ? p[v] = par(p[v]) : v;
	}
	void unite(int i, int j) {
		i = par(i), j = par(j);
		if(i == j) return;
		if(r[i] < r[j]) swap(i, j);
		p[j] = i, r[i] += r[j];
		for(auto x : col[j]) col[i].push_back(x);
	}
};
