const int MAXN = 200000;

vector<vector<int> > g1, g2;
bool seen1[1 + MAXN], seen2[1 + MAXN];
int which1[1 + MAXN], which2[1 + MAXN];
int answer[1 + MAXN];
int components1 = 0, components2 = 0;

void BFS(int start, bool seen[], const vector<vector<int> > &g, int current, int which[]) {
    queue<int> Queue;
    Queue.push(start);
    seen[start] = true;
    which[start] = current;
    while (!Queue.empty()) {
        int node = Queue.front();
        Queue.pop();
        for (auto &it : g[node])
            if (!seen[it]) {
                seen[it] = true;
                which[it] = current;
                Queue.push(it);
            }
    }
}

struct Node {
    pair<int, int> value;
    int index;

    bool operator < (const Node &other) const {
        return value < other.value;
    }
};

Node nodes[1 + MAXN];

int main() {
    int n, k, l;
    cin >> n >> k >> l;
    g1.resize(n + 1);
    g2.resize(n + 1);
    for (int i = 1; i <= k; i++) {
        int a, b;
        cin >> a >> b;
        g1[a].push_back(b);
        g1[b].push_back(a);
    }
    for (int i = 1; i <= l; i++) {
        int a, b;
        cin >> a >> b;
        g2[a].push_back(b);
        g2[b].push_back(a);
    }
    for (int i = 1; i <= n; i++) {
        if (!seen1[i]) {
            components1++;
            BFS(i, seen1, g1, components1, which1);
        }
        if (!seen2[i]) {
            components2++;
            BFS(i, seen2, g2, components2, which2);
        }
        nodes[i] = {make_pair(which1[i], which2[i]), i};
    }
    sort(nodes + 1, nodes + n + 1);
    for (int i = 1, j; i <= n; i = j) {
        int value = 0;
        j = i;
        while (j <= n && nodes[i].value == nodes[j].value) {
            value++;
            j++;
        }
        j = i;
        while (j <= n && nodes[i].value == nodes[j].value) {
            answer[nodes[j].index] = value;
            j++;
        }
    }
    for (int i = 1; i <= n; i++)
        cout << answer[i] << " ";
    return 0;
}

