class DFS {
 public:
  DFS(vector<vector<int>>& g, int n) : g_(g), used_(n, 0) {
    int color = 1;
    for (int i = 0; i < n; i++) {
      if (!used_[i]) {
        Run(i, color);
        ++color;
      }
    }
  }

  void Run(int v, int color) {
    used_[v] = color;
    for (auto u : g_[v]) {
      if (used_[u]) {
        continue;
      }
      Run(u, color);
    }
  }

  const vector<int>& GetColors() const {
    return used_;
  }

 private:
  vector<vector<int>>& g_;
  vector<int> used_;
};

