template<int Maxn>
struct Union_Set {

	int fa[Maxn], sz[Maxn];

	void Init(int n) {
		For (i, 1, n)
			fa[i] = i, sz[i] = 1;
	}

	int find(int x) {
		return x == fa[x] ? x : fa[x] = find(fa[x]); 
	}

	inline bool Connect(int u, int v) {
		return find(u) == find(v);
	}

	inline void Union(int u, int v) {
		if (!Connect(u, v)) 
			sz[fa[find(v)] = find(u)] += sz[find(v)];
	}

};

