const int MAXN = 2e5 + 5;

int N, M1, M2;
Pii E1[MAXN], E2[MAXN];
int fa1[MAXN], fa2[MAXN];

int getFather(int *fa, int u)
{
    return fa[u] == u ? u : fa[u] = getFather(fa, fa[u]);
}

struct Cmp {
    bool operator() (int a, int b) {
        return getFather(fa2, a) < getFather(fa2, b);
    }
};

std::vector<int> set[MAXN];

void input()
{
    read(N); read(M1); read(M2);
    for (int i = 1; i <= M1; ++i) {
        read(E1[i].x); read(E1[i].y);
    }
    for (int i = 1; i <= M2; ++i) {
        read(E2[i].x); read(E2[i].y);
    }
}

void solve()
{
    for (int i = 1; i <= N; ++i) {
        fa1[i] = fa2[i] = i;
    }
    for (int i = 1; i <= M1; ++i) {
        int u = E1[i].x, v = E1[i].y;
        int fu = getFather(fa1, u), fv = getFather(fa1, v);
        if (fu != fv)
            fa1[fu] = fv;
    }
    for (int i = 1; i <= M2; ++i) {
        int u = E2[i].x, v = E2[i].y;
        // printf("(%d, %d)\n", u, v);
        int fu = getFather(fa2, u), fv = getFather(fa2, v);
        if (fu != fv)
            fa2[fu] = fv;
    }

    for (int i = 1; i <= N; ++i) {
        // printf("%d:, fa1 = %d, fa2 = %d\n", i, getFather(fa1, i), getFather(fa2, i));
        set[getFather(fa1, i)].push_back(i);
    }

    static int ans[MAXN];

    for (int i = 1; i <= N; ++i) {
        if (fa1[i] == i) {
            std::sort(set[i].begin(), set[i].end(), Cmp());
            int last = 0;
            for (int j = 0; j < set[i].size(); ++j) {
                if (getFather(fa2, set[i][j]) != getFather(fa2, set[i][last])) {
                    for (int k = last; k < j; ++k) {
                        ans[set[i][k]] = j - last;
                    }
                    last = j;
                }
                for (int k = last; k < set[i].size(); ++k) {
                    ans[set[i][k]] = set[i].size() - last;
                }
            }
        }
    }
    for (int i = 1; i <= N; ++i) {
        write(ans[i]); putchar(' ');
    }
    putchar('\n');
}

