template<typename T> std::unordered_set<T> product(const std::unordered_set<T>& setA, const std::unordered_set<T>& setB) {
	std::unordered_set<T> setR;
	for (const auto& i : setA)
	{
		if (setB.find(i) != setB.end())
		{
			setR.insert(i);
		}
	}
	return setR;
}


class DisjointDataStructure {
public:
	DisjointDataStructure(int number_of_nodes) {
		par = std::vector<int>(number_of_nodes);
		std::iota(par.begin(), par.end(), 0);
		rank = std::vector<int>(number_of_nodes);
		groups = std::vector<std::unordered_set<int>>(number_of_nodes);
		for (int i = 0; i < number_of_nodes; i++)
		{
			groups[i].insert(i);
		}
	}
	int root(int node) {
		if (par[node] == node)
		{
			return node;
		}
		else
		{
			return par[node] = root(par[node]);
		}
	}
	inline bool inTheSameSet(int node1, int node2) {
		return root(node1) == root(node2);
	}
	inline std::unordered_set<int> elementsOfGroup(int x) {
		return groups[root(x)];
	}
	void unite(int node1, int node2) {
		auto x = root(node1);
		auto y = root(node2);
		if (x != y)
		{
			if (rank[x] < rank[y])
			{
				std::swap(x, y);
			}
			par[y] = x;
			groups[x].insert(groups[y].begin(), groups[y].end());
			groups[y].clear();
			if (rank[x] == rank[y])
			{
				rank[x]++;
			}
		}
	}
private:
	std::vector<int> par;
	std::vector<int> rank;
	std::vector<std::unordered_set<int>> groups;
};


int main() {
	std::cin.tie(nullptr);
	std::ios::sync_with_stdio(false);
	int n, k, l;
	std::cin >> n >> k >> l;
	DisjointDataStructure allDDS(n);
	DisjointDataStructure roadDDS(n);
	DisjointDataStructure railDDS(n);
	for (int i = 0; i < k; i++)
	{
		int p, q;
		std::cin >> p >> q;
		p--;
		q--;
		allDDS.unite(p, q);
		roadDDS.unite(p, q);
	}
	for (int i = 0; i < l; i++)
	{
		int r, s;
		std::cin >> r >> s;
		r--;
		s--;
		allDDS.unite(r, s);
		railDDS.unite(r, s);
	}
	for (int i = 0; i < n; i++)
	{
		auto s = product(roadDDS.elementsOfGroup(i), railDDS.elementsOfGroup(i));
		int ans = s.size();
		std::cout << ans;
		if (i < n - 1)
		{
			std::cout << ' ';
		}
	}
	std::cout << std::endl;
	return EXIT_SUCCESS;
}

