#include <bits/stdc++.h>
using namespace std;

struct UnionFind{
  vector<int> par;

  UnionFind(int N) : par(N){
    for(int i=0;i<N;i++) par[i] = i;
  }

  int root(int x){
    if(par[x] == x) return x;
    return par[x] = root(par[x]);
  }

  void unite(int x,int y){
    int rx = root(x);
    int ry = root(y);
    if(rx == ry) return;
    par[rx] = ry;
  }

  bool same(int x, int y){
    int rx = root(x);
    int ry = root(y);
    return rx == ry;
  }
};

int main(){
  int N,K,L;
  cin >> N >> K >> L;

  vector<int> count(N);
  for(int i=0;i<N;i++) count[i] = 1;
  UnionFind tree(N);

  for(int i=0;i<K;i++){
    int p,q;
    cin >> p >> q;
    tree.unite(p-1,q-1);
  }

  for(int i=0;i<L;i++){
    int r,s;
    cin >> r >> s;
    if(tree.same(r-1,s-1)){
      count[r-1] ++;
      count[s-1] ++;
    }
  }
  for(int i=0;i<N;i++){
    if(i) printf(" ");
    printf("%d",count[i]);
  }
  printf("\n");
  return 0;
}

