void dfs1(int v, int label)
{
	lab1[v] = label;
	for (int u : edge1[v]) {
		if (lab1[u] == -1) {
			dfs1(u, label);
		}
	}
	return;
}

void dfs2(int v)
{
	lab2[v] = 0;
	auto ite = tmp.find(lab1[v]);
	if (ite != tmp.end()) {
		ite->second = ite->second + 1;
	} else {
		tmp.insert(make_pair(lab1[v], 1));
	}
	vs.push_back(v);

	for (int u : edge2[v]) {
		if (lab2[u] == -1) {
			dfs2(u);
		}
	}
	return;
}

void solve()
{
	memset(lab1, -1, sizeof(lab1));
	memset(lab2, -1, sizeof(lab2));

	int l = 0;
	for (int i = 0; i < N; ++i) {
		if (lab1[i] == -1) {
			dfs1(i, l++);
		}
	}

	for (int i = 0; i < N; ++i) {
		if (lab2[i] == -1) {
			tmp.clear();
			vs.clear();
			dfs2(i);

			for (int v : vs) {
				lab2[v] = tmp[lab1[v]];
			}
		}
		printf("%d%c", lab2[i], i == N - 1 ? '\n' : ' ');
	}
}

