class UF {
public:
    int par[200000];
    int r[200000];
    UF (int N) {
        for (int i = 0; i < N; i++) {
            par[i] = i;
        }
    }

    int find(int x) {
        if (x == par[x]) return x;

        return par[x] = find(par[x]);
    }

    void add(int x, int y) {
        x = find(x);
        y = find(y);

        if (r[x] < r[y]) par[x] = y;
        else {
            par[y] = x;
            if (r[x] == r[y]) r[x]++;
        }
    }
};

int main() {
    int N, K, L;
    cin >> N >> K >> L;

    vector<vector<int> > md(N);
    vector<vector<int> > mt(N);

