LL N, K, L;

LL ans = 0LL;
void dfs(int v, int p, VVI& G, VI& color, int k) {
	color[v] = k;
	FOR(i, 0, SZ(G[v])) {
		int nx = G[v][i];
		if (nx != p&&color[nx]==0)dfs(nx, v, G, color, k);
	}
}

int main() {
	cin.tie(0);
	ios_base::sync_with_stdio(false);

	cin >> N >> K >> L;

	VVI Rd(N);
	FOR(i, 0, K) {
		int p, q; cin >> p >> q;
		Rd[p - 1].push_back(q - 1);
		Rd[q - 1].push_back(p - 1);
	}
	VVI Ra(N);
	FOR(i, 0, L) {
		int p, q; cin >> p >> q;
		Ra[p - 1].push_back(q - 1);
		Ra[q - 1].push_back(p - 1);
	}

	VI rdc(N, 0);
	VI rac(N, 0);
	int k = 1;

	FOR(i, 0, N) {
		if (rdc[i] == 0)dfs(i, -1, Rd, rdc, k++);
	}
	k = 1;
	FOR(i, 0, N) {
		if (rac[i] == 0)dfs(i, -1, Ra, rac, k++);
	}
	map<PII, int>Map;
	FOR(i, 0, N) {
		Map[PII(rdc[i], rac[i])] ++;
	}
	FOR(i, 0, N) {
		cout<< Map[PII(rdc[i], rac[i])]<<endl;
	}

	return 0;
}

