using namespace std;

vector<int> parentR, urankR, parentT, urankT;

int rootR(int x) { return (parentR.at(x) == x ? x: parentR.at(x) = rootR(parentR.at(x))); }

bool in_sameR(int x, int y) { return rootR(x) == rootR(y); }
void uniteR(int x, int y) {
    x = rootR(x);
    y = rootR(y);
    if (x != y) {
        if (urankR.at(x) < urankR.at(y)) parentR.at(x) = y;
        else {
            parentR.at(y) = x;
            if (urankR.at(x) == urankR.at(y)) ++(urankR.at(x));
        }
    }
}

int rootT(int x) { return (parentT.at(x) == x ? x: parentT.at(x) = rootT(parentT.at(x))); }

bool in_sameT(int x, int y) { return rootT(x) == rootT(y); }
void uniteT(int x, int y) {
    x = rootT(x);
    y = rootT(y);
    if (x != y) {
        if (urankT.at(x) < urankT.at(y)) parentT.at(x) = y;
        else {
            parentT.at(y) = x;
            if (urankT.at(x) == urankT.at(y)) ++(urankT.at(x));
        }
    }
}

int main() {
    int n, k, l, p, q;
    map< pair<int, int>, int> d;
    cin >> n >> k >> l;

    parentR.resize(n);
    urankR.resize(n);
    iota(parentR.begin(), parentR.end(), 0);
    parentT.resize(n);
    urankT.resize(n);
    iota(parentT.begin(), parentT.end(), 0);

    for (int i = 0; i < k; ++i) {
        cin >> p >> q;
        uniteR(--p, --q);
    }
    for (int i = 0; i < l; ++i) {
        cin >> p >> q;
        uniteT(--p, --q);
    }
    for (int i = 0; i < n; ++i) {
        ++d[{rootR(i), rootT(i)}];
    }
    for (int i = 0; i < n; ++i) cout << d.at({rootR(i), rootT(i)}) << endl;
    return 0;
}

