long long find(long long x, std::vector<long long>& par) {
	if (par[x] == x) return x;
	return par[x] = find(par[x],par);
}


int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	long long n, k, l;
	cin >> n >> k >> l;
	vector<long long> rpar(n);
	iota(rpar.begin(), rpar.end(), 0);
	vector<long long>rnk(n, 0);
	long long p, q;
	// 道路
	for (long long i = 0; i < k; i++) {
		cin >> p >> q;
		--p; --q;
		p = find(p,rpar);
		q = find(q,rpar);
		if (p == q) continue;
		if (rnk[p] < rnk[q]) {
			rpar[p] = q;
		}
		else {
			rpar[q] = p;
			if (rnk[p] == rnk[q]) rnk[p]++;
		}
	}
	// 線路
	vector<long long> lpar(n);
	vector<long long> ans(n, 1);
	iota(lpar.begin(), lpar.end(), 0);
	fill(rnk.begin(), rnk.end(), 0);
	for (long long i = 0; i < l; i++) {
		cin >> p >> q;
		--p; --q;
		if (find(p, rpar) != find(q, rpar))continue;
		p = find(p, lpar);
		q = find(q, lpar);
		if (p == q) continue;
		if (rnk[p] < rnk[q]) {
			lpar[p] = q;
			ans[q] += ans[p];
		}
		else {
			lpar[q] = p;
			ans[p] += ans[q];
