struct uni {
  int d[200005];
  void init(){ memset( d,-1,sizeof(d) ); }
  int find(int a){ return d[a]<0?a:(d[a]=find(d[a])); };
  bool merge(int a,int b){
    a = find(a); b = find(b);
    if( a == b ) return false;
    if( d[a] > d[b] ) swap( a, b );
    d[a] += d[b]; d[b] = a;
  }
  bool same(int a,int b){
    return find(a) == find(b);
  }
  int size(int id){ return -d[find(id)]; }
};
uni U1,U2;

int main() {
  cin >> N >> K >> L;
  U1.init(); U2.init();
  for(int i=0;i<K;i++){
    int a,b; cin >> a >> b; --a; --b;
    U1.merge( a, b );
  }
  for(int j=0;j<L;j++){
    int a,b; cin >> a >> b; --a; --b;
    if( U1.same( a, b ) ) {
      U2.merge( a,b );
    }
  }
  for(int i=0;i<N;i++)
    cout << U2.size(i) << endl;
}

