        if (conectivity[vert].first == 0) {
            conectivity[vert].first = con;
            for (const auto & x: edges[vert]) {
                DFS(x, edges, conectivity, roads, con);
            }
        }
    } else {
        if (conectivity[vert].second == 0) {
            conectivity[vert].second = con;
            for (const auto & x: edges[vert]) {
                DFS(x, edges, conectivity, roads, con);
            }
        }
    }
}


