struct disjointSetUnion {

    void init (int n) {
        for (int i = 1 ; i <= n ; i++) {
            root[i] = i ;
            cnt[i] = 1 ;
        }
    }

    int getRoot (int x) {
        if (x == root[x])
            return x ;
        return root[x] = getRoot (root[x]) ;
    }

    void uni (int x , int y) {
        x = getRoot (x) ;
        y = getRoot (y) ;
        if (x == y)
            return ;

        if (cnt[x] <= cnt[y]) {
            root[x] = y ;
            if (cnt[x] == cnt[y])
                cnt[y]++ ;
        }
        else
            root[y] = x ;
    }
};

