  cnt=0;

  REP(i,n){

    if(f[i]) continue;

    set <int> a;

    dfs(i,g2,&a,f);

    a2.pb(a);

    for(int e:a) where[e].se=cnt;
    cnt++;

  }

  vi ans(n,0);

