    if(ans[i]) continue;

    set <int> b1=a1[where[i].fi],b2=a2[where[i].se];
    vi check;

    for(int e:b1)
      if(binary_search(ALL(b2),e))
	check.pb(e);

    for(int e:check) ans[e]=check.size();

  }

  coutALL(ans);

  return 0;

}

