struct UF {
	int id[V];
	vector<int> vec[V];
	void init() {
		inc(i, V) { id[i] = i; vec[i].PB(i); }
	}
	void unite(int x, int y) {
		if(id[x] == id[y]) { return; }
		if(size(x) < size(y)) { swap(x, y); }

		int iy = id[y];
		inc(i, vec[iy].size()) {
			id[ vec[iy][i] ] = id[x];
			vec[ id[x] ].PB(vec[iy][i]);
		}
		vec[iy].clear();
	}
	int find(int x) {
		return id[x];
	}
	int size(int x) {
		return vec[ id[x] ].size();
	}
};

