  R = S = vi( L );
  for( int i = 0; i < L; ++i )
    cin >> R[ i ] >> S[ i ], --R[ i ], --S[ i ];
}

vvi G1, G2;
vvi cc1, cc2;
vi cc1_id, cc2_id;

void dfs( const vvi &g, int u, vi &cc, vi &cc_id ){
  for( int v : g[ u ] )
    if( cc_id[ v ] == -1 )
      cc_id[ v ] = cc_id[ u ],
      cc.emplace_back( v ),
      dfs( g, v, cc, cc_id );
}

void preprocess(){
  G1 = vvi( N );
  for( int i = 0; i < K; ++i )
    G1[ P[ i ] ].emplace_back( Q[ i ] ),
    G1[ Q[ i ] ].emplace_back( P[ i ] );
  G2 = vvi( N );
  for( int i = 0; i < L; ++i )
    G2[ R[ i ] ].emplace_back( S[ i ] ),
    G2[ S[ i ] ].emplace_back( R[ i ] );
  cc1_id = vi( N, -1 );
  for( int i = 0; i < N; ++i )
    if( cc1_id[ i ] == -1 )
      cc1_id[ i ] = cc1.size(),
      cc1.emplace_back( vi( 1, i ) ),
      dfs( G1, i, cc1.back(), cc1_id );
  cc2_id = vi( N, -1 );
  for( int i = 0; i < N; ++i )
    if( cc2_id[ i ] == -1 )
      cc2_id[ i ] = cc2.size(),
      cc2.emplace_back( vi( 1, i ) ),
      dfs( G2, i, cc2.back(), cc2_id );
}

void solve(){
  map< pii, int > mem;
  for( int i = 0; i < N; ++i ){
