      cout << mem[ make_pair( cc1_id[ i ], cc2_id[ i ] ) ] << " \n"[ i + 1 == N ];
    else{
      int ans = 0;
      set< int > has;
      for( int u : cc1[ cc1_id[ i ] ] )
        has.emplace( u );
      for( int v : cc2[ cc2_id[ i ] ] )
        if( has.count( v ) )
          ++ans;
      cout << ( mem[ make_pair( cc1_id[ i ], cc2_id[ i ] ) ] = ans ) << " \n"[ i + 1 == N ];
    }
  }
}

signed main(){
  ios::sync_with_stdio( 0 );
  init();
  preprocess();
  solve();
  return 0;
}

