struct UnionFind {
    vector<int> par;
    UnionFind(int n) : par(n, -1) { }
    void init(int n) { par.assign(n, -1); }

    int rt(int x) {
        if (par[x] < 0) return x;
        else return par[x] = rt(par[x]);
    }

    bool issame(int x, int y) {
        return rt(x) == rt(y);
    }

    bool unite(int x, int y) {
        x = rt(x);
        y = rt(y);
        if (x == y)  return false;

        if (par[x] > par[y]) swap(x, y);
        par[x] += par[y];
        par[y] = x;
        return true;
    }

    int size(int x) {
        return -par[rt(x)];
    }
};

int main() {
