class DSU{
public:
	int dsu[MAXN];
	void init(){
		for(int i = 0;i <= n;i++) dsu[i] = i;
	}
	int getfa(int pos){
		if( dsu[pos] == pos ) return pos;
		dsu[pos] = getfa(dsu[pos]);
		return dsu[pos];
	}
	void pa(int a,int b){
		a = getfa(a); b = getfa(b);
		dsu[a] = b;
	}
	bool same(int a,int b){
		return getfa(a) == getfa(b);
	}
};
DSU road,train;

bool cmp(int pos1,int pos2){
	return train.getfa(pos1) < train.getfa(pos2);
}

