using namespace std;

struct UnionFind {
    vector<int> v;
    vector<int> vsize;
    int n;
    UnionFind(int nin) {
        n = nin;
        for (int i = 0; i < n; ++i){
            v.push_back(i);
            vsize.push_back(1);
        }
    };

    bool Connected(int i, int j) {
        return FindRoot(i) == FindRoot(j);
    }

    // returns the root and compresses the path
    int FindRoot(int p) {
        int root = p;
        while (v[root] != root) {
            root = v[root];
        }
        while (p!=root) {
            int next = v[p];
            v[p] = root;
            p = next;
        }
        return root;
    }

    void Union(int i, int j) {
        int ir = FindRoot(i);
        int jr = FindRoot(j);
        if (ir != jr) {
            if (vsize[ir] > vsize[jr]){
                v[jr] = ir;
                vsize[ir] += vsize[jr];
            } else {
                v[ir] = jr;
                vsize[jr] += vsize[ir]; 
            }
        }
        // cerr << "Union " << i << " and " << j << endl;
        // loop(i, n) {
        //     cout << v[i] << " ";
        // }
        // cout << endl; 
    };
}; 

