    return par_l[x] == x ? x : par_l[x] = find_root_l(par_l[x]);
}

bool same_l(int x, int y) {
    return find_root_l(x) == find_root_l(y);
}

void unite_l(int x, int y) {
    x = find_root_l(x);
    y = find_root_l(y);
    if (x == y) return;

    if (sz_l[x] < sz_l[y]) swap(x, y);
    sz_l[x] += sz_l[y];
    rep(i, children_l[y].size()) children_l[x].push_back(children_l[y][i]);
    children_l[y].clear();
    par_l[y] = x;
}


