//tou分割する
template<typename T> vector<vector<T>> cut(vector<T> &a, int tou = 2) {
    int N = sz(a);
    vector<vector<T>> res(tou);
    int hab = N / tou;
    vi lens(tou, hab);
    rep(i, N % tou) { lens[tou - 1 - i]++; }
    int l = 0;
    rep(i, tou) {
        int len = lens[i];
        int r = l + len;
        res[i].resize(len);
        std::copy(a.begin() + l, a.begin() + r, res[i].begin());
        l = r;
    }
    return res;
}
//長さn毎に分割する
template<typename T> vector<vector<T>> cutn(vector<T> &a, int len) {
    int N = sz(a);
    vector<vector<T>> res(ceil(N, len));
    vi lens(N / len, len);
    if (N % len)lens.push_back(N % len);
    int l = 0;
    rep(i, sz(lens)) {
        int len = lens[i];
        int r = l + len;
        res[i].resize(len);
        std::copy(a.begin() + l, a.begin() + r, res[i].begin());
        l = r;
    }
    return res;
}


