void brail(int u, int id){
	while(!Q.empty()) Q.pop();
	srn[u] = id; Q.push(u); sr[id].push_back(u);
	while(!Q.empty()){
		u = Q.front(); Q.pop();
		for(int i = 0; i < R[u].size(); ++i){
			int v = R[u][i];
			if(!srn[v]){
				srn[v] = id;
				Q.push(v);
				sr[id].push_back(v);
			}
		}
	}
	sort(sr[id].begin(), sr[id].end());
}

