        for (int i = 1; i <= n; i++) {
                par[i] = i;
                sz[i] = 1;
                par1[i] = i;
                sz1[i] = 1;
                ans[i] = 1;
        }
}
ll find_set(ll u){
        if (u == par[u]) return u;
        return par[u] = find_set(par[u]);
}
ll find_set1(ll u){
        if (u == par1[u]) return u;
        return par1[u] = find_set1(par1[u]);
}
void dsu(ll u, ll v){
        u = find_set(u);
        v = find_set(v);
        if (u == v) return;
        if (sz[u] < sz[v]) swap(u, v);
        sz[u] += sz[v];
        par[v] = u;
}
void dsu1(ll u, ll v){
        u = find_set1(u);
        v = find_set1(v);
        if (u == v) return;
        if (sz1[u] < sz1[v]) swap(u, v);
        sz1[u] += sz1[v];
        par1[v] = u;
}
vector<ll> comproad[N], comprail[N];
void tt(ll u, ll v){
        vector<ll> mem;
        int l = 0, r = 0;
        while (l < (int)comproad[u].size() && r < (int)comprail[v].size()){
                if (comproad[u][l] == comprail[v][r]){
                        mem.push_back(comproad[u][l]);
                        l++;
                        r++;
                }
                else if (comproad[u][l] < comprail[v][r]){
                        l++;
                } else {
                        r++;
                }
        }
        for (auto j : mem){
                ans[j] = max(ans[j], (int)mem.size());
        }
}
