class UF{
public:
  vector<int> par,rank,cnt;
  vector<set<int> > U; 
  UF(){};
UF(int n){
  par.resize(N);
  rank.resize(N);
  cnt.resize(N,1);
  U.resize(N);
  for(int i=0;i<N;i++)par[i]=i,rank[i]=0,cnt[i]=0;
}

  int find(int x){
    if(par[x]==x)return x;
    return par[x]=find(par[x]);
  }

  void unite(int x,int y){
    x=find(x);
    y=find(y);
    if(x==y)return;
    if(rank[x]<rank[y])par[x]=y,cnt[y]+=cnt[x];
    else{
      par[y]=x;
      cnt[x]+=cnt[y];
      if(rank[x]==rank[y])rank[x]++;
    }
  }

  bool same(int x,int y){return find(x)==find(y);}

};

