using namespace std;

const int UFS = 100000;

struct UF {
    int data[UFS];

    UF(int n) {
        for (int i=0;i<n;++i) data[i] = -1;
    }

    int root(int i) {
        return data[i] < 0 ? i : data[i] = root(data[i]);
    }

    int size(int i) {
        i = root(i);
        return -data[i];
    }

    void unite(int x, int y) {
        x = root(x), y = root(y);
        if (x == y) return;
        if (size(x) < size(y)) swap(x, y);

        data[x] += data[y];
        data[y] = x;
    }

    bool same(int x, int y) {
        return root(x) == root(y);
    }
};

int N, K, L;

