struct Disjoint_set {
    #define MAX_N 20000
    int pa[MAX_N], Rank[MAX_N];
    int sz[MAX_N];
    void init_union_find(int V) {
        for(int i=0; i<V; i++) {
            pa[i] = i;
            Rank[i] = 0;
            sz[i] = 1;
        }
    }
    int find(int x) {
        return x == pa[x] ? x : pa[x] = find(pa[x]);
    }

    int unite(int x, int y) {
        x = find(x), y = find(y);
        int S = sz[x]+sz[y];
        if(x != y){
            if(Rank[x] < Rank[y]) {
                pa[x] = y; 
                sz[y]=S;
                return y;
            }
            else{
                pa[y] = x;
                sz[x] = S;
                if(Rank[x] == Rank[y]) Rank[x] ++;
                return x;
            }
        }
    }
    bool same(int x, int y) {
        return find(x) == find(y);
    }
};

Disjoint_set s1, s2;
int ans[200000];

int main() {
    int N, K, L; cin >> N >> K >> L;
    s1.init_union_find(N);
    s2.init_union_find(N);
    for(int i = 0; i<K; ++i) {
        int p, q; cin >> p >> q; --p, --q;
        s1.unite(p, q);
    }
    for(int i = 0; i<L; ++i) {
        int p, q; cin >> p >> q; --p, --q;
        if( !s1.same(p, q) ) continue;
        s2.unite(p, q);
    }
    for(int i = 0; i<N; ++i) ++ans[ s2.find(i) ];
    for(int i = 0; i<N; ++i)
        printf("%d%c", ans[ s2.find(i) ], " \n"[i==N-1]);
}

