  //assert(visited[pos] == false);
  visited[pos] = true;
  cities.push_back(pos);
  cnt++;
  for (const auto &val : paths[pos]){
    int next = val;
    if (not visited[next] and ut.is_same(pos, next)){
      dfs(next, cities, ut);
    }
  }

}

