int ans[200010] = {0};
int par[2][200010],ran[2][200010];
void init(int j,int n){
	for(int i=0;i<n;i++){
		par[j][i] = i;
		ran[j][i] = i;
	}
}

int find(int i, int x){
	if(par[i][x]==x){
		return x;
	}else{
		return par[i][x] = find(i,par[i][x]);
	}
}

void unite(int i,int x, int y){
	x = find(i,x);
	y = find(i,y);
	if(x==y) return;
	if(ran[i][x]<ran[i][y]){
		par[i][x] = y;
	}else{
		par[i][y] = x;
		if(ran[i][x]==ran[i][y]) ran[i][x]++;
	}
}

bool same(int i,int x, int y){
	return find(i,x)==find(i,y);
}

int main(){
    int i,j,n,k,l;
    cin >> n >> k >> l;
	init(0,n); init(1,n);
    for(i=0;i<k;i++){
        int p,q;
        cin >> p >> q;
        unite(0,p,q);
    }
    for(i=0;i<l;i++){
        int p,q;
        cin >> p >> q;
        unite(1,p,q);
    }
	for(i=1;i<=n;i++){
		mp[{find(0,i),find(1,i)}]++;
	}
    for(i=1;i<=n;i++){
        cout << mp[{find(0,i),find(1,i)}] << " ";
    }
	cout << endl;
}

