#define REPCLS(i,n) FORCLS(i,1,n)

#define NMAX (200005)
vector<int> edges[2][NMAX];
const int DORO = 0;
const int TETU = 1;
int n;
int kl[2];
vector<vector<int>> connects[2];
int tosiConnectID[2][NMAX];

void dfs(int dorT){
    vector<int>* eg = edges[dorT];
    vector<vector<int>>& con = connects[dorT];
    int* tosiID = tosiConnectID[dorT];
    bool visited[NMAX]; fill(visited, visited + n, false);
    int id = 0;
    con.resize(n);
    REP(i, n){
        if (visited[i]) continue;
        queue<int> q;
        q.push(i);
        while(!q.empty()){
            int j = q.front(); q.pop();
            if (visited[j]) continue;
            visited[j] = true;
            con[id].push_back(j);
            tosiID[j] = id;
            for(int k : eg[j]){
                if (visited[k]) continue;
                q.push(k);
            }
        }
        id++;
    }

}
void solve() {
    cin >> n >> kl[DORO] >> kl[TETU];
    REP(i, 2){
        REP(j, kl[i]){
            int a,b;
            cin >> a >> b;
            a--; b--;
            edges[i][a].push_back(b);
            edges[i][b].push_back(a);
        }
    }
    dfs(DORO);
    dfs(TETU);
    using INT = size_t;
    INT cnts[NMAX]; fill(cnts, cnts + n, -1);

    REP(i,2) for(auto& t : connects[i]){
        sort(begin(t), end(t));
    }
    REP(i, n){
        if (cnts[i] != -1) continue;
        vector<int>& a = connects[DORO][tosiConnectID[DORO][i]];
        vector<int>& b = connects[TETU][tosiConnectID[TETU][i]];
        vector<int> aAndb;
        set_intersection(begin(a), end(a), begin(b), end(b), back_inserter(aAndb));
        INT cnt = aAndb.size();
        for(int j : aAndb){
            cnts[j] = cnt;
        }
    }
    REP(i, n){
        cout << cnts[i];
        if (i == n -1) cout << endl;
        else cout << " ";
    }
}

