struct UnionFind {
  vector<int> data;
  UnionFind(int size) : data(size, -1) { }
  bool unionSet(int x, int y) {
    x = root(x); y = root(y);
    if (x != y) {
      if (data[y] < data[x]) swap(x, y);
      data[x] += data[y]; data[y] = x;
    }
    return x != y;
  }
  bool findSet(int x, int y) {
    return root(x) == root(y);
  }
  int root(int x) {
    return data[x] < 0 ? x : data[x] = root(data[x]);
  }
  int size(int x) {
    return -data[root(x)];
  }
};
int main(){
  int N, K, L;
  cin >> N >> K >> L;
  vector<int> p(K), q(K), r(L), s(L);
  REP(i,K) {
    cin >> p[i] >> q[i]; --p[i]; --q[i];
  }
  REP(i,L) {
    cin >> r[i] >> s[i]; --r[i]; --s[i];
  }

  UnionFind ufroad(N);
  REP(i,K) ufroad.unionSet(p[i], q[i]);
  UnionFind ufline(N);
  REP(i,L) if(ufroad.findSet(r[i], s[i])) {
    ufline.unionSet(r[i], s[i]);
  }
  REP(i,N) {
    if(i) cout << " ";
    cout << ufline.size(i);
  }
  cout << endl;
  return 0;
}

