#include <bits/stdc++.h>
using namespace std;
const int maxn=2e5+10;
int fa[maxn],ma[maxn];
void init(){
    for (int i=0;i<maxn;i++) fa[i]=i,ma[i]=i;//初始化并查集 
}
int fnd(int *k,int x){
    while(k[x]!=x) x=k[x];
    return x;
}
void Union(int *k,int x,int y){
    int fx=fnd(k,x),fy=fnd(k,y);
    if(fx!=fy) k[fy]=fx;//合并并查集 
}
map<pair<int,int>,int>mp;
int main(){
    int n,k,l,u,v;
    init();
    scanf("%d%d%d",&n,&k,&l);
    while(k--){
        scanf("%d%d",&u,&v);
        Union(fa,u,v);
    }
    while(l--){
        scanf("%d%d",&u,&v);
        Union(ma,u,v);
    }
    for (int i=1;i<=n;i++)  mp[make_pair(fnd(fa,i),fnd(ma,i))]++;
    for (int i=1;i<n;i++) printf("%d ",mp[make_pair(fnd(fa,i),fnd(ma,i))]);
    printf("%d\n",mp[make_pair(fnd(fa,n),fnd(ma,n))]);
    return 0;

}

#include<bits/stdc++.h>
using namespace std;
typedef pair<int, int> P;

const int MAX_N = 2e5 + 5;
int N, K, L;
vector<int> G[2][MAX_N];
int used[2][MAX_N];

void bfs(int s, int cnt, int num){
    queue<int> q;
    used[num][s] = cnt; q.push(s);

    while(q.size()){
        int u = q.front(); q.pop();
        for(auto v : G[num][u]){
            if(!used[num][v]){
                used[num][v] = cnt;
                q.push(v);
            }
        }
    }
}

int main(){
    ios::sync_with_stdio(false); cin.tie(0);
    cin >> N >> K >> L;
    for(int i=0;i<K;i++){
        int p, q; cin >> p >> q;
        G[0][p].push_back(q); G[0][q].push_back(p);
    }
    for(int i=0;i<L;i++){
        int p, q; cin >> p >> q;
        G[1][p].push_back(q); G[1][q].push_back(p);
    }

    int cnt = 1;
    for(int i=1;i<=N;i++) if(!used[0][i]) bfs(i, cnt++, 0);
    cnt = 1;
    for(int i=1;i<=N;i++) if(!used[1][i]) bfs(i, cnt++, 1);

    map<P, int> c;
    for(int i=1;i<=N;i++) c[P(used[0][i], used[1][i])]++;

    for(int i=1;i<=N;i++) cout << c[P(used[0][i], used[1][i])] << ' ';
    cout << endl;
    return 0;
}

