#include <bits/stdc++.h>

using namespace std;

struct Union_Find {
    //各要素が属する集合の代表(根)を管理する
    //もし、要素xが根であればdata[x]は負の値を取り、-data[x]はxが属する集合の大きさに等しい
    vector<int> data;

    Union_Find(int size) : data(size, -1) {}
    bool Union(int x, int y) {
        x = Find(x);
        y = Find(y);
        bool is_union = (x != y);
        if (is_union) {
            if (data[x] > data[y]) swap(x, y);
            data[x] += data[y];
            data[y] = x;
        }
        return is_union;
    }
    int Find(int x) {
        if (data[x] < 0) { //要素xが根である
            return x;
        } else {
            data[x] = Find(data[x]); //data[x]がxの属する集合の根でない場合、根になるよう更新される
            return data[x];
        }
    }
    bool same(int x, int y) {
        return Find(x) == Find(y);
    }
    int size(int x) {
        return -data[Find(x)];
    }
};

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	int N, K, L;
	cin >> N >> K >> L;
	Union_Find uf1(N), uf2(N), uf3(N);
	for (int i = 0; i < K; i++) {
		int p, q;
		cin >> p >> q;
		p--;
		q--;
		uf1.Union(p, q);
		uf3.Union(p, q);
	}
	for (int i = 0; i < L; i++) {
		int r, s;
		cin >> r >> s;
		r--;
		s--;
		if (uf3.same(r, s)) {
			if (uf1.same(r, s)) uf2.Union(r, s);
		}
		else uf3.Union(r, s);
	}
	for (int i = 0; i < N; i++) {
		cout << uf2.size(i);
		if (i != N - 1) cout << " ";
		else cout << endl;
	}
	return 0;
}

