const int UF_MAX = 400010;

struct UF{
	int x[UF_MAX];

	UF(){
		for(int i = 0 ; i < UF_MAX ; ++i) x[i] = -1;
	}

	int boss(int a){
		int s = a;
		while(x[s] > -1) s = x[s];
		if(s != a) x[a] = s;
		return s;
	}

	void uni(int a , int b){
		int s = boss(a);
		int t = boss(b);
		if(s != t){
			if(x[s] < x[t]){
				x[s] += x[t];
				x[t] = s;
			} else {
				x[t] += x[s];
				x[s] = t;
			}
		}
	}

	bool find(int a , int b){
		return boss(a) == boss(b);
	}

	int size(int a){
		return -x[boss(a)];
	}
};

UF A,B,C;
vector<int> V[200010];
int N,K,L;
