		A.uni(x,y);
	}
	repp(i,0,L){
		int x,y;
		scanf("%d%d" , &x , &y);
		B.uni(x,y);
	}
	repp(i,1,N+1){
		V[A.boss(i)].PB(i);
	}
	repp(i,1,N+1){
		if((int)V[i].size() == 0) continue;
		repv(int,it,V[i]){
			C.uni(B.boss(*it)+N,(*it));
		}
		repv(int,it,V[i]){
			ans[*it] = C.size(*it) - 1;
		}
		repv(int,it,V[i]){
			C.x[B.boss(*it)+N] = -1;
		}
	}
	repp(i,1,N+1){
		printf("%d%c" , ans[i] , i == N ? '\n' : ' ');
	}
	return 0;
}

