struct mix{
    int v;
    int Gmark;
    int Hmark;
    mix(int v, int Gmark, int Hmark): v(v), Gmark(Gmark), Hmark(Hmark) {}
    bool operator<(const mix& right)const{
        return Gmark == right.Gmark ? Hmark < right.Hmark : Gmark < right.Gmark;
    }
};

void dfsG(Graph &G, int s, int mark){
    if(checkG[s] != -1) return;
    checkG[s] = mark;
    for (int i=0;i<G[s].size();i++){
        if(checkG[G[s][i]] == -1){
            dfsG(G, G[s][i], mark);
        }
    }
}

void dfsH(Graph &G, int s, int mark){
    if(checkH[s] != -1) return;
    checkH[s] = mark;
    for (int i=0;i<G[s].size();i++){
        if(checkH[G[s][i]] == -1){
            dfsH(G, G[s][i], mark);
        }
    }
}

void Connectivity(Graph &G, Graph &H){
    int N = G.size();
    for(int i=0;i<N;i++){
        checkG[i] = -1;
        checkH[i] = -1;
    }
    for (int i=0;i<N;i++){
        dfsG(G, i, i);
    }
    for(int i=0;i<N;i++){
        dfsH(H, i, i);
    }
    vector<mix> mixes;
    for (int i=0;i<N;i++){
        mix m(i, checkG[i], checkH[i]);
        mixes.push_back(m);
    }
    sort(mixes.begin(), mixes.end());
    vector<int> count(N, 0);
    for(int i=0;i<N;i++){
        count[mixes[i].v] = upper_bound(mixes.begin(), mixes.end(), mixes[i]) - lower_bound(mixes.begin(), mixes.end(), mixes[i]);
    }
    for (int i=0;i<N;i++){
        cout << count[i] << endl;
    }
}

