void link(int x, int y, int kind) {
	if (isUnion(x, y, kind))return;
	int px, py;
	px = findp(x, kind);
	py = findp(y, kind);
	if (prank[py] < prank[px]) {
		p[kind][py] = px;
	}
	else {
		if (prank[kind][px] == prank[kind][py])prank[kind][py]++;
		p[kind][px] = py;
	}
	return;
}

