class UnionFind
{
public:
	//以下公開

	//親の番号を格納する。親である場合は-(その集合のサイズ)
	vector<ll> Parent;

	//作るときはParentの値を全て-1にする
	//こうすると全てバラバラになる
	UnionFind(ll N)
	{
		Parent = vector<ll>(N, -1);
	}

	//Aがどのグループに属しているか調べる
	ll root(ll A)
	{
		if (Parent[A] < 0)
			return A;
		return Parent[A] = root(Parent[A]);
	} //代入しておくことで参照を速くする

	//自分のいるグループの頂点数を調べる
	ll size(ll A)
	{
		return -Parent[root(A)];
	} //親である場合は-(その集合のサイズ)なので、Ａの親の

	//AとBをくっ付ける
	bool connect(ll A, ll B)
	{
		//AとBを直接つなぐのではなく、root(A)にroot(B)をくっつける
		A = root(A);
		B = root(B);
		if (A == B)
		{
			//すでにくっついてるからくっ付けない
			return false;
		}

		//大きい方(A)に小さいほう(B)をくっ付けたい
		//大小が逆だったらひっくり返しちゃう。
		if (size(A) < size(B))
			swap(A, B);

		//Aのサイズを更新する
		Parent[A] += Parent[B];
		//Bの親をAに変更する
		Parent[B] = A;

		return true;
	}

	bool same(ll A, ll B)
	{
		return root(A) == root(B);
	}
};

