    }

    map<pair<ll, ll>, ll> m;
    REP(i, n){
        m[{uni1.find(i), uni2.find(i)}]++;
    }
    REP(i, n - 1){
        cout << m[{uni1.find(i), uni2.find(i)}] << ' ';
    }
    cout << m[{uni1.find(n - 1), uni2.find(n - 1)}] << endl;
}

