struct UnionFind{
  vector<int> parent;
  UnionFind(int n){
    parent.resize(n);
    for(int i=0;i<n;++i)parent[i]=i;
  }
  int find(int x){ return parent[x]==x?x:(parent[x]=find(parent[x]));}
  void unite(int x,int y){if(find(x)!=find(y))parent[find(y)]=find(x);}
  bool issame(int x,int y){return find(x)==find(y);}
};

