  for(i=0;i<k;i++){
    cin>>p>>q;
    v[i]=P(p,q);
    G[p].push_back(q);
    G[q].push_back(p);
    u1.unite(p,q);
  }
  for(i=0;i<l;i++){
    cin>>p>>q;
    v[k+i]=P(p,q);
    u2.unite(p,q);
  }
  for(i=0;i<k+l;i++){
    p=v[i].first;q=v[i].second;
    if(u1.same(p,q)&&u2.same(p,q)) u3.unite(p,q);
  }
  bool u[n+1];
  memset(u,0,sizeof(u));
  for(i=1;i<=n;i++){
    if(u[i]) continue;
    queue<int> qu;
    qu.push(i);
    while(!qu.empty()){
      p=qu.front();qu.pop();
      if(u[p]) continue;
      u[p]=1;
      if(u1.same(i,q)&&u2.same(i,q)) u3.unite(i,q);
      for(j=0;j<G[p].size();j++) if(!u[G[p][j]]) qu.push(G[p][j]);
    }
  }
  for(i=1;i<=n;i++) printf("%d%c",u3.r[u3.find(i)]," \n"[i==n]);
  return 0;
}

