		chk[i] = ++cnt;
		dfs(i);
	}
	cnt = 0;
	for (int i = 1; i <= n; i++) {
		if (vis[i]) continue;
		vis[i] = ++cnt;
		DFS(i);
	}
	for (int i = 1; i <= n; i++) {
		val[i] = chk[i] * 1000000LL + vis[i];
		M[val[i]]++;
	}
	for (int i = 1; i <= n; i++) cout << M[val[i]] << " \n"[i == n];
	return 0;
}

