using namespace std;

const int N = 2e5 + 10;

int n, k, l, lim;
vector<int> V[N];
vector<int> P[N], Q[N];
int idp[N], idq[N];
int que[N], head, tail;
int set_p[N], set_q[N];

vector<bitset<N> > bs_p, bs_q;
bitset<N> tmp;
bool vis[N];

void bfs(int x, int id, vector<int>* G, int* idx, int* mp, vector<bitset<N> > &bs){
	head = tail = 0;
	que[tail++] = x;
	vis[x] = 1;
	idx[x] = id;
	G[id].clear();
	G[id].push_back(x);
	while(head < tail){
		x = que[head++];
		for(int i=0; i<V[x].size(); i++){
			int j = V[x][i];
            if(!vis[j]){
				vis[j] = 1;
				idx[j] = id;
				que[tail++] = j;
				G[id].push_back(j);
            }
		}
	}

    sort(G[id].begin(), G[id].end());
    if(G[id].size() >= lim){
        tmp.reset();
		for(int i=0; i<G[id].size(); i++){
			int j = G[id][i];
            tmp.set(j);
		}
        mp[id] = bs.size();
		bs.push_back(tmp);
    } else {
        mp[id] = -1;
    }
}

void init(int m, vector<int>* G, int* idx, int* mp, vector<bitset<N> > &bs){
    int x, y;
    for(int i=1; i<=n; i++){
		V[i].clear();
		vis[i] = 0;
    }
    while(m--){
		scanf("%d %d", &x, &y);
		V[x].push_back(y);
		V[y].push_back(x);
    }
    m = 0;
    bs.clear();
    for(int i=1; i<=n; i++){
		if(!vis[i]){
            bfs(i, m, G, idx, mp, bs);
			m++;
		}
    }
}

int solve(int x){
	int px = idp[x];
	int qx = idq[x];
    if(set_p[px]!=-1){
        if(set_q[qx] != -1){
            tmp = bs_p[set_p[px]] & bs_q[set_q[qx]];
            return tmp.count();
        } else {
			int z = set_p[px];
			int ret = 0;
            for(int i=0; i<Q[qx].size(); i++){
                int j = Q[qx][i];
                if(bs_p[z].test(j)){
                    ret++;
                }
            }
            return ret;
        }
    } else {
    	if(set_q[qx] != -1){
			int z = set_q[qx];
			int ret = 0;
            for(int i=0; i<P[px].size(); i++){
                int j = P[px][i];
                if(bs_q[z].test(j)){
                    ret++;
                }
            }
            return ret;
    	} else {
            int n = P[px].size(), m = Q[qx].size();
            int ret = 0;
            int i=0, j=0;
            while(i<n && j<m){
                if(P[px][i] == Q[qx][j]){
                    ret++;
                    i++;
                    j++;
                } else if(P[px][i] < Q[qx][j]){
					i++;
                } else {
					j++;
                }
            }
            return ret;
    	}
    }
}

int main(){
	while(~scanf("%d %d %d", &n, &k, &l)){
		lim = (int)sqrt(n * 1.0);

        init(k, P, idp, set_p, bs_p);
        init(l, Q, idq, set_q, bs_q);

        for(int i=1; i<=n; i++){
			printf("%d%c", solve(i), i==n?'\n':' ');
        }
	}
	return 0;
}

