            if(!t_visit[next]){
                dfs(next, false, train);
            }
        }
    }

    if(road){
        for(int i = 0; i < RL[v].size(); i++){
            int next = RL[v][i];
            if(!r_visit[next]){
                dfs(next, road, false);
