struct Graph
{
    Graph(const std::size_t v) : V{v}, edge(v), rev_edge(v) {}
    void addEdge(const std::size_t from, const std::size_t to) { edge[from].push_back(to), rev_edge[to].push_back(from); }
    const std::size_t V;
    std::vector<std::vector<std::size_t>> edge, rev_edge;
};

class SCC
{
public:
    SCC(const Graph& g) : size(g.V), comp(size, size)
    {
        for (std::size_t i = 0; i < size; i++) {
            for (const std::size_t to : g.edge[i]) { edge.push_back({i, to}); }
        }
        std::vector<std::size_t> st;
        std::vector<bool> used(size, false);
        auto dfs1 = [&](auto&& self, const std::size_t s) -> void {
            used[s] = true;
            for (const std::size_t to : g.edge[s]) {
                if (not used[to]) { self(self, to); }
            }
            st.push_back(s);
        };
        auto dfs2 = [&](auto&& self, const std::size_t s) -> void {
            comp[s] = comp_num;
            for (const std::size_t to : g.rev_edge[s]) {
                if (comp[to] != size) { continue; }
                self(self, to);
            }
        };
        for (std::size_t i = 0; i < size; i++) {
            if (used[i]) { continue; }
            dfs1(dfs1, i);
        }
        for (std::size_t i = 0; i < st.size(); i++) {
            const std::size_t s = st[st.size() - i - 1];
            if (comp[s] != size) { continue; }
            dfs2(dfs2, s), comp_num++;
        }
    }
    const std::vector<std::size_t>& getComp() const { return comp; }
    Graph toDAG() const
    {
        Graph dag(comp_num);
        for (const auto& e : edge) {
            const std::size_t u = comp[e.first], v = comp[e.second];
            if (u != v) { dag.addEdge(u, v); }
        }
        return dag;
    }

private:
    std::size_t size, comp_num = 0;
    std::vector<std::size_t> comp;
    std::vector<std::pair<std::size_t, std::size_t>> edge;
};
int main()
{
    int N, K, L;
    std::cin >> N >> K >> L;
    Graph g1(N), g2(N);
    for (int i = 0, p, q; i < K; i++) { std::cin >> p >> q, p--, q--, g1.addEdge(p, q), g1.addEdge(q, p); }
    for (int i = 0, p, q; i < L; i++) { std::cin >> p >> q, p--, q--, g2.addEdge(p, q), g2.addEdge(q, p); }
    const auto c1 = SCC(g1).getComp();
    std::vector<bool> used(N, false);
    std::vector<int> ans(N, 0);
    for (int i = 0; i < N; i++) {
        if (used[i]) { continue; }
        const int c = c1[i];
        std::queue<int> q;
        q.push(i), used[i] = true;
        std::vector<int> comp{i};
        while (not q.empty()) {
            const int s = q.front();
            q.pop();
            for (const int to : g2.edge[s]) {
                if (not used[to] and c1[to] == c) {
                    used[to] = true;
                    comp.push_back(to), q.push(to);
                }
            }
        }
        const int num = comp.size();
        for (const int e : comp) { ans[e] = num; }
    }
    for (int i = 0; i < N; i++) { std::cout << ans[i] << " "; }
    std::cout << std::endl;
    return 0;
}

