#include <vector>

const int MAXN = 2e5 + 5;

int N, M1, M2;
Pii E1[MAXN], E2[MAXN];
int fa1[MAXN], fa2[MAXN];

int getFather(int *fa, int u)
{
    return fa[u] == u ? u : fa[u] = getFather(fa, fa[u]);
}

std::vector<Pii> set[MAXN];

void input()
{
    read(N); read(M1); read(M2);
    for (int i = 1; i <= M1; ++i) {
        read(E1[i].x); read(E1[i].y);
    }
    for (int i = 1; i <= M2; ++i) {
        read(E2[i].x); read(E2[i].y);
    }
}

void solve()
{
    for (int i = 1; i <= N; ++i) {
        fa1[i] = fa2[i] = i;
    }
    for (int i = 1; i <= M1; ++i) {
        int u = E1[i].x, v = E1[i].y;
        int fu = getFather(fa1, u), fv = getFather(fa1, v);
        if (fu != fv)
            fa1[fu] = fv;
    }
    for (int i = 1; i <= M2; ++i) {
        int u = E2[i].x, v = E2[i].y;
        // printf("(%d, %d)\n", u, v);
        int fu = getFather(fa2, u), fv = getFather(fa2, v);
        if (fu != fv)
            fa2[fu] = fv;
    }

    for (int i = 1; i <= N; ++i) {
        // printf("%d:, fa1 = %d, fa2 = %d\n", i, getFather(fa1, i), getFather(fa2, i));
        set[getFather(fa1, i)].push_back(MP(getFather(fa2, i), i));
    }

    static int ans[MAXN];

    for (int i = 1; i <= N; ++i) {
        if (fa1[i] == i) {
            std::sort(set[i].begin(), set[i].end());
            int last = 0;
            for (int j = 0; j < set[i].size(); ++j) {
                if (set[i][j].x != set[i][last].x) {
                    for (int k = last; k < j; ++k) {
                        ans[set[i][k].y] = j - last;
                    }
                    last = j;
                }
            }
            for (int k = last; k < set[i].size(); ++k) {
                ans[set[i][k].y] = set[i].size() - last;
            }
        }
    }

    for (int i = 1; i <= N; ++i) {
        write(ans[i]); putchar(' ');
    }
    putchar('\n');
}

int main()
{
#ifdef __DEBUG
    freopen("D.in", "r", stdin);
    freopen("D.out", "w", stdout);
#endif

    input();
    solve();

    return 0;
}

