using namespace std;

template <typename T>
struct UnionFind {
  vector<int> par, rank;
  vector<T> wSum;

  UnionFind(int n = 1, T init = 0) : par(n), rank(n, 0), wSum(n, init) {
    iota(begin(par), end(par), 0);
  }
  int root(int x) {
    if (par[x] == x) {
      return x;
    } else {
      int r = root(par[x]);
      wSum[x] += wSum[par[x]];
      return par[x] = r;
    }
  }
  T weight(int x) {
    root(x);
    return wSum[x];
  }
  bool isSame(int x, int y) { return root(x) == root(y); }
  void unite(int x, int y, T w = 0) {
    w += weight(x) - weight(y);
    x = root(x);
    y = root(y);
    if (x == y) return;

    if (rank[x] < rank[y]) swap(x, y), w = negate<T>()(w);
    rank[x] += rank[y];
    par[y] = x;
    wSum[y] = w;
  }
  T getDiff(int x, int y) { return weight(y) - weight(x); }
};

int main() {
  int n, k, l;
  cin >> n >> k >> l;
  UnionFind<int> ufk(n), ufl(n);
  for (int i = 0; i < k; i++) {
    int p, q;
    cin >> p >> q, p--, q--;
    ufk.unite(p, q);
  }
  for (int i = 0; i < l; i++) {
    int r, s;
    cin >> r >> s, r--, s--;
    ufl.unite(r, s);
  }
  map<int, set<int>> mpk, mpl;
  for (int i = 0; i < n; i++) {
    mpk[ufk.root(i)].insert(i);
    mpl[ufl.root(i)].insert(i);
  }
  for (int i = 0; i < n; i++) {
    if (i > 0) cout << " ";
    auto a = mpk[ufk.root(i)];
    auto b = mpl[ufl.root(i)];
    vector<int> res;
    set_intersection(begin(a), end(a), begin(b), end(b), back_inserter(res));
    cout << res.size();
  }
  cout << endl;
}

