long root(long x,long *uf){
    //cout << "x : " << x <<  "  uf : " << uf[x] << "\n";
    if(uf[x]==x){
        return x;
    }
    else{
        return uf[x] = root(uf[x],uf);
    }
}

void ufmerge(long x,long y,long *uf,long *rank_uf){
    x=root(x,uf);
    y=root(y,uf);
    if(x==y){
        return;
    }
    else{
        if(rank_uf[x]<rank_uf[y]){
            uf[x]=y;
        }
        else{
            uf[y]=x;
            if(rank_uf[x]==rank_uf[y]) rank_uf[x]++;
        }
    }
}

