struct UnionFind{
	vector<int> data;

	UnionFind(int sz){
		data.assign(sz, -1);
	}

	bool unite(int x, int y){
		x = find(x); y = find(y);
		if(x == y) return false;
		if(data[x] > data[y]) swap(x, y);
		data[x] += data[y];
		data[y] = x;
		return true;
	}

	int find(int k){
		if(data[k] < 0) return k;
		else return data[k] = find(data[k]);
	}

	bool same(int x, int y){
		if(find(x) == find(y)) return true;
		else return false;
	}

	int size(int k){
		return -data[find(k)];
	}
};

