class UnionFind{

	int par[_K];
	int siz[_K];

public:
	void init(int n){
		for(int i=0; i<n; i++) par[i]=i;
		for(int i=0; i<n; i++) siz[i]=1;
	}
	int find(int x){
		if(par[x]==x){
			return x;
		}else{
			return par[x]=find(par[x]);
		}
	}
	bool same(int x, int y){
		return find(x)==find(y);
	}
	void uni(int x, int y){
		x=find(x);
		y=find(y);
		if(x==y) return;
		if(siz[x]<siz[y]) swap(x, y);
		par[y]=x;
		siz[x]+=siz[y];
	}
	int size(int x){
		return siz[find(x)];
	}
};

