template<int um> struct UF {
	vector<int> d; vector<pair<int, int>> history;
	UF() { d = vector<int>(um); clear(); }
	void clear() { rep(i, 0, um) d[i] = i; history.clear(); }
	int operator[](int x) { return d[x] == x ? x : d[x] = operator[](d[x]); }
	void operator()(int x, int y) {
		x = operator[](x); y = operator[](y); if (x == y) return;
		if (d[x] > d[y]) swap(x, y);
		if (d[x] == d[y]) history.push_back(make_pair(x, d[x])), d[x]--;
		history.push_back(make_pair(y, d[y]));
		d[y] = x;
	}
	void snapshot() { history.clear(); }
	void rollback() { while (history.size()) { d[history.back().first] = history.back().second; history.pop_back(); }}
};
