//Union-Find
class UnionFind {
private:
	std::vector<int> parent;
	std::vector<int> height;

public:
	UnionFind(int size) : parent(size), height(size, 0) {
		REP(i, size) {
			parent[i] = i;
		}
	}
	void init(int size) {
		parent.resize(size);
		height.resize(size, 0);
		REP(i, size) {
			parent[i] = i;
		}
	}
	int find(int x) {
		if (parent[x] == x) {
			return x;
		}
		return parent[x] = find(parent[x]);
	}
	void unite(int x, int y) {
		x = find(x);
		y = find(y);
		if (x == y) return;
		if (height[x] < height[y]) parent[x] = y;
		else parent[y] = x;
		if (height[x] == height[y]) ++height[x];
	}
	bool same(int x, int y) {
		return find(x) == find(y);
	}
};

