class DisjointSet {
public:
  V<ll> rank, p;
  DisjointSet() {};
  DisjointSet(ll size) {
    rank.resize(size, 0);
    p.resize(size, 0);
    REP(i, size) makeSet(i);
  }

  void makeSet(ll x) {
    p[x] = x;
    rank[x] = 0;
  }

  bool same(ll x, ll y) {
    return findSet(x) == findSet(y);
  }

  void unite(ll x, ll y) {
    link(findSet(x), findSet(y));
  }

  void link(ll x, ll y) {
    if (rank[x] > rank[y]) {
      p[y] = x;
    } else {
      p[x] = y;
      if (rank[x] == rank[y]) rank[y]++;
    }
  }

  ll findSet(ll x) {
    if (x != p[x]) p[x] = findSet(p[x]);
    return p[x];
  }
};

