class union_find
{
private:
	std::vector<int>parent;
	std::vector<int>rank;
public:
	union_find(int siz)
	{
		parent.resize(siz);
		rank.resize(siz);
		for (int i = 0; i < siz; ++i)
		{
			parent[i] = i;
			rank[i] = 0;
		}
	}
	void unite(int x, int y)
	{
		int xr = find(x);
		int yr = find(y);
		if (xr == yr)return;
		if (rank[xr] < rank[yr])
		{
			parent[xr] = yr;
		}
		else
		{
			parent[yr] = xr;
			if (rank[xr] == rank[yr])rank[xr]++;
		}
	}
	int find(int x)
	{
		if (parent[x] == x)
		{
			return x;
		}
		else
		{
			return parent[x] = find(parent[x]);
		}
	}
	bool check(int x, int y)
	{
		return find(x) == find(y);
	}
};


#include <unordered_set>
#include <unordered_map>

union_find *road, *rail;

int n, k, l;
int dict[234567];

int par[234567];
void transfer(int dex)
{
	if (par[dex] >= 0)return;
	for (int i = 0; i < n; ++i)
	{
		if (road->check(dex, i) && rail->check(dex, i))
		{
			par[i] = dex;
		}
	}
}

int main(void)
{
	scanf("%d %d %d", &n, &k, &l);
	auto a = union_find(n);
	auto b = union_find(n);
	road = &a;
	rail = &b;
	for (int i = 0; i < k; ++i)
	{
		int p, q;
		scanf("%d %d", &p, &q);
		road->unite(p - 1, q - 1);
	}
	for (int j = 0; j < l; ++j)
	{
		int r, s;
		scanf("%d %d", &r, &s);
		rail->unite(r - 1, s - 1);
	}
	fill(par, par + n, -1);
	fill(dict, dict + n, 0);
	for (int a = 0; a < n; ++a)
	{
		transfer(a);
		++dict[par[a]];
	}
	for (int a = 0; a < n; ++a)
	{
		printf("%d", dict[par[a]]);
		if (a != n - 1)printf(" ");
	}
	printf("\n");
	return 0;
}

