struct uni {
  int d[200005];
  void init(){ memset( d,-1,sizeof(d) ); }
  int find(int a){ return d[a]<0?a:(d[a]=find(d[a])); };
  bool merge(int a,int b){
    a = find(a); b = find(b);
    if( a == b ) return false;
    if( d[a] > d[b] ) swap( a, b );
    d[a] += d[b]; d[b] = a;
  }
  bool same(int a,int b){
    return find(a) == find(b);
  }
  int size(int id){ return -d[find(id)]; }
};
uni U1,U2,U;

int main() {
  cin >> N >> K >> L;
  U.init(); U1.init(); U2.init();
  vector<int> A,B;
  for(int i=0;i<K;i++){
    int a,b; cin >> a >> b; --a; --b;
    A.push_back( a ); B.push_back( b );
    U1.merge( a, b );
  }
  for(int j=0;j<L;j++){
    int a,b; cin >> a >> b; --a; --b;
    A.push_back( a ); B.push_back( b );
    U2.merge( a,b );    
  }

  for(int i=0;i<K+L;i++){
    int a = A[i], b = B[i];
    if( U1.same( a, b ) && U2.same( a, b ) ) U.merge( a, b );
  }

  for(int i=0;i<N;i++)
    cout << U.size(i) << endl;
}

