const int MAX = 212345;

int vis[MAX];
vector<int> con[MAX][2];
vector<int> edge[MAX][2];
int ids[MAX][2];

int etot;

void dfs(int u, int type) {
    vis[u] = true;
    con[etot][type].push_back(u);
    ids[u][type] = etot;
    for (auto v : edge[u][type]) {
        if (vis[v]) continue;
        dfs(v, type);
    }
}

int ans[MAX];
int ok[MAX];
int tans[MAX];

int main() {
    int n, k, l, u, v;
    scanf("%d %d %d", &n, &k, &l);
    for (int i = 0; i < k; i++) {
        scanf("%d %d", &u, &v);
        edge[u][0].push_back(v);
        edge[v][0].push_back(u);
    }
    for (int i = 0; i < l; i++) {
        scanf("%d %d", &u, &v);
        edge[u][1].push_back(v);
        edge[v][1].push_back(u);
    }
    memset(vis, 0, sizeof(vis));
    etot = 0;
    for (int i = 1; i <= n; i++) {
        if (vis[i]) continue;
        etot++;
        dfs(i, 0);
    }
    int scc1 = etot;
    memset(vis, 0, sizeof(vis));
    etot = 0;
    for (int i = 1; i <= n; i++) {
        if (vis[i]) continue;
        etot++;
        dfs(i, 1);
    }
    int scc2 = etot;
    int pro1, pro2;
    if (scc1 <= scc2) {
        pro1 = 0, pro2 = 1;
    } else {
        pro1 = 1, pro2 = 0;
    }
    memset(vis, 0, sizeof(vis));
    for (int i = 1; i <= n; i++) {
        for (auto x : con[i][pro1]) {
            vis[x] = i;
        }
        for (auto x : con[i][pro1]) {
            if (ok[ids[x][pro2]] != i) {
                tans[ids[x][pro2]] = 0;
                for (auto y : con[ids[x][pro2]][pro2]) {
                    if (vis[y] == i) tans[ids[x][pro2]]++;
                }
                ok[ids[x][pro2]] = i;
            }
            ans[x] = tans[ids[x][pro2]];
        }
    }
    for (int i = 1; i <= n; i++) {
        printf("%d%c", ans[i], i == n ? '\n' : ' ');
    }
}

