{
	if(par[x]==x)return x;else return par[x]=root(par[x]);
}
void un(int x,int y)
{
	x=root(x);y=root(y);
	if(x==y)return;
	if(rk[x]<rk[y])
	{
		par[x]=y;
		s[y]+=s[x];
	}
	else
	{
		if(rk[x]==rk[y])rk[x]++;
		par[y]=x;
		s[x]+=s[y];
	}
}
