ll GCD(ll x, ll y)
{
    if (y == 0)
    {
        return x;
    }
    else
    {
        return GCD(y, x % y);
    }
}
ll LCM(ll x, ll y)
{
    return x / GCD(x, y) * y;
}
struct UnionFind
{
    vector<int> par; // par[i]:iの親の番号　(例) par[3] = 2 : 3の親が2

    UnionFind(int N) : par(N)
    { //最初は全てが根であるとして初期化
        for (int i = 0; i < N; i++)
            par[i] = i;
    }

    int root(int x)
    { // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
        if (par[x] == x)
            return x;
        return par[x] = root(par[x]);
    }

    void unite(int x, int y)
    {                     // xとyの木を併合
        int rx = root(x); //xの根をrx
        int ry = root(y); //yの根をry
        if (rx == ry)
            return;   //xとyの根が同じ(=同じ木にある)時はそのまま
        par[rx] = ry; //xとyの根が同じでない(=同じ木にない)時：xの根rxをyの根ryにつける
    }

    bool same(int x, int y)
    { // 2つのデータx, yが属する木が同じならtrueを返す
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }
};
//使い方　インスタンス化(頂点数)　uniteつなぐ(双方向注意) same判定
int main()
{
    int n, k, l;
    cin >> n >> k >> l;
    UnionFind tree(n);
    for (int i = 0; i < k;i++){
        int p, q;
        cin >> p >> q;
        p--;q--;
        tree.unite(p, q);
        tree.unite(q, p);
    }
    UnionFind tree1(n);
    for (int i = 0; i < l;i++){
        int r, s;
        cin >> r >> s;
        r--;s--;
        tree1.unite(r, s);
        tree1.unite(s, r);
    }
    for (int i = 0;i<n;i++){
        int c = 0;
        for (int j = 0; j < n;j++){
            if(tree.same(i,j)&&tree1.same(i,j)){
                c++;
            }
        }
        cout << c <<" ";
    }
    cout<<endl;
}

