using ll = long long;

const int N = 2 * 1e5 + 10;
const int K = 1e5 + 10;
const int L = 1e5 + 10;

vector<int> road[K];
vector<int> rail[L];
vector<int> matrix_road[N];
vector<int> matrix_rail[N];
vector<int> visited[N];

int result[N];

static int netcount = 0;
static int notstart = 0;

void initialize_road(int n, int k){
  int p,q;
  netcount = 0;
  notstart = 0;
  for(int i = 0; i < n; i++){
    for(int j = 0; j < n; j++){
      matrix_road[i].push_back(0);
    }
  }

  for(int i = 0; i < k; i++){
    cin >> p >> q;
    --p;
    --q;
    //cout << p << q << endl;
    road[p].emplace_back(q);
    road[q].emplace_back(p);
  }
}

void initialize_rail(int n, int l){
  int r,s;
  netcount = 0;
  notstart = 0;
  for(int i = 0; i < n ; i++){
    for(int j = 0; j < n; j++){
      matrix_rail[i].push_back(0);
    }
  }
  for(int i = 0; i < l ; i++){
    cin >> r >> s;
    --r;
    --s;
    rail[r].emplace_back(s);
    rail[s].emplace_back(r);
  }
}

int judge_in_net(int city){
  for(auto &elem : visited[netcount]){
    if(elem == city) return 1;
  }
  return 0;
}

int judge_bet_net(int net, int city){
  for(auto &elem : visited[net]){
    //cout << "elem : " <<elem << endl;
    if(elem == city) return 1;
  }
  return 0;
}

int not_searched_city(int n){
  int flag;
  int city = notstart;
  //cout << "notstart" << notstart << endl;
  while(city < n){
    flag = 0;
    for(int net = 0; net < netcount ; net++){
      if(judge_bet_net(net, city) == 1){
        flag = 1;
        break;
      }
    }

    if(flag == 0){
      notstart = city + 1;
      return city;
    }
    city++;
  }

  return -1;
}

//networkができている

void dfs_road(int prev, int now,int n){
  cout << "now : " << now << endl;
  if(judge_in_net(now) == 0) visited[netcount].emplace_back(now);
  //cout << "size" << road[now].size() << endl;
  for(auto &next : road[now]){
    if(prev == next) continue;
    //cout << "OK";
    dfs_road(now, next,n);
  }
}

void dfs_rail(int prev, int now,int n){
  //cout << "now : " << now << endl;
  if(judge_in_net(now) == 0) visited[netcount].emplace_back(now);
  cout << "size" << road[now].size();
  for(auto &next : rail[now]){
    if(prev == next) continue;
    //cout << "OK";
    dfs_rail(now, next,n);
  }
}

void solver_road(int n){
  while(1){
    int start = not_searched_city(n);
    if(start < 0) return;
    //cout << "start : " << start;
    dfs_road(-1,start,n);
    ++netcount;
  }
}

void solver_rail(int n){
  while(1){
    int start = not_searched_city(n);
    if(start < 0) return;
    dfs_rail(-1,start,n);
    ++netcount;
  }
}


int main(){
  int n, k, l;

  cin >> n >> k >> l;

  initialize_road(n,k);

  solver_road(n);
  for(int net = 0; net <= netcount; net++){
    for(int i = 0; i < visited[net].size(); i++){
      for(int j = i; j < visited[net].size(); j++){
        matrix_road[visited[net][i]][visited[net][j]] = 1;
        matrix_road[visited[net][j]][visited[net][i]] = 1;
      }
    }
  }

  initialize_rail(n,l);

  for(int i = 0; i < N; i++){
    visited[i].clear();
  }

  solver_rail(n);
  for(int net = 0; net <= netcount; net++){
    for(int i = 0; i < visited[net].size(); i++){
      for(int j = i; j < visited[net].size(); j++){
        matrix_rail[visited[net][i]][visited[net][j]] = 1;
        matrix_rail[visited[net][j]][visited[net][i]] = 1;
      }
    }
  }

  for(int i = 0; i < n; i++){
    for(int j = 0; j < n; j++){
      if(matrix_rail[i][j] == 1 && matrix_road[i][j] == 1) result[i]++;
    }
  }

  for(int i = 0; i < n; i++){
    cout << result[i] << " ";
  }

  return 0;


}

