// Union-Find 木 (Verified: AtCoder Typical Contest 001 B)
struct UnionFind {
private:
    int n;
    int __size;
    int uf[200010][3];
public:
    // 初期化 UnionFind uni(n) のように宣言すれば良い
    void init(int _n) {
        n = _n;
        __size = _n;
        rep(i,0,_n) rep(k,0,3) uf[i][k] = -1;
    }
    // find (木の根を求める)
    int find(int x, int k) {return (uf[x][k] < 0) ? x : uf[x][k] = find(uf[x][k], k);}
        // x が属する集合の要素数
    int size(int x) {return -uf[find(x, 2)][2];}
    // x と y の属する集合を併合
    bool unite(int x, int y, int k) {
        if(k != 2) {
            x = find(x, k); y = find(y, k);
            if(x == y) return false;
            __size--;
            if(uf[y][k] < uf[x][k]) swap(x, y);
            uf[x][k] += uf[y][k]; uf[y][k] = x;
            return true;
        }
        else {
            int x1 = find(x, 0), y1 = find(y, 0);
            int x2 = find(x, 1), y2 = find(y, 1);
            if(x1 == y1 && x2 == y2) {
                int tx = find(x, 2), ty = find(y, 2);
                if(tx == ty) return false;
                __size--;
                if(uf[ty][2] < uf[tx][2]) swap(tx, ty);
                uf[tx][2] += uf[ty][2]; uf[ty][2] = tx;
                return true;
            }
        }
        return false;
    }
};

int main() {
    int n, k, l; cin >> n >> k >> l;
    UnionFind uf;
    uf.init(n);
    int p, q;
    rep(i,0,k) {
        cin >> p >> q; p--; q--;
        uf.unite(p, q, 0);
    }
    rep(i,0,l) {
        cin >> p >> q; p--; q--;
        if(uf.unite(p, q, 1)) uf.unite(p, q, 2);
    }
    rep(i,0,n) {
        if(i != 0) printf(" ");
        printf("%d", uf.size(i));
    }
    cout << endl;
    return 0;
}

