        this->rank.resize(N);
        this->parent.resize(N);
        this->size.resize(N);
        for (int i = 0; i < N; ++i) {
            this->rank[i] = 1;
            this->parent[i] = i;
            this->size[i] = 1;
        }
    }
    int find(int a){
        if (this->parent[a] == a) {
            return a;
