void doshit(int x[2], bool f) {
	int n[2] = {(int)comp[0][x[0]].size(), (int)comp[1][x[1]].size()}, l = 0, res = 0;
	vector<int> vec;
	for (int i = 0; i + 1 < n[f]; i++) {
		while (comp[!f][x[!f]][l] < comp[f][x[f]][i])
			l++;
		if (comp[!f][x[!f]][l] == comp[f][x[f]][i]) 
			vec.push_back(comp[f][x[f]][i]), res++;
	}
	for (auto it: vec)
		ans[it] += res - 1;
}	

void dfs(int root, bool tp) {
	vis[tp][root] = true;
	col[tp][root] = cnt[tp];
	comp[tp][cnt[tp]].push_back(root);
	for (auto u: adj[tp][root])
		if (!vis[tp][u])
			dfs(u, tp);
}

