	}
}

int find(int x, vector<int> &par) {
	if (par[x] == x) {
		return x;
	}
	else {
		return par[x] = find(par[x], par);
	}
}

void unite(int x, int y, vector<int> &par, vector<int> &rank) {
	x = find(x, par);
	y = find(y, par);
	if (x == y) return;

	if (rank[x] < rank[y]) {
		par[x] = y;
	}
	else {
		par[y] = x;
		if (rank[x] == rank[y])rank[x]++;
	}
}

bool same(int x, int y, vector<int> &par) {
	return find(x, par) == find(y, par);
}

