class UnionFind {
public:
//以下公開

	//親の番号を格納する。親である場合は-(その集合のサイズ)
	vector<int> Parent;

	//作るときはParentの値を全て-1にする
	//こうすると全てバラバラになる
	UnionFind(int N) {
		Parent = vector<int>(N, -1);
	}

	//Aがどのグループに属しているか調べる
	int root(int A) {
		if (Parent[A] < 0) return A;
		return Parent[A] = root(Parent[A]);
	}//代入しておくことで参照を速くする

	//自分のいるグループの頂点数を調べる
	int size(int A) {
		return -Parent[root(A)];
	}//親である場合は-(その集合のサイズ)なので、Ａの親の

	//AとBをくっ付ける
	bool connect(int A, int B) {
		//AとBを直接つなぐのではなく、root(A)にroot(B)をくっつける
		A = root(A);
		B = root(B);
		if (A == B) {
			//すでにくっついてるからくっ付けない
			return false;
		}

		//大きい方(A)に小さいほう(B)をくっ付けたい
		//大小が逆だったらひっくり返しちゃう。
		if (size(A) < size(B)) swap(A, B);

		//Aのサイズを更新する
		Parent[A] += Parent[B];
		//Bの親をAに変更する
		Parent[B] = A;

		return true;
	}

    bool same(int A,int B){
        return root(A)==root(B);
    }
};

signed main(){
  ll n,k,l;cin>>n>>k>>l;
  vector<int> ans(n+1,0);
  UnionFind UnionFind(n) ;

  rep(i,k){
    int p,q;cin>>p>>q;
    UnionFind.connect(p,q);
  }

  rep(i,l){
    int r,s;cin>>r>>s;
    if(UnionFind.same(r,s)){
      int R=ans.at(r),S=ans.at(s);
      ans.at(s)+=R+1;
      ans.at(r)+=S+1;
    }

  }

  for(int i=0;i < n;i++)
  {
    cout<<ans.at(i+1)+1<<(i+2<siz(ans) ? ' '  : '\n');
  }
}

