		UNION(p,q);
	}
	while(c--){
		int p,q;scanf("%d%d",&p,&q);p--;q--;
		if(FIND(p)!=FIND(q))continue;
		UNION(p+a,q+a);
	}
	for(int i=0;i<a;i++){
		if(i)printf(" ");
		printf("%d",-UF[FIND(a+i)]);
	}
	printf("\n");
}

