template<typename T>
class UF
{
public:
	UF() {
		size = 0;
	}

	//値を挿入する
	void push( T a ) {
		M[a] = size;
		V.push_back( size );
		rank.push_back( 0 );
		C.push_back( 1 );
		size++;
	}

	//同じグループにする
	void unite( T a, T b ) {
		long long int x = find( M[a] );
		long long int y = find( M[b] );
		if( x == y )return;
		if( rank[x] < rank[y] ) {
			V[x] = y;
			C[y] += C[x];
		} else {
			V[y] = x;
			C[x] += C[y];
			if( rank[x] == rank[y] )rank[x]++;
		}
	}

	void merge( T a, T b ) {
		unite( a, b );
	}

	//同じグループにいるかどうか判定する
	bool same( T a, T b ) {
		return find( M[a] ) == find( M[b] );
	}

	//今何グループあるか数を返す
	long long int group() {
		set<long long int >S;
		for( long long int i = 0; i < V.size(); i++ ) {
			S.insert( find( V[i] ) );
		}
		return S.size();
	}

	//グループに属している数を返す
	long long int count( T a ) {
		return C[find( M[a] )];
	}


	//今属しているグループのIDを返す
	long long int groupID( T a ) {
		return find( M[a] );
	}
private:
	vector<long long int>
		C, V, rank;
	map < T, long long int>M;
	long long int size;

	//祖先までたどる
	long long int find( long long int x ) {
		if( V[x] == x )return x;
		else return V[x] = find( V[x] );
	}
};

int main() {
	long long int N, K, L;
	cin >> N >> K >> L;
	UF<long long int>uf1, uf2;
	for( size_t i = 0; i < N; i++ ) {
		uf1.push( i );
		uf2.push( i );
	}
	for( size_t i = 0; i < K; i++ ) {
		long long int p, q;
		cin >> p >> q;
		p--; q--;
		uf1.merge( p, q );
	}
	for( size_t i = 0; i < L; i++ ) {
		long long int r, s;
		cin >> r >> s;
		r--; s--;
		uf2.merge( r, s );
	}
	map<long long int, map<long long int, long long int>>ansmap;
	for( size_t i = 0; i < N; i++ ) {
		ansmap[uf1.groupID( i )][uf2.groupID(i)]++;
	}
	for( size_t i = 0; i < N; i++ ) {
		cout << ansmap[uf1.groupID( i )][uf2.groupID( i )] << (i == N - 1 ? "\n" : " ");
	}
}

