int dfs(int now, int prev) {
    if (cnt[now] != -1) return cnt[now];
    int res = 0;
    int cc = 0;
    FORE(e, graph2[now]) {
        if (!uf.same(now, e)) continue;
        if (e == prev) {
            cc++;
            continue;
        }
        res += dfs(e, now);
    }
    return cnt[now] = res + cc;
}

