const int N = 2e5+5;

int up[N];

int Find(int x) {
	if (up[x] < 0) {
		return x;
	}
	int root = Find(up[x]);
	up[x] = root;
	return root;
}

void Union(int x, int y) {
	if (x == y) {
		return;
	}
	if (up[x] < up[y]) {
		up[x] += up[y];
		up[y] = x;
	}
	else {
		up[y] += up[x];
		up[x] = y;
	}
}

