using namespace std;
typedef pair<int, int>P;

class UnionFind {
	vector<int>par, high;
public:
	vector<int>size;
	UnionFind(int n) {
		par = high = vector<int>(n);
		size = vector<int>(n, 1);
		for (int i = 0; i < n; i++)par[i] = i;
	}
	int find(int x) {
		if (par[x] == x)return x;
		return par[x] = find(par[x]);
	}
	void unite(int x, int y) {
		x = find(x); y = find(y);
		if (x == y)return;
		if (high[x] > high[y]) {
			par[y] = x;
			size[x] += size[y];
		}
		else {
			par[x] = y;
			size[y] += size[x];
			if (high[x] == high[y])high[y]++;
		}
	}
	bool same(int x, int y) {
		return find(x) == find(y);
	}
};
