const ll INF = static_cast<ll>(1e9) + 7ll;
const ll LINF = INF * INF;
const int MAXN = static_cast<int>(1e6) + 17;

int n, m1, m2, us;
vector<int> g[MAXN];
int U[MAXN], res[MAXN];

bool read() {
    if (!(cin >> n >> m1 >> m2))
        return false;

    return true;
}

int dfs(int v) {
    U[v] = us;
    int res = 1;

    for (auto to : g[v])
        if (U[to] != us)
            res += dfs(to);

    return res;
}

void solve() {
    while (m1 --> 0) {
        int u, v;
        cin >> u >> v;
        g[u].pb(v);
        g[v].pb(u);
    }

    for (int v = 1; v <= n; ++v, ++us)
        if (U[v] != us)
            dfs(v);

    for (int v = 1; v <= n; ++v)
        g[v].clear();

    while (m2 --> 0) {
        int u, v;
        cin >> u >> v;

        if (U[u] == U[v]) {
            g[u].pb(v);
            g[v].pb(u);
        }
    }

    fill(U, U + n, 0);
    us = 1;

    for (int v = 1; v <= n; ++v, ++us)
        if (U[v] != us)
            res[us] = dfs(v);

    for (int i = 1; i <= n; ++i)
        cout << res[U[i]] << ' ';

    cout << endl;
}

int main() {
    cin.tie(nullptr);
    std::ios_base::sync_with_stdio(false);

    while (read())
        solve();

    return 0;
}

