	int p1 = getparent1(par1[x]);
	return par1[x]=p1;
}
int getparent2(int x)
{
	if(par2[x]==x)
		return x;
	int p2 = getparent2(par2[x]);
	return par2[x]=p2;
}
inline void unite1(int p1, int p2)
{
	if(p1==p2)
		return;
	if(comp1[p1]<comp1[p2])
		unite1(p2,p1);
	else
	{
		comp1[p1]+=comp1[p2];
		par1[p2] = p1;
	}
}
inline void unite2(int p1, int p2)
{
	if(p1==p2)
		return;
	if(comp2[p1]<comp2[p2])
		unite2(p2,p1);
	else
	{
		comp2[p1]+=comp2[p2];
		par2[p2] = p1;
	}
}
