struct UnionFind
{
	//number of parents(par[i] = i => root)
	vector <int> par;
	//rank of tree
	vector <int> rank;

	UnionFind(int n) : par(n), rank(n, 1) {
		//initialize
		rep(n, i) par[i] = i;
	}

	//find root (keiroasshuku at the same time)
	int root(int x){
		if (par[x] == x) return x;
		else return par[x] = root(par[x]);
	}

	//unite
	void unite(int x, int y){
		x = root(x);
		y = root(y);
		if (x == y) return;
		if (rank[x] > rank[y]) swap(x, y);
		par[x] = y;
		rank[y] += rank[x];
	}

	//same tree?
	bool same(int x, int y){
		return root(x) == root(y);
	}
};


void solve(void)
{
	int N, K, L;
	cin >> N >> K >> L;

	UnionFind uf1(N), uf2(N);

	while(K--)
	{
		int u, v;
		cin >> u >> v;
		uf1.unite(u-1, v-1);
	}

	while(L--)
	{
		int u, v;
