		uf2.unite(u-1, v-1);
	}

	map<intP, int> mp;

	rep(N, i)
	{
		mp[intP(uf1.root(i), uf2.root(i))]++;
	}

	rep(N, i)
	{
		cout << mp[intP(uf1.root(i), uf2.root(i))] << (i == N-1 ? '\n' : ' ');
	}


}

