void DFS(int s){
	if (check[s]) return;
	q.push_back(s);
	int f = uf.find(s);
	cnt[f]++;
	re[s] = f;
	check[s] = true;
	for (int to : G[s]) {
		if(not check[to]) DFS(to);
	}
}

void solve() {
	int N, K, L; cin >> N >> K >> L;
	REP(i, K) {
		uf.unite(in()-1, in()-1);
	}
	REP(i, L) {
		int r = in() - 1;
		int s = in() - 1;
		G[r].push_back(s);
		G[s].push_back(r);
	}

	REP(i, N) {
		q.clear();
		DFS(i);
		for (int a : q) {
			res[a] = cnt[re[a]];
		}
		for (int a : q) {
			cnt[re[a]] = 0;
			re[a] = -1;
		}
