struct UF {
  int n;
  vector<int> d;
  UF(int n):n(n), d(n, -1) {}
  int root(int v) {
    if (d[v] < 0) return v;
    return d[v] = root(d[v]);
  }
  bool unite(int x, int y) {
    x = root(x); y = root(y);
    if (x == y) return false;
    if (size(x) < size(y)) swap(x,y);
    d[x] += d[y];
    d[y] = x;
    return true;
  }
  int size(int v) { return -d[root(v)];}
};

int main(void){
	int n, k, l;
	cin >> n >> k >> l;
	UF c(n), t(n);

	rep(i, k){
		int p, q; cin >> p >> q;
