		c.unite(p, q);
	}
	rep(i, l){
		int p, q; cin >> p >> q;
		p--; q--;
		t.unite(p, q);
	}

	vector<int> a;
	unordered_map<lli, int> mp;
	lli ta[n];
	rep(i, n) ta[i] = lli(c.root(i))*lli(n) + lli(t.root(i));

	rep(i, n){
