#include<unordered_map>
#include<unordered_set>
#include<iostream>
using namespace std;

void BuildCon(unordered_map<int, unordered_set<int>>& paths, int n)
{
	for (int k = 1; k <= n; k++)
		for (int i = 1; i <= n; i++)
			for (int j = 1; j <= n && j != i; j++)
			{
				if (paths[i].find(k) != paths[i].end() && paths[k].find(j) != paths[k].end())
				{
					paths[i].insert(j);
					paths[j].insert(i);
				}
			}
}

int main()
{
	int N, K, L;
	cin >> N >> K >> L;
	unordered_map<int, unordered_set<int>>	roads;
	unordered_map<int, unordered_set<int>>	railways;
	for (int i = 0; i < K; i++)
	{
		int a, b;
		cin >> a >> b;
		roads[a].insert(b);
		roads[b].insert(a);
	}
	BuildCon(roads, N);
	for (int i = 0; i < L; i++)
	{
		int a, b;
		cin >> a >> b;
		railways[a].insert(b);
		railways[b].insert(a);
	}
	BuildCon(railways, N);
	for (int i = 1; i <= N; i++)
	{
		int count = 1;
		for (auto t : roads[i])
		{
			if (railways[i].find(t) != railways[i].end())
				count++;
		}
		cout << count;
		if (i != N)
			cout << " ";
		else
			cout << endl;
	}
    return 0;
}

