using namespace std;

using G = typename std::unordered_map<int64_t, std::vector<int64_t>>;

std::vector<int64_t>
grouping(G& g, const int64_t N)
{
    std::vector<int64_t> group(N, -1);

    for (int64_t i = 0; i < N; ++i) {
        auto f = [&g, &group, col=i](auto F, int64_t from, int64_t prev) -> void {
            group[from] = col;

            for (auto&& to: g[from]) {
                if (group[to] == -1 && to != prev) {
                    F(F, to, from);
                }
            }
        };

        if (group[i] == -1) {
            f(f, i, -1);
        }
    }
    return group;
}


int main()
{
    int64_t N, K, L;
    std::cin >> N >> K >> L;

    G road;
    for (int64_t i = 0; i < K; ++i) {
        int64_t p, q;
        std::cin >> p >> q;
        p--;
        q--;
        road[p].push_back(q);
        road[q].push_back(p);
    }

    G rail;
    for (int64_t i = 0; i < L; ++i) {
        int64_t r, s;
        std::cin >> r >> s;
        r--;
        s--;
        rail[r].push_back(s);
        rail[s].push_back(r);
    }

    const auto road_group = grouping(road, N);
    const auto rail_group = grouping(rail, N);

    for (int64_t i = 0; i < N; ++i) {
        int64_t count = 0;
        const auto road_col = road_group[i];
        const auto rail_col = rail_group[i];
        for (int64_t j = 0; j < N; ++j) {
            if (road_group[j] == road_col &&
                rail_group[j] == rail_col)
            {
                count++;
            }
        }
        std::cout << count << " ";
    }

    return 0;
}

