    auto ref = (*itr).second;
    map<int,int> M_cnt;
    for(auto node : ref){
      M_cnt[train.find_set(node)]++;
    }
    for(auto node:ref){
      ans[node] = M_cnt[train.find_set(node)];
    }
  }
  for(int i = 0;i < n;i++){
    if (i)cout <<"  ";
    cout << ans[i];
  }
  cout << endl;

  return 0;
}

