    vector<int> v;

    Union_Find(int n):size(n){
        v = vector<int>(size,-1);
    }

    int parent(int a){
        if(v[a] < 0){
            return a;
        }

        return v[a] = parent(v[a]);
    }

    bool find(int a,int b){
        if(parent(a) == parent(b)){
            return true;
        }else{
            return false;
        }
    }

    void set(int a,int b){
        int pa = parent(a);
        int pb = parent(b);
        if(pa == pb){
            return;
        }

        if(v[pa] > v[pb]){
            v[pb] = v[pa];
            v[pa] = pb;
        }else{
            v[pa] = v[pb];
            v[pb] = pa;
        }

        return;
    }

};

