struct Union{
  vector<int> r,p;
  Union(){}
  void init(int size){
    r.resize(size,0);
    p.resize(size,0);
    for(int i=0;i<size;i++) r[i]=1,p[i]=i;
  }

  int find(int x){
    if(x!=p[x]) p[x]=find(p[x]);
    return p[x];
  }

  bool same(int x,int y){
    return find(x)==find(y);
  }
  void unite(int x,int y){
    x=find(x);y=find(y);
    if(r[x]>r[y]) {
      r[x]+=r[y];
      p[y]=x;
    }else {
      p[x]=y;
      r[y]+=r[x];
    }
  }
};
