	vector<int> a;
public:
	UnionFind(int n) : n(n), a(n, -1) {}
	int find(int x) { return a[x] < 0 ? x : (a[x] = find(a[x])); }
	bool same(int x, int y) { return find(x) == find(y); }
	bool same(Pii& p) { return same(p.first, p.second); }
	bool unite(int x, int y) {
		x = find(x), y = find(y);
		if (x == y) return false;
		if (a[x] > a[y]) swap(x, y);
		a[x] += a[y];
		a[y] = x;
		n--;
		return true;
	}
	bool unite(Pii& p) { return unite(p.first, p.second); }
	int size() const { return n; }
	int size(int x) { return -a[find(x)]; }
};


int main() {

	int n; reader(n);

	UnionFind uf1(n), uf2(n);
	int k, l; reader(k, l);
	FOR(i, k) {
		int p, q; reader(p, q); p--; q--;
		uf1.unite(p, q);
	}
	FOR(i, l) {
		int p, q; reader(p, q); p--; q--;
		uf2.unite(p, q);
	}

	map<Pii, int> mp;
	FOR(i, n) {
		mp[Pii(uf1.find(i), uf2.find(i))]++;
	}
	vector<int >ans;
	FOR(i, n) {
		int x = mp[Pii(uf1.find(i), uf2.find(i))];
		ans.push_back(x);
	}

	writerArr(ans);
	return 0;
}

