    }
    pool[PI(ra, rb)]++;
  }
  REP(i, 0, n) {
    int ra = uf_a.root(i);
    int rb = uf_b.root(i);
    cout << pool[PI(ra, rb)] << (i == n - 1 ? "\n" : " ");
  }
}

