    for(int i = 1; i <= N; i++)
        tmp[i] = i;
    sort(tmp+1, tmp+N+1, [](int x, int y)-> bool {return d1.fa[x] < d1.fa[y];});
    for(int i = 1; i <= N; i++)
        d1.fa[i] = d1.find(i),
