const int MAX_N = 2 * 100000 + 5;

class uni{
public:

	int par[MAX_N]; // 親
	int rank[MAX_N]; // 木の深さ 

	uni(int n){
		for(int i = 0; i < n; i++){
			par[i] = i;
			rank[i] = 0;
		}
	}

	int find(int x){
		if (par[x] == x){
			return x;
		} else {
			return par[x] = find(par[x]);
		}
	}

	void unite(int x, int y){
		x = find(x);
		y = find(y);
		if(x == y) return;

		if(rank[x] < rank[y]){
			par[x] = y;
		} else {
			par[y] = x;
			if(rank[x] == rank[y])
				rank[x]++;
		}
	}

	bool same(int x, int y){
		return find(x) == find(y);
	}
};

void solve(){
	int N, K, L;
	int count[MAX_N] = {0};
