	}
}
//OKye2
void moalefeK() {
	for (int i = 1, num = 1; i <= n; i++)
		if (visK[i] == 0)
			dfsK(i, num), num++;
	for (int i = 1; moaL[i].size() != 0; i++)
		sort(moaK[i].begin(), moaK[i].end());
