//OKye3
void moalefeL() {
	for (int i = 1, num = 1; i <= n; i++)
		if (visL[i] == 0)
			dfsL(i, num), num++;
	for (int i = 1; moaL[i].size() != 0; i++)
		sort(moaL[i].begin(), moaL[i].end());
}

bool bs(int x, int p) {
	int it = lower_bound(moaL[p].begin(), moaL[p].end(), x) - moaL[p].begin();
	return (x == moaL[p][it]);
}

void updateDpL() {
	for (int i = 1; i <= n; i++) {
		int postK = visK[i], postL = visL[i];
		int tmp = -1;
		for (int j = 0; moaK[postK][j] < i; j++) 
			if (bs(moaK[postK][j], postL) == true)
				tmp = moaK[postK][j];
		tmp == -1? dpL[i] = 1: dpL[i] = dpL[tmp] + 1;
	}
}

void updateDpR() {
	for (int i = n; i >= 1; i--) {
		int postK = visK[i], postL = visL[i];
		int tmp = -1;
		for (int j = moaK[postK].size() - 1; moaK[postK][j] > i; j--) 
			if (bs(moaK[postK][j], postL) == true)
				tmp = moaK[postK][j];
		tmp == -1? dpR[i] = 1: dpR[i] = dpR[tmp] + 1;
	}
}
//hale
void writeOutput() {
	for (int i = 1; i <= n; i++)
		cout << dpR[i] + dpL[i] - 1 << ' ';
}

void runProgram() {
	readInput();
	moalefeK();
	moalefeL();
	updateDpL();
	updateDpR();
	writeOutput();
}

