struct UnionFind {
	vector<int> data;
	UnionFind(int size) : data(size, -1) {}
	bool unionSet(int x, int y) {
		x = root(x); y = root(y);
		if (x != y) {
			if (data[y] < data[x]) swap(x, y);
			data[x] += data[y]; data[y] = x;
		}
		return x != y;
	}
	bool findSet(int x, int y) {
		return root(x) == root(y);
	}
	int root(int x) {
		return data[x] < 0 ? x : data[x] = root(data[x]);
	}
	int size(int x) {
		return -data[root(x)];
	}
};

signed main() {
	int n, k, l;
	cin >> n >> k >> l;
	UnionFind uq(n);
	rep(i, k) {
		int p, q; cin >> p >> q;
		p--; q--;
		uq.unionSet(p, q);
	}
	V ans(n, 1);
	rep(i, l) {
		int p, q; cin >> p >> q;
		p--; q--;
		if (uq.findSet(p, q)) {
			ans[p]++;
			ans[q]++;
		}
	}
	rep(i, n) {
		cout << ans[i] << (i + 1 == n ? "\n" : " ");
	}
	system("pause");
}

