int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	int n, k, l;
	cin >> n >> k >> l;
	vector<int> rpar(n);
	iota(rpar.begin(), rpar.end(), 0);
	vector<int>rnk(n, 0);
	int p, q;
	// 道路
	for (int i = 0; i < k; i++) {
		cin >> p >> q;
		--p; --q;
		p = find(p,rpar);
		q = find(q,rpar);
		if (p == q) continue;
		if (rnk[p] < rnk[q]) {
			rpar[p] = q;
		}
		else {
			rpar[q] = p;
			if (rnk[p] == rnk[q]) rnk[p]++;
		}
	}
	// 線路
	vector<int> lpar(n);
	vector<int> ans(n, 1);
	iota(lpar.begin(), lpar.end(), 0);
	fill(rnk.begin(), rnk.end(), 0);
	for (int i = 0; i < l; i++) {
		cin >> p >> q;
		--p; --q;
		if (find(p, rpar) != find(q, rpar))continue;
		p = find(p, lpar);
		q = find(q, lpar);
		if (p == q) continue;
		if (rnk[p] < rnk[q]) {
			lpar[p] = q;
			ans[q] += ans[p];
		}
		else {
			lpar[q] = p;
			ans[p] += ans[q];
			if (rnk[p] == rnk[q]) rnk[p]++;
		}
	}
	for (int i = 0; i < n-1; i++) {
		cout << to_string(ans[lpar[i]]) << " ";
	}
	cout << to_string(ans[lpar[n - 1]]) << endl;


	return 0;
}

