        cin >> r[i] >> s[i];
        --s[i], --r[i];
        uft.unite(s[i],r[i]);
    }
    vector<int> a(n), b(n);
    REP(i,n) {
        a[i] = ufr.find(i); b[i] = uft.find(i);
        ans[{a[i],b[i]}]++;
    }

    REP(i,n) {
        cout << ans[{a[i], b[i]}] << endl;
    }
    return 0;
}

