class DFS {
 public:
  DFS(vector<vector<int>>& g, int n) : g_(g), used_(n, 0) {
    int color = 1;
    for (int i = 0; i < n; i++) {
      if (!used_[i]) {
        Run(i, color);
        ++color;
      }
    }
  }

  void Run(int v, int color) {
    used_[v] = color;
    for (auto u : g_[v]) {
      if (used_[u]) {
        continue;
      }
      Run(u, color);
    }
  }

  bool IsSameComp(int a, int b) const {
    return used_[a] == used_[b];
  }

 private:
  vector<vector<int>>& g_;
  vector<int> used_;
};

class DFS1 {
 public:
  DFS1(vector<vector<int>>& g, int n, DFS& dfs) : g_(g), used_(n, false), dfs_(dfs), ans_(n, -1) {
    for (int i = 0; i < n; i++) {
      if (!used_[i]) {
        comp_.clear();
        Run(i);
        for (auto x : comp_) {
          CHECK(ans_[x] == -1);
          ans_[x] = comp_.size();
        }
      }
    }
  }

  void Run(int v) {
    used_[v] = true;
    comp_.push_back(v);
    for (auto u : g_[v]) {
      if (used_[u] || !dfs_.IsSameComp(v, u)) {
        continue;
      }
      Run(u);
    }
  }

  const vector<int>& GetAns() const {
    return ans_;
  }

 private:
  vector<vector<int>>& g_;
  vector<bool> used_;
  vector<int> comp_;
  DFS& dfs_;
  vector<int> ans_;
};

void solve() {
  int n, k, l;
