    P1[root1(b)]=root1(a);
}
void unite2(int a, int b)
{
    if(sz2[root2(a)]<sz2[root2(b)])
    {
        swap(a, b);
    }
    sz2[root2(a)]+=sz2[root2(b)];
    P2[root2(b)]=root2(a);
}
