int root(int *uni,int a){
    if(uni[a]<0) return a;
    else return uni[a]=root(uni, uni[a]);
}
bool connect(int *uni,int ia,int ib){
    int a=root(uni,ia),b=root(uni,ib);
    if(a==b) return false;

    if(uni[a]>uni[b]){
        uni[b]+=uni[a];
        uni[a]=b;
    }else{
        uni[a]+=uni[b];
        uni[b]=a;
    }
    return true;
}

