struct dsu{
    int p[200002], sz[200002];
    void init(int n){
        for(int i=1;i<=n;i++) p[i] = i, sz[i] = 1;
    }
    int root(int a){
        return p[a] == a?a:(p[a]=root(p[a]));
    }
    void merge(int a, int b){
        a = root(a), b = root(b);
        if(a != b){
            sz[b] += sz[a];
            p[a] = b;
        }
    }
}d1, d2;

