int N,K,L;
vector<int> G1[100010],G2[100010];
int mem[100010][3] = {0};// *ans 1 2
int ans[100010] = {0};

void solve()
{
    for(int i = 1; i < N + 1; i++)
    {
        vector<int> V;
        int sum = 0;
        if(mem[i][0])
        {
            continue;
        }
        if(mem[i][1] == 0)
        {
            queue<int> Q;
            Q.push(i);
            while(Q.size())
            {
                int now = Q.front();
                Q.pop();
                if(mem[now][1])
                {
                    continue;
                }
                mem[now][1] = i;
                if(mem[now][2] == mem[i][2] && mem[now][2] + mem[i][2] != 0)
                {
                    sum++;
                    V.push_back(now);
                }
                for(int j = 0; j < G1[now].size(); j++)
                {
                    Q.push(G1[now][j]);
                }
            }
        }
        if(mem[i][2] == 0)
        {
            queue<int> Q;
            Q.push(i);
            while(Q.size())
            {
                int now = Q.front();
                Q.pop();
                if(mem[now][2])
                {
                    continue;
                }
                mem[now][2] = i;
                if(mem[now][1] == mem[i][1] && mem[now][1] + mem[i][1] != 0)
                {
                    sum++;
                    V.push_back(now);
                }
                for(int j = 0; j < G2[now].size(); j++)
                {
                    Q.push(G2[now][j]);
                }
            }
        }
        ans[i] = sum;
        for(int j = 0; j < V.size(); j++)
        {
            mem[V[j]][0] = i;
        }
    }
    for(int i = 1; i < N + 1; i++)
    {
        printf("%d\n",ans[mem[i][0]]);
    }
    return;
}

int main()
{
    scanf("%d%d%d",&N,&K,&L);
    for(int i = 0; i < K; i++)
    {
        int p,q;
        scanf("%d%d",&p,&q);
        G1[p].push_back(q);
        G1[q].push_back(p);
    }
    for(int i = 0; i < L; i++)
    {
        int p,q;
        scanf("%d%d",&p,&q);
        G2[p].push_back(q);
        G2[q].push_back(p);
    }
    solve();
    return 0;
}

