void addEdge(int *head, int from, int to)
{
    e[cnt].next = head[from];
    e[cnt].to = to;
    head[from] = cnt++;
}

void getNumberDFS(int cur)
{
    vis[cur] = true;
    number[cur] = cnt;
    for (int i = RoadHead[cur]; ~i; i = e[i].next)
    {
        int to = e[i].to;
        if (!vis[to])
            getNumberDFS(to);
    }
}

void DFS(int *head, int cur)
{
    vis[cur] = true;
    int curNumber = number[cur];
    for (int i = 0; i < v[curNumber].size(); i++)
        ans[v[curNumber][i]]++;
    ans[cur] += v[curNumber].size();
    v[curNumber].push_back(cur);
    for (int i = head[cur]; ~i; i = e[i].next)
    {
        if (!vis[e[i].to])
            DFS(head, e[i].to);
    }
}

