struct dsu {
  vector<int> r, p;
  dsu() = default;
  dsu(int n) {
    r.assign(n, 0);
    p.assign(n, -1);
  }
  void merge(int u, int v) {
    int x = find(u), y = find(v);
    if (x == y) return;
    if (r[x] < r[y]) p[x] = y;
    else if (r[x] > r[y]) p[y] = x;
    else {
      p[x] = y;
      r[x]++;
    }
  }
  int find(int x) {
    if (p[x] == -1) return x;
    else return p[x] = find(p[x]);
  }
};

void solve(std::istream &in, std::ostream &out) {

  int n, k, l;
  in >> n >> k >> l;
  dsu d1(n), d2(n);
  for (int i = 0, u, v; i < k; ++i) {
    in >> u >> v;
    --u;
    --v;
    d1.merge(u, v);
  }
  for (int i = 0, u, v; i < l; ++i) {
    in >> u >> v;
    --u;
    --v;
    d2.merge(u, v);
  }
  map<pair<int, int>, int> mp;
  for (int i = 0; i < n; ++i) {
    mp[{d1.find(i), d2.find(i)}]++;
  }
  for (int i = 0; i < n; ++i) {
    out << mp[{d1.find(i), d2.find(i)}] << ' ';
  }
}

