void out() {
	for (int i = 1; i <= n; i++)
		cout << arr_ans[i] << " ";
}

void solve() {
	for (int i = 1; i <= n; i++) {
		if (mark1[i] == false) {
			dfs1(i);
			while (ver.size() > 0) {
				cnt = *(ver.begin());
				dfs2(cnt);
				cou = res.size();
				while (res.size() > 0) {
					mark1[res.front()] = 1;
					arr_ans[res.front()] = cou;
					ver.erase(res.front());
					res.pop();
				}
			}
		}
	}
}

void dfs1(int a) {
	mark2[a] = 1;
	ver.insert(a);
	for (unsigned int u = 0; u < gr[a].size(); u++)
		if (mark2[gr[a][u]] == 0)
			dfs1(gr[a][u]);
}

void dfs2(int a) {
	mark2[a] = 2;
	res.push(a);
	for (unsigned int u = 0; u < adj[a].size(); u++) {
		if (ver.find(adj[a][u]) == ver.end())
			continue;
		if (mark2[adj[a][u]] == 1)
			dfs2(adj[a][u]);
	}
}

