struct UF {
    vector<int> par, sz;

    UF(int n) {
        par.resize(n);
        sz.resize(n);
        for (int i = 0; i < n; ++i) {
            par[i] = i;
            sz[i] = 1;
        }
    }

    int find_root(int x) {
        return par[x] == x ? x : par[x] = find_root(par[x]);
    }

    bool same(int x, int y) {
        return find_root(x) == find_root(y);
    }

    void unite(int x, int y) {
        x = find_root(x);
        y = find_root(y);
        if (x == y) return;

        if (sz[x] < sz[y]) swap(x, y);
        sz[x] += sz[y];
        par[y] = find_root(x);
    }
};

int main (int argc, char *argv[]) {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int n, k, l;
    cin >> n >> k >> l;
    UF road(n), rail(n);
    rep(i, k) {
        int p, q;
        cin >> p >> q;
        road.unite(p - 1, q - 1);
    }
    rep(i ,l) {
        int r, s;
        cin >> r >> s;
        rail.unite(r - 1, s - 1);
    }

    vector<pair<int, int> > V(n);
    map<pair<int, int>, int> M;
    rep(i, n) {
        //cout << "| " << road.par[i] << " " << road.find_root(i) << " | " << rail.par[i] << " " << rail.find_root(i) << endl;
        V[i].first = road.par[i];
        V[i].second = rail.par[i];
        ++M[V[i]];
    }

    rep(i, n) {
        if (i) cout << " ";
        cout << M[V[i]];
    }
    cout << endl;

    return 0;
}

