#include <bits/stdc++.h>
using namespace std;

struct union_find {
    private:
        vector<int> parents;
        vector<int> ranks;

    public:
        union_find(int n) : parents(n, -1), ranks(n, 0) {}

        void unite(int a, int b) {
            int pa = find(a);
            int pb = find(b);
            if (pa == pb) return;
            assert(pa != pb);

            int np, nc;
            if (ranks[pa] == ranks[pb]) {
                np = pa; nc = pb;
                ranks[np]++;
            } else if (ranks[pa] < ranks[pb]) {
                np = pb; nc = pa;
            } else {
                np = pa; nc = pb;
            }

            parents[nc] = np;
        }

        int find(int a) {
            while (parents[a] != -1) { a = parents[a]; }
            return a;
        }
};

int main() {
    int N, K, L;
    cin >> N >> K >> L;

    union_find road(N);
    for (int i = 0; i < K; i++) {
        int p, q;
        cin >> p >> q;
        p--; q--;
        road.unite(p, q);
    }

    union_find rail(N);
    for (int i = 0; i < L; i++) {
        int p, q;
        cin >> p >> q;
        p--; q--;
        rail.unite(p, q);
    }

    map<pair<int, int>, int> gs;
    for (int i = 0; i < N; i++) {
        gs[pair<int, int>(road.find(i), rail.find(i))]++;
    }

    bool first = true;
    for (int i = 0; i < N; i++) {
        if (first) {
            first = false;
        } else {
            cout << ' ';
        }
        cout << gs[pair<int, int>(road.find(i), rail.find(i))];
    }
    cout << endl;

    return 0;
}

