    for (int i=0; i<n; i++) {
      u.push_back(i);
      r.push_back(1);
    }
  }

  int find(int x) {
    if (u[x] == x) return x;
    return u[x] = find(u[x]);
  }

  void unite(int x, int y) {
    x = find(x), y = find(y);
    if (x == y) return;
    if (r[x] < r[y]) swap(x, y);
    u[y] = x;
    r[x] += r[y];
    r[y] = 0;
  }

  bool same(int x, int y) {
    return find(x) == find(y);
  }
};

