        }
        queue<int> Q;
        Q.push(i);
        while(Q.size())
        {
            int now = Q.front();
            Q.pop();
            if(mem[now][1])
            {
                continue;
            }
            mem[now][1] = i;
            for(int j = 0; j < G1[now].size(); j++)
