class UnionFind {
	vector<int> par;
	vector<int> rank;
	vector<int> msize;
public:
	UnionFind(int max_n) :par(max_n), rank(max_n), msize(max_n) {}
	void init(int n) {
		for (int i = 0; i<n; i++) {
			par[i] = i;
			rank[i] = 0;
			msize[i] = 1;
		}
	}
	int find(int x) {
		if (par[x] == x)return x;
		return par[x] = find(par[x]);
	}
	void unite(int x, int y) {
		x = find(x);
		y = find(y);
		if (rank[x]<rank[y]) {
			par[x] = y;
			msize[y] += msize[x];
		}
		else {
			par[y] = x;
			msize[x] += msize[y];
			if (rank[x] == rank[y])rank[x]++;
		}
	}
	bool same(int x, int y) {
		return find(x) == find(y);
	}
	int size(int x) {
		return msize[find(x)];
	}
};






