        uf1.unite(p-1,q-1);
    }

    vector<int> ans(n);

    for(int i = 0; i < l ;i++){
        int p,q;
        cin >> p >> q;

        if(uf1.same(p-1,q-1)){
            ans[p-1]++;
            ans[q-1]++;
        }

    }

    for(int i = 0; i < n; i++) cout << ans[i]+1 << ((i + 1 == n) ? '\n' : ' ');

}

