struct UFT {
    vector<ll> parent;
    UFT(ll N) : parent(N) { rep(i, N) parent[i] = i; }
    def root(ll x) {
        if (parent[x] == x)
            return x;
        else
            return parent[x] = root(parent[x]);
    }
    def unite(ll x, ll y) {
        ll root_x = root(x), root_y = root(y);
        if (root_x != root_y) {
            if (root_x > root_y) swap(root_x, root_y);
            parent[root_x] = root_y;
        }
    }
    def same(ll x, ll y) { return root(x) == root(y); }
};

signed main() {
    ll N = in<ll>(), K = in<ll>(), L = in<ll>();
    UFT UFK(N), UFL(N);
    vector<ll> A(N);
    map<ll, ll> MAP;
    rep(i, K) UFK.unite(in<ll>() - 1, in<ll>() - 1);
    rep(i, L) UFL.unite(in<ll>() - 1, in<ll>() - 1);
    rep(i, N) MAP[UFK.root(i) * N + UFL.root(i)]++;
    rep(i, N) A[i] = MAP[UFK.root(i) * N + UFL.root(i)];
    out<ll>({A}, 1, N, space, endl);
}

