bool vis[N];

vector<int> adj[N];

int Find (int X) {return par[X] = (par[X] == X ? X : Find(par[X]));}

void Union (int A, int B) {
	A = Find(A); B = Find(B);
	if(A == B) return;
	sz[B] += sz[A];
	par[A] = B;
}

void getcp (int M, int C[], bool T) {
	iota(par, par+n+1, 0);
	fill(sz, sz+n+1, 1);
	for(int i=1;i<=M;i++) {
		int A, B;
		scanf("%d%d",&A,&B);
		if(T) {
			adj[A].push_back(B);
			adj[B].push_back(A);
		}
		Union(A, B);
	}
	for(int i=1;i<=n;i++) C[i] = Find(i);
}

void dfs1 (int I) {
	vis[I] = true; cc[cp2[I]]++;
	for(auto &T : adj[I]) if(!vis[T]) dfs1(T);
}

void dfs2 (int I) {
	vis[I] = false; ans[I] = cc[cp2[I]];
	for(auto &T : adj[I]) if(vis[T]) dfs2(T);
}

void dfs3 (int I) {
	vis[I] = true; cc[cp2[I]] = 0;
	for(auto &T : adj[I]) if(!vis[T]) dfs3(T);
}

