using namespace std;
class UF{
public:
  int o[200100];
  int u[200100];
  UF(int n){
    for(int i=0;i<n;i++){
      o[i]=-1;
      u[i]=i;
    }
  }
  int root(int s){
    while(o[s]>=0)
      s=o[s];
    return u[s];
  }
  void merge(int x, int y){
    x = root(x);
    y = root(y);
    if(x == y) return;
    o[x]+=o[y];
    o[y]=x;
  }
  bool same(int x,int y){
    return root(x) == root(y);
  }
};
map<ll,ll>mama;
int main(){
  ll n,k,l;
  cin>>n>>k>>l;
  UF uni(n);
  UF uni2(n);
  for(int i=0;i<k;i++){
    int p,q;cin>>p>>q;p--;q--;
    uni.merge(p,q);
  }
  for(int i=0;i<l;i++){
    int p,q;cin>>p>>q;p--;q--;
    uni2.merge(p,q);
  }
  vector<pair<int,int> >num1(n);
  for(int i=0;i<n;i++){
    num1[i]=mp(uni.root(i),uni2.root(i));
  }
  sort(num1.begin(),num1.end());

  int cnt=1;
  for(int i=0;i<n-1;i++){
    while(num1[i].F==num1[i+1].F&&num1[i].S==num1[i+1].S&&i!=n-2){
