vector<int> toposort(const Graph &g, int start)
{
	int n = g.size();
	vector<int> res;
	res.reserve(n);
	vector<bool> used(n,false);
	function<void(int)> rec = [&](int p){
		if(used[p]) return;
		used[p] = true;
		for(auto&& e : g[p]) {
			rec(e.to);
		}
		res.push_back(p);
	};
	rec(start);
	return res;
}

tuple<cost_t,int,int> getTreeDiameter(const Graph &g){
	using P = pair<cost_t,int>;

	function<P(int,int)> dfs = [&](int p, int par) -> P{
		P res = {0,p};
		for(auto&& e : g[p]) {
			if(e.to == par) continue;
			auto v = dfs(e.to,p);
			v.first += e.cost;
			res = max(res,v);
		}
		return res;
	};

	auto ap1 = dfs(0,-1);
	auto ap2 = dfs(ap1.second,-1);
	return make_tuple(ap2.first,ap2.second,ap1.second);
}

pair<int,int> getTreeCenter(const Graph& g){
	cost_t di;
	int x, y;
	tie(di, x, y) = getTreeDiameter(g);
	pair<int,int> res(-1,-1);
	cost_t mi;
	function<cost_t(int,int)> rec 
	 = [&](int p, int par) -> cost_t{
		if(p == y){
			return 0;
		}
		cost_t ress = -1;
		for(auto&& e : g[p]) if(e.to != par){
			cost_t v = rec(e.to,p);
			if(v != -1){
				v += e.cost;
				ress = v;
				v = max(v, di-(v));
				if(mi > v){
					mi = v;
					res = {p,-1};
				}else if(mi == v){
					res.second = p;
				}
			}
		}
		return ress;
	};
	rec(x,-1);
	return res;
}
