using namespace std;

struct UnionFind {
        int n;
        vector<int> parent;
        vector<int> rank;
        vector<int> num;
        int find(int x) {
                if (parent[x] == x) return  x;
                return parent[x] = find(parent[x]);
        }
        UnionFind(int n_) {
                n = n_;
                parent.resize(n);
                for (int i = 0; i < n; i ++) parent[i] = i;
                rank.assign(n, 0);
                num.assign(n, 1);
        }
        void unite(int x, int y) {
                if ((x = find(x)) != (y = find(y))) {
                        if (rank[x] < rank[y]) {
                                parent[x] = y;
                                num[y] += num[x];
                        } else {
                                parent[y] = x;
                                if (rank[x] == rank[y]) rank[x] ++;
                                num[x] += num[y];
                        }
                        n --;
                }
        }
        bool same(int x, int y) { return find(x) == find(y); }
        int get() { return n; }
        int get(int x) { return num[find(x)]; }
};

int main() {
        int i, j;
        int n, k, l;
        cin >> n >> k >> l;
        UnionFind uf1(n), uf2(n);
        for (i = 0; i < k; i ++) {
                int a, b;
                cin >> a >> b;
                a --, b --;
                uf1.unite(a, b);
        }
        for (i = 0; i < l; i ++) {
                int a, b;
                cin >> a >> b;
                a --, b --;
                uf2.unite(a, b);
        }
        for (i = 0; i < n; i ++) {
                int cnt = 0;
                for (j = 0; j < n; j ++) {
                        if (uf1.same(i, j) && uf2.same(i, j)) cnt ++;
                }
                if (i == n - 1) cout << cnt << endl;
                else cout << cnt << ' ';
        }
        return 0;
}

