int vis[N],ans[N];

void dfs1(int u,int tag,map<int,int>&M)  //块计数
{
    if(vis[u]==tag)return;
    vis[u]=tag;
    M[father(u)]++;
    for(int i=head[u];~i;i=e[i].next)
    {
        dfs1(e[i].t,tag,M);
    }
}

void dfs2(int u,int tag,map<int,int>&M)
{
    if(vis[u]==tag)return;
    vis[u]=tag;
    ans[u]+=M[father(u)];
    for(int i=head[u];~i;i=e[i].next)
    {
        dfs2(e[i].t,tag,M);
    }
}

