class UFT {
  int *par;
  int *rank;

public:

  UFT(const size_t N): par(new int [N]), rank(new int [N]) {
    std::iota(par, par + N, 0);
    std::fill(rank, rank + N, 0);
  }

  ~UFT() { delete [] par; delete [] rank; }

  int find(int x) { return par[x] == x ? x : par[x] = find(par[x]); }
  bool same(int x, int y) { return find(x) == find(y); }

  void unite(int x, int y) {
    x = find(x);
    y = find(y);
    if (x == y) return;

    if (rank[x] < rank[y]) {
      par[x] = y;
    } else {
      par[y] = x;
      if (rank[x] == rank[y])
        ++rank[x];
    }
  }

};

