    }

    UnionFind pq(N),rs(N);
    for(int i = 0; i < K;i++) pq.unionSet(p[i], q[i]);
    for(int i = 0; i < L;i++) rs.unionSet(r[i], s[i]);
    map<pii,int> mp;
    for(int i = 0; i < N;i++) mp[pii(pq.root(i),rs.root(i))]++;
    for(int i = 0; i < N;i++){
        cout << mp[pii(pq.root(i),rs.root(i))] << " ";
    }
    cout << endl;
    return 0;
}

