ll N, K, L;
unordered_map<ll, vector<ll> > road, line;

void patrol(ll node, unordered_map<ll, vector<ll> >& graph, vector<bool>& used) {
    used[node] = true;

    for (auto next : graph[node]) {
        if (!used[next]) {
            patrol(next, graph, used);
        }
    }
}

int main(void) {
    cin.tie(0);
    ios::sync_with_stdio(false);

    cin >> N >> K >> L;

    for (ll i = 0; i < K; i++) {
        ll from, to;
        cin >> from >> to;
        road[from].push_back(to);
        road[to].push_back(from);
    }

    for (ll i = 0; i < L; i++) {
        ll from, to;
        cin >> from >> to;
        line[from].push_back(to);
        line[to].push_back(from);
    }

    vector<ll> road_link(N + 1), line_link(N + 1);

    vector<bool> road_used(N + 1, false), line_used(N + 1, false);
    for (ll i = 1; i <= N; i++) {
        if (!road_used[i]) {
            auto old = road_used;
            patrol(i, road, road_used);
            for (ll j = 1; j <= N; j++) {
                if (!old[j] && road_used[j]) {
                    road_link[j] = i;
                }
            }
        }

        if (!line_used[i]) {
            auto old = line_used;
            patrol(i, line, line_used);
            for (ll j = 1; j <= N; j++) {
                if (!old[j] && line_used[j]) {
                    line_link[j] = i;
                }
            }
        }
    }

    vector<bool> used(N + 1, false);
    vector<ll> ans_list(N + 1, 0);

    for (ll i = 1; i <= N; i++) {
        if (!used[i]) {
            vector<ll> connected;
            ll ans = 0;
            ll road_id = road_link[i];
            ll line_id = line_link[i];
            for (ll j = 1; j <= N; j++) {
                if (road_link[j] == road_id && line_link[j] == line_id) {
                    connected.push_back(j);
                    used[j] = true;
                    ans++;
                }
            }

            for (auto c : connected) {
                ans_list[c] = ans;
            }
        }

        cout << ans_list[i] << " \n"[i == N];
    }

    return 0;
}

