      return min(1+solve(i+1,-1),1+solve(i+1,1));
    }else if(a[i]>0){
      return min(solve(i+1,a[i]),a[i]+1+solve(i+1,-1));
    }else{
      return min(solve(i+1,a[i]),1-a[i]+solve(i+1,1));
