using namespace std;
const int MAXN = 2 * (int)1e5 + 5;

class DSU {
private:
  std::vector<int> rank, p, size;
public:
  DSU(int n): rank(n, 0), p(n), size(n, 1) {
    for (int i = 0; i < n; ++i) p[i] = i;
  }

  int findRep(int x) {
    if (p[x] != x) {
      p[x] = findRep(p[x]);
    }
    return p[x];
  }

  void unite(int x, int y) {
    int p1 = findRep(x), p2 = findRep(y);
    if (p1 == p2) return;
    if (rank[p1] < rank[p2]) std::swap(p1, p2);

    if (rank[p1] == rank[p2]) rank[p1]++;
    p[p2] = p1;
    size[p1] += size[p2];
  }

  int getSize(int x) {
    int xRep = findRep(x);
    return size[xRep];
  }

  bool isSame(int x, int y) {
    return findRep(x) == findRep(y);
  }
};

int main() {
  int n, k, l;
  cin >> n >> k >> l;
  DSU dsu1(n); DSU dsu2(n);
  for (int i = 0; i < k; ++i) {
    int p, q;
    cin >> p >> q;
    p--; q--;
    dsu1.unite(p, q);
  }

  for (int i = 0; i < l; ++i) {
    int r, s;
    cin >> r >> s;
    r--; s--;
    dsu2.unite(r, s);
  }

  map<pair<int, int>, int> m;
  for (int i = 0; i < n; ++i) {
    int x = dsu1.findRep(i), y = dsu2.findRep(i);
    m[pair<int, int>(x, y)]++;
  }

  for (int i = 0; i < n; ++i) {
    int x = dsu1.findRep(i), y = dsu2.findRep(i);
    int ans = m[pair<int, int>(x, y)];
    cout << ans << " ";
  }
  puts("");
  return 0;
}

