        x = find(x); y = find(y);
        if (x == y)return;
        if (sz[x] > sz[y]) {
            par[y] = x;
            sz[x] += sz[y];
        }
        else {
            par[x] = y;
            sz[y] += sz[x];
        }
    }
    bool issame(int x, int y) {
        return find(x) == find(y);
    }
    int size(int x) {
        return sz[find(x)];
    }
};


