class UnionFind
{
private:
	vec<int> p;
	vec<int> Rank;

public:
	UnionFind(int n) : p(n), Rank(n, 0) {
		rep(i, n) p[i] = i;
	}

	void init(int n)
	{
		p.resize(n);
		rep(i, n) p[i] = i;
		Rank.resize(n);
		rep(i, n) Rank[i] = 0;
	}

	int root(int a)
	{
		if (p[a] == a) return a;
		p[a] = root(p[a]);
		return p[a];
	}

	void unite(int a, int b)
	{
		int ra = root(a);
		int rb = root(b);
		if (Rank[ra] > Rank[rb]) p[rb] = ra;
		else p[ra] = rb;
		if (Rank[ra] == Rank[rb]) Rank[rb]++;
	}

	int is_same_group(int a, int b)
	{
		return (root(a) == root(b));
	}
};

int main(void)
{
	int n, k, l;
	cin >> n >> k >> l;

	UnionFind road(n), train(n);
	rep(i, k) {
		int a, b;
