		a--;
		b--;
		train.unite(a, b);
	}

	vec<pair<pair<int, int>, int>> set(n);
	rep(i, n) {
		set[i].first.first = road.root(i);
		set[i].first.second = train.root(i);
		set[i].second = i;
	}

	sort(set.begin(), set.end());
	vec<int> ans(n);
	int cur = 0;
	while(cur < n) {
		int prev = cur;

		for (; cur <= n; cur++) {
			if (cur < n && set[prev].first == set[cur].first) continue;
			break;
		}
		for (int i = prev; i < cur; i++) ans[set[i].second] = cur - prev;
	}

	rep(i, n - 1) cout << ans[i] << " ";
	cout << ans[n - 1] << endl;
	return 0;
}

