        for (int i = 1; i <= n; i++){
                comproad[find_set(i)].push_back(i);
        }
        for (int i = 1; i <= l; i++){
                ll u, v;
                fs(u); fs(v);
                dsu1(u, v);
        }
        for (int i = 1; i <= n; i++){
                comprail[find_set1(i)].push_back(i);
        }
        for (int i = 1; i <= n; i++){
                if (fuck[{find_set(i), find_set1(i)}] == 0){
                        fuck[{find_set(i), find_set1(i)}] = 1;
                        if (comproad[find_set(i)].size() == 1 || comprail[find_set1(i)].size() == 1) {
                                continue;
                        }
                        tt(find_set(i), find_set1(i));
                }
        }
        for (int i = 1; i <= n; i++) cout << ans[i] << " ";
}

