int r[100010], s[100010];

class UnionFind {
private:
    static const int MAX = 100010;
    int par[MAX];
    int r[MAX];
public:
    UnionFind(int n = MAX) {
	for (int i = 0; i < n; i++) {
	    par[i] = i;
	    r[i] = 0;
	}
    }

    int find(int x) {
	if (par[x] == x) {
	    return x;
	} else {
	    return par[x] = find(par[x]);
	}
    }

    void unite(int x, int y) {
	x = find(x);
	y = find(y);
	if (x == y) return;
	if (r[x] < r[y]) {
	    par[x] = y;
	} else {
	    par[y] = x;
	    if (r[x] == r[y]) r[x]++;
	}
    }

    bool same(int x, int y) {
	return find(x) == find(y);
    }
};

void solve() {
    UnionFind uf[2];
    for (int i = 0; i < k; i++) {
        uf[0].unite(p[i], q[i]);
    }
    for (int i = 0; i < l; i++) {
        uf[1].unite(r[i], s[i]);
    }

    P label[100010];
    unordered_map<P, int, pairhash> mp;
    for (int i = 0; i < n; i++) {
        P v = P(uf[0].find(i), uf[1].find(i));
        label[i] = v;
        mp[v]++;
    }
    for (int i = 0; i < n; i++) {
        cout << mp[label[i]] << (i==n-1?endl:' ');
    }
}

