struct union_find {
    vector<int> p;
    union_find(int n) : p(n, -1) {};
    bool unite(int u, int v) {
        if ((u = root(u)) == (v = root(v))) return false;
        if (p[u] > p[v]) swap(u, v);
        p[u] += p[v]; p[v] = u;
        return true;
    }
    bool find(int u, int v) { return root(u) == root(v); }
    int root(int u) { return p[u] < 0 ? u : p[u] = root(p[u]); }
    int size(int u) { return -p[root(u)]; }
};



int main() {
    int n, k, l;
    cin >> n >> k >> l;

    union_find uf1(n);
    rep(i, k) {
        int p, q;
        scanf("%d%d", &p, &q);
        p--; q--;
        uf1.unite(p, q);
    }

    vector<int> connected(n, 1);
    rep(i, l) {
        int p, q;
        scanf("%d%d", &p, &q);
        p--; q--;
        if (uf1.find(p, q)) {
            connected[p]++;
            connected[q]++;
        }
    }

    rep(i, n) {
        cout << connected[i] << " \n"[i == n - 1];
    }

    return 0;
}

