struct UF {
	int par[SIZE], ran[SIZE];
	void init(int n) {
		REP(i, n, 0) par[i] = i;
	}
	int getpar(int n) {
		if (par[n] == n) return n;
		par[n] = getpar(par[n]);
		return par[n];
	}
	void mrg(int a, int b) {
		a = getpar(a), b = getpar(b);
		if (a == b) return;
		if (ran[a] > ran[b]) par[a] = b;
		else {
			par[b] = a;
			if (ran[a] == ran[b]) ran[a]++;
		}

	}
} UA, UB;

