void bfs (int source , vector<int> adj[], int *parent, int n) {
    queue <int> qe;
    int visited[n+1] = {0};
    qe.push(source);
    while (!qe.empty()) {
        int cur = qe.front(); qe.pop();
        visited[cur] = 1;
        //cout << cur << " ->";
        for (int i: adj[cur]) {
            if (visited[i]) continue;
            parent[i] = parent[cur];
            qe.push(i);
        }
    }
    //cout << endl;
}

