#include "bits/stdc++.h"
using namespace std; 

const int maxn = 200005;

vector<int> edges[maxn];
int par[maxn], sz[maxn];

int get(int x){
  if(par[x] == x)return x;
  else {
    return par[x] = get(par[x]);
  }
}

void unite(int x, int y){
  x = get(x); y = get(y);
  if(x == y)return;
  if(sz[y] > sz[x])swap(x, y);
  par[y] = x;
  sz[x] += sz[y];
}

int vis[maxn], ans[maxn];
vector<int> v;

void dfs(int x, int p){
  vis[x] = 1;
  v.push_back(x);
  for(auto i : edges[x]){
    if(i != p && get(i) == get(p)){
      dfs(i, x);
    }
  }
}

int main(int argc, char const *argv[])
{
	int n, m, k; 
  scanf("%d %d %d", &n, &m, &k);
  for(int i = 1; i <= n; ++i){
    par[i] = i;
    sz[i] = 1;
  }
  for(int i = 0; i < m; ++i){
    int x, y;
    scanf("%d %d", &x, &y); 
    unite(x, y);
  }
  for(int i = 0; i < k; ++i){
    int x, y;
    scanf("%d %d", &x, &y);
    edges[x].push_back(y);
    edges[y].push_back(x);
  }
  for(int i = 1; i <= n; ++i){
    if(!vis[i]){
      v.clear();
      dfs(i, i);
      int cnt = v.size();
      for(auto j : v){
        ans[j] = cnt;
      }
    }
  }
  for(int i = 1; i <= n; ++i){
    printf("%d ", ans[i]);
  }

	return 0;
}

