void Union(int x, int y, int *fat, int *c)
{
    if (c[x] > c[y])
    {
        fat[y] = x;
        c[x] += c[y];
    }
    else
    {
        fat[x] = y;
        c[y] += c[x];
    }
}

int Find(int x, int *fat)
{
    while (x != fat[x]) x = fat[x];
    return x;
}

