 \                                                                                       **/
struct UFF{
    int par[MAX_N];
    int ran[MAX_N];
    void init(int n){
        rep(i,0,n){
            par[i] = i;
            ran[i] = 0;
        }
    }
    int _find(int x){
        if(par[x] == x){
            return x;
        } else {
            return par[x] = _find(par[x]);
        }
    }
    void unite(int x,int y){
        x = _find(x);
        y = _find(y);
        if(x==y)return;

        if(ran[x] < ran[y]) {
            par[x] = y;
        } else {
            par[y] = x;
            if(ran[x] == ran[y]){
                ran[x]++;
            }
        }
    }
    bool same(int x,int y){
        return _find(x) == _find(y);
    }
};\
