	REPU(i, 1, n + 1) {
		mp[uf1.find(i)].push_back(i);
	}
	UF uf2(n);
	REPU(_, 0, l) {
		int r, s; cin >> r >> s;
		uf2.unite(r, s);
	}
	unordered_map<int, vector<int>> sub;
