pair<vl,vvl> comps(vvl adj) {
	ll n = sz(adj);
	vb mark(n);
	vvl comps;
	vl c(n,-1);
	ll C = 0;
	FOR(i,0,n) if (!mark[i]) {
		queue<ll> q;
		q.push(i);
		mark[i] = true;
		vl comp = {i};
		c[i] = C;
		while (sz(q)) {
			ll j = q.front(); q.pop();
			for (ll k: adj[j]) if (c[k] == -1)
					c[k] = C, q.push(k), comp.pb(k), mark[k] = true;
		}
		comps.pb(comp);
		C++;
	}
	return {c,comps};
}


