class UnionFind {
public:
  vector<int> r, p, s;
  UnionFind(int N)
  {
    for (int i = 0; i < N; ++i) {
      r.push_back(0);
      p.push_back(i);
      s.push_back(1);
    }
  }
  void unite(int a, int b)
  {
    int z = is_same_set(a, b) ? size(a) : size(a) + size(b);
    link(find(a), find(b));
    s[find(a)] = z;
  }
  int find(int a)
  {
    return (a == p[a]) ? a : p[a] = find(p[a]);
  }
  bool is_same_set(int a, int b)
  {
    return find(a) == find(b);
  }
  size_t size(int x)
  {
    return s[find(x)];
  }
  void link(int a, int b)
  {
    if (r[a] > r[b]) {
      p[b] = a;
    } else {
      p[a] = b;
      if(r[a] == r[b]) r[b]++;
    }
  }
};

