			}
			else
			{
				st2[par[i+n]].erase(it);
				g[x]=sg;
				ans[sg]++;
				vis[x]=true;
			}
		}
		st1[par[i]]=stt;
	}
	for(int i=1;i<=n;i++)
	{
		printf("%d ",ans[g[i]]);
	}
}

