    p--;
    q--;
    road.unite(p, q);
  }

  for (int i = 0; i < L; i++) {
    int r, s;
    cin >> r >> s;
    r--;
    s--;
    train.unite(r, s);
  }

  Counter<pair<int, int>> c;
  for (int i = 0; i < N; i++) {
    c.add(make_pair(road.par[i], train.par[i]));
  }

  for (int i = 0; i < N; i++) {
    cout << c.get(make_pair(road.par[i], train.par[i]));
    if (i < N - 1) {
      cout << " ";
    }
  }
  cout << endl;
  return 0;
}

