using namespace std;

int find(int x, int par[], int ran[]) {
    if (x == par[x])
        return x;
    return par[x] = find(par[x], par, ran);
}

void unite(int x, int y, int par[], int ran[]) {
    x = find(x, par, ran);
    y = find(y, par, ran);
    if (x == y)
        return;
    if (ran[x] < ran[y]) {
        par[x] = par[y];
    } else {
        par[y] = par[x];
        if (ran[x] == ran[y])
            ran[x]++;
    }
}


