int par_road[200001];
int rank_road[200001];
int par_train[200001];
int rank_train[200001];



struct PARENT{
    int num;
    int road;
    int train;
};

bool cmp(const PARENT a,const PARENT b){
    if(a.road==b.road){
        return a.train<b.train;
    }else{
        return a.road<b.road;
    }
}

void init(int n,int *par,int *rank){
    for(int i=0;i<n;i++){
        par[i]=i;
        rank[i]=0;
    }
}

int find(int x,int *par){
    if(par[x]==x){
        return x;
    }else{
        return par[x]=find(par[x],par);
    }
}

void unite(int x, int y,int *par,int *rank){
    x=find(x,par);
    y=find(y,par);
    if(x==y) return;

    if(rank[x]<rank[y]){
        par[x]=y;
    }else{
        par[y]=x;
        if(rank[x]==rank[y]){
            rank[x]++;
        }
    }
}

bool same(int x,int y,int *par){
    return find(x,par)==find(y,par);
}

int main(void) {
    int n,k,l;
    cin>>n>>k>>l;

    init(n,par_road,rank_road);
    init(n,par_train,rank_train);
    int p,q,r,s;
    for(int i=0;i<k;i++){
        cin>>p>>q;
        unite(p-1,q-1,par_road,rank_road);
    }
    for(int i=0;i<l;i++){
        cin>>r>>s;
        unite(r-1,s-1,par_train,rank_train);
    }
    PARENT *parent=new PARENT[n];
    for(int i=0;i<n;i++){
        parent[i].num=i;
        parent[i].road=par_road[i];
        parent[i].train=par_train[i];
    }




    sort(parent,parent+n,cmp);


    int *answer=new int[n];
    int memo_start=0,count=1;
    int i;

    for(i=1;i<n;i++){
        if(parent[i].road==parent[i-1].road && parent[i].train==parent[i-1].train){
            count++;
        }else{
            for(memo_start;memo_start<i;memo_start++){//memo_startは現在の位置を指して終わる
                answer[(parent[memo_start]).num]=count;
            }
            count=1;
        }
    }


    for(memo_start;memo_start<i;memo_start++){
        answer[parent[memo_start].num]=count;
    }

    for(int i=0;i<n;i++){
        cout<<answer[i]<<" ";
    }
    cout<<endl;

    return 0;
}

