struct UnionFind {
    vector<int> data;
    // data[i]はマイナスなら連結成分の要素数を表す
    //プラスならば親ノードを表す
    UnionFind(int sz) { data.assign(sz, -1); }

    bool unite(int x, int y) {
        x = find(x), y = find(y);
        if(x == y)
            return (false);
        if(data[x] > data[y])
            swap(x, y);
        data[x] += data[y];
        data[y] = x;
        return (true);
    }

    int find(int k) {
        if(data[k] < 0)
            return (k);
        return (data[k] = find(data[k]));
    }
    bool isSame(int x, int y) { return find(x) == find(y); }
    ll size(int k) { return (-data[find(k)]); }
};
int main() {
    int n, k, l;
    cin >> n >> k >> l;
    UnionFind uf1(n), uf2(n);
    for(size_t i = 0; i < k; i++) {
        int p, q;
        cin >> p >> q;
        p--, q--;
        uf1.unite(p, q);
    }
    for(size_t i = 0; i < l; i++) {
        int p, q;
        cin >> p >> q;
        p--, q--;
        if(uf1.isSame(p, q)) {
            uf2.unite(p, q);
        }
    }
    for(size_t i = 0; i < n; i++) {
        cout << uf2.size(i) << " ";
    }
    cout << endl;
}

