        par = vector<int>(n,-1);
    }
    inline int root(int x){
        if(par[x]<0){
            return x;
        }else{
            return par[x]=root(par[x]);
        }
    }
    void unite(int x,int y){
        x=root(x);
        y=root(y);
        if(x!=y){
            if(par[x]<par[y]) swap(x,y);
            /*REP(i,rtov[x].size()){
                rtov[y].push_back(rtov[x][i]);
            }*/
            copy(ALL(rtov[x]),back_inserter(rtov[y]));
            par[y] += par[x];
            par[x] = y;

        }
        return;
    }
    void unite2(int x,int y){
        x=root(x);
        y=root(y);
        if(x!=y){
            if(par[x]<par[y]) swap(x,y);
            /*REP(i,rtov[x].size()){
                rtov[y].push_back(rtov[x][i]);
            }*/
            par[y] += par[x];
            par[x] = y;

        }
        return;
    }
    inline bool same(int x,int y){
        return root(x) == root(y);
    }
    int size(int x){
        return -par[root(x)];
    }
};
