	scanf("%d%d", &K, &L);
	for (int i = 0; i < K; ++i) {
		int p, q;
		scanf("%d%d", &p, &q);
		edge1[p-1].push_back(q-1);
		edge1[q-1].push_back(p-1);
	}
	for (int i = 0; i < L; ++i) {
		int p, q;
		scanf("%d%d", &p, &q);
		edge2[p-1].push_back(q-1);
		edge2[q-1].push_back(p-1);
	}
	solve();

	return 0;
}

