const function<void(int)>& pre_node = [](int) {},
const function<void(typename graph::EType&)>& pre_edge = [](typename graph::EType&) {},
const function<void(typename graph::EType&)>& pos_edge = [](typename graph::EType&) {},
const function<void(int)>& pos_node = [](int) {},
int root = 0) {
    vector<bool> vis(g.size() + 1);
    function<void(int)> dfs = [&](int u) {
        vis[u] = true;
        pre_node(u);
        for(int i : g[u]) if(not vis[g(i).v]) {
            pre_edge(g(i)), dfs(g(i).v), pos_edge(g(i));
        }
        pos_node(u);
    };
    if(root) {
        dfs(root);
    } else {
        for(int u = 1; u <= g.size(); u++) if(not vis[u]) {
            dfs(u);
        }
    }
}
