const int MAXN = 200000;
const int MAXA = 100000;
const int MAXB = 100000;

int n, ma, mb;
int ahead[MAXN], anxt[2 * MAXA], ato[2 * MAXA];
int bhead[MAXN], bnxt[2 * MAXB], bto[2 * MAXB];

int par[MAXN], rnk[MAXN];
int find(int p) { if (par[p] == p) return p; return par[p] = find(par[p]); }
void unite(int p, int q) {
	p = find(p), q = find(q);
	if (p == q) return;
	if (rnk[q] > rnk[p]) swap(p, q);
	par[q] = p; if (rnk[p] == rnk[q]) ++rnk[p];
}

bool done[MAXN];
int q[MAXN], qhead, qtail;
int cnt[MAXN], mark[MAXN], curmark;
int ret[MAXN];

void run() {
	scanf("%d%d%d", &n, &ma, &mb);
	REP(i, n) ahead[i] = bhead[i]= -1;
	REP(i, ma) {
		int a, b; scanf("%d%d", &a, &b); --a, --b;
		anxt[2 * i + 0] = ahead[a]; ahead[a] = 2 * i + 0; ato[2 * i + 0] = b;
		anxt[2 * i + 1] = ahead[b]; ahead[b] = 2 * i + 1; ato[2 * i + 1] = a;
	}
	REP(i, mb) {
		int a, b; scanf("%d%d", &a, &b); --a, --b;
		bnxt[2 * i + 0] = bhead[a]; bhead[a] = 2 * i + 0; bto[2 * i + 0] = b;
		bnxt[2 * i + 1] = bhead[b]; bhead[b] = 2 * i + 1; bto[2 * i + 1] = a;
	}
	REP(i, n) par[i] = i, rnk[i] = 0;
	REP(i, ma) {
		int p = ato[2 * i + 1], q = ato[2 * i + 0];
		unite(p, q);
	}
	REP(i, n) done[i] = false, mark[i] = -1; curmark = -1;
	REP(s, n) if (!done[s]) {
		//printf("start at %d\n", s);
		qhead = qtail = 0; ++curmark; q[qhead++] = s; done[s] = true;
		while (qtail < qhead) {
			int at = q[qtail++];
			for (int x = bhead[at]; x != -1; x = bnxt[x]) {
				int to = bto[x];
				if (!done[to]) q[qhead++] = to, done[to] = true;
			}
		}
		int nq = qhead;
		REP(i, nq) {
			int at = q[i], x = find(at);
			if (mark[x] != curmark) mark[x] = curmark, cnt[x] = 0;
			++cnt[x];
		}
		REP(i, nq) {
			int at = q[i], x = find(at);
			//printf("\t%d = %d (%d)\n", at, cnt[x], x);
			ret[at] = cnt[x];
		}
	}
	REP(i, n) { if (i != 0) printf(" "); printf("%d", ret[i]); } puts("");
}


int main() {
	run();
	return 0;
}

