  void unite(ll x, ll y){
    ll rx=root(x), ry=root(y);
    if(rx==ry)
      return;
    par[ry]=rx;
    siz[rx]+=siz[ry];    
  }

  bool issame(ll x, ll y){
    return root(x)==root(y);
  }

  ll size(ll x){
    return siz[root(x)];
  }
};

