void bfs(std::vector<std::list<unsigned>> &graph,
         unsigned index,
         std::vector<bool> &watch,
         std::list<unsigned> &group) {
  watch[index] = true;
  group.push_back(index);
  for (auto &i : graph[index]) {
    if (!watch[i]) {
      bfs(graph, i, watch, group);
    }
  }
}

int main() {
  unsigned N, K, L;
  std::cin >> N >> K >> L;
  std::vector<std::list<unsigned>> load(N + 1);
  std::vector<std::list<unsigned>> train(N + 1);
  std::vector<bool> watch(N + 1, false);
  for (unsigned i = 0; i < K; ++i) {
    unsigned p, q;
    std::cin >> p >> q;
    load[p].push_back(q);
    load[q].push_back(p);
  }
  for (unsigned i = 0; i < L; ++i) {
    unsigned r, s;
    std::cin >> r >> s;
    train[r].push_back(s);
    train[s].push_back(r);
  }
  std::list<unsigned> group;
  std::vector<unsigned> load_group(N + 1);
  std::vector<unsigned> train_group(N + 1);
  unsigned foo = 0u;
  for (unsigned i = 1; i <= N; ++i) {
    if (!watch[i]) {
      ++foo;
      group.clear();
      bfs(load, i, watch, group);
      for (const auto &j : group) {
        load_group[j] = foo;
      }
    }
  }
  foo = 0u;
  for (unsigned i = 1; i <= N; ++i) {
    watch[i] = false;
  }
  for (unsigned i = 1; i <= N; ++i) {
    if (!watch[i]) {
      ++foo;
      group.clear();
      bfs(train, i, watch, group);
      for (const auto &j : group) {
        train_group[j] = foo;
      }
    }
  }
  std::vector<unsigned> ans(N + 1, 0u);
  for (unsigned i = 1; i <= N; ++i) {
    if (ans[i] == 0u) {
      group.clear();
      unsigned ret = 0u;
      for (unsigned j = 1; j <= N; ++j) {
        if (load_group[i] == load_group[j] && train_group[i] == train_group[j]) {
          group.push_back(j);
          ++ret;
        }
      }
      for (const auto &j : group) {
        ans[j] = ret;
      }
    }
  }
  for (unsigned i = 1; i < N; ++i) {
    std::cout << ans[i] << " ";
  }
  std::cout << ans[N];
  return 0;
}

