class union_find{
private:
  int p[200000];
  int r[200000];

  int find(int x){
    if(p[x] == x){
      return x;
    }else{
      return p[x] = find(p[x]);
    }
  }
public:
  union_find(int n){
    for(int i=0;i < n;i++){
      p[i] = i;
      r[i] = 0;
    }
  }
  void unite(int x, int y){
    x = find(x);
    y = find(y);
    if(x == y) return;

    if(r[x] < r[y]){
      p[x] = y;
    }else{
      p[y] = x;
      if(r[x] == r[y]) r[x]++;
    }
  }
  bool same(int x, int y){
    return find(x) == find(y);
  }
};
int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);
	int n, k, l;
  cin >> n >> k >> l;
  union_find road(n);
  rep(i,k){
    int p, q;
    cin >> p >> q;
    road.unite(p-1, q-1);
  }
  union_find line(n);
  rep(i,l){
    int r, s;
    cin >> r >> s;
    line.unite(r-1, s-1);
  }

  vi ans(n);
  rep(i,n){
    for(int j=i;j < n;j++){
      if(road.same(i,j) && line.same(i,j)){
        ans[i]++;
        ans[j]++;
      }
    }
  }
  rep(i,n) cout << ans[i]-1 << " ";
  cout << endl;

	return 0;
}

