class UnionFind {
	vector<int> data;
	int root(int a) {
		return data[a] < 0 ? a : data[a] = root(data[a]);
	}
public:
	UnionFind(int n) : data(n, -1) {}
	bool Find(int a, int b) {
		return root(a) == root(b);
	}
	void Union(int a, int b) {
		int ra = root(a), rb = root(b);
		if (ra == rb) return;
		if (data[ra] < data[rb]) {
			data[ra] += data[rb];
			data[rb] = a;
		}
		else {
			data[rb] += data[ra];
			data[ra] = b;
		}
	}
	int size(int a) {
		return -data[root(a)];
	}
};

int main()
{
	int N, K, L;
	cin >> N >> K >> L;
	UnionFind road(N), train(N), dou(N);
	vector<int> PP(K), QQ(K), P(L), Q(L);
	for (int i = 0; i < K; i++) {
		cin >> PP[i] >> QQ[i];
		road.Union(PP[i] - 1, QQ[i] - 1);
	}
	for (int i = 0; i < L; i++) {
		cin >> P[i] >> Q[i];
		train.Union(P[i] - 1, Q[i] - 1);
	}
	while (K--) {
		if (train.Find(PP[K] - 1, QQ[K] - 1)) {
			dou.Union(PP[K] - 1, QQ[K] - 1);
		}
	}
	while (L--) {
		if (road.Find(P[L] - 1, Q[L] - 1)) {
			dou.Union(P[L] - 1, Q[L] - 1);
		}
	}
	for (int i = 0; i < N - 1; i++) {
		cout << dou.size(i) << ' ';
	}
	cout << dou.size(N - 1) << endl;
	return 0;
}

