void init(int n)
{
	for(int i=1;i<=2*n;i++)
	{
		par[i] = i;
		rank[i] = 0;
	}
	memset(num,0,sizeof num);
}

int find(int x)
{
	if(par[x] == x)
	return x;
	return par[x] = find(par[x]);
}

void unite(int x,int y)
{
	x = find(x);
	y = find(y);
	if(x == y)
	return ;
	if(rank[x] < rank[y])
	par[x] = y;
	else 
	{
		par[y] = x;
		if(rank[x] == rank[y])
		rank[x]++;
	}
}

bool same(int x,int y)
{
	return find(x) == find(y);
}

