typedef long long ll;

struct UnionFind{
	vector<int> par;
	vector< set<int> > dat;
	UnionFind(int n)
		:par(n + 1,0),dat(n + 1,set<int>()){
			for(int i = 1;i <= n;i++){
				par [i] = i;
				dat [i].insert(i);
			}
		}
	int find(int x){
		if(par [x] == x) return x;
		return par [x] = find(par [x]);
	}
	bool connect(int x,int y){
		x = find(x),y = find(y);
		if(x == y) return false;
		if(dat [x].size() < dat [y].size()) swap(x,y);
		par [y] = x;
		for(auto it : dat [y]){
			dat [x].insert(it);
		}
		return true;
	}
	set<int>& getData(int x){
		return dat [find(x)];
	}
};

int N,K,L;

int main()
{
	scanf("%d%d%d",&N,&K,&L);
	UnionFind x(N),y(N);
	FOR(i,0,K){
		int p,q;
		scanf("%d%d",&p,&q);
		x.connect(p,q);
	}
	FOR(i,0,L){
		int r,s;
		scanf("%d%d",&r,&s);
		y.connect(r,s);
	}

	vector<int> ans(N + 1);
	for(int i = 1;i <= N;i++) if(ans [i] == 0){
		set<int> st;
		for(auto it : x.getData(i)){
			if(y.getData(i).count(it)){
				st.insert(it);
			}
		}
		for(auto it : st){
			ans [it] = st.size();
		}
	}
	for(int i = 1;i <= N;i++){
		printf("%d%s",ans [i],i == N ? "\n" : " ");
	}

	return 0;
}

