        if(road_gr_dic.count(i)) continue;
        queue<int> q;
        q.push(i);
        set<int> gr;
        while(q.size()) {
            auto f = q.front(); q.pop();
            gr.insert(f);
            road_gr_dic.insert(make_pair(f, road_gr_list.size()));
            for(auto&& n:ROAD[f]) {
                if(road_gr_dic.count(n)) continue;
                q.push(n);
            }
        }
        road_gr_list.push_back(gr);
    }

    map<int,int> rail_gr_dic;
    vector<set<int>> rail_gr_list;
    for (size_t i = 1; i <= N; ++i) {
        if(rail_gr_dic.count(i)) continue;
        queue<int> q;
        q.push(i);
        set<int> gr;
