            auto f = q.front(); q.pop();
            gr.insert(f);
            rail_gr_dic.insert(make_pair(f, rail_gr_list.size()));
            for(auto&& n:RAIL[f]) {
                if(rail_gr_dic.count(n)) continue;
                q.push(n);
            }
        }
        rail_gr_list.push_back(gr);
    }

