    for(auto&& road_set:road_gr_list){
        for(auto&& rail_set:rail_gr_list){
            vector<int> vs;
            set_intersection(road_set.begin(), road_set.end(), rail_set.begin(), rail_set.end(), back_inserter(vs));
            for(auto &&v:vs) ans_dic[v] = vs.size();
        }
