#include <bits/stdc++.h>
using namespace std;

long long int N, K, L, p, q, a, i, fi;
long long int parr[200000], rankr[200000], part[200000], rankt[200000];
map<pair<long long int, long long int>, vector<long long int> > mp;

void shokika(long long int* par, long long int* ran, long long int n){
    for(fi = 0; fi < n; ++fi){
        par[fi] = fi;
        ran[fi] = 0;
    }
}

inline long long int finr(long long int* par, long long int n){
    if(par[n] == n){
        return n;
    }else{
        return par[n] = finr(par, par[n]);
    }
}

inline void union_(long long int* par, long long int* ran, long long int x, long long int y){
    x = finr(par, x);
    y = finr(par, y);
    if(x == y) return;
    if(ran[x] < ran[y]){
        par[x] = y;
    }else{
        par[y] = x;
        if(ran[x] == ran[y])ran[x]++;
    }
}

inline bool same(long long int* par, long long int x, long long int y){
    return finr(par, x) == finr(par, y);
}

int main(){
    scanf("%lld%lld%lld", &N, &K, &L);
    shokika(parr, rankr, N);
    shokika(part, rankt, N);
    for(i = 0; i < K; ++i){
        scanf("%lld%lld", &p, &q);
        union_(parr, rankr, p - 1, q - 1);
    }
    for(i = 0; i < L; ++i){
        scanf("%lld%lld", &p, &q);
        union_(part, rankt, p - 1, q - 1);
    }
    for(i = 0; i < N; ++i){
        mp[make_pair(finr(parr, i), finr(part, i))].push_back(i);
    }
    for(i = 0; i < N; ++i){
        cout << mp[make_pair(parr[i], part[i])].size() << (i==N-1?"\n":" ");
    }
    return 0;
}

