using namespace std;

const int MAX_N = 2 * 100000 + 5;

class uni{
public:

	int par[MAX_N]; // 親
	int rank[MAX_N]; // 木の深さ 

	uni(int n){
		for(int i = 0; i < n; i++){
			par[i] = i;
			rank[i] = 0;
		}
	}

	int find(int x){
		if (par[x] == x){
			return x;
		} else {
			return par[x] = find(par[x]);
		}
	}

	void unite(int x, int y){
		x = find(x);
		y = find(y);
		if(x == y) return;

		if(rank[x] < rank[y]){
			par[x] = y;
		} else {
			par[y] = x;
			if(rank[x] == rank[y])
				rank[x]++;
		}
	}

	bool same(int x, int y){
		return find(x) == find(y);
	}
};

void solve(){
	int N, K, L;
	map<pair<int, int>,int> count;
	cin >> N >> K >> L;

	uni a(N);
	uni b(N);

	for(int i = 0; i < K; i++){
		int p,q;
		cin >> p >> q;
		a.unite(p-1, q-1);
	}

	for(int i = 0; i < L; i++){
		int p,q;
		cin >> p >> q;
		b.unite(p-1, q-1);
	}

	for(int i = 0; i < N; i++){
		count[make_pair(a.find(i), b.find(i))]++;
	}

	for(int i = 0; i < N; i++){
		cout<< count[make_pair(a.find(i), b.find(i))];
		if(i != N-1){
			cout << " ";
		}else{
			cout << endl;
		}
	}
}

int main(){
	solve();
	return 0;
}

#include <bits/stdc++.h>

using namespace std;
typedef long long int lli;

const int MAXN = 200010;

int n, k, l;

int ind[MAXN];
int ans[MAXN];
int freq[MAXN];

bool marc[MAXN][2];

vector< int > component;

vector< int > adj[MAXN][2];

void DFS(int cur, int t, int root = 0)
{
	marc[cur][t] = true;

	if( t == 0 ) ind[ cur ] = root;
	else component.push_back( cur );

	for(int i = 0 ; i < adj[cur][t].size() ; i++)
	{
		int viz = adj[cur][t][i];

		if( !marc[viz][t] ) DFS( viz , t , root );
	}
}

int main()
{
	scanf("%d %d %d",&n,&k,&l);

	for(int i = 1 ; i <= k ; i++)
	{
		int U, V;
		scanf("%d %d",&U,&V);

		adj[ U ][0].push_back( V );
		adj[ V ][0].push_back( U );
	}

	for(int i = 1 ; i <= l ; i++)
	{
		int U, V;
		scanf("%d %d",&U,&V);

		adj[ U ][1].push_back( V );
		adj[ V ][1].push_back( U );
	}

	for(int i = 1 ; i <= n ; i++)
		if( !marc[i][0] ) DFS( i , 0 , i );

	for(int i = 1 ; i <= n ; i++)
	{
		if( marc[i][1] ) continue;

		DFS( i , 1 );

		for(int j = 0 ; j < component.size() ; j++)
		{
			int cur = component[j];
			freq[ ind[cur] ]++;
		}

		for(int j = 0 ; j < component.size() ; j++)
		{
			int cur = component[j];
			ans[cur] = freq[ ind[cur] ];
		}

		for(int j = 0 ; j < component.size() ; j++)
		{
			int cur = component[j];
			freq[ ind[cur] ]--;
		}

		component.clear();
	}

	for(int i = 1 ; i <= n ; i++)
		printf("%d ",ans[i]);
}

#include <cstdio>
#include <vector>

enum {
  MAXN = 200000 + 5
};

struct DSU {
  static const int MAXSIZE = MAXN;
  int fa[MAXSIZE];
  DSU() {
    int i;
    for (i=0; i<MAXSIZE; ++i)
      fa[i] = i;
  }
  int find(int x) {
    return x == fa[x]? x : fa[x] = find(fa[x]);
  }
  void link(int u, int v) {
    u = find(u);
    v = find(v);
    fa[u] = v;
  }
} t1, t2;

int n, k, l;
std::vector<int> vec[MAXN];
int sum[MAXN];
int ans[MAXN];

void exec() {
  int i, u, v, j;
  scanf("%d%d%d", &n, &k, &l);
  for (i=0; i<k; ++i) {
    scanf("%d%d", &u, &v), --u, --v;
    t1.link(u, v);
  }
  for (i=0; i<l; ++i) {
    scanf("%d%d", &u, &v), --u, --v;
    t2.link(u, v);
  }
  for (u=0; u<n; ++u)
    vec[t1.find(u)].push_back(u);
  for (i=0; i<n; ++i) {
    for (j=0; j<(int) vec[i].size(); ++j)
      sum[t2.find(vec[i][j])] = 0;
    for (j=0; j<(int) vec[i].size(); ++j)
      ++ sum[t2.find(vec[i][j])];
    for (j=0; j<(int) vec[i].size(); ++j)
      ans[vec[i][j]] = sum[t2.find(vec[i][j])];
  }
  for (u=0; u<n; ++u)
    printf("%d%c", ans[u], " \n"[u+1 == n]);
}

int main() {
  if (fopen("D.in", "r") != NULL) {
    freopen("D.in", "r", stdin);
    freopen("D.out", "w", stdout);
  }
  exec();
