class UnionFind
{
public:
    //以下公開

    //親の番号を格納する。親である場合は-(その集合のサイズ)
    vector<ll> Parent;

    //作るときはParentの値を全て-1にする
    //こうすると全てバラバラになる
    UnionFind(ll N)
    {
        Parent = vector<ll>(N, -1);
    }

    //Aがどのグループに属しているか調べる
    ll root(ll A)
    {
        if (Parent[A] < 0)
            return A;
        return Parent[A] = root(Parent[A]);
    } //代入しておくことで参照を速くする

    //自分のいるグループの頂点数を調べる
    ll size(ll A)
    {
        return -Parent[root(A)];
    } //親である場合は-(その集合のサイズ)なので、Ａの親の

    //AとBをくっ付ける
    bool connect(ll A, ll B)
    {
        //AとBを直接つなぐのではなく、root(A)にroot(B)をくっつける
        A = root(A);
        B = root(B);
        if (A == B)
        {
            //すでにくっついてるからくっ付けない
            return false;
        }

        //大きい方(A)に小さいほう(B)をくっ付けたい
        //大小が逆だったらひっくり返しちゃう。
        if (size(A) < size(B))
            swap(A, B);

        //Aのサイズを更新する
        Parent[A] += Parent[B];
        //Bの親をAに変更する
        Parent[B] = A;

        return true;
    }

    bool same(ll A, ll B)
    {
        return root(A) == root(B);
    }
};

signed main()
{
    ll n, k, l, cnt = 1;
    cin >> n >> k >> l;
    UnionFind UnionFind(n + 1), UF(n + 1);

    rep(i, k)
    {
        ll p, q;
        cin >> p >> q;
        UnionFind.connect(p, q);
    }

    rep(i, l)
    {
        ll r, s;
        cin >> r >> s;
        UF.connect(r, s);
    }

    vector<P> v;
    map<P, int> ap;

    for (ll i = 1; i <= n; i++)
    {
        v.pb({UnionFind.root(i), UF.root(i)});
    }
    sort(all(v));

    for (int i = 0; i < siz(v) - 1; i++)
    {
        P next = v[i + 1];
        if (next == v[i])
            cnt++;
        else
        {
            ap[v[i]] = cnt;
            cnt = 1;
        }
    }
    ap[v[siz(v) - 1]] = cnt;

    for (int i = 1; i <= n; i++)
    {
        cout << ap[{UnionFind.root(i), UF.root(i)}] << (i == n ? '\n' : ' ');
    }
}

#include<bits/stdc++.h>
using namespace std;
const int MAX_N=200009;

struct unionfind{
  int par[MAX_N];
  int myrank[MAX_N];
  int size[MAX_N];
  void init(int n){
    for(int i=1;i<=n;i++){par[i]=i; myrank[i]=0; size[i]=1;}
  }
  int find(int x){
    if(par[x]==x){return x;}
    else{return par[x]=find(par[x]);}
  }
  void unite(int x, int y){
    x=find(x); y=find(y);
    if(x==y){return;}
    if(myrank[x]<myrank[y]){par[x]=y; size[y]+=size[x];}
    else{par[y]=x; size[x]+=size[y];}
    if(myrank[x]==myrank[y]){myrank[x]++;}
  }
  bool same(int x, int y){return find(x)==find(y);}
};

int main(){
