const ll mod = 1e9 + 7;

int find(int i, vector<int> &par)
{
  if (par[i] == i)
    return i;
  else
    return par[i] = find(par[i], par);
}

void merge(int i, int j, vector<int> &par, vector<int> &rank)
{
  int x = find(i,par);
  int y = find(j,par);
  if (x != y) 
    {
      if (rank[x] > rank[y]) 
    	{
    	  par[y] = x;
    	  rank[x] += rank[y];
    	}
      else 
    	{
    	  par[x] = y;
    	  rank[y] += rank[x];
    	}	  
    }
}

