        comp[i] = -1;
        sz[i] = 0;
    }
    int curcomp = 0;
    vector<int> cities;
    for(int i = 0; i < n; i++)
        if(!visited[i])
        {
            dfs(i, 0, curcomp, cities);
            curcomp++;
        }
    assert(cities.empty());
    for(int i = 0; i < n; i++)
        visited[i] = 0;
    for(int i = 0; i < n; i++)
        if(!visited[i])
        {
            dfs(i, 1, -1, cities);
