void Create()
{
    int i;
    int x,y;
    for(i=1; i<=city; ++i)
    {
        road_cont[0][i]=road_cont[1][i]=i;
    }
    for(i=1; i<=n_road; ++i)
    {
        scanf("%d%d",&x,&y);

        int f1=Find(0,x);
        int f2=Find(0,y);
        if(f1!=f2) join(0,f1,f2);
    }
    for(i=1; i<=n_rail; ++i)
    {
        scanf("%d%d",&x,&y);

        int f1=Find(1,x);
        int f2=Find(1,y);
        if(f1!=f2) join(1,f1,f2);
    }
}

int main()
{
    scanf("%d%d%d",&city,&n_road,&n_rail);
    Create();
    for(int j=1; j<=city; ++j)
    {
        way_cont[0][Find(0,j)].insert(j);
    }
    //公路
    for(int j=1; j<=city; ++j)
    {
        way_cont[1][Find(1,j)].insert(j);
    }
    //火车
    for(int i=1; i<=city&&!visit[i]; i++)
    {
        int top=0;
        int Root1,Root2;
        Root1=Find(0,i);
        Root2=Find(1,i);
        bool ok;
        if(way_cont[0][Root1].size() > way_cont[1][Root2].size())
        {
            ok=1;
            temp_cont=way_cont[1][Root2];
        }
        else
        {
            ok=0;
            temp_cont=way_cont[0][Root1];
        }

        int Roots[2]= {Root1,Root2};
        for(it=temp_cont.begin(); it!=temp_cont.end(); ++it)
        {
            int p=*it;
            if(way_cont[!ok][Roots[!ok]].find(p)!=way_cont[!ok][Roots[!ok]].end())
            {
                path[++top]=(p);
                visit[p]=1;

                way_cont[ok][Roots[ok]].erase(p);
                way_cont[!ok][Roots[!ok]].erase(p);
            }
        }
        for(int j=1; j<=top; ++j)
        {
            cont[path[j]]=top;
        }
    }
    for(int i=1; i<=city; ++i)
    {
        if(i!=1)printf(" ");
        printf("%d",cont[i]);
    }
    return 0;
}

