class UnionFind {
public:
  vector<int> data;
  vector<int> sizes;
  UnionFind(int size) {
    data.resize(size, 0);
    sizes.resize(size, 0);
    for(int i=0; i<size; i++) data[i] = i;
  }
  int find(int x) {
    if(x == data[x]) return x;
    return data[x] = find(data[x]);
  }
  void unite(int x, int y){
    x = find(x);
    y = find(y);
    if( x == y ) return;
    if( sizes[x] < sizes[y] ) swap(x, y);
    data[y] = x;
    sizes[x] += sizes[y];
  }
  bool same(int x, int y){
    return find(x) == find(y);
  }

};

