{
    int parent[200010];
    int rank[200010];
    int cnt[200010];
    int comp;
    void init(lli N){
        for(int i=1;i<=N;i++){
            rank[i] = 0;
            parent[i] = i;
            cnt[i] = 1;
        }
        comp = N;
    }
    lli Find(lli u){
        if(parent[u]!=u) parent[u]=Find(parent[u]);
        return parent[u];
    }
    void Union(lli u,lli v){
        lli pv=Find(v),pu=Find(u);
        if(pu==pv) return;
        if(rank[u]>rank[v]) parent[pv]=pu,cnt[pu]+=cnt[pv];
        else parent[pu]=pv,cnt[pv]+=cnt[pu];
        if(rank[u]==rank[v]) rank[pv]++;
        comp--;
    }
};

