struct Node
{
    int rank = 0;
    int parent = 0;
};

int get_parent(Node node[], int x)
{
    if(node[x].parent == 0)
        return x;
    return get_parent(node, node[x].parent);
}

void Union(Node node[], int a,int b)
{
    a = get_parent(node, a);
    b = get_parent(node, b);
    if (a == b) return;
    if(node[a].rank > node[b].rank)
        node[b].parent = a;
    else
    {
        node[a].parent = b;
        if(node[a].rank == node[b].rank)
            node[b].rank++;
    }
}

