	{
		set<int> explored = bfs(road, checkedId);

		while (checked[checkedId])
			++checkedId;

		roadComponents.push_back(explored);
	}

	for (int i = 1; i <= N; ++i)
	{
		checked[i] = false;
	}

	checkedId = 1;
	while (checkedId <= N)
	{
		set<int> explored = bfs(rail, checkedId);

		while (checked[checkedId])
			++checkedId;

		railComponents.push_back(explored);
	}

	for (int i = 0; i < roadComponents.size(); ++i)
	{
		for (int j = 0; j < railComponents.size(); ++j)
		{
			vector<int>::iterator itEnd = set_intersection(roadComponents[i].begin(), roadComponents[i].end(),
				railComponents[j].begin(), railComponents[j].end(), intersectV.begin());
			int intersectSize = itEnd - intersectV.begin();
			for (vector<int>::iterator it = intersectV.begin(); it != itEnd; ++it)
			{
				results[*it] += intersectSize;
			}
		}
	}


	for (int i = 1; i <= N; ++i)
