using namespace std;
typedef pair<int, int>P;

class UnionFind {
	vector<int>par, high;
public:
	UnionFind(int n) {
		par = high = vector<int>(n);
		for (int i = 0; i < n; i++)par[i] = i;
	}
	int find(int x) {
		if (par[x] == x)return x;
		return par[x] = find(par[x]);
	}
	void unite(int x, int y) {
		x = find(x); y = find(y);
		if (x == y)return;
		if (high[x] > high[y]) {
			par[y] = x;
		}
		else {
			par[x] = y;
			if (high[x] == high[y])high[y]++;
		}
	}
	bool same(int x, int y) {
		return find(x) == find(y);
	}
};
unordered_map<int, unordered_map<int, int>>E;
int main() {
	int n, k, l; scanf("%d%d%d", &n, &k, &l);
	UnionFind road(n), rail(n);
	rep(i, k) {
		int p, q; scanf("%d%d", &p, &q); p--; q--;
		road.unite(p, q);
	}
	rep(i, l) {
		int r, s; scanf("%d%d", &r, &s); r--; s--;
		rail.unite(r, s);
	}
	rep(i, n) {
		E[road.find(i)][rail.find(i)]++;
	}
	rep(i, n) {
		printf("%d", E[road.find(i)][rail.find(i)]);
		if (i == n - 1)printf("\n");
		else printf(" ");
	}
}

#include<bits/stdc++.h>
using namespace std;

#define pb push_back
int mark[200009][2],cnt[200009];
vector<int>bfsroad(int source,vector<int>ed[],int m)
{
    int i,j,k,u,v,sz;
    queue<int>q;
    q.push(source);
    mark[source][0]=m;
    vector<int>ans;
    ans.pb(source);
    while(!q.empty())
    {
        u=q.front();
        q.pop();
        sz=ed[u].size();
        for(i=0;i<sz;i++)
        {
            v=ed[u][i];
            if(mark[v][0]==0)
            {
                mark[v][0]=m;
                q.push(v);
                ans.pb(v);
            }
        }
    }
    return ans;
}
vector<int> bfsrail(int source,vector<int>ed[],int m,int n)
{
    int i,j,u,v,sz;
    queue<int>q;
    vector<int>ans;
    ans.pb(source);
    q.push(source);
    mark[source][1]=n;
    while(!q.empty())
    {
        u=q.front();
        q.pop();
        sz=ed[u].size();
        for(i=0;i<sz;i++)
        {
        v=ed[u][i];
            if(mark[v][0]==m && mark[v][1]==0)
            {
                mark[v][1]=n;
                q.push(v);
                ans.pb(v);
            }
        }
    }

    return ans;

}

int main()
{
