    for(i=0;i<k;i++)
    {
        cin >> node1 >> node2;
        roads[node1].pb(node2);
        roads[node2].pb(node1);
    }
    for(i=0;i<l;i++)
    {
        cin >> node1 >> node2;
        rail[node1].pb(node2);
        rail[node2].pb(node1);
    }
    int m=0,n=0;
    vector<int>rd,rl;
    for(i=1;i<=nodes;i++)
    {
        if(mark[i][0]==0)
        {
            m++;
            rd=bfsroad(i,roads,m);

            sz=rd.size();
            for(j=0;j<sz;j++)
            {

                if(mark[rd[j]][1]==0)
                {
                    n++;
                    rl = bfsrail(rd[j],rail,m,n);
                    sz2 = rl.size();

                    for(k=0;k<sz2;k++)
