}
void Aunite(int a,int  b) {
	A[Apar(a)] = Apar(b);
	Asize[Apar(b)] = Asize[Apar(b)] + Asize[Apar(a)];
	return;
}
int  Bpar(int a) {
	int x = a;
	int y = a;
	while (B[x] != x) {
		x = B[x];
	}
	while (B[y] != y) {
		int z = B[y];
		B[y] = x;
		y = z;
	}
	return x;
}
bool Bfind(int a, int b) {
	return Bpar(a) == Bpar(b);
}
