const int N = 2e5 + 5;

int n, m, k, par[N], sz[N], ans[N];
vector <int> vec, adj[N];
bool mark[N];

int root(int v) {
	return ((par[v] == v)? v : par[v] = root(par[v]));
}

void merge(int v, int u) {
	v = root(v), u = root(u);
	if(v == u)
		return;
	if(sz[u] < sz[v])
		swap(v, u);
	sz[u] += sz[v];
	par[v] = u;
}

void dfs(int v) {
	mark[v] = true;
	for (auto u : adj[v])
		if(!mark[u] && root(v) == root(u))
