    par1[y]=x;
    len1[x]++;
  }
  else{
    par1[x]=y;
    len1[y]++;
  }
  return;
}
void unit2(int x,int y){
  x=root2(x);y=root2(y);
  if(x==y)return;
  if(len2[x]>len2[y]){
    par2[y]=x;
    len2[x]++;
  }
