/*** UnionFindクラス ***/
class UnionFind {
private:
    //uni[i]<0ならばiが親，そうでなければfind(uni[i])が親
    vector<int> uni;
    //グループ数
    int SIZE;
public:

    UnionFind(int size) {
        //初期状態では全ノード-1に設定し，よってすべてが親
        this->uni.resize(size, -1);
        this->SIZE = size;
    }
     UnionFind() {}
     void resize(int size) {
         this->uni.resize(size, -1);
         this->SIZE = size;
     }

    //xの親を返す
    int find(int x) {
        //uni[x]<0なのでxは親
        if (uni[x] < 0) return x;
        //uni[x]に親ノードを入れることで連続での探索時間の短縮
        return uni[x] = find(uni[x]);
    }

    //xとyが同じグループならばtrue
    bool same(int x, int y) {
        //xとyの親が同じならば同じグループに属するといえる
        return find(x) == find(y);
    }

    //xとyがそれぞれ属するグループを併合
    //併合処理を行ったならばtrueを返す
    //xとyがもともと同じグループならばfalseを返す
    bool unite(int x, int y) {
        x = find(x); y = find(y);
        if (x == y) return false;
        //木の深さが小さいノードから大きいノードへ辺をはる
        if (uni[x] > uni[y]) swap(x, y);
        //yのグループをxに足す
        uni[x] += uni[y];
        //yの親をxとする
        uni[y] = x;
        this->SIZE--;
        return true;
    }

    //グループ数を返す
    int size() {
        return this->SIZE;
    }

    //xが属するグループのノード数を返す
    int size(int x) {
        return -uni[find(x)];
    }
};

const int MAX = (2 * 1e5)+5;

int N, K, L;
VI graph2[MAX];
UnionFind uf(MAX);
int cnt[MAX];

int dfs(int now, int prev) {
    if (cnt[now] != -1) return cnt[now];
    int res = 0;
    int cc = 0;
    FORE(e, graph2[now]) {
        if (!uf.same(now, e)) continue;
        if (e == prev) {
            cc++;
            continue;
        }
        res += dfs(e, now);
    }
    return cnt[now] = res + cc;
}

int main(void) {
    scanf("%d%d%d", &N, &K, &L);
    REP(i, K) {
        int a, b;
        scanf("%d%d", &a, &b);
        a--;b--;
        uf.unite(a, b);
    }
    REP(i, L) {
        int a, b;
        scanf("%d%d", &a, &b);
        a--;b--;
        graph2[a].EB(b);
        graph2[b].EB(a);
    }
    REP(i, N) cnt[i] = -1;
    REP(i, N) dfs(i, -1);
    REP(i, N) {
        printf("%d", cnt[i] != -1 ? cnt[i] + 1: 1);
        if (i != N - 1) printf(" ");
    }
    printf("\n");
    //while (true);
}

