using namespace std;

using ll = long long;
using p  = pair<ll, ll>;
constexpr ll INF = 1LL << 62;

ll N, K, L;
unordered_map<ll, vector<ll> > road, line;

void patrol(ll node, unordered_map<ll, vector<ll> >& graph, vector<bool>& used) {
    used[node] = true;

    for (auto next : graph[node]) {
        if (!used[next]) {
            patrol(next, graph, used);
        }
    }
}

int main(void) {
    cin.tie(0);
    ios::sync_with_stdio(false);

    cin >> N >> K >> L;

    for (ll i = 0; i < K; i++) {
        ll from, to;
        cin >> from >> to;
        road[from].push_back(to);
        road[to].push_back(from);
    }

    for (ll i = 0; i < L; i++) {
        ll from, to;
        cin >> from >> to;
        line[from].push_back(to);
        line[to].push_back(from);
    }

    vector<ll> road_link(N + 1), line_link(N + 1);

    vector<bool> road_used(N + 1, false), line_used(N + 1, false);
    for (ll i = 1; i <= N; i++) {
        if (!road_used[i]) {
            auto old = road_used;
            patrol(i, road, road_used);
            for (ll j = 1; j <= N; j++) {
                if (!old[j] && road_used[j]) {
                    road_link[j] = i;
                }
            }
        }

        if (!line_used[i]) {
            auto old = line_used;
            patrol(i, line, line_used);
            for (ll j = 1; j <= N; j++) {
                if (!old[j] && line_used[j]) {
                    line_link[j] = i;
                }
            }
        }
    }

    vector<p> v;
    unordered_map<ll, unordered_map<ll, ll> > m;
    for (ll i = 1; i <= N; i++) {
        v.push_back(p(road_link[i], line_link[i]));
        m[road_link[i]][line_link[i]] += 1;
    }

    for (ll i = 1; i <= N; i++) {
        cout << m[road_link[i]][line_link[i]] << " \n"[i == N];
    }

    return 0;
}

