uftree::uftree(int n)
{
    size = n;
    for (int i = 0; i < size; i++) {
        par[i] =  i;
        rank[i] = 0;
    }
}

int uftree::find(int x) {
    if (par[x] == x) {
        return x;
    } else {
        return par[x] = find(par[x]);
    }
}

void uftree::unite(int x, int y) {
    x = find(x);
    y = find(y);
    if (x == y) {
        return ;
    }

    if (rank[x] < rank[y]) {
        par[x] = y;
    } else {
        par[y] = x;
        if (rank[x] == rank[y]) {
            rank[x]++;
        }
    }
}

bool uftree::same(int x, int y) {
    return find(x) == find(y);
}

