template <typename T>
class union_find : public vector<pair<lli,lli> >{
public:
    union_find():vector<pair<lli,lli> >(){}
    union_find(lli n):vector<pair<lli,lli> >(n){
        for(lli i = 0;i < n;i++){
            (*this)[i].first = i;
            (*this)[i].second = 0;
        }
    }
    lli find(T x){
        if((*this)[x].first == x) return x;
        else return (*this)[x].first = find((*this)[x].first);
    }
    void unite(T x,T y){
        x = find(x);y = find(y);
        if(x == y) return;
        if((*this)[x].second < (*this)[y].second) (*this)[x].first = y;
        else {
            (*this)[y].first = x;
            if((*this)[x].second == (*this)[y].second) (*this)[x].second++;
        }
    }
    bool same(T x,T y){
        return find(x) == find(y);
    }
};

