void merge(int id, int a, int b) {
	if (check(id, a, b)) return;

	if (vecs[id][pts[id][a]].size() > vecs[id][pts[id][b]].size()) swap(a, b);

	int pta = pts[id][a];
	int ptb = pts[id][b];

