    if(x==y)return;
    if(rank[x]<rank[y])par[x]=y;
    else{
      par[y]=x;
      if(rank[x]==rank[y])rank[x]++;
    }
  }

  bool same(int x,int y){return find(x)==find(y);}

};

int used[N];
UF K,L;

void dfsK(int pos){
  for(int i=0;i<GK[pos].size();i++){
    int nx=GK[pos][i];
    if(used[nx]||K.same(pos,nx))continue;
    used[nx]=1;
    K.unite(pos,nx);
    dfsK(nx);
  }
}


void dfsL(int pos){
  for(int i=0;i<GL[pos].size();i++){
    int nx=GL[pos][i];
    if(used[nx]||L.same(pos,nx))continue;
    used[nx]=1;
    L.unite(pos,nx);
    dfsL(nx);
  }
}

UF U;
void And(int pos){

  if(U.find(pos)!=pos)return;

  for(int i=0;i<K.U[K.find(pos)].size();i++){
    int nx=K.U[K.find(pos)][i];
    if(L.same(pos,nx)) U.unite(pos,nx);
  }
}

