    }

    UnionFind uf_route(N), uf_both(N);
    for(int i=0; i<K; i++){
        int u = route[i].first, v = route[i].second;
        uf_route.unite(u, v);
    }
    for(int i=0; i<L; i++){
        int u = rail[i].first, v = rail[i].second;
        if(uf_route.same(u, v)) uf_both.unite(u, v);
