		cin >> r[i] >> s[i];
		r[i]--;
		s[i]--;
	}
	UnionFind uf(N);
	UnionFind uf2(N);
	UnionFind uf3(N);
	for(long long i = 0; i < K; i++){
		uf.unite(p[i], q[i]);
	}

	for(long long i = 0; i < L; i++){
		uf2.unite(r[i], s[i]);
	}

	for(long long i = 0; i < K; i++){
		long long ppar1 = uf.find(p[i]);
		long long qpar1 = uf.find(q[i]);
		if(uf2.same(ppar1, q[i])){
			uf3.unite(ppar1, q[i]);
		}
		if(uf2.same(ppar1, p[i])){
			uf3.unite(ppar1, p[i]);
		}
		if(uf2.same(qpar1, q[i])){
			uf3.unite(qpar1, q[i]);
		}
		if(uf2.same(qpar1, p[i])){
			uf3.unite(qpar1, p[i]);
		}

		if(uf2.same(q[i], p[i])){
			uf3.unite(q[i], p[i]);
		}
	}

	for(long long i = 0; i < L; i++){
		long long rpar2 = uf2.find(r[i]);
		long long spar2 = uf2.find(s[i]);
		if(uf.same(rpar2, s[i])){
			uf3.unite(rpar2, s[i]);
		}
		if(uf.same(rpar2, r[i])){
			uf3.unite(rpar2, r[i]);
		}
		if(uf.same(spar2, s[i])){
			uf3.unite(spar2, s[i]);
		}
		if(uf.same(spar2, r[i])){
			uf3.unite(spar2, r[i]);
		}
		if(uf.same(s[i], r[i])){
			uf3.unite(s[i], r[i]);
		}
	}

	for(long long i = 0; i < N; i++){
		cout << uf3.size(i);
		if(i != N - 1){
			cout << " ";
		}else{
			cout << endl;
		}
	}
}

