struct UF {
	int num[200001];
	int sz[200001];

	void init(int n) {
		for (int i = 0; i < n; i++) {
			num[i] = i;
			sz[i] = 1;
		}
	}

	int root(int x) { if (num[x] == x) return x; return (num[x] = root(num[x])); }
	void marge(int x, int y) {
		x = root(x);
		y = root(y);
		if (x == y) return;

		num[x] = y;
		sz[y] += sz[x];
	}

	int size(int x) {
		return sz[root(x)];
	}

	int is_same(int x, int y) {
		return root(x) == root(y);
	}
};

