    /** output whole vector. ex) vector<int>{1, 2, 3} -> '1 2 3'. */
    template<typename T>
    ostream& operator<<(ostream& os, const vector<T>& xs) {
       if (xs.empty()) return os;
       os << xs[0];
       for (auto i = 1; i < xs.size(); i++) os << ' ' << xs[i];
       return os;
    }

    struct UnionFind {
        int N;
        vector<int> P;
        UnionFind(int N) : N(N) {
            P.clear();
            P.resize(N, -1);
        }
        int root(int x) {
            if (P[x] == -1) return x;
            return P[x] = root(P[x]);
        }
        int query(int x, int y) { return root(x) == root(y); }
        void merge(int x, int y) {
            x = root(x);
            y = root(y);
            if (x == y) return;
            P[x] = y;
        }
    };

    void solve() {
        cin >> N >> K >> L;
        UnionFind a(N), b(N);
        for (int i = 0; i < K; i++) {
            int p, q; cin >> p >> q;
            p--; q--;
            a.merge(p, q);
