struct UnionFind {
    vector<int> data;
    UnionFind(int size) : data(size, -1) { }
    // x, yをマージ
    bool unite(int x, int y) {
        x = root(x); y = root(y);
        if (x != y) {
            if (data[y] < data[x]) swap(x, y);
            data[x] += data[y]; data[y] = x;
        }
        return x != y;
    }
    // x, yが同じ集合なら1
    bool find(int x, int y) {
        return root(x) == root(y);
    }
    // xの根を探す。同じ集合なら同じ根が帰る
    int root(int x) {
        return data[x] < 0 ? x : data[x] = root(data[x]);
    }
    // xが含まれる集合の大きさを返す
    int size(int x) {
        return -data[root(x)];
    }
    // 分離されている集合の数を返す
    int setNum(void) {
        map<int, int> c;
        rep(i, data.size()) {
            c[root(i)]++;
        }
        return c.size();
    }
    // O(n)
    // 集合ごとに全部の要素を出力
    map<int, set<int>> c;
    void getUnionList(void) {
        for (int i = 0; i < data.size(); i++) 
            c[root(i)].insert(i);
    }
    /*
    void print(void) {
        auto c = getUnionList();
        for (auto x : c) {
            for (auto y : x) 
                cout << y << " ";
            cout << endl;
        }
    }
    */
};

int main(void) {
    cin.tie(0); ios::sync_with_stdio(false);
    ll n, k, l; cin >> n >> k >> l;
    vector<ll> p(k), q(k); rep(i, k) { cin >> p[i] >> q[i]; p[i]--, q[i]--; }
    vector<ll> r(l), s(l); rep(i, l) { cin >> r[i] >> s[i]; r[i]--, s[i]--; }

    vector<int> ret(n);
    UnionFind uf(n);
    rep(i, k) {
        uf.unite(p[i], q[i]);
    }
    uf.getUnionList();

    map<int/*root*/, set<int>> connected;
    rep(i, l) {
        if (uf.root(r[i]) != uf.root(s[i])) continue;
        connected[uf.root(r[i])].insert(i);
    }

    for (auto&& x : uf.c) {
        if (!connected.count(x.fi)) continue;

        unordered_map<int, int> inv; // 何番目の都市がtrの何番目か
        unordered_map<int, int> fow; // trの何番目が何番目の都市か
        ll j = 0;
        for (auto&& y : connected[x.fi]) {
            if (!inv.count(r[y])) {inv[r[y]] = j; fow[j] = r[y]; j++; }
            if (!inv.count(s[y])) {inv[s[y]] = j; fow[j] = s[y]; j++; }
        }
        UnionFind tr(j);
        for (auto&& y : connected[x.fi]) {
            tr.unite(inv[r[y]], inv[s[y]]);
        }
        rep(i, j) {
            ret[fow[i]] = tr.size(i);
        }
    }

    rep(i, n) {
        cout << (ret[i] == 0 ? 1 : ret[i]) << " ";
    }
    cout << endl;

    return 0;
}

