const int NMAX = 200005;

int n,k,l;

struct union_find
{
    vector<int>v,comp;
    union_find(int n): v(n + 1, -1), comp(n + 1, 1) {}
    int Find(int x)
    {
        if (v[x] == -1) return x;
        return v[x] = Find(v[x]);
    }

    void Union(int x, int y)
    {
        x = Find(x); y = Find(y);
        if (x == y) return ;
        if (comp[x] > comp[y])
        {
            comp[x] += comp[y];
            v[y] = x;
        }
        else 
        {
            comp[y] += comp[x];
            v[x] = y;
        }
    }
};  

