struct UnionFind
{
    vector<int> data;

    UnionFind(int sz)
    {
        data.assign(sz, -1);
    }

    bool unite(int x, int y)
    {
        x = find(x), y = find(y);
        if (x == y)
            return false;
        if (data[x] > data[y])
            swap(x, y);
        data[x] += data[y];
        data[y] = x;
        return true;
    }

    int find(int k)
    {
        if (data[k] < 0)
            return k;
        return (data[k] = find(data[k]));
    }

    int size(int k)
    {
        return (-data[find(k)]);
    }

    bool connected(int x, int y)
    {
        return (find(x) == find(y));
    }
};

int N, K, L;

int main()
{
    scanf("%d%d%d", &N, &K, &L);
    UnionFind pre(N), uf(N);
    for (int i = 0; i < K; i++)
    {
        int p, q;
        scanf("%d%d", &p, &q);
        p--, q--;
        pre.unite(p, q);
    }

    for (int i = 0; i < L; i++)
    {
        int r, s;
        scanf("%d%d", &r, &s);
        r--, s--;
        if (pre.connected(r, s))
        {
            uf.unite(r, s);
        }
    }

    for (int i = 0; i < N; i++)
    {
        printf("%d%c", uf.size(i), (i == N - 1 ? '\n' : ' '));
    }
}

