int par1[max_n], par2[max_n];
int r1[max_n], r2[max_n];

void init(int n, int (&par)[max_n], int (&r)[max_n]){
    REP(i, n){
        par[i] = i;
        r[i] = 0;
    }
}

int find(int x, int (&par)[max_n]){
    if(par[x] == x){
        return x;
    } else {
        return par[x] = find(par[x], par);
    }
}

void unite(int x, int y, int (&par)[max_n], int (&r)[max_n]){
    x = find(x, par);
    y = find(y, par);

    if(x == y) return;
    if(r[x] < r[y]){
        par[x] = y;
    } else {
        par[y] = x;
        if(r[x] == r[y]) r[x]++;
    }
}

bool same(int x, int y, int (&par)[max_n]){
    return find(x, par) == find(y, par);
}

int main(){
    cin >> n >> k >> l;
    init(n, par1, r1);
    REP(i, k){
        int p, q;
        cin >> p >> q;
        unite(p-1, q-1, par1, r1);
    }
    init(n, par2, r2);
    REP(i, l){
        int r, s;
        cin >> r >> s;
        if(same(r-1, s-1, par1)){
            unite(r-1, s-1, par2, r2);
        }
    }

    REP(i, n) c[i] = 0;
    REP(i, n) c[find(i, par2)] += 1;
    REP(i, n){
        cout << c[find(i, par2)];
        if(i<n-1){
            cout << " ";
        } else {
            cout << endl;
        }
    }
}

