int par_road[200001], par_rail[200001];
int root(int* par, int x) {
	return par[x] == x ? x : par[x] = root(par, par[x]);
}
void unite(int* par, int x, int y) {
	int xp = root(par, x), yp = root(par, y);
	if (xp < yp)par[yp] = xp;
	else if (xp > yp)par[xp] = yp;
}
int main() {
	int n, k, l, i, j, a, b;
	scanf("%d%d%d", &n, &k, &l);
	for (i = 1; i <= n; i++) {
		par_road[i] = i;
		par_rail[i] = i;
	}
	for (i = 1; i <= k; i++) {
		scanf("%d%d", &a, &b);
		unite(par_road, a, b);
	}
	for (i = 1; i <= l; i++) {
		scanf("%d%d", &a, &b);
		unite(par_rail, a, b);
	}
	std::multiset<std::pair<int, int>> p;
	for (i = 1; i <= n; i++) {
		par_road[i] = root(par_road, i);
