set<int> bfs(vector<int> graph[], int start)
{
	set<int> explored;

	queue<int> q;
	q.push(start);
	while (!q.empty())
	{
		int first = q.front();
		checked[first] = true;
		for (int i = 0; i < graph[first].size(); ++i)
		{
			if (!checked[graph[first][i]])
				q.push(graph[first][i]);
		}
		q.pop();
		explored.insert(first);
	}

	return explored;
}

