			parent[xr] = yr;
			set[yr].insert(set[yr].end(), set[xr].begin(), set[xr].end());
			set[xr].clear();
		}
		else if (xr != yr)
		{
			parent[yr] = xr;
			set[xr].insert(set[xr].end(), set[yr].begin(), set[yr].end());
			set[yr].clear();
			++rank[xr];
		}
	}
	int find(int x)
	{
		if (parent[x] == x)
