using namespace std;

class unionfind {
private:
    int* p,*c;
    queue<int> q;
    int root(int n) {
        while(!q.empty()) q.pop();
        int m = n;
        while(p[m] != -1) {
            q.push(m);
            m = p[m];
        }
        while(!q.empty()) {
            p[q.front()] = m;
            q.pop();
        }
        return m;
    }
public:
    unionfind(int n) {
        p = new int[n];
        c = new int[n];
        for(int i = 0;i < n;i++) p[i] = -1;
        for(int i = 0;i < n;i++) c[i] = 1;
    }
    ~unionfind() {
        delete p;
        delete c;
    }
    bool f(int a,int b) {
        return root(a) == root(b);
    }
    void u(int a,int b) {
        if(!f(a,b)) {
            c[root(b)] += c[root(a)];
            p[root(a)] = root(b);
        }
    }
    int s(int a) {
        return c[root(a)];
    }
};

