class UF{
private:
    vector<int> par,rank,elm;
public:
    int groups;

    UF(int __size):par(__size) , rank(__size,0) , elm(__size,1) , groups(__size){
        for(int i=0;i<__size;i++)par[i]=i;
    }

    int elements(int n){
        return elm[find(n)];
    }

    int find(int x){
        if(par[x]==x) {
            return x;
        }else{
            return par[x]=find(par[x]);
        }
    }

    void unite(int x,int y){
        x=find(x);
        y=find(y);
        if(x==y) return;

        groups--;
        if(rank[x]<rank[y]){
            par[x]=y;
            elm[y]+=elm[x];
        }else{
            par[y]=x;
            elm[x]+=elm[y];
            if(rank[x]==rank[y])rank[x]++;
        }
    }

    bool isSame(int x,int y){
        return find(x)==find(y);
    }
};

