struct DSU{
  vector<int>fa,sz;
  DSU(int n){
    fa.clear();
    sz.clear();
    fa.resize(n);
    sz.resize(n);
    for(int i=0;i<n;i++){
      fa[i]=i;
      sz[i]=1;
    }
  }
  int get(int x){
    if(fa[x]==x){
      return x;
    }
    return fa[x]=get(fa[x]);
  }
  void merge(int x,int y){
    x=get(x);y=get(y);
    if(x==y){
      return;
    }
    if(sz[x]<sz[y]){
      swap(x,y);
    }
    fa[y]=x;
    sz[x]+=sz[y];
    sz[y]=0;
  }
};

