long long int apar[300000];
long long int arank[300000];

void ainit(long long int n) {
	for (long long int i = 0; i < n; i++) {
		apar[i] = i;
		arank[i] = 0;
	}
}

long long int afind(long long int x) {
	if (apar[x] == x) {
		return x;
	} else {
		return apar[x] = afind(apar[x]);
	}
}

void aunite(long long int x, long long int y) {
	x = afind(x);
	y = afind(y);
	if (x == y) return;

	if (arank[x] < arank[y]) {
		apar[x] = y;
	} else {
		apar[y] = x;
		if (arank[x] == arank[y]) arank[x]++;
	}
}

bool asame(long long int x, long long int y) {
	return afind(x) == afind(y);
}

long long int bpar[300000];
long long int brank[300000];

void binit(long long int n) {
	for (long long int i = 0; i < n; i++) {
		bpar[i] = i;
		brank[i] = 0;
	}
}

long long int bfind(long long int x) {
	if (bpar[x] == x) {
		return x;
	} else {
		return bpar[x] = bfind(bpar[x]);
	}
}

void bunite(long long int x, long long int y) {
	x = bfind(x);
	y = bfind(y);
	if (x == y) return;

	if (brank[x] < brank[y]) {
		bpar[x] = y;
	} else {
		bpar[y] = x;
		if (brank[x] == brank[y]) brank[x]++;
	}
}

bool bsame(long long int x, long long int y) {
	return bfind(x) == bfind(y);
}

