#include <bits/stdc++.h>

using namespace std;

struct UnionFind
{
  vector< int > data;

  UnionFind(int sz)
  {
    data.assign(sz, -1);
  }

  void unite(int x, int y)
  {
    x = find(x), y = find(y);
    if(x != y) {
      if(data[x] > data[y]) swap(x, y);
      data[x] += data[y];
      data[y] = x;
    }
  }

  int find(int k)
  {
    if(data[k] < 0) return (k);
    return (data[k] = find(data[k]));
  }

  int size(int k)
  {
    return (-data[find(k)]);
  }
};

int main()
{
  int N, K, L;

  cin >> N >> K >> L;
  UnionFind uf1(N), uf2(N);
  for(int i = 0; i < K; i++) {
    int p, q;
    cin >> p >> q;
    uf1.unite(--p, --q);
  }
  for(int i = 0; i < L; i++) {
    int p, q;
    cin >> p >> q;
    uf2.unite(--p, --q);
  }

  map< int, map< int, int > > link;

  for(int i = 0; i < N; i++) {
    link[uf1.find(i)][uf2.find(i)]++;
  }
  for(int i = 0; i < N; i++) {
    if(i > 0) cout << " ";
    cout << link[uf1.find(i)][uf2.find(i)];
  }
  cout << endl;
}

