#include <deque>

namespace kosaraju{
	vector<int> cmp;
	vector<bool> visited;
	int cmp_num;
	deque<size_t> l;

	void visit(size_t v, Graph& g){
		if(visited[v])
			return;
		visited[v] = true;
		for(auto e: g.adj_lst[v]){
			visit(e->dest,g);
		}
		l.push_front(v);
	}

	void assign(size_t v,int num, Graph& g){
		if(cmp[v] >= 0)
			return;
		cmp[v] = num;
		for(auto e: g.rev_adj_lst[v]){
			assign(e->src,num,g);
		}
	}

	vector<int> kosaraju(Graph& g){
		cmp.assign(g.size(),-1);
		visited.assign(g.size(),false);
		int cmp_num = 0;

		for(size_t i = 0; i < g.size();i++){
			visit(i,g);
		}
		for(size_t i = 0; i < g.size();i++){
			if(cmp[l[i]] < 0){
				assign(l[i],cmp_num,g);
				cmp_num++;
			}
		}
		return cmp;
	}
}

