        pa = _find(i); pb = _find1(i);
        sza = mp1[pa].size(), szb = mp2[pb].size();
        cnt.clear();
        a = 0, b = 0;
        while(a < sza && b < szb){
            if(mp1[pa][a] == mp2[pb][b]){
                cnt[mp1[_find(i)][a]]++;
                a++;
                b++;
            }
            else if(mp1[pa][a] > mp2[pb][b]){
                if(b + 1== szb){
                    break;
                }
                else if(mp1[pa][a] > mp2[pb][szb - 1]){
                    break;
                }
                else{
                    l = b, r = szb;
                    b = szb - 1;
                    while(l + 1 < r){
                        mid = (l + r) >> 1;
                        if(mp1[pa][a] <= mp2[pb][mid]){
                            r = mid;
                            b = min(b, mid);
                        }
                        else l = mid;
                    }

                }
            }
            else{
