                        if(mp1[pa][mid] >= mp2[pb][b]){
                            r = mid;
                            a = min(a, mid);
                        }
                        else l = mid;
                    }
                }
            }
        }
        sza = cnt.size();
        for(auto k = cnt.begin(); k != cnt.end(); k++){
