int par[400000];
int arank[400000];

void init(int n){
	for(int i = 0;i < n;i++){
		par[i] = i;
		arank[i] = 0;
	}
}

int find(int x){
	if(par[x] == x) return x;
	else return par[x] = find(par[x]);
}

void unite(int x,int y){
	x = find(x);
	y = find(y);
	if(x == y) return;
	if(arank[x] < arank[y]){
		par[x] = y;
	}else{
		par[y] = x;
		if(arank[x] == arank[y]) arank[x]++;
	}
}

bool same(int x,int y){
	return find(x) == find(y);
}

