    viz[x] = 1;
    wh[x] = nr;

    for (auto it : v[x])
        if (!viz[it])
            Dfs(it);
}

void Union(int x, int y)
{
    if (comp[y] < comp[x])
    {
        f[y] = x;
        comp[x] += comp[y];
    }
    else
    {
        f[x] = y;
        comp[y] += comp[x];
    }
}

int Find(int x)
{
    int w,z;
    z = x;
    while (x != f[x]) x = f[x];
    while (z != f[z])
    {
        w = f[z];
        f[z] = x;
        z = w;
    }

    return x;
}

