using namespace std;

int FindHead(int node, vector<int>& pre)
{
	int head = node;
	while (pre[head] != head)
		head = pre[head];
	while (pre[node] != head)
	{
		int cur = pre[node];
		pre[node] = head;
		node = cur;
	}
	return head;
}

int main()
{
	int N, K, L;
	cin >> N >> K >> L;
	vector<int> pre_road(N + 1);
	vector<int> pre_railway(N + 1);
	for (int i = 1; i <= N; i++)
	{
		pre_road[i] = i;
		pre_railway[i] = i;
	}

	for (int i = 0; i < K; i++)
	{
		int a, b;
		cin >> a >> b;
		int head1 = FindHead(a, pre_road);
		int head2 = FindHead(b, pre_road);
		if (head1 != head2)
			pre_road[head2] = head1;
	}

	for (int i = 0; i < L; i++)
	{
		int a, b;
		cin >> a >> b;
		int head1 = FindHead(a, pre_railway);
		int head2 = FindHead(b, pre_railway);
		if (head1 != head2)
			pre_railway[head2] = head1;
	}

	map<pair<int, int>, int> count_map;
	for (int i = 1; i <= N; i++)
	{
		int head1 = FindHead(i, pre_road);
		int head2 = FindHead(i, pre_railway);
		count_map[make_pair(head1, head2)] ++;
	}

	for (int i = 1; i <= N; i++)
	{
		int head1 = FindHead(i, pre_road);
		int head2 = FindHead(i, pre_railway);
		cout << count_map[make_pair(head1, head2)];
		if (i != N)
			cout << " ";
		else
			cout << endl;
	}
    return 0;
}

