struct UnionFind {

	int n;
	int parent[MAX_V];

	void init(int m) {
		n = m;
		for (int i = 0; i < n; i++) {
			parent[i] = i;
		}
	}

	int find(int i) {
		if (i == parent[i]) return i;
		else return parent[i] = find(parent[i]);
	}

	void unite(int x, int y) {
		int a = find(x);
		int b = find(y);
		if (a == b) return;
		else {
			parent[a] = b;
		}
	}

	bool is_same(int x, int y) {
		return find(x) == find(y);
	}

};


