struct UnionFind {
    UnionFind() : m_parents(0), m_rank(0) {}
    UnionFind(size_t N) : m_parents(N), m_rank(N) {
        REP (i, N) {
            m_parents[i] = i;
            m_rank[i] = 0;
        }
    }

    void merge(size_t t1, size_t t2) {
        auto p1 = this->parent(t1);
        auto p2 = this->parent(t2);

        if (p1 == p2) {
            return ;
        }

        if (this->m_rank[p1] < this->m_rank[p2]) {
            this->m_parents[p1] = p2;
        } else {
            this->m_parents[p2] = p1;
            if (this->m_rank[p1] == this->m_rank[p2]) {
                this->m_rank[p1] += 1;
            }
        }
    }
    bool is_same(size_t t1, size_t t2) const {
        return this->parent(t1) == this->parent(t2);
    }

    size_t parent(size_t t) const {
        auto p = this->m_parents[t];
        if (p == t) {
            return t;
        } else {
            auto p2 = this->parent(p);
            this->m_parents[t] = p2;
            return p2;
        }
    }
private:
    mutable vector<size_t> m_parents;
    vector<u64> m_rank;

};


void body() {
    auto N = read<i64>();
    auto K = read<i64>();
    auto L = read<i64>();
    auto pq = read<i64, i64>(K);
    auto rs = read<i64, i64>(L);
    EACH(e, pq) {
        e.first -= 1;
        e.second -= 1;
    }
    EACH(e, rs) {
        e.first -= 1;
        e.second -= 1;
    }

    UnionFind u_k(N);
    EACH (e, pq) {
        u_k.merge(e.first, e.second);
    }
    UnionFind u_l(N);
    EACH (e, rs) {
        u_l.merge(e.first, e.second);
    }

    Vector<pair<size_t, size_t>> node2id(N);
    OrderedMap<pair<size_t, size_t>, i64> num;

    REP (i, N) {
        auto p_k = u_k.parent(i);
        auto p_l = u_l.parent(i);
        node2id[i] = make_pair(p_k, p_l);
        if (num.find(make_pair(p_k, p_l)) == num.end()) {
            num.emplace(make_pair(p_k, p_l), 0);
        }
        num[make_pair(p_k, p_l)] += 1;
    }

    REP (i, N) {
        cout << num[node2id[i]];

        if (i != N - 1) {
            cout << " ";
        }
    }
    cout << endl;
}

