struct UnionFind {
	int *par;
	int *rank;
	int *cnt;
	UnionFind(int n) {
		par = new int[n];
		rank = new int[n];
		cnt = new int[n];
		rep(i, n) {
			par[i] = i;
			rank[i] = 0;
			cnt[i] = 1;
		}
	}
	int find(int x) {
		if (x == par[x]) return x;
		return par[x] = find(par[x]);
	}
	bool same(int x, int y) {
		return find(x) == find(y);
	}
	void unite(int x, int y) {
		x = find(x);
		y = find(y);
		if (x == y) return;
		if (rank[x] < rank[y]) {
			par[x] = y;
			cnt[y] += cnt[x];
		}
		else {
			par[y] = x;
			cnt[x] += cnt[y];
			if (rank[x] == rank[y]) rank[x]++;
		}
	}
};
