//        printf("%d%c", number[i], i == vertex ? '\n' : ' ');
    memset(vis, false, sizeof(vis));
    for (int i = 1; i <= vertex; i++)
    {
        if (!vis[i])
        {
            DFS(i);
            for (int i = 0; i < valid.size(); i++)
            {
                int id = valid[i];
                for (int j = 0; j < v[id].size(); j++)
