using namespace std;

struct DJS
{
	int par[200001],sz[200001];
	void init(int n)
	{
		for(int i=1;i<=n;i++)
			par[i]=i, sz[i]=1;
	}
	int Find(int a)
	{
		if(par[a]==a) return a;
		else return par[a]=Find(par[a]);
	}
	void Union(int a,int b)
	{
		a=Find(a), b=Find(b);
		if(a==b) return;
		par[a]=b;
		sz[b]+=sz[a];
	}
} d,w;

struct Elem
{
	int g1,g2,ind;
	Elem(int g1,int g2,int ind)
	{
		this->g1=g1;
		this->g2=g2;
		this->ind=ind;
	}
    bool operator<(const Elem &other)const
    {
        if(g1==other.g1) return g2<other.g2;
        else return g1<other.g1;
	}
};
vector<Elem> v;
int ans[200001];

int main()
{
	int n,k,l;
	scanf("%d %d %d",&n,&k,&l);

	d.init(n);
	for(int i=1,a,b;i<=k;i++)
	{
		scanf("%d %d",&a,&b);
		d.Union(a,b);
	}

	w.init(n);
	for(int i=1,a,b;i<=l;i++)
	{
		scanf("%d %d",&a,&b);
		w.Union(a,b);
	}

	for(int i=1;i<=n;i++)
		v.push_back(Elem(d.Find(i),w.Find(i),i));
	sort(v.begin(),v.end());

	for(int i=0;i<n;i++)
	{
		int j=i;
		while(j+1<n && v[j+1].g1==v[j].g1 && v[j+1].g2==v[j].g2)
			j++;
		for(int k=i;k<=j;k++)
			ans[v[k].ind]=j-i+1;
		i=j;
	}

    for(int i=1;i<=n;i++)
		printf("%d ",ans[i]);
	puts("");
	return 0;
}

