    return par3[x].num=root3(par3[x].num);//経路圧縮
  }
}
//属する集合の要素数を求める
int size3(int x){
  return par3[root3(x)].size;
}
//x,yが同じ集合に属するか否か
bool same3(int x,int y){
  return (root3(x)==root3(y));
}
//x,yの属する集合を併合
void unite3(int x,int y){
  x=root3(x);
  y=root3(y);
  if(x==y)return;
  par3[y].size += par3[x].size;
  par3[x].num = y;
}
