void search1(int root,ll depth,int pre){
  record[root]=true;
  //cout << "eee" << endl;
  //ここにやりたい処理を書く
  if(pre!=-1){
    unite1(root,pre);
  }
  for(auto i:vs[root]->nexts){
    if(pre==i.to->num || i.type==1||record[i.to->num]==true){
      continue;
    }
    search1(i.to->num,depth+i.length,root);
  }
  return;
}
void search2(int root,ll depth,int pre){
  record[root]=true;
  //cout << "eee" << endl;
  //ここにやりたい処理を書く
  if(pre!=-1){
    unite2(root,pre);
  }
  for(auto i:vs[root]->nexts){
    if(pre==i.to->num || i.type==0||record[i.to->num]==true){
      continue;
    }
    search2(i.to->num,depth+i.length,root);
  }
  return;
}
void search3(int root,ll depth,int pre){
  record[root]=true;
  if(pre!=-1){
    if(same1(root,pre)&&same2(root,pre)){
      unite3(root,pre);
    }
  }

  //ここにやりたい処理を書く
  for(auto i:vs[root]->nexts){
    if(pre==i.to->num||record[i.to->num]==true){
      continue;
    }
    search3(i.to->num,depth+i.length,root);
  }
  return;
}

