using namespace std;
int N, K, L;
vector<vector<int>> pq;
vector<vector<int>> rs;
bool flag[20000];

class UnionFind {
    int n;
    vector<int> par;
    vector<int> rank;

public:
    UnionFind(int a) : n(a), rank(a, 0) {
        par.reserve(n);
        for (int i = 0; i < a; i++) par.push_back(i);
    }
    int find(int x) {
        if (par[x] == x) return x;
        return par[x] = find(par[x]);
    }
    void unite(int x, int y) {
        int x_root = find(x);
        int y_root = find(y);
        if (rank[x_root] > rank[y_root]) {
            par[y_root] = x_root;
        } else if (rank[x_root] < rank[y_root]) {
            par[x_root] = y_root;
        } else if (x_root != y_root) {
            par[y_root] = x_root;
            rank[x_root]++;
        }
    }
    bool same(int x, int y) { return find(x) == find(y); }
};

void dfs_pq(int n, UnionFind &uf) {
    if (flag[n]) return;
    flag[n] = true;
    for (int i = 0; i < pq[n].size(); i++) {
        uf.unite(n, pq[n][i]);
    }
}

void dfs_rs(int n, UnionFind &uf, UnionFind &uf2) {
    if (flag[n]) return;
    flag[n] = true;
    for (int i = 0; i < rs[n].size(); i++) {
        if (uf.same(n, rs[n][i])) uf2.unite(n, rs[n][i]);
    }
}

int main() {
