    cin >> N >> K >> L;
    UnionFind uf(N);
    UnionFind uf2(N);
    pq.resize(N);
    rs.resize(N);
    for (int i = 0; i < K; i++) {
        int p, q;
        cin >> p >> q;
        p--; q--;
        pq[p].push_back(q);
        pq[q].push_back(p);
    }
    for (int i = 0; i < L; i++) {
        int r, s;
        cin >> r >> s;
        r--; s--;
        rs[r].push_back(s);
        rs[s].push_back(r);
    }

    fill_n(flag, N, false);
    for (int i = 0; i < N; i++) dfs_pq(i, uf);

    fill_n(flag, N, false);
    for (int i = 0; i < N; i++) dfs_rs(i, uf, uf2);

    int ans[20000] = {0};
    for (int i = 0; i < N; i++) {
