vector<int> road[200005];
vector<int> way[200005];
int id[200005];
int cnt[200005];
int vs[200005], vs2[200005], vs3[200005];
int res[200005];

int ptr;

void dfs(int v){
    if(id[v]) return;
    id[v] = ptr;
    for(int i=0; i<road[v].size(); i++) dfs(road[v][i]);
    return;
}

void initialize(int v){
    if(vs[v]) return;
    vs[v] = 1;
    cnt[id[v]]++;
    for(int i=0; i<way[v].size(); i++) initialize(way[v][i]);
    return;
}

void run(int v){
    if(vs2[v]) return;
    vs2[v] = 1;
    res[v] = cnt[id[v]];
    for(int i=0; i<way[v].size(); i++) run(way[v][i]);
    return;
}

void rem(int v){
    if(vs3[v]) return;
    vs3[v] = 1;
    cnt[id[v]]--;
    for(int i=0; i<way[v].size(); i++) rem(way[v][i]);
    return;
}

