    int N, K, L;
    scanf("%d%d%d", &N, &K, &L);
    for(int i=0; i<K; i++){
        int p, q;
        scanf("%d%d", &p, &q);
        road[p].push_back(q);
        road[q].push_back(p);
    }
    for(int i=1; i<=N; i++) ptr = i, dfs(i);
    for(int i=0; i<L; i++){
        int r, s;
        scanf("%d%d", &r, &s);
        way[r].push_back(s);
        way[s].push_back(r);
    }
    for(int i=1; i<=N; i++){
        initialize(i);
        run(i);
        rem(i);
    }
    for(int i=1; i<=N; i++) printf("%d ", res[i]);
    return 0;
}

