struct UnionFind{
    std::vector < int > rank;
    std::vector < int > parent;
    std::vector < int > size;
    UnionFind(int N){
        this->rank.resize(N);
        this->parent.resize(N);
        this->size.resize(N);
        for (int i = 0; i < N; ++i) {
            this->rank[i] = 1;
            this->parent[i] = i;
            this->size[i] = 1;
        }
    }
    ~UnionFind(){
        this->parent.clear();
        this->rank.clear();
        this->size.clear();
        std::vector<int>().swap(this->rank);
        std::vector<int>().swap(this->parent);
        std::vector<int>().swap(this->size);
    }
    int find(int a){
        if (this->parent[a] == a) {
            return a;
        }
        return this->parent[a] = find(this->parent[a]);
    }

    bool unite(int a, int b){
        int pa = this->find(a);
        int pb = this->find(b);

        if (pa == pb) {
            return false;
        }
        if (this->rank[pa] < this->rank[pb]) {
            this->parent[pa] = pb;
            this->size[pb] += this->size[pa];
        }
        else {
            this->parent[pb] = pa;
            this->size[pa] += this->size[pb];
            if (this->rank[pa] == this->rank[pb]) {
                this->rank[pa]++;
            }
        }
        return true;
    }

    bool isSame(int a,int b){
        return (this->parent[a] == this->parent[b]);
    }
};
