		g[u].push_back(v);
		g[v].push_back(u);
	}

	void dfs(int u){
		vis[u]=1;
		c[u]=comp;
		cl[comp].push_back(u);
		for(auto v:g[u]){
			if(!vis[v]){
				dfs(v);
			}
		}
	}

	void solve(){
		for(int i=0;i<n;i++){
			if(!vis[i]){
				cl.emplace_back();
				dfs(i);
				comp++;
			}
		}
	}

};

