typedef long long ll;

struct UnionFind{
    vector<int> par;
    vector<int> rank;
    UnionFind(int n){
        par = vector<int>(n, -1);
        rank = vector<int>(n, 0);
    }

    int root(int x){
        if(par[x] < 0){
            return x;
        }
        return par[x] = root(par[x]);
    }

    bool isSame(int a, int b){
        return root(a) == root(b);
    }

    bool merge(int a, int b){
        a = root(a);
        b = root(b);
        if(isSame(a, b)){
            return false;
        }
        if(rank[a] < rank[b]){
            swap(a, b);
        }
        if(rank[a] == rank[b]){
            rank[a] ++;
        }
        par[a] += par[b];
        par[b] = a;
        return true;
    }

};

int main(){
