const int V = 200000;
struct UF {
	int arr[V];
	// std::vector<int> vec[V];
	std::vector<int> * vec;

	void init() {
		vec = new std::vector<int>[V];
		inc(i, V) {
			arr[i] = i;
			vec[i].push_back(i);
		}
	}
	void unite(int x, int y) {
		if(arr[x] == arr[y]) { return; }
		if(vec[ arr[x] ].size() < vec[ arr[y] ].size()) { swap(x, y); }
		int ax = arr[x], ay = arr[y];
		for(auto && e: vec[ay]) {
			arr[e] = ax;
			vec[ax].push_back(e);
		}
		vec[ay].clear();
	}
};

int main() {
