		K.unite(p, q);
	}
	inc(i, l) {
		int r, s;
		scanf("%d%d", &r, &s); r--; s--;
		if(K.arr[r] == K.arr[s]) { L.unite(r, s); }
	}

	inc(i, n) {
		printf("%s%d", (i == 0 ? "" : " "), L.vec[ L.arr[i] ].size());
	}

