		a--; b--;
		rail.unite(a, b);
	}

	rep (i, n) {
		int cnt = 0;
		if (road.showRank(road.root(i)) == 0 ||  rail.showRank(rail.root(i)) == 0) {
			cnt++;
		} else {
			rep (j, n) {
				cnt += road.same(i, j) && rail.same(i, j);
			}
		}
		cout << cnt << (i != n - 1 ? " " : "\n");
	}

	return 0;
}

