struct kaka {
    int fi, se, value;
} a[N];

bool cmp(kaka x, kaka y) {
    return (x.fi < y.fi) || (x.fi == y.fi && x.se < y.se);
}

int anc(int p, int par[]) {
    if (p == par[p]) return p;
    return par[p] = anc(par[p], par);
}

int join(int p, int q, int par[]) {
    par[anc(p, par)] = anc(q, par);
}

int main() {
    //freopen("065D.txt", "r", stdin);
