bool road_connected(int a, int b)
{
	if(a==b) {
		roadvisited[a].insert(b);
		return true;
	}
	set<int>::iterator it=roads[a].find(b);
	if(it!=roads[a].end()) {
		roadvisited[a].insert(b);
		return true;
	}

	it=roadvisited[a].find(b);
	if(it!=roadvisited[a].end()) {
		return false;
	}

	roadvisited[a].insert(b);
	it=roads[a].begin();
	for(;it!=roads[a].end();it++) {
		if(road_connected((*it), b)) {
			roads[a].insert(b);
			return true;
		}
	}
	return false;
}

bool rail_connected(int a, int b)
{
	if(a==b) {
		return true;
	}
	set<int>::iterator it=rails[a].find(b);
	if(it!=rails[a].end()) {
		return true;
	}
	it=railvisited[a].find(b);
	if(it!=railvisited[a].end()) {
		return false;
	}
	railvisited[a].insert(b);
	it=rails[a].begin();
	for(;it!=rails[a].end();it++) {
		if(rail_connected((*it), b)) {
			rails[a].insert(b);
			return true;
		}
	}
	return false;
}

bool connected(int a, int b)
{
	if(a==b) {
		visited[a].insert(b);
		return true;
	}
	set<int>::iterator it=boths[a].find(b);
	if(it!=boths[a].end()) {
		visited[a].insert(b);
		return true;
	}

	it=visited[a].find(b);
	if(it!=visited[a].end()) {
		return false;
	}

	visited[a].insert(b);

	set<int>::iterator it_road=roads[a].begin();
	// bool bRoad = false;
	// bool bRail = false;
	for(;it!=roads[a].end();it++) {
		if(!road_connected((*it), b)) {
			continue;
		}
		roads[a].insert(b);

		set<int>::iterator it_rail=rails[a].begin();
		if(!rail_connected((*it), b)) {
			continue;
		}
		rails[a].insert(b);
		boths[a].insert(b);
		return true;
	}
	return false;
}


