vector<int> solve(vector<vector<int>> &neig, int n)
{
	vector<int> parent(n + 1), vis(n + 1);
	for (int i = 1; i <= n; i++)
	{
		if (vis[i])
		{
			continue;
		}
		queue<int> q;
		q.push(i);
		vis[i] = 1;
		parent[i] = i;
		while (!q.empty())
		{
			int cur = q.front();
			q.pop();
			for (int v : neig[cur])
			{
				if (!vis[v])
				{
					vis[v] = 1;
					q.push(v);
					parent[v] = parent[cur];
				}
			}
		}
	}
	return parent;
}

