template <typename T>
struct UnionFind
{
    vector<T> data;

    UnionFind(int sz)
    {
        data.assign(sz, -1);
    }

    bool unite(T x, T y)
    {
        x = find(x), y = find(y);
        if (x == y)
            return false;
        if (data[x] > data[y])
            swap(x, y);
        data[x] += data[y];
        data[y] = x;
        return true;
    }

    int find(T k)
    {
        if (data[k] < 0)
            return k;
        return (data[k] = find(data[k]));
    }

    int size(T k)
    {
        return (-data[find(k)]);
    }

    bool connected(T x, T y)
    {
        return (find(x) == find(y));
    }
};

int N, K, L;

int main()
{
    scanf("%d%d%d", &N, &K, &L);
    UnionFind<int> pre(N), uf(N);
    for (int i = 0; i < K; i++)
    {
        int p, q;
        scanf("%d%d", &p, &q);
        p--, q--;
        pre.unite(p, q);
    }

    for (int i = 0; i < L; i++)
    {
        int r, s;
        scanf("%d%d", &r, &s);
        r--, s--;
        if (pre.connected(r, s))
        {
            uf.unite(r, s);
            cout << r << " " << s << endl;
        }
    }

    for (int i = 0; i + 1 < N; i++)
    {
        printf("%d ", uf.size(i));
    }
    cout << uf.size(N - 1) << endl;
}

