struct Graph {
private:
    vector<vector<int> > g;
    vector<int> comp;
    int n, id;
public:
    Graph(int n): n(n) {
        g.assign(n+1, vector<int>());
    }

    void addEdge(int u, int v) {
        g[u].pb(v); g[v].pb(u);
    }

    void DFS(int u) {
        comp[u] = id;
        for(int v: g[u]) {
            if (!comp[v]) DFS(v);
        }
    }

    vector<int> getComp() {
        comp.assign(n+1, 0);
        id = 0;
        fto(u, 1, n) {
            if (!comp[u]) {
                ++id;
                DFS(u);
            }
        }
        return comp;
    }
};

