const int maxn=2*100005;
class DSU{
    int parent[maxn];
    int size[maxn];
public:
    void make_set(int v){
        parent[v]=v;
        size[v]=1;
    }
    int find_set(int v){
        if(parent[v]==v)return v;
        return parent[v]=find_set(parent[v]);
    }
    void union_sets(int a,int b){
        int x=find_set(a);
        int y=find_set(b);
        if(x==y)return;
        if(size[x]<size[y])swap(x,y);
        parent[y]=x;
        size[x]+=size[y];
    }
