map<int, vector<int> > mp1, mp2;
map<int, int> cnt;
int ans[maxn];

int main()
{
    int n, p, q, u, v;
    cin >> n >> p >> q;
    DisjointSet(n), DisjointSet1(n);
    while(p--)
    {
        cin >> u >> v;
        if(_find(u) != _find(v)) _merge(_find(u), _find(v));
    }

    while(q--)
    {
        cin >> u >> v;
        if(_find1(u) != _find1(v)) _merge1(_find1(u), _find1(v));
    }

    for(int i = 1; i <= n; i++)
    {
        mp1[_find(i)].push_back(i);
    }
    for(int i = 1; i <= n; i++)
    {
        mp2[_find1(i)].push_back(i);
    }

    for(map <int, vector<int> > :: iterator i = mp1.begin(); i != mp1.end(); i++)
    {
        sort((i->second).begin(), (i->second).end());
    }
    for(map <int, vector<int> > :: iterator i = mp2.begin(); i != mp2.end(); i++)
    {
        sort((i->second).begin(), (i->second).end());
    }

    //cout << "?"<<endl;

    int i, a, b, pa, pb, sza, szb, l, r, mid;
    for(i = 1; i <= n; i++)
    {
        if(ans[i] != 0) continue;
        pa = _find(i);
        pb = _find1(i);
        sza = mp1[pa].size(), szb = mp2[pb].size();
        cnt.clear();
        a = 0, b = 0;
        while(a < sza && b < szb)
        {
            if(mp1[pa][a] == mp2[pb][b])
            {
                cnt[mp1[_find(i)][a]]++;
                a++;
                b++;
            }
            else if(mp1[pa][a] > mp2[pb][b])
            {
                if(b + 1== szb)
                {
                    break;
                }
                else if(mp1[pa][a] > mp2[pb][szb - 1])
                {
                    break;
                }
                else
                {
                    l = b, r = szb;
                    b = szb - 1;
                    while(l + 1 < r)
                    {
                        mid = (l + r) >> 1;
                        if(mp1[pa][a] <= mp2[pb][mid])
                        {
                            r = mid;
                            b = min(b, mid);
                        }
                        else l = mid;
                    }

                }
            }
            else
            {
                if(a + 1 == sza)
                {
                    break;
                }
                else if(mp1[pa][sza - 1] < mp2[pb][b])
                {
                    break;
                }
                else
                {
                    l = a, r = sza;
                    a = sza - 1;
                    while(l + 1 < r)
                    {
                        mid = (l + r) >> 1;
                        if(mp1[pa][mid] >= mp2[pb][b])
                        {
                            r = mid;
                            a = min(a, mid);
                        }
                        else l = mid;
                    }
                }
            }
        }
        sza = cnt.size();
        for(map <int, int> :: iterator k = cnt.begin(); k != cnt.end(); k++)
        {
            ans[k->first] = sza;
        }
    }

    for(i = 1; i <= n; i++)
    {
        if(i == 1) cout << ans[i];
        else cout << " " << ans[i];
    }
    cout << endl;
    return 0;
}

