int par[2][200001];
int Rank[2][200001];

void init(int n) {
  for (int i = 0; i < 2; i++) {
    for (int j = 0; j < n; j++) {
      par[i][j] = j;
      Rank[i][j] = 1;
    }
  }
}

int find(int i, int x) {
  if (par[i][x] == x) return x;
  return par[i][x] = find(i, par[i][x]);
}

void unite(int i, int x, int y) {
  x = find(i, x);
  y = find(i, y);
  if (x == y) return;
  if (Rank[i][x] < Rank[i][y]) {
    par[i][x] = y;
  } else {
    par[i][y] = x;
    if (Rank[i][x] == Rank[i][y]) {
      Rank[i][x]++;
    }
  }
}

