void init()
{
	REP(i, N)
	{
		RoadTree[i] = i;
		RoadRank[i] = 0;
		TrainTree[i] = i;
		TrainRank[i] = 0;
	}
}

int find(int x, int* tree)
{
	if (x == tree[x])
	{
		return x;
	}
	return tree[x] = find(tree[x], tree);
}

void unit(int x, int y, int* tree, int* rank)
{
	x = find(x, tree);
	y = find(y, tree);
	if (x == y)return;

	if (rank[x] < rank[y])
	{
		tree[x] = y;
	}
	else
	{
		tree[y] = x;
		if (rank[x] == rank[y])rank[x]++;
	}
}

bool same(int x, int y, int* tree)
{
	return find(x, tree) == find(y, tree);
}

int main()
{
	cin >> N >> K >> L;
	init();
	REP(i, K)
	{
		int p,q;
		cin >> p >> q;
		p--; q--;
		unit(p, q, RoadTree, RoadRank);
	}
	REP(i, L)
	{
		int p, q;
		cin >> p >> q;
		p--; q--;
		if (same(p, q, RoadTree))
		{
			unit(p, q, TrainTree, TrainRank);
		}
	}

