const int UF_MAX = 400010;

class UF{
	int x[UF_MAX];

public:

	void dft(){
		for(int i = 0 ; i < UF_MAX ; ++i) x[i] = -1;
	}

	int boss(int a){
		int s = a;
		while(x[s] > -1) s = x[s];
		if(s != a) x[a] = s;
		return s;
	}

	void uni(int a , int b){
		int s = boss(a);
		int t = boss(b);
		if(s != t){
			if(x[s] < x[t]){
				x[s] += x[t];
				x[t] = s;
			} else {
				x[t] += x[s];
				x[s] = t;
			}
		}
	}

	bool find(int a , int b){
		return boss(a) == boss(b);
	}

	int size(int a){
		return -x[boss(a)];
	}
};

UF A,B,C;
vector<int> V[200010];
int N,K,L;
int ans[200010];

int main(){
	scanf("%d%d%d" , &N , &K , &L);
	A.dft();
	B.dft();
	repp(i,0,K){
		int x,y;
		scanf("%d%d" , &x , &y);
		A.uni(x,y);
	}
	repp(i,0,L){
		int x,y;
		scanf("%d%d" , &x , &y);
		B.uni(x,y);
	}
	repp(i,1,N+1){
		V[A.boss(i)].PB(i);
	}
	repp(i,1,N+1){
		if((int)V[i].size() == 0) continue;
		C.dft();
		repv(int,it,V[i]){
			C.uni(B.boss(*it)+N,(*it));
		}
		repv(int,it,V[i]){
			ans[*it] = C.size(*it) - 1;
		}
	}
	repp(i,1,N+1){
		printf("%d%c" , ans[i] , i == N ? '\n' : ' ');
	}
	return 0;
}

