void sunion(vector<ll>& s,vector<ll>& t){
  vector<ll> u;
  auto its=s.begin(),itt=t.begin();
  while(its!=s.end()&&itt!=t.end()){
    if(*its<*itt){u.pb(*its);its++;}
    else{u.pb(*itt);itt++;}
  }
  while(its!=s.end()) u.pb(*(its++));
  while(itt!=t.end()) u.pb(*(itt++));
  s=u;
}

