  int Rank[100001];
  void init(int n){
    for(int i=0;i<n;i++){
      par[i]=i;
      Rank[i]=0;
    }
  }
  int Find(int a){
    if(par[a]==a)return a;
    return Find(par[a]);
  }
  bool same(int a,int b){
    return Find(a)==Find(b);
  }
  void Unite(int a,int b){
    if(Find(a)==Find(b))return;
    if(Rank[a]>Rank[b]){
      par[b]=a;
    }else{
      par[a]=b;
      if(Rank[a]==Rank[b]){
        Rank[a]++;
      }
    }
  }
  void Union(int a,int b){
    Unite(Find(a),Find(b));
  }
};

