int par[200000], ra[200000];
int sz;
int inv[200000];

void dsuInit(int dsz) {
    sz = dsz;
    forn(i, sz) {
        par[i] = i;
        ra[i] = 1;
    }
}

int dsuParent(int v) {
    if (v == par[v]) {
        return v;
    }
    return par[v] = dsuParent(par[v]);
}

void dsuMerge(int u, int v) {
    u = dsuParent(u);
    v = dsuParent(v);
    if (u == v) {
        return;
    }
    if (ra[u] < ra[v]) {
        swap(u, v);
    }
    par[v] = u;
    ra[u] += ra[v];
}

