struct unionfind {
    vector<int> data;
    unionfind(int size) : data(size, -1) { }
    bool union_set(int x, int y) {
        x = root(x); y = root(y);
        if (x != y) {
            if (data[y] < data[x]) swap(x, y);
            data[x] += data[y]; data[y] = x;
        }
        return x != y;
    }
    bool find_set(int x, int y) {
        return root(x) == root(y);
    }
    int root(int x) {
        return data[x] < 0 ? x : data[x] = root(data[x]);
    }
    int size(int x) {
        return -data[root(x)];
    }
};

struct qunionfind{
    vector<vector<int>> toItems; // MEMO:何故かdequeになってた
    vector<int> data;

    qunionfind(int size) : data(size, -1) { 
        toItems.resize(size);
        for (int i=0;i<size;i++){
            toItems[i].emplace_back(i);
        }
    }
    bool union_set(int x, int y) {
        x = root(x); y = root(y);
        if (x != y) {
            if (data[y] < data[x]) swap(x, y);
            toItems[x].insert(toItems[x].end(),ALL(toItems[y]));
            data[x] += data[y]; data[y] = x;
        }
        return x != y;
    }
    inline bool find_set(int x, int y) {
        return root(x) == root(y);
