struct UnionFindTree {
	int n, c;
	vector<int> p;

	UnionFindTree(int n): n(n), c(n), p(n, -1) {}

	// xが属する集合とyが属する集合の併合
	bool unite(int x, int y) {
		x = find(x); y = find(y);
		if (x == y) return false;
		if (p[x] > p[y]) swap(x, y);
		p[x] += p[y];
		p[y] = x;
		c--;
		return true;
	}

	// xが属する集合の親
	int find(int x) { return (p[x] < 0 ? x : p[x] = find(p[x])); }

	// xとyが同一の集合に属するか判定
	bool same(int x, int y) { return find(x) == find(y); }

	// xが属する集合の大きさ
	int size(int x) { return -p[find(x)]; }

	// 連結成分の個数
	int count() { return c; }
};
