class auxtree
{
    public:

  vector<pair<int,int> > aux; //first: parent second:rank(height)



  auxtree(int v)
  {
     aux.resize(v+1);
    for(int i=1;i<=v;i++)
    {
        aux[i].first=i;
        aux[i].second=0;
    }

  }

  int find_par(int x)
  {
      if(aux[x].first==x)
        return x;
      return aux[x].first=find_par(aux[x].first);
  }

  void tre_union(int x,int y)
  {
       x=find_par(x);
       y=find_par(y);

      if(aux[x].second>aux[y].second)
      {
          aux[y].first=x;
          return;
      }
      else if(aux[y].second>aux[x].second)
      {
          aux[x].first=y;
          return;
      }

      aux[x].second++;
      aux[y].first=x;

  }


};


