using namespace std;

struct UnionFindTree {
    size_t n;
    vector<int> tree;
    UnionFindTree(size_t n): n(n) {
        tree = vector<int>(n, -1);
    }
    int find_root(size_t v) {
        if (tree[v] < 0) return v;
        return tree[v] = find_root(tree[v]);
    }
    bool unite(size_t x, size_t y) {
        x = find_root(x);
        y = find_root(y);
        if (x == y) return false;
        if (rank(x) < rank(y)) swap(x, y);
        tree[x] += tree[y];
        tree[y] = x;
        return true;
    }
    bool has_same_root(size_t x, size_t y) {
        return find_root(x) == find_root(y);
    }
    int rank(size_t v) {
        return -tree[find_root(v)];
    }
};

int main() {
    size_t N, K, L;
    scanf("%zu %zu %zu", &N, &K, &L);

    UnionFindTree g(N);
    for (size_t i=0; i<K; ++i) {
        size_t p, q;
        scanf("%zu %zu", &p, &q);
        --p; --q;

        g.unite(p, q);
    }

    UnionFindTree h(N);
    for (size_t i=0; i<L; ++i) {
        size_t r, s;
        scanf("%zu %zu", &r, &s);
        --r; --s;

        if (g.has_same_root(r, s))
            h.unite(r, s);
    }

    for (size_t i=0; i<N; ++i)
        printf("%d%c", h.rank(i), i<N-1? ' ':'\n');

    return 0;
}

