typedef long long int ll;


const int MAX_N = 200000;
const int MAX_KL = 100000;

class UnionFind{
    public:
        void init(int n);
        void unite(int a, int b);
        bool same(int a, int b);
        int count(int a);
    private:
        int root(int a);
        int par[MAX_N];
        int rank[MAX_N];
        int size[MAX_N];
};

void UnionFind::init(int n) {
    for (int i = 0; i < n; i++) {
        par[i] = i;
        rank[i] = 0;
        size[i] = 1;
    }
    return;
}

void UnionFind::unite(int a, int b) {
    a = root(a);
    b = root(b);
    if (a == b) {
        return;
    }
    if (rank[a] < rank[b]) {
        par[a] = b;
        size[b] += size[a];
    } else {
        par[b] = a;
        size[a] += size[b];
        if (rank[a] == rank[b]) {
            rank[a]++;
        }
    }
    return;
}

bool UnionFind::same(int a, int b) {
    return root(a) == root(b);
}

int UnionFind::count(int a) {
    return size[root(a)];
}

int UnionFind::root(int a) {
    if (par[a] != a) {
        par[a] = root(par[a]);
    }
    return par[a];
}


