struct UnionFind{
	vector<int> par,sz;
	UnionFind(int n)
		:par(n + 1),sz(n + 1,1){
		for(int i = 1;i <= n;i++) par [i] = i;
	}
	int find(int x){
		if(par [x] == x) return x;
		return par [x] = find(par [x]);
	}
	bool connect(int x,int y){
		x = find(x),y = find(y);
		if(x == y) return false;
		if(sz [x] < sz [y]) swap(x,y);
		par [y] = x;
		sz [x] += sz [y];
		return true;
	}
	int size(int x){
		return sz [find(x)];
	}
	bool same(int x,int y){
		return find(x) == find(y);
	}
};

