int get_root(int p[], int v) {
    if (p[v] == v) {
        return v;
    }
    return p[v] = get_root(p, p[v]);
}

void un(int p[], int r[], int v, int u) {
    v = get_root(p, v);
    u = get_root(p, u);
    if (r[v] < r[u]) {
        swap(v, u);
    }
    if (r[v] == r[u]) {
        ++r[v];
    }
    p[u] = v;
}

