const int MAX_N = 200000;

int road[MAX_N];
int rank1[MAX_N];
int railway[MAX_N];
int rank2[MAX_N];
int tree_size[MAX_N];

void initial(int* par,int* rank,int* cnt,int n){		//初期化
	for(int i=0;i<n;i++){
		par[i] = i;
		rank[i] = 0;
		cnt[i] = 1; //iが根の場合その木の要素数
	}
}

int find(int* par,int x){		//木の根を求める
	if(par[x] == x){
		return x;
	}else{
		return par[x] = find(par,par[x]);
	}
}

void unite(int* par,int* rank,int* cnt,int x,int y){	//x,yの属する集合を結合する
	x = find(par,x);
	y = find(par,y);
	if(x == y) return;
	if(rank[x] < rank[y]){
		par[x] = y;
		cnt[y] += cnt[x];
	}else{
		par[y] = x;
		cnt[x] += cnt[y];
		if(rank[x] == rank[y]){
			rank[x]++;
		}
	}
}

bool same(int* par,int x,int y){		//x,yの属する集合が同一かどうかを判定する
	return find(par,x) == find(par,y);
}

int main()
{
	int N,K,L,p1,p2;
	cin >> N;
	cin >> K;
	cin >> L;
	initial(road,rank1,tree_size,N);
	for(int i=0;i<K;i++){
