    s--;
    railway.merge(r, s);
  }
  auto roots = map<pair<int, int>, int>();
  REP(i, N) {
    pair<int, int> p = {road.root(i), railway.root(i)};
    roots[p]++;
  }
  REP(i, N) {
    pair<int, int> p = {road.root(i), railway.root(i)};
    int cnt = roots[p];
    cout << cnt;
    if(i != N - 1) {
      cout << " ";
    } else {
      cout << endl;
    }
  }
}

