struct DSU
{
	int S;

	struct node
	{
		int p;
		unordered_map<int,int> ma;
	};
	vector<node> dsu;

	DSU(int n)
	{
		S = n;
		for(int i = 0; i < n; i++)
		{
			node tmp;
			tmp.p = i;
			dsu.pb(tmp);
		}
	}

	void reset(int n, vi &vec)
	{
		dsu.clear();
		S = n;
		for(int i = 0; i < n; i++)
		{
			node tmp;
			tmp.p = i;
			tmp.ma[vec[i]]++;
			dsu.pb(tmp);
		}
	}

	int rt(int u)
	{
		if(dsu[u].p == u) return u;
		dsu[u].p = rt(dsu[u].p);
		return dsu[u].p;
	}

	void merge(int u, int v)
	{
		u = rt(u); v = rt(v);
		if(u == v) return ;
		if(dsu[v].ma.size()>dsu[u].ma.size()) swap(u,v);
		dsu[v].p = u;
		while(!dsu[v].ma.empty())
		{
			mit it = dsu[v].ma.begin();
			dsu[u].ma[it->fi]+=it->se;
			dsu[v].ma.erase(it);
		}
	}

	bool sameset(int u, int v)
	{
		if(rt(u) == rt(v)) return true;
		return false;
	}

};
