		railParent[i] = i;
		pathParent[i] = i;
		pathSize[i] = 1;
		railSize[i] = 1;
	}				
}
int findSetPath(int u) {
	if (pathParent[u] == u) {
		return u;
	}
	return pathParent[u] = findSetPath(pathParent[u]); 
}
int findSetRail(int u) {
	if (railParent[u] == u) {
		return u;
	}
	return railParent[u] = findSetRail(railParent[u]);
}
void path_unite(int u, int v) {
	int a = findSetPath(u);
	int b = findSetPath(v);
// cout << a << " " << b << endl;
	if (a != b) {
		 if (pathSize[a] < pathSize[b]) {
		 	swap(a, b);
		 }
		 pathParent[b] = a;
		 pathSize[a] += pathSize[b];
	}
// cout << pathParent[a] << " " << pathParent[b] << endl;
}
void rail_unite(int u, int v) {
	int a = findSetRail(u);
	int b = findSetRail(v);

	if (a != b) {
		 if (railSize[a] < railSize[b]) {
		 	swap(a, b);
		 }
		 railParent[b] = a;
		 railSize[a] += railSize[b];
	}
}
