class UnionFind {
public:
  vector<int> r, p;
  UnionFind(int N)
  {
    for (int i = 0; i < N; ++i) {
      r.push_back(0);
      p.push_back(i);
    }
  }
  void unite(int a, int b)
  {
    link(find(a), find(b));
  }
  int find(int a)
  {
    return (a == p[a]) ? a : p[a] = find(p[a]);
  }
  bool is_same_set(int a, int b)
  {
    return find(a) == find(b);
  }
  void link(int a, int b)
  {
    if (a == b) return ;
    if (r[a] > r[b]) {
      p[b] = a;
    } else {
      p[a] = b;
      if(r[a] == r[b]) r[b]++;
    }
  }
};

