//union-find tree
#define MAX_N 200008
ll par[MAX_N][2];
ll depth[MAX_N][2];

void init(ll n, ll istrain){
	for(ll i = 1; i <= n; i++){
		par[i][istrain] = i;
		depth[i][istrain] = 0;
	}
}

ll find(ll x, ll istrain){
	if(x == par[x][istrain]){
		return x;
	}else{
		return par[x][istrain] = find(par[x][istrain], istrain);
	}
}

void unite(ll x, ll y, ll istrain){
	x = find(x, istrain);
	y = find(y, istrain);
	if(x == y){return;}

	if(depth[x][istrain] < depth[y][istrain]){
		par[x][istrain] = y;
		if(istrain == 1){ans[par[x][1]] += ans[par[y][1]];} 
	}else{
		par[y][istrain] = x;
		if(depth[x][istrain] == depth[y][istrain]) depth[x][istrain]++;
		if(istrain == 1){ans[par[y][1]] += ans[par[x][1]];} 
	}
}

bool same(ll x, ll y, ll istrain){
	return find(x, istrain) == find(y, istrain);
}
//
int main(){
	cin >> n >> k >> l;

	init(n, 0);
	for(ll i = 1; i <= k; i++){
		cin >> p >> q;
		unite(p, q, 0);
	}

	for(ll i = 1; i <= n; i++){ans[i] = 1;}

	init(n, 1);
	for(ll j = 1; j <= l; j++){
		cin >> p >> q;
		if(same(p, q, 0)){
			unite(p, q, 1);
		}
	}

	for(ll i = 1; i <= n-1; i++){cout << ans[find(i, 1)] << " ";}
	cout << ans[find(n, 1)] << endl;
	return 0;
}

