struct dsu {
  int sz[N], par[N];
  int n;
  dsu(int _n) : n(_n) {
    fill(sz+1, sz+1+n, 1);
    memset(par, 0, sizeof par);
    iota(par+1, par+1+n, 1);
  }
  int find(int u) {
    return par[u] == u ? u : par[u] = find(par[u]);
  }
  int unite(int u, int v) {
    u = find(u);
    v = find(v);
    if(u != v) {
      if(sz[u] > sz[v]) swap(u, v);
      sz[v] += sz[u];
      par[u] = v;
      return 1;
    } return 0;
  }
};

