void Calc() {
  int n, k, l;
  in, n, k, l;
  UnionFind a(n), b(n), c(n), d(n);
  vector<pair<int, int>> aa;
  rep(i, k) {
    int p, q;
    in, p, q;
    p--, q--;
    a.unite(p, q);
    aa.push_back({ p, q });
  }
  rep(i, l) {
    int r, s;
    in, r, s;
    r--, s--;
    b.unite(r, s);
    aa.push_back({ r, s });
  }
  for (auto& i : aa) {
    if (a.same(i.first, i.second) && b.same(i.first, i.second)) {
      c.unite(i.first, i.second);
    }
  }
  vector<int> out(n);

  rep(i, n) {
    out[i] = c.size(i);
  }

  OutContainer(all(out)); cout << endl;
}

