const llong inf = llong(1e18)+7;
const llong mod = 1e9+7;

struct Unifind{
	vector<int> par;

	Unifind(){}
	Unifind(int n) :
		par(n+1, -1)
	{}
	int root(int x){
		if(par[x] < 0) return x;
		return par[x] = root(par[x]);
	}
	int size(int x){
		return -par[root(x)];
	}
	bool same(int a, int b){
		return root(a) == root(b);
	}
	bool marge(int a, int b){
		a = root(a), b = root(b);
		if(a == b) return false;
		if(par[a] > par[b]) swap(a, b);
		par[a] += par[b];
		par[b] = a;
		return true;
	}
};

int main(){
	llong N, K, L;
	cin >> N >> K >> L;

	Unifind road(N), train(N), ans(N);
	int p,q;
	for(int i = 0; i < K; i++){
		cin >> p >> q;
		road.marge(p,q);
	}
	int r,s;
	for(int i = 0; i < L; i++){
		cin >> r >> s;
		train.marge(r,s);
		if(road.same(r,s) && train.same(r,s))
			ans.marge(r,s);
	}

	for(int i = 1; i <= N; i++)
		cout << ans.size(i) << " ";
	cout << endl;

	return 0;
}

