    road_uinion.unite(--p, --q);
  }
  for (int i = 0; i < L; ++i) {
    int r, s;
    cin >> r >> s;
    rail_uinion.unite(--r,--s);
  }

  map<pii, int> group;
  for (int i = 0; i < N; ++i) {
    ++group[pii(road_uinion.find(i), rail_uinion.find(i))];
  }


  for (int i = 0; i < N; ++i) {
    cout << group[pii(road_uinion.find(i), rail_uinion.find(i))] << endl;
  }

}

