ll par[10][1001000];
ll ranks[10][1001000];

void init(ll n){
	REP(j, 10){
		for (ll i = 0; i < n + 1; i++){
			par[j][i] = i;
			ranks[j][i] = 0;
		}
	}
}

ll find(ll x, ll g){
	if (par[g][x] == x){
		return x;
	}
	else{
		return par[g][x] = find(par[g][x], g);
	}
}

void unite(ll x, ll y, ll g){
	x = find(x, g);
	y = find(y, g);
	if (x == y)return;

	if (ranks[g][x] < ranks[g][y]){
		par[g][x] = y;
	}
	else{
		par[g][y] = x;
		if (ranks[g][x] == ranks[g][y])ranks[g][max(x, y)]++;
	}
}

bool same(ll x, ll y, ll g){
	return find(x, g) == find(y, g);
}

