int bfs(ll x)
{
    queue<ll>q;
    q.push(x);
    visit[x] = 1;
    while(!q.empty())
    {
        int r = q.front();
        q.pop();
        for(int i=0; i<vec[r].size(); i++)
        {
            if(visit[vec[r][i]]==0)
            {
                visit[vec[r][i]] = 1;
                q.push(vec[r][i]);
            }
        }
    }
}int bfs2(ll x)
{
    queue<ll>q;
    q.push(x);
    ac[x] = 1;
    while(!q.empty())
    {
        int r = q.front();
        q.pop();
        for(int i=0; i<rail[r].size(); i++)
        {
            if(ac[rail[r][i]]==0)
            {   ac[rail[r][i]] = 1;

                q.push(rail[r][i]);
            }
        }
    }
}
