int par[2][1001000];//親の要素の番号（par[x]=xの時、xは木の根）
int ranks[2][1001000];//木の深さ

void init(int n){
	REP(j, 2){
		for (int i = 0; i < n; i++){
			par[j][i] = i;
			ranks[j][i] = 0;
		}
	}
}

//木の根を求める
int find(int x, int g){
	if (par[g][x] == x){
		return x;
	}
	else{
		return par[g][x] = find(par[g][x], g);
	}
}

//xとyの属する集合を併合
void unite(int x, int y, int g){
	x = find(x, g);
	y = find(y, g);
	if (x == y)return;

	if (ranks[g][x] < ranks[g][y]){
		par[g][x] = y;
	}
	else{
		par[g][y] = x;
		if (ranks[g][x] == ranks[g][y])ranks[g][x]++;
	}
}

//xとyが同じ集合に属するかどうか
bool same(int x, int y, int g){
	return find(x, g) == find(y, g);
}

