struct UnionFind
{
    vector<int> rnk, par;

    UnionFind(int N) : par(N), rnk(N)
    {
        for (int i = 0; i < N; ++i)
        {
            rnk[i] = 1;
            par[i] = i;
        }
    }
    int root(int x)
    {
        if (par[x] == x)
            return x;
        return par[x] = root(par[x]);
    }
    void unite(int x, int y)
    {
        x = root(x);
        y = root(y);

        if (x == y)
            return;

        if (rnk[x] > rnk[y])
            par[y] = x;
        else
        {
            par[x] = y;
            if (rnk[x] == rnk[y])
                rnk[y]++;
        }
    }
    bool same(int x, int y)
    {
        x = root(x);
        y = root(y);
        return x == y;
    }
};

