struct N001 {
   long n;
   std::vector<long> parents;
   std::vector<long> numbers;
   N001(long n_) : n(n_), parents(n+1, -1), numbers(n+1, -1) {
   }
};
long find(N001& s, long x) {
   if( s.parents[x] == -1 ) return x;
   return s.parents[x] = find(s, s.parents[x]);
}
bool same(N001& s, long x, long y) {
   return find(s, x) == find(s, y);
}
void unite(N001& s, long x, long y) {
   long x2 = find(s, x);
   long y2 = find(s, y);
   if( x2 == y2 ) return;
   if( not ( s.numbers[x2] <= s.numbers[y2] ) )
      std::swap(x2, y2);
   s.parents[x2] = y2;
   s.numbers[y2] += s.numbers[x2];
}

struct Solver {
   Solver() { fprintf(stderr, "--------Solver begin--------\n"); }
   ~Solver() { fprintf(stderr, "--------Solver end--------\n"); }
   void solve() {
      long n, k, l; scan(n, k, l);
      N001 uf1(n), uf2(n);
      for(long i = 0; i < k; ++i) {
         long a, b; scan(a, b);
         unite(uf1, a, b);
      }
      for(long i = 0; i < l; ++i) {
         long a, b; scan(a, b);
         unite(uf2, a, b);
      }
      std::map<std::pair<int, int>, int> map;
      for(long i = 1; i <= n; ++i) {
         map[std::make_pair(find(uf1, i), find(uf2, i))] += 1;
      }
      std::vector<long> rs;
      for(long i = 1; i <= n; ++i) {
         long res = map[std::make_pair(find(uf1, i), find(uf2, i))];
         rs.push_back(res);
      }
      printf("%ld", rs[0]);
      for(long i = 1; i < (long)rs.size(); ++i) {
         printf(" %ld", rs[i]);
      }
      putchar('\n');
   }
};

