struct UnionFind {
  vector<int> d;
  UnionFind() {}
  UnionFind(int n) :d(n, -1) {}
  bool unite(int x, int y) {
    int a = root(x), b = root(y);
    if (a == b) return false;
    if (size(a) < size(b)) swap(a, b);
    d[a] += d[b];
    d[b] = a;
    return true;
  }
  int size(int v) { return -d[root(v)]; }
  int root(int v) { return d[v] < 0 ? v : d[v] = root(d[v]); }
  bool same(int x, int y) { return root(x) == root(y); }
};
template<class A>void OutContainer(A b, A e, const char *between = " ") {
  if (b != e)while (cout << *b, ++b != e) cout << between;
}
template<class T>void Out(const char* b, const T &t) { cout << t; }
template<class T, class... Args>void Out(const char* b, const T& t, const Args&... args) {
  cout << t << b;
  Out(b, args...);
}
template<class T, class... Args>void OutSpace(const T& t, const Args&... args) { Out(" ", t, args...); }

void Calc() {
  int n, k, l;
  in, n, k, l;
  UnionFind a(n), b(n), c(n), d(n);
  vector<pair<int, int>> aa;
  rep(i, k) {
    int p, q;
    in, p, q;
    p--, q--;
    a.unite(p, q);
    aa.push_back({ p, q });
  }
  rep(i, l) {
    int r, s;
    in, r, s;
    r--, s--;
    if (a.same(r, s)) {
      b.unite(r, s);
    }
    d.unite(r, s);
  }
  for (auto& i : aa) {
    if (d.same(i.first, i.second)) {
      c.unite(i.first, i.second);
    }
  }
  vector<int> out(n);

  rep(i, n) {
    out[i] = max(b.size(i), c.size(i));
  }

  OutContainer(all(out)); cout << endl;
}

