struct DSU
{
  vector <int> p, w;

  void build(int n)
  {
    w.resize(n);
    p.resize(n);
    forn(i, n)
      w[i] = 1, p[i] = i;
  }

  int get_leader(int v)
  {
    return v == p[v] ? v : p[v] = get_leader(p[v]);
  }

  void Union(int a, int b)
  {
    a = get_leader(a);
    b = get_leader(b);

    if (a == b)
      return;
    if (w[a] < w[b])
      swap(a, b);
    p[b] = a;
    w[a] += w[b];
  }
};

