class UF{
public:
  vector<int> par,rank,cnt;
  vector<set<int> > U; 
  UF(){};
  UF(int n){
    par.resize(N);
    rank.resize(N);
    cnt.resize(N,1);
    U.resize(N);
    for(int i=0;i<N;i++)par[i]=i,rank[i]=0,cnt[i]=0;
  }

  int find(int x){
    if(par[x]==x)return x;
    return par[x]=find(par[x]);
  }

  void unite(int x,int y){
    x=find(x);
    y=find(y);
    if(x==y)return;
    if(rank[x]<rank[y])par[x]=y,cnt[y]+=cnt[x];
    else{
      par[y]=x;
      cnt[x]+=cnt[y];
      if(rank[x]==rank[y])rank[x]++;
    }
  }

  bool same(int x,int y){return find(x)==find(y);}

};

UF K,L;
void dfsK(int pos){
  for(int i=0;i<GK[pos].size();i++){
    int nx=GK[pos][i];
    if(K.same(pos,nx))continue;
    K.unite(pos,nx);
    dfsK(nx);
  }
}


void dfsL(int pos){
  for(int i=0;i<GL[pos].size();i++){
    int nx=GL[pos][i];
    if(L.same(pos,nx))continue;
    L.unite(pos,nx);
    dfsL(nx);
  }
}

UF U;
int ans[N];
void And(int pos){
  if(ans[U.find(pos)]) return;

  int res=0;
  int par=K.find(pos);
  set<int>::iterator it = K.U[par].begin();
  while(it!=K.U[par].end()){
    int nx=*it;
    if(!L.same(pos,nx))break;
    U.unite(pos,nx);
    res++;
    K.U[par].erase(it++);

  }
  ans[U.find(pos)]+=res;
}

