    ll N,M,T; cin >> N >> M >> T;
    vector<ll> A(N); for(auto& in:A) cin >> in;
    vector<vector<pair<pll,ll>>> G(N);
    vector<vector<pair<pll,ll>>> rG(N);
    for(int i = 0; i < M;i++){
        ll a,b,c; cin >> a >> b >> c;
        a--; b--;
        G[a].push_back({{a,b},c});
        rG[b].push_back({{b,a},c});
    }
    vector<ll> dist(N,LINF),rdist(N,LINF);
    queue<ll> q;
    q.push(0);
    dist[0] = 0;
    while(q.size()){
        ll n = q.front(); q.pop();
        for(auto e: G[n]){
            ll next = e.first.second, cost = e.second;
            if(dist[next] > dist[n] + cost){
                dist[next] = dist[n] + cost;
                q.push(next);
            }
        }
    }

    q.push(0);
    rdist[0] = 0;
    while(q.size()){
        ll n = q.front(); q.pop();
        for(auto e: rG[n]){
            ll next = e.first.second, cost = e.second;
            if(rdist[next] > rdist[n] + cost){
                rdist[next] = rdist[n] + cost;
                q.push(next);
            }
        }
    }
//    cout << dist << endl;
//    cout << rdist << endl;
//
    ll ans = 0;
    for(int i = 0; i < N;i++){
        if(dist[i]+rdist[i]>T) continue;
        ans = max(ans,A[i]*(T-dist[i]-rdist[i]));
    }
    cout << ans << endl;
    return 0;
}

