vector<int>bfsroad(int source,vector<int>ed[],int m)
{
    int i,j,k,u,v,sz;
    queue<int>q;
    q.push(source);
    mark[source][0]=m;
    vector<int>ans;
    ans.pb(source);
    while(!q.empty())
    {
        u=q.front();
        q.pop();
        sz=ed[u].size();
        for(i=0;i<sz;i++)
        {
            v=ed[u][i];
            if(mark[v][0]==0)
            {
                mark[v][0]=m;
                q.push(v);
                ans.pb(v);
            }
        }
    }
    return ans;
}
vector<int> bfsrail(int source,vector<int>ed[],int m,int n)
{
    int i,j,u,v,sz;
    queue<int>q;
    vector<int>ans;
    ans.pb(source);
    q.push(source);
    mark[source][1]=n;
    while(!q.empty())
    {
        u=q.front();
        q.pop();
        sz=ed[u].size();
        for(i=0;i<sz;i++)
        {
        v=ed[u][i];
            if(mark[v][0]==m && mark[v][1]==0)
            {
                mark[v][1]=n;
                q.push(v);
                ans.pb(v);
            }
        }
    }

    return ans;

}

