        return parent[v]=find_set(parent[v]);
    }
    int find_sz(int v){
    	return size[find_set(v)];
    }
    void union_sets(int a,int b){
        int x=find_set(a);
        int y=find_set(b);
        if(x==y)return;
        if(size[x]<size[y])swap(x,y);
        parent[y]=x;
        size[x]+=size[y];
    }
