vector<int> bfs(vector<int> graph[], int start)
{

	vector<int> explored;

	queue<int> q;
	q.push(start);
	while (!q.empty())
	{
		int first = q.front();
		checked[first] = true;
		for (int i = 0; i < graph[first].size(); ++i)
		{
			if (!checked[graph[first][i]])
				q.push(graph[first][i]);
		}
		q.pop();
		explored.push_back(first);
	}

	return explored;
}

int main()
{
	//ifstream cin("input.txt");

	cin >> N >> K >> L;

	for (int i = 0; i < K; ++i)
