	for (int i = 0; i < L; ++i)
	{
		cin >> r >> s;
		rail[r].push_back(s);
		rail[s].push_back(r);
	}

	for (int i = 1; i <= N; ++i)
	{
		int it1 = 0;
		int it2 = 0;
		while (it1 < road[i].size() && it2 < rail[i].size())
		{
			if (road[i][it1] < rail[i][it2])
				++it1;
			else if (road[i][it1] > rail[i][it2])
				++it2;
			else
			{
				both[i].push_back(road[i][it1]);
				++it1;
				++it2;
			}
		}
	}

	for (int i = 1; i <= N; ++i)
	{
		results[i] = 0;
	}

	set<int> cities;
	for (int i = 1; i <= N; ++i)
	{
		cities.insert(i);
		checked[i] = false;
	}

	while (cities.size() > 0)
	{
		vector<int> explored = bfs(both, *cities.begin());

		for (int i = 0; i < explored.size(); ++i)
		{
			cities.erase(explored[i]);
			results[explored[i]] += explored.size();
		}
	}

	for (int i = 1; i <= N; ++i)
	{
		cout << results[i] << " ";
	}


	return 0;
}

