union_find *road, *rail;

int n, k, l;
int dict[234567];

int par[234567];
unordered_map<int, vector<int>>parse;
void transfer(int dex)
{
	if (par[dex] >= 0)return;
	for (auto i : parse[road->find(dex)])
	{
		if (road->check(dex, i) && rail->check(dex, i))
		{
			par[i] = dex;
		}
	}
}

int main(void)
{
	scanf("%d %d %d", &n, &k, &l);
	auto a = union_find(n);
	auto b = union_find(n);
