	for (int i = 0; i < k; ++i)
	{
		int p, q;
		scanf("%d %d", &p, &q);
		road->unite(p - 1, q - 1);
	}
	for (int j = 0; j < l; ++j)
	{
		int r, s;
		scanf("%d %d", &r, &s);
		rail->unite(r - 1, s - 1);
	}
	fill(par, par + n, -1);
	fill(dict, dict + n, 0);
	for (int a = 0; a < n; ++a)
	{
		int thpar = road->find(a);
		parse[thpar].push_back(a);
