const int MAX_N = 200000, MAX_K = 100000, MAX_L = 100000;

int N;
int K, L;
vector<int> edge1[MAX_N], edge2[MAX_N];

int lab1[MAX_N];
int lab2[MAX_N];

vector<int> tmp;
vector<vector<int>> ans;

void dfs1(int v, int label)
{
	lab1[v] = label;
	for (int u : edge1[v]) {
		if (lab1[u] == -1) {
			dfs1(u, label);
		}
	}
	return;
}

void dfs2(int v, int label)
{
	lab2[v] = label;
	++tmp[lab1[v]];
	for (int u : edge2[v]) {
		if (lab2[u] == -1) {
			dfs2(u, label);
		}
	}
	return;
}

void solve()
{
	memset(lab1, -1, sizeof(lab1));
	memset(lab2, -1, sizeof(lab2));

	int l = 0;
	for (int i = 0; i < N; ++i) {
		if (lab1[i] == -1) {
			dfs1(i, l++);
		}
	}

	int m = 0;
	for (int i = 0; i < N; ++i) {
		if (lab2[i] == -1) {
			tmp.clear();
			tmp.resize(l);
			dfs2(i, m++);
			ans.push_back(tmp);
		}
	//	printf("%d %d %d\n", i, lab1[i], lab2[i]);
		printf("%d%c", ans[lab2[i]][lab1[i]], i == N - 1 ? '\n' : ' ');
	}
}

int main()
{
	scanf("%d", &N);
	scanf("%d%d", &K, &L);
	for (int i = 0; i < K; ++i) {
		int p, q;
		scanf("%d%d", &p, &q);
		edge1[p-1].push_back(q-1);
		edge1[q-1].push_back(p-1);
	}
	for (int i = 0; i < L; ++i) {
		int p, q;
		scanf("%d%d", &p, &q);
		edge2[p-1].push_back(q-1);
		edge2[q-1].push_back(p-1);
	}
	solve();

	return 0;
}

