	{
		int p, q;
		cin >> p >> q;
		train[p - 1].push_back(q - 1);
		train[q - 1].push_back(p - 1);
	}

	int cid_max = 1;
	REP(i, N)
	{
		if (car_id[i] > 0) continue;
		queue<int> q;
		q.push(i);
		car_id[i] = cid_max;
		car_vec[cid_max].push_back(i);
		while (q.size() > 0)
		{
			int size = q.size();
			REP(j, size)
			{
				int p = q.front();
				q.pop();
				for (int c : car[p])
				{
					if (car_id[c] > 0) continue;
					car_id[c] = cid_max;
					q.push(c);
					car_vec[cid_max].push_back(c);
				}
			}
		}
		cid_max++;
	}
	cid_max--;

	int id = 1;
	REP(i, N)
	{
		if (train_id[i] > 0) continue;
		queue<int> q;
		q.push(i);
