int par[2][MAX_N];  //親
int ran[2][MAX_N]; //深さ

//初期化
void init(int n){
	FOR1(n){
		par[0][i] = i;
		par[1][i] = i;
		ran[0][i] = 0;
		ran[1][i] = 0;
	}
}

//根を求める
int find(int x, int t){
	if(par[t][x] == x){
		return x;
	}else{
		return par[t][x] = find(par[t][x], t);
	}
}

//xとyの属する集合の併合
void unite(int x, int y, int t){
	x = find(x, t);
	y = find(y, t);
	if(x == y) return;

	if(ran[t][x] < ran[t][y]){
		par[t][x] = y;
	}else{
		par[t][y] = x;
		if(ran[t][x] == ran[t][y]) ran[t][x]++;
	}
}

//同じ集合に属するか否か
bool same(int x, int y, int t){
	return find(x, t) == find(y, t);
}


