using namespace std;

struct Node
{
    int rank = 0;
    int parent = 0;
};

int get_parent(Node node[], int x)
{
    if(node[x].parent == 0)
        return x;
    return get_parent(node, node[x].parent);
}

void Union(Node node[], int a,int b)
{
    a = get_parent(node, a);
    b = get_parent(node, b);
    if (a == b) return;
    if(node[a].rank > node[b].rank)
        node[b].parent = a;
    else
    {
        node[a].parent = b;
        if(node[a].rank == node[b].rank)
            node[b].rank++;
    }
}

int main() {
    int N, K, L;
    cin >> N >> K >> L;
    Node roads[100001];
    Node railways[100001];
    for (int i = 0; i < K; ++i) {
        int p, q;
        cin >> p >> q;
        Union(roads, p, q);
    }
    for (int i = 0; i < L; ++i) {
        int r, s;
        cin >> r >> s;
        Union(railways, r, s);
    }
    for (int i = 1; i <= N; ++i) {
        int both = 0;
        int rootr = get_parent(roads, i);
        int rootw = get_parent(railways, i);
        for (int j = 1; j <= N; ++j) {
            int groupr = get_parent(roads, j);
            int groupw = get_parent(railways, j);
            both += (groupr == rootr) && (groupw == rootw);
        }
        cout << both << " ";
    }
    cout << endl;
    return 0;
}

