#include "bits/stdc++.h"
using namespace std;
const int N = 2e5 + 5;
int n , k , l;
int a , b;
int parent1[N];
int parent2[N];
int sz[N];
int find(int node , int parent[]){
    if(node != parent[node]){
        parent[node] = find(parent[node] , parent);
    }
    return parent[node];
}
int main(){
    scanf("%d %d %d" , &n , &k , &l);
    for(int i = 1 ; i <= n ; ++i){
        parent1[i] = i;
        parent2[i] = i;
        sz[i] = 1;
    }
    while(k--){
        scanf("%d %d" , &a , &b);
        parent1[find(a , parent1)] = find(b , parent1);
    }
    while(l--){
        scanf("%d %d" , &a , &b);
        if(find(a , parent1) == find(b , parent1)){
            if(find(a , parent2) != find(b , parent2)){
                sz[find(a , parent2)] += sz[find(b , parent2)];
                parent2[b] = find(a , parent2);
            }
        }
    }
    for(int i = 1 ; i <= n ; ++i){
        printf("%d%c" , sz[find(i , parent2)] , " \n"[i == n]);
    }
}

#include <iostream>
