using namespace std;

#define rep(i, n) for (int i = 0; i < (int)n; i++)
#define vec vector
#define ll long long

class UnionFind
{
public:
	vec<int> p;
	vec<int> Rank;

	UnionFind(int n) : p(n), Rank(n, 0) {
		rep(i, n) p[i] = i;
	}

	void init(int n)
	{
		p.resize(n);
		rep(i, n) p[i] = i;
		Rank.resize(n);
		rep(i, n) Rank[i] = 0;
	}

	int root(int a)
	{
		if (p[a] == a) return a;
		p[a] = root(p[a]);
		return p[a];
	}

	void unite(int a, int b)
	{
		int ra = root(a);
		int rb = root(b);
		if (Rank[ra] > Rank[rb]) p[rb] = ra;
		else p[ra] = rb;
		if (Rank[ra] == Rank[rb]) Rank[rb]++;
	}

	int is_same_group(int a, int b)
	{
		return (root(a) == root(b));
	}
};

int main(void)
{
	int n, k, l;
	cin >> n >> k >> l;

	UnionFind road(n), train(n);
	rep(i, k) {
		int a, b;
		cin >> a >> b;
		a--;
		b--;
		road.unite(road.root(a), road.root(b));
	}
	rep(i, l) {
		int a, b;
		cin >> a >> b;
		a--;
		b--;
		train.unite(train.root(a), train.root(b));
	}

	vec<pair<pair<int, int>, int>> set(n);
	rep(i, n) {
		set[i].first.first = road.p[i];
		set[i].first.second = train.p[i];
		set[i].second = i;
	}

	sort(set.begin(), set.end());
	vec<int> ans(n);
	int cur = 0;
	while(cur < n) {
		int prev = cur;

		for (; cur <= n; cur++) {
			if (cur < n && set[prev].first == set[cur].first) continue;
			break;
		}
		for (int i = prev; i < cur; i++) ans[set[i].second] = cur - prev;
	}

	rep(i, n - 1) cout << ans[i] << " ";
	cout << ans[n - 1] << endl;
	return 0;
}

