int n,k,l,road_no[200100],rail_no[200100],no_jalur[200100];
map<int,vi> road,rail,jalan,rel,jalur;
bool vis_road[200100],vis_rail[200100],vis_kota[200100];
int main()
{
	scanf("%d%d%d",&n,&k,&l);
	for(int i=0,p,q;i<k;i++)
	{
		scanf("%d%d",&p,&q);
		road[p].pb(q);	road[q].pb(p);
	}
	for(int i=0,p,q;i<l;i++)
	{
		scanf("%d%d",&p,&q);
		rail[p].pb(q);	rail[q].pb(p);
	}
	int cnt_road = 1;
	for(int i=1;i<=n;i++)
	{
		if(!vis_road[i])
		{
			//bfs
			queue<int> qi;
			vis_road[i] = true;
			road_no[i] = cnt_road;
			jalan[cnt_road].pb(i);
			qi.push(i);
			while(!qi.empty())
			{
				int qf = qi.front();
				int sz = road[qf].size();
				qi.pop();
				for(int j=0;j<sz;j++)
				{
					if(!vis_road[road[qf][j]])
					{
						vis_road[road[qf][j]] = true;
						qi.push(road[qf][j]);
						road_no[road[qf][j]] = cnt_road;
						jalan[cnt_road].pb(road[qf][j]);
					}
				}
			}
			cnt_road++;
		}
	}
	int cnt_rail = 1;
	for(int i=1;i<=n;i++)
	{
		if(!vis_rail[i])
		{
			//bfs
			queue<int> qi;
			vis_rail[i] = true;
			rail_no[i] = cnt_rail;
			rel[cnt_rail].pb(i);
			qi.push(i);
			while(!qi.empty())
			{
				int qf = qi.front();
				int sz = rail[qf].size();
				qi.pop();
				for(int j=0;j<sz;j++)
				{
					if(!vis_rail[rail[qf][j]])
					{
						vis_rail[rail[qf][j]] = true;
						qi.push(rail[qf][j]);
						rail_no[rail[qf][j]] = cnt_rail;
						rel[cnt_rail].pb(rail[qf][j]);
					}
				}
			}
			cnt_rail++;
		}
	}
	int cnt_jalur = 0;
	for(int i=1;i<=n;i++)
	{
		if(!vis_kota[i])
		{
			vis_kota[i] = true;
			no_jalur[i] = cnt_jalur;
			jalur[cnt_jalur].pb(i);
			int no = road_no[i];
			int sz = jalan[no].size();
