class range {private: struct I{int x;int operator*(){return x;}bool operator!=(I& lhs){return x<lhs.x;}void operator++(){++x;}};I i,n;
public:range(int n):i({0}),n({n}){}range(int i,int n):i({i}),n({n}){}I& begin(){return i;}I& end(){return n;}};

void get_chunk(int N, int K, vector<int>& chunk) {
  vector<vector<int>> vg(N);
  for (int j : range(K)) {
    int p, q; scanf("%d%d", &p, &q);
    p--; q--;
    vg[p].push_back(q);
    vg[q].push_back(p);
  }
  vector<vector<int>> lll;
  vector<char> vis(N);
  for (int i : range(N)) {
    if (vis[i]) continue;
    queue<int> q;
    q.push(i);

    vector<int> vis2;
    while (!q.empty()) {
      int j = q.front(); q.pop();
      if (vis[j]) continue;
      vis[j] = 1;
      vis2.push_back(j);
      for (auto k : vg[j]) {
        if (!vis[k]) q.push(k);
      }
    }
    lll.push_back(vis2);
  }
  chunk.assign(N, 0);
  for (int i : range(lll.size())) {
    for (int k : lll[i]) {
      chunk[k] = i;
    }
  }
}

int main() {
  int N, K, L;
  while (scanf("%d%d%d", &N, &K, &L) != EOF) {
    vector<int> ch1, ch2;
    get_chunk(N, K, ch1);
    get_chunk(N, L, ch2);

    map<pair<int, int>, int> cnt;
    for (int i : range(N)) {
      cnt[make_pair(ch1[i], ch2[i])]++;
    }

    for (int i : range(N)) {
      if (i) printf(" ");
      int d = cnt[make_pair(ch1[i], ch2[i])];
      printf("%d", d);
    }
    puts("");
  }
}

