using namespace std;
struct Union{
  vector<int> r,p;
  Union(int size){init(size);}
  void init(int size){
    r.resize(size);
    p.resize(size);
    for(int i=0;i<size;i++) r[i]=1,p[i]=i;
  }
  int find(int x){
    if(x!=p[x]) p[x]=find(p[x]);
    return p[x];
  }
  bool same(int x,int y){
    return find(x)==find(y);
  }
  void unite(int x,int y){
    x=find(x);y=find(y);
    if(x==y) return;
    if(r[x]<r[y]) swap(x,y);
    r[x]+=r[y];
    p[y]=x;
  }
};
typedef pair<int,int> P;
int main(){
  int n,k,l,i,j,p,q;
  cin>>n>>k>>l;
  Union u1(n+1),u2(n+1),u3(n+1);
  vector<P> v(k+l);
  for(i=0;i<k;i++){
    cin>>p>>q;
    v[i]=P(p,q);
    u1.unite(p,q);
  }
  for(i=0;i<l;i++){
    cin>>p>>q;
    v[k+i]=P(p,q);
    u2.unite(p,q);
  }
  for(i=0;i<k+l;i++){
    p=v[i].first;q=v[i].second;
    if(u1.same(p,q)&&u2.same(p,q)) u3.unite(p,q);
    if(u1.same(1,p)&&u2.same(1,p)) u3.unite(1,p);
    if(u1.same(1,q)&&u2.same(1,q)) u3.unite(1,q);
  }
  for(i=1;i<=n;i++) printf("%d%c",u3.r[u3.find(i)]," \n"[i==n]);
  return 0;
}

