    if(par2[x] == x) return x;
    else return par2[x] = find2(par2[x]); // root を return しつつ、次回 find の高速化のためにノード x を直接 root につなぐ
}

bool same2(int x, int y) { // クエリ1 (判定)
    return find2(x) == find2(y);
}

void unite2(int x, int y) { // クエリ2 (二つの木をまとめる)
    x = find2(x);
    y = find2(y);
    if(x == y) return;
    if(rnk2[x] < rnk2[y]) { // root が x の木の方が root が y の木よりも低い
        par2[x] = y; // root y に x の木をつなぐ
    }
    else {
        par2[y] = x; // root x に y の木をつなぐ
        if(rnk2[x] == rnk2[y]) ++rnk2[x]; // 同じ高さだったならばまとめたことによって高さ +1
    }
}

