class UnionFind {
public:
vector<ll> parent;
UnionFind(int n) {
    parent = vector<ll>(n, -1);
}
int root(int a) {
    if(parent[a] < 0) return a;
    return parent[a] = root(parent[a]);
}
int size(int a) {
    return -parent[root(a)];
}
bool same(int x, int y){
    return root(x) == root(y);
}
bool unite(int a, int b) {
    a = root(a);
    b = root(b);
    if(a == b) {
        return false;
    }
    if(size(a) < size(b)) swap(a, b);
    parent[a] += parent[b];
    parent[b] = a;
    return true;
}
};

