struct Count {
    ll count;
    ll road;
    ll rail;
    Count(ll road, ll rail) {
        this->count = 0LL;
        this->road = road;
        this->rail = rail;
    }
    bool operator==(const Count& x) const {
        if (this->road != x.road) return false;
        if (this->rail != x.rail) return false;
        return true;
    }
    bool operator<(const Count& x) const {
        if (this->road < x.road) return true;
        if (this->road > x.road) return false;
        if (this->rail < x.rail) return true;
        if (this->rail > x.rail) return false;
        return false;
    }
    bool operator>(const Count& x) const {
        if (this->road > x.road) return true;
        if (this->road < x.road) return false;
        if (this->rail > x.rail) return true;
        if (this->rail < x.rail) return false;
        return false;
    }
};

void make_counts(V<Count> &counts, UnionFind &uf_road, UnionFind &uf_rail, ll n)
{
    set<Count> scounts;
    rep (i0, n) {
        ll i = i0 + 1LL;
        ll root_road = uf_road.root(i);
        ll root_rail = uf_rail.root(i);
        scounts.insert(Count(root_road, root_rail));
    }
    for (auto count : scounts) counts.pb(count);
}

void countup(V<Count> &counts, Count *pcounts[],
             UnionFind &uf_road, UnionFind &uf_rail,
             ll n)
{
    rep (i0, n) {
        ll i = i0 + 1LL;
        ll root_road = uf_road.root(i);
        ll root_rail = uf_rail.root(i);

        auto iter = lower_bound(ALL(counts), Count(root_road, root_rail));
        ll idx = iter - counts.begin();
        counts[idx].count++;
        pcounts[i] = &counts[idx];
    }
}

int _main()
{
    ll n; llin(n);
    ll road; llin(road);
    ll rail; llin(rail);
    V<t2> pqlist; llinl2(pqlist, road);
    V<t2> rslist; llinl2(rslist, rail);

    UnionFind uf_road(n+1);
    for (auto pq : pqlist) uf_road.unite(get<0>(pq), get<1>(pq));
    UnionFind uf_rail(n+1);
    for (auto rs : rslist) uf_rail.unite(get<0>(rs), get<1>(rs));

    V<Count> counts;
    make_counts(counts, uf_road, uf_rail, n);

    Count *pcounts[n+1];
    countup(counts, pcounts, uf_road, uf_rail, n);

    rep (i0, n) {
        ll i = i0 + 1LL;
        cout << pcounts[i]->count << ((i == n) ? "" : " ");
    }

    return 0;
}

