//木の根を求める
ll find(ll x, ll g){
	if (par[g][x] == x){
		return x;
	}
	else{
		return par[g][x] = find(par[g][x], g);
	}
}

//xとyの属する集合を併合
void unite(ll x, ll y, ll g){
	x = find(x, g);
	y = find(y, g);
	if (x == y)return;

	if (ranks[g][x] < ranks[g][y]){
		par[g][x] = y;
	}
	else{
		par[g][y] = x;
		if (ranks[g][x] == ranks[g][y])ranks[g][x]++;
	}
}

//xとyが同じ集合に属するかどうか
bool same(ll x, ll y, ll g){
	return find(x, g) == find(y, g);
}

