        }
        rr = min(rr, rs);
        rs = max(rr, rs);
        while (r != rr) {
            int u = railways[r];
            railways[r] = rr;
            r = u;
        }
        while (s != rs) {
            int u = railways[s];
            railways[s] = rr;
            s = u;
        }
        if (r != s) {
            railways[rs] = rr;
        }
    }
    for (int i = 1; i <= N; ++i) {
        int both = 0;
        int rootr = i;
        int rootw = i;
        while (roads[rootr] != 0) {
            rootr = roads[rootr];
        }
        while (railways[rootw] != 0) {
            rootw = railways[rootw];
        }
        for (int j = 1; j <= N; ++j) {
            int groupr = j;
            int groupw = j;
            while (roads[groupr] != 0) {
                groupr = roads[groupr];
            }
            while (railways[groupw] != 0) {
                groupw = railways[groupw];
            }
            both += (groupr == rootr) && (groupw == rootw);
        }
        cout << both << " ";
    }
    cout << endl;
    return 0;
}

