int get(int a, int b)
{
	if (w[a][b] == a)
		return w[a][b];
	return w[a][b] = get(w[a][b],b);
}

void merge(int a, int b, int id)
{
	a = get(a, id);
	b = get(b, id);
	if (a == b)
		return;
	w[a][id] = b;
	sz[b][id] += sz[a][id];
}

