using namespace std;

int visit[N];
int road_con[N];
int rail_con[N];
int n_road,n_rail;
int city;
int cont[N];

int Find1(int x)
{
    while(x!=road_con[x])
    x=road_con[x];
    return x;
}
int Find2(int x)
{
    while(x!=rail_con[x])
    x=rail_con[x];
    return x;
}

void join_road(int a, int b)
{
    int aa = Find1(a);
    int bb = Find1(b);
    if(aa != bb) road_con[aa] = bb;
}

void join_rail(int a, int b)
{
    int aa = Find2(a);
    int bb = Find2(b);
    if(aa != bb) rail_con[aa] = bb;
}

bool ok_road(int a,int b)
{
    if(Find1(a)==Find1(b))return true;
    else return false;
}
bool ok_rail(int a,int b)
{
    if(Find2(a)==Find2(b))return true;
    else return false;
}

void Create()
{
    int i;
    int x,y;
    for(i=0;i<=city;i++)
    {
        road_con[i]=i;
        rail_con[i]=i;
    }
    for(i=0;i<n_road;i++)
    {
        scanf("%d%d",&x,&y);
        join_road(x,y);
        road_con[y]=road_con[x]=Find1(x);
    }
    for(i=0;i<n_rail;i++)
    {
        scanf("%d%d",&x,&y);
        join_rail(x,y);
        rail_con[x]=rail_con[y]=Find2(x);
    }
    memset(visit,0,sizeof(visit));
}

int main()
{
    int i,j;
    while (~scanf("%d%d%d",&city,&n_road,&n_rail))
    {
        Create();
        for(i=0;i<=city;i++)cont[i]=1;
        for(i=1;i<city;i++)
        {
            for(j=i+1;j<=city;j++)
            {
                if(!visit[j]&&ok_road(i,j)&&ok_rail(i,j))
                {
                    cont[i]++;
                    cont[j]++;
                }
            }
            visit[i]=1;
        }
        for(i=1;i<=city;i++)
        {
            if(i!=1)printf(" ");
            printf("%d",cont[i]);
        }
        printf("\n");
    }
}

#include<bits/stdc++.h>
using namespace std;
const int N = 200005;

int n, m1, m2, par[N], sz[N], cp1[N], cp2[N], wh[N], cs[N], cc;
bool vis[N];

vector<int> adj[N];

int Find (int X) {return par[X] = (par[X] == X ? X : Find(par[X]));}

void Union (int A, int B) {
	A = Find(A); B = Find(B);
	if(A == B) return;
	sz[B] += sz[A];
	par[A] = B;
}

void getcp (int M, int C[], bool B) {
	iota(par, par+n+1, 0);
	fill(sz, sz+n+1, 1);
	for(int i=1;i<=M;i++) {
		int A, B;
		scanf("%d%d",&A,&B);
		if(B) {
			adj[A].push_back(B);
			adj[B].push_back(A);
		}
		Union(A, B);
	}
	for(int i=1;i<=n;i++) C[i] = Find(i);
}

void dfs (int I) {
	vis[I] = true; wh[I] = cc; cs[cc]++;
	for(auto &T : adj[I]) {
		if(!vis[T] && cp1[T] == cp1[I] && cp2[T] == cp2[I]) dfs(T);
	}
}

int main()
{
	scanf("%d%d%d",&n,&m1,&m2);
	getcp(m1, cp1, 1); getcp(m2, cp2, 0);
	for(int i=1;i<=n;i++) {
		if(!vis[i]) {dfs(i); cc++;}
		printf("%d ",cs[wh[i]]);
	}
	puts("");
}

