struct DJS
{
	int par[200001],sz[200001];
	void init(int n)
	{
		for(int i=1;i<=n;i++)
			par[i]=i, sz[i]=1;
	}
	int Find(int a)
	{
		if(par[a]==a) return a;
		else return par[a]=Find(par[a]);
	}
	void Union(int a,int b)
	{
		a=Find(a), b=Find(b);
		if(a==b) return;
		par[a]=b;
		sz[b]+=sz[a];
	}
