template <typename TYPE> class UnionFindTree
{
	public:
		// UnionFindTree(int size)
		UnionFindTree()
			: m_parents()
		{
		}
		UnionFindTree(vector<TYPE> &members)
			: m_parents()
		{
			m_parents.clear();
			m_parents.resize(members.size());
			typename vector<TYPE>::iterator it;
			for(it=members.begin();
					it!=members.end();
					it++) {
				m_parents[*it] = *it;
			}
		}
		void setMembers(vector<TYPE> &members)
		{
			m_parents.clear();

			m_parents.resize(members.size());
			typename vector<TYPE>::iterator it;
			for(it=members.begin();
					it!=members.end();
					it++) {
				m_parents[*it] = *it;
			}
		}
	private:
		// vector<int>				 m_parents;
		// map<TYPE, TYPE>				 m_parents;
		vector<TYPE>                 m_parents;
	public:
		TYPE	findRoot(TYPE i, int &out_depth)
		{
			if(m_parents[i]==-1) {
				return -1;
			}
			if(m_parents[i] == i) {
				return i;
			}
			int depth = 0;
			TYPE root = findRoot(m_parents[i], depth);
			out_depth = depth+1;
			m_parents[i] = root;
			return root;
		}
		bool sameRoot(TYPE i, TYPE j)
		{
			int depth_i=0, depth_j=0;
			return findRoot(i, depth_i) == findRoot(j, depth_j);
		}
		void unionTree(TYPE i, TYPE j)
		{
			int depth_i=0, depth_j=0;
			TYPE root_i = findRoot(i, depth_i);
			TYPE root_j = findRoot(j, depth_j);
			if(root_i==root_j) {
				return;
			}

			if(depth_i<depth_j) {
				// i側がj側に併合
				m_parents[root_i] = root_j;
			}
			else {
				// j側がi側に併合
				m_parents[root_j] = root_i;
			}
		}
};


