int root(int t, int x){
  if(p[t][x]==x) return x;
  else return p[t][x]=root(t,p[t][x]);
}

bool same(int t, int x, int y){
  return root(t,x)==root(t,y);
}

void unite(int t, int x, int y){
  x = root(t,x);
  y = root(t,y);
  if(x==y) return;

  p[t][x] = y;
}

