int find(vector<int>& parent, int x){
  if (parent[x] == x){
    return x;
  }else{
    return (parent[x] = find(parent, parent[x]));
  }
}

void unite(vector<int>& parent, vector<int>& rank, int x, int y){
  x = find(parent, x);
  y = find(parent, y);
  if (x == y) return;
  if (rank[x] < rank[y]){
    parent[x] = y;
  }else{
    parent[y] = x;
    if (rank[x] == rank[y]){
      rank[x]++;
    }
  }
}

bool same(vector<int>& parent, int x, int y){
  return find(parent, x) == find(parent, y);
}

