int GetIntersection(const vector<int>& A, const vector<int>& B) {

    int p2=0;
    int p1=0;
    int answer=0;



    while(p1 < A.size() && p2 < B.size()) {
        if (B.back() < A[p1])
            break;

        int low=p2;
        int high=B.size()-1;
        while(low < high) {
            int mid = (low+high)/2;
            if (B[mid] < A[p1])
                low=mid+1;
            else
                high=mid;

        }

        p2=low;

        if (B[p2]==A[p1]) {
            p1++;
            p2++;
            answer++;
        } else {

            // edges[u][k] > road_verts[p1].

            // first p1 such that edges[u][k] <= road_verts[p1].

            if (A.back() < B[p2])
                break;


            low=0;
            high=A.size()-1;
            while(low < high) {
                int mid = (low+high)/2;
                if (B[p2] > A[mid])
                    low=mid+1;
                else
                    high=mid;

            }


            p1 = low;


        }
    }
    return answer;
}


