class UF{
public:
  vector<int> par,rank;
  UF(){};
  UF(int n){
    rank.resize(n,0);
    par.resize(n);
    for(int i=0;i<n;i++)par[i]=i;
  }

  int find(int x){
    if(par[x]==x)return x;
    return par[x]=find(par[x]);
  }

  void unite(int x,int y){
    x=find(x);
    y=find(y);
    if(x==y)return;
    if(rank[x]<rank[y])par[x]=y;
    else{
      par[y]=x;
      if(rank[x]==rank[y])rank[x]++;
    }
  }

  bool same(int x,int y){return find(x)==find(y);}

};


void dfs(int pos,vector<vector<int> >&G,UF &U){
  for(int i=0;i<G[pos].size();i++){
    int nx=G[pos][i];
    if(U.same(pos,nx))continue;
    U.unite(pos,nx);
    dfs(nx,G,U);
  }
}

