#include "bits/stdc++.h"
using namespace std;

struct Union {
	int Par;
	int Rank;
};

static Union Road[200000], Rail[200000];

void init(int X) {
	for (int i = 0; i < X; i++) {
		Road[i].Par = i;
		Road[i].Rank = 0;
		Rail[i].Par = i;
		Rail[i].Rank = 0;
	}
}

int root(int X, Union Y[]) {
	if (Y[X].Par == X) return X;
	else return Y[X].Par = root(Y[X].Par, Y);
}

void unite(int X, int Y, Union Z[]) {
	X = root(Z[X].Par, Z), Y = root(Z[Y].Par, Z);
	if (X == Y) return;
	if (Z[X].Rank < Z[Y].Rank) Z[X].Par = Y;
	else {
		Z[Y].Par = X;
		if (Z[X].Rank == Z[Y].Rank) Z[X].Rank++;
	}
}

bool same(int X, int Y, Union Z[]) {
	return root(Z[X].Par, Z) == root(Z[Y].Par, Z);
}

int main() {
	int N, K, L;
	cin >> N >> K >> L;
	init(N);
	for (int i = 0; i < K; i++) {
		int p, q;
		cin >> p >> q;
		p--, q--;
		unite(p, q, Road);
	}
	for (int i = 0; i < L; i++) {
		int r, s;
		cin >> r >> s;
		r--, s--;
		unite(r, s, Rail);
	}
	map<pair<int, int>, int> mp;
	for (int i = 0; i < N; i++) {
		mp[{root(Road[i].Par, Road), root(Rail[i].Par, Rail)}]++;
	}
	for (int i = 0; i < N; i++) {
		if (i != 0) cout << " ";
		cout << mp[{Road[i].Par, Rail[i].Par}];
	}
}

