class UnionFind{
 private:
  std::vector<int> p_gs_; //正なら親ノードの番号で負なら自身がルートで値は-groupsize
  int groups_;            //groupの数

 public:
  const int nodes;        //ノードの数

  UnionFind(int size):p_gs_(size, -1),groups_(size),nodes(size){}

  bool unite(int x, int y){
    int rx = root(x), ry = root(y);
    if(rx!=ry){
      --groups_;
      if(p_gs_[ry] < p_gs_[rx]) std::swap(rx, ry); //rx<ryにしてrxにryを連結
      p_gs_[rx] += p_gs_[ry];
      p_gs_[ry] = rx;
    }
    return rx != ry;
  }

  bool same(int x, int y){ return root(x)==root(y); }
  int root(int x){ return p_gs_[x]<0 ? x : p_gs_[x]=root(p_gs_[x]); }
  int gsize(int x){ return -p_gs_[root(x)]; }
  int groups() const{ return groups_; }
};

int main() {
    cin.tie(nullptr); ios::sync_with_stdio(false);

    int n, k, l;
    cin >> n >> k >> l;
    UnionFind a(n), b(n);

    vector<int> p(k), q(k);
    for(int i = 0; i < k; ++i){
        cin >> p[i] >> q[i];
        p[i] -= 1;
        q[i] -= 1;
        a.unite(p[i], q[i]);
    }

    vector<int> r(l), s(l);
    for(int i = 0; i < l; ++i){
        cin >> r[i] >> s[i];
        r[i] -= 1;
        s[i] -= 1;
        b.unite(r[i], s[i]);
    }

    UnionFind c(n);
    for(int i = 0; i < k; ++i){
        // aのやつ
        if(b.same(p[i], q[i])) {
            c.unite(p[i], q[i]);
        }
    }

    for(int i = 0; i < l; ++i){
        // bのやつ
        if(a.same(r[i], s[i])) {
            c.unite(r[i], s[i]);
        }
    }


    map<tuple<int, int>, int> answers;

    for(int i = 0; i < n; ++i){
        answers[make_tuple(a.root(i), b.root(i))] += 1;
    }
    for(int i = 0; i < n; ++i){
        if(i != 0){
            cout << " ";
        }
        cout << answers[make_tuple(a.root(i), b.root(i))];
    }
    cout << endl;

    return 0;
}

