class uf{
  public:
    uf(int n){
      stack = new int[n];
      for (int i = 0; i < n; i++) {
        stack[i]=-1;
      }
    }
    int find(int x){
        return stack[x]<0 ? x : stack[x]=find(stack[x]);
    }
    bool check(int x,int y){
      return find(x)==find(y);
    }
    void marge(int x,int y){
      x = find(x);
      y = find(y);
      if(x==y)return ;
      if(-stack[x]<-stack[y])swap(x,y);
      stack[x]+=stack[y];
      stack[y]=x;
    }

    ~uf(){delete stack;}
    int *stack;
};

