using namespace std;

const int size = 200000;

class UnionFind {
  int par[size], rk[size];
public:
  void init() {
    for(int i = 0; i < size; i++){
      par[i] = i;
      rk[i] = 0;
    }
  }

  int find(int x) {
    if(par[x] == x)
      return x;
    return par[x] = find(par[x]);
  }

  int merge(int x, int y) {
    x = find(x);
    y = find(y);
    if(rk[x] > rk[y]) {
      par[y] = x;
    }else if(rk[x] < rk[y]) {
      par[x] = y;
    }else {
      par[y] = x;
      rk[x]++;
    }
  }

};

int main(){
  int N, K, L;
  cin >> N >> K >> L;
  UnionFind train, car;

  train.init();
  car.init();

  for(int i = 0; i < K; i++){
    int from, to;
    cin >> from >> to;
    from -= 1;
    to -= 1;
    train.merge(from,to);
  }

  for(int i = 0; i < L; i++){
    int from, to;
    cin >> from >> to;
    from -= 1;
    to -= 1;
    car.merge(from,to);
  }

