void init_r(int n) {
    par_r.resize(n);
    sz_r.resize(n);
    children_r.resize(n);
    for (int i = 0; i < n; ++i) {
        par_r[i] = i;
        sz_r[i] = 1;
        children_r[i].push_back(i);
    }
}

int find_root_r(int x) {
    return par_r[x] == x ? x : par_r[x] = find_root_r(par_r[x]);
}

bool same_r(int x, int y) {
    return find_root_r(x) == find_root_r(y);
}

void unite_r(int x, int y) {
    x = find_root_r(x);
    y = find_root_r(y);
    if (x == y) return;

    if (sz_r[x] < sz_r[y]) swap(x, y);
    sz_r[x] += sz_r[y];
    rep(i, children_r[y].size()) children_r[x].push_back(children_r[y][i]);
    children_r[y].clear();
    par_r[y] = x;
}

