		// cout << "Asche" << endl;
	}

	for (int i = 0; i < k; ++i) {
		cin >> u >> v;
		rail_unite(u, v);
	}

	for (int i = 1; i < n; ++i) {
		cout << min(pathSize[pathParent[i]], railSize[railParent[i]]) << " ";
	}
	cout << min(pathSize[pathParent[n]], railSize[railParent[n]]) << "\n";
