class UnionFind {
public:
    vector<int> pir;

    UnionFind(int size) : pir(size, -1) {}

    bool unite(int x, int y) {
        x = root(x);
        y = root(y);
        if (x != y) {
            if (pir[y] < pir[x]) swap(x, y);
            pir[x] += pir[y];
            pir[y] = x;
        }
        return x != y;
    }

    bool same(int x, int y) {
        return root(x) == root(y);
    }

    int root(int x) {
        if (pir[x] < 0) {
            return x;
        } else {
            return pir[x] = root(pir[x]);
        }
    }

    int size(int x) {
        return -pir[root(x)];
    }
};

