void make_set_list(set<ll> *set_list[], UnionFind &uf, ll n)
{
    rep (i0, n) {
        ll i = i0 + 1LL;
        ll root = uf.root(i);
        if (!set_list[root]) set_list[root] = new set<ll>();
        set_list[root]->insert(i);
        set_list[i] = set_list[root];
    }

