    rep (i0, n) {
        ll i = i0 + 1LL;
        debug_printf("---- set_list[%lld]\n", i); debug_print(*set_list[i]);
    }
}

void make_intersection(set<ll> *intersections[],
                       set<ll> *road_set_list[],
                       set<ll> *rail_set_list[],
                       ll n)
{
    set<ll> *checked[n+1];
    memset(checked, 0, sizeof(checked));

    rep (i0, n) {
        ll i = i0 + 1LL;

        if (checked[i]) {
            intersections[i] = checked[i];
            continue;
        }

        set<ll> *p = new set<ll>();
        debug_printf("---- road_set_list[i]=%p rail_set_list[i]=%p\n",
                     road_set_list[i], rail_set_list[i]);
        intersection(*road_set_list[i], *rail_set_list[i], *p);
        intersections[i] = p;
        for (auto node : *intersections[i]) checked[node] = p;
    }

    rep (i0, n) {
        ll i = i0 + 1LL;
        debug_printf("---- intersections[%lld]\n", i);
        debug_print(*intersections[i]);
    }
}

