const int nil = -1;
const int N = 1111111;

struct graphics
{
	int n;
	int head[N];

	int id;
	int to[N];
	int next[N];
	int type[N];

	void init(int n) {
		this->n = n;
		REP (i, n) head[i] = nil;
	}
	void add1(int a, int b, int t) {
		to[id] = b; next[id] = head[a]; type[id] = t; head[a] = id++;
	}
	void add(int a, int b, int t) {
		add1(a, b, t); add1(b, a, t);
	}

	int belong[2][N]; int cnt[2][N];
	int stack[N], top;
	void dfs(int u, int t, int p) {
		top = 0; stack[top++] = u;
		while (top > 0) {
			u = stack[--top];
			if (belong[t][u] == nil) {
				belong[t][u] = p; cnt[t][p]++;
				if (t == 0) {
					EDGE(u, v, e) if(type[e] == 0) {
						stack[top++] = v;
					}
				} else {
					EDGE(u, v, e) if(type[e] == 1 && belong[0][v] == belong[0][u]) {
						stack[top++] = v;
					}
				}
			}
		}
	}
	void solve() {
		REP (t, 2) {
			REP (i, n) belong[t][i] = nil;
			REP (i, n) if (belong[t][i] == nil)
				dfs(i, t, i);
		}
	}
} g;

