template <typename T>
class union_find
{
  static const ll MAX_N = 100005;

  private:
    T par[MAX_N], rank[MAX_N];

  public:
    void init(T n)
    { // add a set
        rep(i, 0, n+1)
        {
            par[i] = i;
            rank[i] = 0;
        }
    }

  public:
    T find(T x)
    { // find the parent of x
        if (par[x] == x)
            return x;
        else
            return par[x] = find(par[x]);
    }

  public:
    void unite(T x, T y)
    { // unite x and y
        x = find(x);
        y = find(y);
        if (x == y)
            return;
        if (rank[x] < rank[y])
            par[x] = y;
        else
            par[y] = x;
        if (rank[x] == rank[y])
            rank[x]++;
    }

  public:
    bool same(T x, T y)
    { // compare x's parent and y's parent
        return find(x) == find(y);
    }
};
