void join_road(int a, int b)
{
    int aa = Find1(a);
    int bb = Find1(b);
    if(aa != bb)
    {
        if(road[aa]<road[bb])
        {
            road_con[aa]=bb;
            ++road[aa];
        }
        else
        {
            road_con[bb]=aa;
            ++road[bb];
        }
    }
}

void join_rail(int a, int b)
{

    int aa = Find2(a);
    int bb = Find2(b);
    if(aa != bb)
    {
        if(rail[aa]<rail[bb])
        {
            rail_con[aa]=bb;
            ++rail[aa];
        }
        else
        {
            rail_con[bb]=aa;
            ++rail[bb];
        }
    }
}

