class DisjointSet {
 public:
  int p[ N ];
  void Init( int x ) {
    for ( int i = 1 ; i <= x ; ++i )
      p[ i ] = i;
  }
  int Find( int x ) {
    return x == p[ x ] ? x : p[ x ] = Find( p[ x ] );
  }
  void Union( int x, int y ) {
    p[ Find( x ) ] = Find( y );
  }
};
DisjointSet st, pst;
void init() {
  cin >> n >> k >> l;
  st.Init( n );
  pst.Init( n );
  for ( int i = 0 ; i < k ; ++i ) {
    int x, y;
    cin >> x >> y;
    pst.Union( x, y );
  }
  for ( int i = 1 ; i <= n ; ++i )
    ans[ i ] = 1;
  for ( int i = 0 ; i < l ; ++i ) {
    int x, y;
    cin >> x >> y;
    if ( pst.Find( x ) == pst.Find( y ) ) 
      st.Union( x, y );
  }
}
void solve() {
  vector< vector< int > > group;
  map< int, int > mp;
  int sz = 0;
  for ( int i = 1 ; i <= n ; ++i ) {
    if ( mp.count( st.Find( i ) ) == 0 ) {
      mp[ st.Find( i ) ] = sz;
      vector< int > tmp;
      tmp.PB( i );
      group.PB( tmp );
      ++sz;
    }
    else {
      group[ mp[ st.Find( i ) ] ].PB( i );
    }
  }
  for ( int i = 0 ; i < group.size() ; ++i ) {
    for ( int j = 0 ; j < group[ i ].size() ; ++j ) {
      int now = group[ i ][ j ];
      ans[ now ] += group[ i ].size() - 1;
    }
  }

  for ( int i = 1 ; i <= n ; ++i )
    cout << ans[ i ] << " ";
  cout << endl;
}
int main() {
  IOS;
  int __ = 1;
  //cin >> __;
  while ( __-- ) {
    init();
    solve();
  }
  return 0;
}

