#define forn(i, n) for (int i = 0; i < (int)(n); ++i)
typedef long long LL;
typedef pair<int, int> PII;

int n, m, mm;
vector<int> g[200000], gg[200000];
int c[200000], cc[200000];
vector<int> cm[200000], ccm[200000];

vector<int> *curg;
int *curc;
int curnum;

void dfs(int v) {
    curc[v] = curnum;
    for (int to : curg[v]) {
        if (curc[to] == -1) {
            dfs(to);
        }
    }
}

void solve(vector<int> *g, int *c) {
    curg = g;
    curc = c;
    memset(curc, -1, sizeof cc);
    curnum = 0;
    forn(i, n) {
        if (curc[i] == -1) {
            dfs(i);
            ++curnum;
        }
    }
}

vector<int> vv;
vector<int> res;

int ans[200000];

void dfs2(int v) {
    res.pb(v);
    ans[v] = 0;
    for (int x : vv) if (ans[x] == -1 && cc[v] == cc[x]) {
        dfs2(x);
    }
}

int par[200000], ra[200000];
int sz;
int inv[200000];

void dsuInit(int dsz) {
    sz = dsz;
    forn(i, sz) {
        par[i] = i;
        ra[i] = 1;
    }
}

int dsuParent(int v) {
    if (v == par[v]) {
        return v;
    }
    return par[v] = dsuParent(par[v]);
}

void dsuMerge(int u, int v) {
    u = dsuParent(u);
    v = dsuParent(v);
    if (u == v) {
        return;
    }
    if (ra[u] < ra[v]) {
        swap(u, v);
    }
    par[v] = u;
    ra[u] += ra[v];
}

int main() {
    //freopen("input.txt", "r", stdin);
    scanf("%d%d%d", &n, &m, &mm);
    forn(i, m) {
        int from, to;
        scanf("%d%d", &from, &to), --from, --to;
        g[from].pb(to);
        g[to].pb(from);
    }
    forn(i, mm) {
        int from, to;
        scanf("%d%d", &from, &to), --from, --to;
        gg[from].pb(to);
        gg[to].pb(from);
    }
    solve(g, c);
    solve(gg, cc);
    forn(i, n) cm[c[i]].pb(i);
    forn(i, n) ccm[cc[i]].pb(i);
    memset(ans, -1, sizeof ans);
    memset(inv, -1, sizeof inv);
    forn(i, n) {
        vv = cm[i];
        if (int(vv.size()) < 450) {
            for (int x : vv) {
                if (ans[x] == -1) {
                    res.clear();
                    dfs2(x);
                    for (int y : res) {
                        ans[y] = int(res.size());
                    }
                }
            }
        } else {
            int vsz = int(vv.size());
            forn(j, vsz) {
                inv[vv[j]] = j;
            }
            dsuInit(vsz);
            forn(j, n) {
                if (ccm[j].empty()) {
                    break;
                }
                int pre = -1;
                for (int x : ccm[j]) {
                    if (inv[x] == -1) {
                        continue;
                    }
                    if (pre != -1) {
                        dsuMerge(pre, inv[x]);
                    }
                    pre = inv[x];
                }
            }
            forn(j, vsz) {
                inv[vv[j]] = -1;
            }
            forn(j, vsz) {
                ans[vv[j]] = ra[dsuParent(j)];
            }
        }
    }
    forn(i, n) {
        printf("%d ", ans[i]);
    }
    printf("\n");
    return 0;
}

