void add_edge(graph& g, int from, int to) {
    g[from].push_back((edge){from, to});
}

void dfs(graph& g, int v, int i, vector<int>& id) {
    id[v] = i;
    for(auto e : g[v]) {
        int u = e.to;
        if(id[u] == -1) {
            dfs(g, u, i, id);
        }
    }
}

