using namespace std;

class UF {
public:
	int *root;
	UF(int n) {
		root = new int[n];
		for (int i = 0; i < n; i++) {
			root[i] = i;
		}
	}
	~UF() {
		delete[] root;
	}
	int findRoot(int a) {
		int r = root[a];
		if (r == a) {
			return r;
		} else {
			r = findRoot(r);
			root[a] = r;
			return r;
		}
	}
	void connect(int a, int b) {
		root[findRoot(a)] = findRoot(b);
	}
	bool isConnected(int a, int b) {
		return findRoot(a) == findRoot(b);
	}
};

