const int N = 200002;
int parent[N];
int sz[N];
void build() {
    for(int i=1; i<N; i++)
    {
        parent[i] = i;
        sz[i] = 1;
    }
}

int find_set(int v) {
    if (parent[v] == v) return v;
    parent[v] = find_set(parent[v]);
    return parent[v];
}

void union_set(int a, int b) {
    a = find_set(a);
    b = find_set(b);
    if (a!=b) {
        if (sz[a] < sz[b]) {
            swap(a, b);
        }
        parent[b] = a;
        sz[a] += sz[b];
    }
}


