using namespace std;

class UnionFindTree
{
	vector<int> m_parents;
	vector<int> m_depths;

	public:
		UnionFindTree(int N)
			: m_parents(N), m_depths(N)
		{
			FOR(n,N) {
				m_parents[n]=n;
				m_depths[n]=0;
			}
		}

	public:
		void unionTree(int i, int j)
		{
			// DOUT << "unionTree("<<i<<","<<j<<")"<<endl;
			int depth_i = 0;
			int depth_j = 0;
			int root_i = findRoot(i, depth_i);
			int root_j = findRoot(j, depth_j);
			if(root_i==root_j) {
				return;
			}
			if(depth_i<depth_j) {
				m_parents[root_i] = root_j;
				m_depths[root_i] = 1;
			}
			else {
				m_parents[root_j] = root_i;
				m_depths[root_j] = 1;
			}
		}

		int findRoot(int i, int &out_depth)
		{
			if(i==m_parents[i]) {
				out_depth = 0;
				return i;
			}
			int depth = 0;
			int root = findRoot(m_parents[i], depth);
			m_parents[i] = root;
			m_depths[i] = depth+1;
			out_depth = depth+1;
			return root;
		}

		bool sameRoot(int i, int j)
		{
			int depth_i=0;
			int depth_j=0;
			return findRoot(i, depth_j) == findRoot(j, depth_i);
		}
};

