template<int Max>
class SetUF {
public:
	SetUF() :size(0) {}

	SetUF(int n) :size(n)
	{
		for (int i = 0; i < n; i++)
			id[i] = i;
	}

	void setSize(int n)
	{
		size = n;
		for (int i = 0; i < n; i++)
			id[i] = i;
	}

	bool connected(int p, int q)
	{
		return id[p] == id[q];
	}

	int root(int p)
	{
		return id[p];
	}

	void unite(int p, int q)
	{
		int pid = id[p];
		int qid = id[q];

		for (int i = 0; i < size; i++)
		{
			if (id[i] == pid)
			{
				id[i] = qid;
			}
		}
	}

private:
	int id[Max];
	int size;

};

