void initial(int n,int id){		//初期化
	for(int i=0;i<n;i++){
		par[i][id] = i;
		nrank[i][id] = 0;
	}
}

int find(int x,int id){		//木の根を求める
	if(par[x][id] == x){
		return x;
	}else{
		return par[x][id] = find(par[x][id],id);
	}
}

void unite(int x,int y,int id){
	x = find(x,id);
	y = find(y,id);
	if(x == y) return;
	if(nrank[x][id] < nrank[y][id]){
		par[x][id] = y;
	}else{
		par[y][id] = x;
		if(nrank[x][id] == nrank[y][id])
			nrank[x][id]++;
	}
}

bool same(int x,int y,int id){
	return find(x,id) == find(y,id);
}

