class UnionFind
{
public:
    std::vector<long> _parent;
    std::vector<long> _rank;
    UnionFind(long n)
    {
        for(long i = 0; i < n; i++) {
            _parent.push_back(i);
            _rank.push_back(0);
        }
    }

    long root(long i)
    {
        return (_parent[i] == i) ? i: 
                _parent[i] = root(_parent[i]);
    }

    bool same(long i, long j)
    {
        return root(i) == root(j);
    }

    void unite(long i, long j)
    {
        i = root(i);
        j = root(j);
        if (i == j) return;

        if(_rank[i] < _rank[j])
            _parent[i] = j;
        else {
            _parent[j] = i;
            if (_rank[i] == _rank[j])
                _rank[i]++;
        }
    }
};

int
main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);
