    for (int i = 0; i < K; ++i) {
        int p, q;
        cin >> p >> q; p--; q--;
        if (p > q) v[i] = make_pair(q, p);            
        else v[i] = make_pair(p, q);
    }
    sort(v.begin(), v.end());
    for (int i = 0; i < K; ++i) {
        pair<int, int> pq = v[i];
        car.unite(pq.first, pq.second);
    }

    UnionFind train(N);
    vector<pair<int, int> > vv(L);
    for (int i = 0; i < L; ++i) {
        int p, q; 
        cin >> p >> q; p--; q--;
        if (p > q) vv[i] = make_pair(q, p);            
        else vv[i] = make_pair(p, q);
    }
    sort(vv.begin(), vv.end());
    for (int i = 0; i < L; ++i) {
        pair<int, int> pq = vv[i];
        train.unite(pq.first, pq.second);
    }

    map<long, bitset<MAX_N> > cmap;
    for (int i = 0; i < N; ++i) {
        int parent = car.root(i);
        if (cmap.find(parent) == cmap.end()) {
            bitset<MAX_N> bs(0);
            cmap.insert(make_pair(parent, bs));
        }
        cmap[parent].set(i, 1);
    }
    map<long, bitset<MAX_N> > tmap;
    for (int i = 0; i < N; ++i) {
        int parent = train.root(i);
        if (tmap.find(parent) == tmap.end()) {
            bitset<MAX_N> bs(0);
            tmap.insert(make_pair(parent, bs));
        }
        tmap[parent].set(i, 1);
    }

    map<pair<int, int>, bitset<MAX_N> > ctmap;
    for (int i = 0; i < N; ++i) {
        int croot = car.root(i);
        int troot = train.root(i);
        pair <int, int> p = make_pair(croot, troot);
        if (ctmap.find(p) == ctmap.end()) {
            bitset<MAX_N>& cbs = cmap[croot];
            bitset<MAX_N>& tbs = tmap[troot];
            ctmap.insert(make_pair(p, cbs & tbs));
        }

        if (i != 0) cout << " ";
        cout << ctmap[p].count();

    }
    cout << endl;
    return 0;
}

