class UnionFind {
private:
    vector<int> parent;

public:
    UnionFind(int n)
    {
        parent = vector<int>(n, -1);
    }
    int getparent(int n)
    {
        if(parent[n] == -1) return n;
        else return parent[n] = getparent(parent[n]);
    }
    void connect(int x, int y)
    {
        x = getparent(x);
        y = getparent(y);
        if(x > y) swap(x, y);
        parent[y] = x;
    }
};

