        int ans = 0;
        for(int j=1;j<=N;j++){
            if(uf1.issame(i,j) && uf2.issame(i,j)) ans++;
        }
        cout << ans;

        if(i==N) cout << endl;
        else cout << " ";
    }

    return 0;
}

