using namespace std;
const int maxn=2e5+1212;

int n,m1,m2;
int edgenum,Time,scccnt,stacknum;
bool isstack[maxn],vis[maxn];
int head[maxn],Next[maxn],Stack[maxn],low[maxn],dfn[maxn],V[maxn],color[maxn];
int num[maxn];
vector <int> human;
void init()
{
    memset(num,0,sizeof(num));
    memset(head,-1,sizeof(head));
    memset(isstack,false,sizeof(isstack));
    memset(dfn,-1,sizeof(dfn));
    Time=stacknum=edgenum=0;
}

void add(int u,int v)
{
    V[++edgenum]=v;
    Next[edgenum]=head[u];
    head[u]=edgenum;
}

void dfs(int u)
{
    Time++;
    isstack[u]=true;
    Stack[++stacknum]=u;
    low[u]=dfn[u]=Time;
    for(int i=head[u];i!=-1;i=Next[i])
    {
        int v=V[i];
        if(dfn[v]==-1)
        {
            dfs(v);
            low[u]=min(low[u],low[v]);
        }
        else if(isstack[v]==true) low[u]=min(low[u],dfn[v]);
    }
    if(dfn[u]==low[u])
    {
        scccnt++;
        while(true)
        {
            int v=Stack[stacknum];
            color[v]=scccnt;
            isstack[v]=false;
            stacknum--;
            if(v==u&&stacknum==0) break;
        }
    }
}

void Taijin()
{
    for(int i=1;i<=n;i++)
        if(dfn[i]==-1) dfs(i);
}

void DFS(int u)
{
    human.push_back(u);
    vis[u]=true;
    for(int i=head[u];i!=-1;i=Next[i])
    {
        int v=V[i];
        if(color[v]==color[u]&&vis[v]==false) DFS(v);
    }
}

int main()
{
    int u,v;
    while(scanf("%d %d %d",&n,&m1,&m2)!=EOF)
    {
        init();
        scccnt=0;
        for(int i=1;i<=m1;i++)
        {
            scanf("%d %d",&u,&v);
            add(u,v);
            add(v,u);
        }
        Taijin();
        memset(vis,false,sizeof(vis));
        memset(head,-1,sizeof(head));
        edgenum=0;
        for(int i=1;i<=m2;i++)
        {
            scanf("%d %d",&u,&v);
            add(u,v);
            add(v,u);
        }
        for(int i=1;i<=n;i++)
        {
            human.clear();
            if(vis[i]==false)
            {
                DFS(i);
                for(int j=0;j<(int)human.size();j++)
                {
                    int pos=human[j];
                    num[pos]=num[pos]+human.size();
                }
            }
        }
        for(int i=1;i<=n;i++)
        {
            if(i==n) printf("%d\n",num[i]);
            else printf("%d ",num[i]);
        }
    }
    return 0;
}

