class DSU {
private:
  std::vector<int> p;
public:
  DSU(int n): p(n, - 1) {}

  int findRep(int x) {
    return p[x] < 0? x: p[x] = findRep(p[x]);
  }

  void unite(int x, int y) {
    int p1 = findRep(x), p2 = findRep(y);
    if (p1 == p2) return;
    if (-p[p1] < -p[p2]) std::swap(p1, p2);
    p[p1] += p[p2];
    p[p2] = p1;    
  }

  int getSize(int x) {
    return -p[findRep(x)];
  }

  bool isSame(int x, int y) {
    return findRep(x) == findRep(y);
  }
};

