};

vector<int> uni_road, uni_rail;

void init(vector<int> &r, int n) 
{
    REP (i, n) r.push_back(-1);
}

int root(vector<int> &r, int a)
{
    if (r[a] < 0) return a;
    else return r[a] = root(r, r[a]);
}

bool connect(vector<int> &r, int a, int b)
{
    a = root(r, a);
    b = root(r, b);
    if (a == b) return false;
    if (r[a] > r[b]) swap(a, b);
    r[a] += r[b];
    r[b] = a;
    return true;
}

bool isSame(vector<int> r, int x, int y)
{
    return root(r, x) == root(r, y);
}

