    int N = G.size();
    for(int i=0;i<N;i++){
        checkG[i] = -1;
        checkH[i] = -1;
    }
    for (int i=0;i<N;i++){
        dfsG(G, i, i);
    }
    for(int i=0;i<N;i++){
        dfsH(H, i, i);
    }
