using namespace std;

class UnionFindTree
{
private:
    const int n;
    int groupNum;       // グループの数
    vector<int> parent; // 親ノード
    vector<int> rank;   // 木の高さの上限
    vector<int> num;    // グループの要素数
    int find(int i){
        if(parent[i] == i)
            return i;
        else
            return parent[i] = find(parent[i]);
    }
public:
    UnionFindTree(int n) : n(n){ // コンストラクタ
        groupNum = n;
        parent.resize(n);
        for(int i=0; i<n; ++i)
            parent[i] = i;
        rank.assign(n, 0);
        num.assign(n, 1);
    }
    void unite(int a, int b){ // aとbのグループを併合
        if((a = find(a)) != (b = find(b))){
            if(rank[a] < rank[b]){
                parent[a] = b;
                num[b] += num[a];
            }
            else{
                parent[b] = a;
                if(rank[a] == rank[b])
                    ++ rank[a];
                num[a] += num[b];
            }
            -- groupNum;
        }
    }
    bool same(int a, int b){ // aとbのグループが同じかを調べる
        return find(a) == find(b);
    }
    int getNum(){ // グループの数を返す
        return groupNum;
    }
    int getNum(int a){ // aのグループの要素数を返す
        return num[find(a)];
    }
    void getGroup(vector<int>& index){ // グループ構成を返す
        index.resize(n);
        for(int i=0; i<n; ++i)
            index[i] = find(i);
    }
};

int main()
{
    int n, k, l;
    cin >> n >> k >> l;

    vector<int> a(k), b(k);
    UnionFindTree uft1(n);
    for(int i=0; i<k; ++i){
        cin >> a[i] >> b[i];
        -- a[i];
        -- b[i];
        uft1.unite(a[i], b[i]);
    }

    vector<int> c(l), d(l);
    UnionFindTree uft2(n);
    for(int i=0; i<l; ++i){
        cin >> c[i] >> d[i];
        -- c[i];
        -- d[i];
        uft2.unite(c[i], d[i]);
    }

    vector<int> index1, index2;
    uft1.getGroup(index1);
    uft2.getGroup(index2);
    map<pair<int, int>, int> cnt;
    for(int i=0; i<n; ++i)
        ++ cnt[make_pair(index1[i], index2[i])];

    vector<int> ans(n);
    for(int i=0; i<n; ++i)
        ans[i] = cnt[make_pair(index1[i], index2[i])];

    cout << ans[0];
    for(int i=1; i<n; ++i)
        cout << ' ' << ans[i];
    cout << endl;

    return 0;
}

#include <bits/stdc++.h>
