	for(int i = 0 ; i < k ; i ++){
		uf[0].unit(p[i],q[i]);
	}
	for(int i = 0 ; i < l ; i ++){
		uf[1].unit(r[i],s[i]);
	}

	static map<P,int> cnt;
	for(int i = 1 ; i <= n ; i ++){
		cnt[P(uf[0].find(i),uf[1].find(i))] ++;
	}
