	rep(i, k) {
		int p, q;
		cin >> p >> q; 
		p--; q--;
		road[p].push_back(q);
		road[q].push_back(p);
	}
	rep(i, l) {
		int r, s;
		cin >> r >> s;
		r--; s--;
		line[r].push_back(s);
		line[s].push_back(r);
	}

