	function<void(int, int)> dfs_road = [&](int m, int nm) {
		if (num_road[m] != -1)return;
		num_road[m] = nm;
		each(to, road[m]) {
			dfs_road(to, nm);
		}
	};

	vector<int> num_line(n, -1);

	function<int(int, int)> dfs_line = [&](int m, int nm) {
		if (num_line[m] != -1)return 0ll;
		num_line[m] = nm;

		int ret = 1;
		each(to, line[m]) {
			if (num_road[m] == num_road[to]) {
				ret += dfs_line(to, nm);
