using namespace std;

struct UnionFindTree {
    size_t n;
    vector<int> tree;
    UnionFindTree(size_t n): n(n) {
        tree = vector<int>(n, -1);
    }
    size_t find_root(size_t v) {
        if (tree[v] < 0) return v;
        return tree[v] = find_root(tree[v]);
    }
    bool unite(size_t x, size_t y) {
        x = find_root(x);
        y = find_root(y);
        if (x == y) return false;
        if (rank(x) < rank(y)) swap(x, y);
        tree[x] += tree[y];
        tree[y] = x;
        return true;
    }
    bool connected(size_t x, size_t y) {
        return find_root(x) == find_root(y);
    }
    int rank(size_t v) {
        return -tree[find_root(v)];
    }
};

int main() {
    size_t N, K, L;
    scanf("%zu %zu %zu", &N, &K, &L);

    UnionFindTree g(N);
    for (size_t i=0; i<K; ++i) {
        size_t p, q;
        scanf("%zu %zu", &p, &q);
        --p, --q;

        g.unite(p, q);
    }

    UnionFindTree h(N);
    for (size_t i=0; i<L; ++i) {
        size_t r, s;
        scanf("%zu %zu", &r, &s);
        --r, --s;

        h.unite(r, s);
    }

    vector<size_t> ar(N), br(N);
    for (size_t i=0; i<N; ++i) {
        ar[i] = g.find_root(i);
        br[i] = h.find_root(i);
    }

    map<pair<size_t, size_t>, int> dict;
    for (size_t i=0; i<N; ++i)
        ++dict[make_pair(ar[i], br[i])];

    for (size_t i=0; i<N; ++i)
        printf("%d%c", dict[make_pair(ar[i], br[i])], i<N-1? ' ':'\n');

    return 0;
}

