using namespace std;


struct Union_find{
	Union_find(int n){par.resize(n),iota(_all(par),0);}
	int find(int x){return (par[x]==x)?x:par[x]=find(par[x]);}
	void unite(int a,int b){a=find(a),b=find(b);par[a]=b;}
	bool same(int a,int b){return find(a)==find(b);}
	vector<int> par;
};

using edge=tuple<int,int>;

const int limit=200010;
vector<int> group[limit];
map<int,int> g2i;

vector<edge> group_e[limit];

int ans[limit];

int main(void){
	int n,k,l;
	cin >> n >> k >> l;

	Union_find uf(n);
	rep(loop,k){
		int p,q;
		cin >> p >> q;
		p--,q--;
		uf.unite(p,q);
	}

	rep(i,n) group[uf.find(i)].push_back(i);

	rep(i,n) rep(j,group[i].size()) g2i[group[i][j]]=j;


	rep(loop,l){
		int p,q;
		cin >> p >> q;
		p--,q--;

		if(uf.same(p,q)==false) continue;

		const int i=uf.find(p);
		int pi=g2i[p];
		int qi=g2i[q];
		group_e[i].push_back(edge(pi,qi));
	}

	rep(i,n){
		const int gn=group[i].size();
		if(gn==0) continue;

		sort(_all(group_e[i]));
		Union_find uf2(gn);
		for(auto &e:group_e[i]){
			int p,q;
			tie(p,q)=e;
			uf2.unite(p,q);
		}

		vector<int> tmp(gn,0);
		rep(j,gn) uf2.find(j);
		rep(j,gn) tmp[uf2.find(j)]++;
		rep(j,gn) ans[group[i][j]]=tmp[uf2.find(j)];
	}

	rep(i,n) cout << (i?" ":"") << ans[i];
	cout << endl;

	return 0;
}

