class DisjointSets {
    private:
        vector<int> f, h;
    public:
        DisjointSets(int n = 0) {
            f.assign(n + 1, 0);
            h.assign(n + 1, 1);
            for (int i = 1; i <= n; ++ i) {
                f[i] = i;
            }
        }
        int father(int x) {
            return x == f[x] ? x : (f[x] = father(f[x]));
        }
        void unite(int x, int y) {
            x = father(x);
            y = father(y);
            if (x == y) {
                return;
            }
            if (h[x] == h[y]) {
                h[x] += 1;
                f[y] = x;
            } else if (h[x] > h[y]) {
                f[y] = x;
            } else {
                f[x] = y;
            }
        }
};
