class UF {
private:
  vector<int> data; // parent or size
  void init(int n) {
    data.assign(n, -1);
  }

public:
  UF() {}
  UF(int n) {
    init(n);
  }
  int root(int x) {
    if (data[x] < 0) return x;
    return data[x] = root(data[x]);
  }
  bool unite(int x, int y) {
    x = root(x);
    y = root(y);
    if (x == y) return false;
    if (data[x] > data[y]) swap(x, y); // data[x] and data[y] are negative.
    data[x] += data[y];
    data[y] = x;
    return true;
  }
  int size(int x) {
    return -data[root(x)];
  }
  bool same(int x, int y) {
    return root(x) == root(y);
  }
};

int main() {
  int n, k, l;
  scan(n, k, l);
  auto ufk = UF(n);
  auto ufl = UF(n);
  rep (i, k) {
