	FOR(a,N) {
		FORUL(b,a,N) {
			if(roadconnected.sameRoot(a,b) && railconnected.sameRoot(a,b)) {
				counts[a]++;
				if(a!=b) {
					counts[b]++;
				}
			}
		}
	}
	FOR(n,N) {
