int dfs(const vector<vector<int>> &adj_lists, vector<int> &con_list,
        vector<int> &visited, int v, int g) {
  int ret = 1;
  for (int u : adj_lists[v]) {
    if (visited[u] < 0) {
      visited[u] = g;
      con_list.push_back(u);
      ret += dfs(adj_lists, con_list, visited, u, g);
    }
  }
  return ret;
}

