  for (int i = 1; i <= n; ++i) {
    int ans = 1;
    for (auto itr : e[i]) {
      if (uf_train.find(itr) == uf_train.find(i)) ans += 1;
    }
    if (i == n) {
      cout << ans << endl;
      return 0;
    }
    cout << ans << " ";
  }
}

