vector<vector<int>> pq;
vector<vector<int>> rs;

class UnionFind {
    int n;
    vector<int> par;
    vector<int> rank;

public:
    UnionFind(int a) : n(a), rank(a, 0) {
        par.reserve(n);
        for (int i = 0; i < a; i++) par.push_back(i);
    }
    int find(int x) {
        if (par[x] == x) return x;
        return par[x] = find(par[x]);
    }
    void unite(int x, int y) {
        int x_root = find(x);
        int y_root = find(y);
        if (rank[x_root] > rank[y_root]) {
            par[y_root] = x_root;
        } else if (rank[x_root] < rank[y_root]) {
            par[x_root] = y_root;
        } else if (x_root != y_root) {
            par[y_root] = x_root;
            rank[x_root]++;
        }
    }
    bool same(int x, int y) { return find(x) == find(y); }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> N >> K >> L;
    UnionFind uf(N);
    UnionFind uf2(N);
    pq.resize(N);
    rs.resize(N);
    for (int i = 0; i < K; i++) {
        int p, q;
        cin >> p >> q;
        p--;
        q--;
        pq[p].push_back(q);
        pq[q].push_back(p);
    }
    for (int i = 0; i < L; i++) {
        int r, s;
        cin >> r >> s;
        r--;
        s--;
        rs[r].push_back(s);
        rs[s].push_back(r);
    }

    for (int i = 0; i < N; i++)
        for (int j = 0; j < pq[i].size(); j++) uf.unite(i, pq[i][j]);
    for (int i = 0; i < N; i++)
        for (int j = 0; j < rs[i].size(); j++) uf2.unite(i, rs[i][j]);

    unordered_map<unsigned long long, int> mp;
    for(int i=0; i<N; i++)
        mp[200000 * uf.find(i) + uf2.find(i)]++;

    for (int i = 0; i < N; i++) cout << mp[200000 * uf.find(i) + uf2.find(i)] << " ";

    return 0;
}

