using namespace std;
struct UnionFind{
  vector<int> par,rank;
  UnionFind(int N){
    par.resize(N);
    rank.resize(N);
    for(int i=0;i<N;i++){
      par[i]=i;
      rank[i]=1;
    }
  }
  int find(int x){
    if(par[x]==x)
      return x;
    else{
      int y=find(par[x]);
      par[x]=y;
      return y;
    }
  }
  void unite(int x,int y){
    int x2=find(x),y2=find(y);
    if(x2==y2)
      return;
    if(rank[x2]>=rank[y2])
      par[y2]=x2,rank[x2]=max(rank[x2],rank[y2]+1);
    else
      par[x2]=y2;
  }
  bool same(int x,int y){
    return find(x)==find(y);
  }
};
signed main(){
  int N,K,L;
  cin>>N>>K>>L;
  UnionFind A(N),B(N);
  while(K--){
    int a,b;
    cin>>a>>b;
    A.unite(a-1,b-1);
  }
  while(L--){
    int a,b;
    cin>>a>>b;
    B.unite(a-1,b-1);
  }
  map<pair<int,int>,int> C;
  for(int i=0;i<N;i++)
    C[{A.find(i),B.find(i)}]++;
  for(int i=0;i<N;i++){
    cout<<C[{A.find(i),B.find(i)}];
    if(i==N)cout<<endl;
    else cout<<' ';
  }
}

