#include <iostream>
#include <vector>
using namespace std;

struct UF {
	int num[200001];
	int sz[200001];

	void init(int n) {
		for (int i = 0; i < n; i++) {
			num[i] = i;
			sz[i] = 1;
		}
	}

	int root(int x) { if (num[x] == x) return x; return (num[x] = root(num[x])); }
	void marge(int x, int y) {
		x = root(x);
		y = root(y);
		if (x == y) return;

		num[x] = y;
		sz[y] += sz[x];
	}

	int size(int x) {
		return sz[root(x)];
	}

	int is_same(int x, int y) {
		return root(x) == root(y);
	}
};

UF uf1;
UF uf2;

int n, k, l;
int a, b;

signed main() {
	int i;

	cin >> n >> k >> l;
	uf1.init(n);
	uf2.init(n);

	for (i = 0; i < k; i++) {
		cin >> a >> b;
		a--; b--;
		uf1.marge(a, b);
	}

	for (i = 0; i < l; i++) {
		cin >> a >> b;
		a--; b--;

		if (uf1.is_same(a, b)) {
			uf2.marge(a, b);
		}
	}

	for (i = 0; i < n; i++) {
		cout << uf2.size(i) << endl;
	}
	return 0;
}

