class UnionFind {
public:
	UnionFind(int n) : par(n), rank(n) {
		for (int i = 0; i < n; i++)	par[i] = i;
	}
	int find(int x) {
		return par[x] == x ? x : par[x] = find(par[x]);
	}
	bool same(int x, int y) {
		return find(x) == find(y);
	}
	void unite(int x, int y) {
		x = find(x);
		y = find(y);
		if (x == y) return;
		if (rank[x] < rank[y]) {
			par[x] = y;
		} else {
			par[y] = x;
			if (rank[x] == rank[y]) rank[x]++;
		}
	}
private:
	vector<int> par, rank;
};

int main() {
	int N, K, L;
