    REP(i, N + 1) a[i] = i;
}

int root(int a[], int x) {
    if (a[x] == x) return x;
    else           return a[x] = root(a, a[x]);
}

void unite(int a[], int x, int y) {
    x = root(a, x);
    y = root(a, y);
    if (x != y) a[x] = y;
}

