const int MAX_UF = 100;

class UnionFind {
private:
  int par[MAX_UF];
  int rank[MAX_UF];

public:
  int find(int x);
  void init(int n);
  void unite(int x, int y);
  bool same (int x, int y);
};

void UnionFind::init(int n) {
  for (int i = 0; i < n; ++i) {
    par[i] = i;
    rank[i] = 0;
  }
}

int UnionFind::find(int x) {
  if (par[x] == x) {
    return x;
  } else {
    return par[x] = find(par[x]);
  }
}

void UnionFind::unite(int x, int y) {
  x = find(x); y = find(y);
  if (x == y) {
    return;
  } else {
    if (rank[x] > rank[y]) {
      par[y] = x;
    } else {
      par[x] = y;
      if (rank[x] == rank[y]) ++rank[y];
    }
  }
}

bool UnionFind::same(int x, int y) {
  return find(x) == find(y);
}

