  }
  REP(i, L) {
    int r, s;
    cin >> r >> s;
    r--;
    s--;
    rail.unite(r, s);
  }

  Counter<pair<int, int>> c;
  REP(i, N) {
    c.add(make_pair(road.par[i], rail.par[i]));
  }
  REP(i, N) {
    cout << c.get(make_pair(road.par[i], rail.par[i]));
    if (i < N - 1) {
      cout << " ";
    }
  }
  cout << endl;
  return 0;
}

