    int a, b;
    cin >> a >> b;
    --a;
    --b;
    G1[a].push_back(b);
    G1[b].push_back(a);
  }
  for (int i = 0; i < L; i++) {
    int a, b;
    cin >> a >> b;
    --a;
    --b;
    G2[a].push_back(b);
    G2[b].push_back(a);
  }
  vector<int> id(N, -1);
  int sz = 0;
  for (int i = 0; i < N; i++) {
    if (id[i] != -1) {
      continue;
    }
    queue<int> q;
    id[i] = sz;
    q.push(i);
    while (!q.empty()) {
      int v = q.front();
      q.pop();
      for (int u : G1[v]) {
        if (id[u] == -1) {
          id[u] = sz;
          q.push(u);
        }
      }
    }
    ++sz;
  }
  vector<int> cnt(sz, 0), res(N);
  vector<bool> used(N, false);
  for (int i = 0; i < N; i++) {
    if (used[i]) {
      continue;
    }
    vector<int> vs;
    vs.push_back(i);
    used[i] = true;
    for (int j = 0; j < vs.size(); j++) {
