const int maxn=200005;
int n,k,l;
int f1[maxn],f2[maxn],f3[maxn],col[maxn],sz[maxn];
bool vis[maxn];
vector<int>con[maxn];

int Find(int f[],int x){
	return f[x]==x?x:f[x]=Find(f,f[x]);
}

void Union(int f[],int x,int y){
	x=Find(f,x);y=Find(f,y);
	if(x!=y)f[x]=y,sz[y]+=sz[x];
}

int main(){
	ios::sync_with_stdio(false);
	cin>>n>>k>>l;
	REP(i,n)f1[i]=f2[i]=f3[i]=i,sz[i]=1;
	while(k--){
		int u,v;
		cin>>u>>v;
		Union(f1,u,v);
	}
	REP(i,n)con[Find(f1,i)].push_back(i),col[i]=Find(f1,i);
	REP(i,n)sort(con[i].begin(),con[i].end());
	while(l--){
		int u,v;
		cin>>u>>v;
		Union(f2,u,v);
	}
	REP(i,n)sz[i]=1;
	REP(i,n){
		if(!vis[i]){
			int k=col[i];
			vector<int>can;
			rep(j,con[k].size()){
				int x=con[k][j];
				if(Find(f2,i)==Find(f2,x)){
					Union(f3,i,x);
					vis[x]=true;
					can.push_back(x);
				}
			}
			rep(i,can.size())con[k].erase(lower_bound(con[k].begin(),con[k].end(),can[i]));
		}
	}
	REP(i,n)cout<<sz[Find(f3,i)]<<" ";
	return 0;
}

