typedef vector<int> Edges;
typedef vector<Edges> Graph;
const int N_MAX = 100000;

int checkG[N_MAX];
int checkH[N_MAX];

void dfsG(Graph &G, int s, int mark){
    if(checkG[s] != -1) return;
    checkG[s] = mark;
    for (int i=0;i<G[s].size();i++){
        if(checkG[G[s][i]] == -1){
            dfsG(G, G[s][i], mark);
        }
    }
}

void dfsH(Graph &H, int s, int mark){
    if(checkH[s] != -1) return;
    checkH[s] = mark;
    for (int i=0;i<H[s].size();i++){
        if(checkH[H[s][i]] == -1 && checkG[H[s][i]] == checkG[mark]){
            dfsH(H, H[s][i], mark);
        }
    }
}

void Connectivity(Graph &G, Graph &H){
    int N = G.size();
    for(int i=0;i<N;i++){
        checkG[i] = -1;
        checkH[i] = -1;
    }
    for (int i=0;i<N;i++){
        dfsG(G, i, i);
    }
    for(int i=0;i<N;i++){
        dfsH(H, i, i);
    }
    int count[N];
    for (int i=0;i<N;i++){
        count[i] = 0;
    }
    for(int i=0;i<N;i++){
        count[checkH[i]]++;
    }
    for (int i=0;i<N;i++){
        cout << count[checkH[i]] << endl;
    }
}

int main(){
    int N, K, L, p, q, r, s;
    cin >> N >> K >> L;
    Graph G(N), H(N);
    for (int i=0;i<K;i++){
        cin >> p >> q;
        p--;q--;
        G[p].push_back(q);
        G[q].push_back(p);
    }
    for (int i=0;i<L;i++){
        cin >> r >> s;
        r--;s--;
        H[r].push_back(s);
        H[s].push_back(r);
    }
    Connectivity(G, H);
    return 0;
}

