#define MAX_N 200005
class UnionFind{
	public:
	int par[MAX_N], rank[MAX_N], ans[MAX_N];
	void init(int n){
		for(int i=0; i<n; i++){
			par[i] = i;
			rank[i] = 0;
			ans[i] = 0;
		}
	}

	int root(int x){
		return par[x] == x ? x : par[x] = root(par[x]);
	}

	bool same(int x, int y){
		return root(x) == root(y);
	}

	void unite(int x, int y){
		x = root(x);
		y = root(y);
		if(x == y) return;

		if(rank[x] < rank[y]){
			par[x] = y;
		}else{
			par[y] = x;
			if(rank[x] == rank[y]) rank[x]++;
		}
	}
};

int main(void) {
	//ios_base::sync_with_stdio(false);
	//cin.tie(0);
	UnionFind road = UnionFind();
	UnionFind rail = UnionFind();
	UnionFind total = UnionFind();

	int n, k, l;
	cin >> n >> k >> l;

	road.init(n);
	rail.init(n);
	total.init(n);
	for(int i=0; i<k; i++){
