		int p, q;
		cin >> p >> q;
		rail.unite(p, q);
		if(road.same(p, q)){
			total.unite(p, q);
		}
	}

	for(int i=1; i<=n; i++){
		total.ans[total.root(i)]++;
	}
	for(int i=1; i<=n; i++){
		if(i != n)printf("%d ", total.ans[total.root(i)]);
		else printf("%d\n", total.ans[total.root(i)]);
	}

	return 0;
}

