using namespace std;

int visit[N];
int road_con[N];
int road[N];
int rail_con[N];
int rail[N];
int n_road,n_rail;
int city;
int cont[N];

int Find1(int x)
{
    if(x==road_con[x])return x;
    else return road_con[x]=Find1(road_con[x]);
}
int Find2(int x)
{
    if(x==rail_con[x])return x;
    else return rail_con[x]=Find2(rail_con[x]);
}

void join_road(int a, int b)
{
    int aa = Find1(a);
    int bb = Find1(b);
    if(aa != bb)
    {
        if(road[aa]<road[bb])road_con[aa]=bb;
        else { road_con[bb]=aa; ++road[bb]; }
    }
}

void join_rail(int a, int b)
{

    int aa = Find2(a);
    int bb = Find2(b);
    if(aa != bb)
    {
        if(rail[aa]<rail[bb]){rail_con[aa]=bb;++rail[aa];}
        else{ rail_con[bb]=aa; ++rail[bb];}
    }
}

bool ok_road(int a,int b)
{
    if(Find1(a)==Find1(b))return true;
    else return false;
}
bool ok_rail(int a,int b)
{
    if(Find2(a)==Find2(b))return true;
    else return false;
}

void Create()
{
    int i;
    int x,y;
    memset(road,0,sizeof(road));
    memset(rail,0,sizeof(rail));

    for(i=0;i<=city;i++)
    {
        road_con[i]=i;
        rail_con[i]=i;
    }
    for(i=0;i<n_road;i++)
    {
        scanf("%d%d",&x,&y);
        join_road(x,y);
    }
    for(i=0;i<n_rail;i++)
    {
        scanf("%d%d",&x,&y);
        join_rail(x,y);
    }
    memset(visit,0,sizeof(visit));
}

int main()
{
    int i,j;
    while (~scanf("%d%d%d",&city,&n_road,&n_rail))
    {
        Create();
        for(i=0;i<=city;i++)cont[i]=1;
        for(i=1;i<city;i++)
        {
            for(j=i+1;j<=city;j++)
            {
                if(!visit[j]&&ok_road(i,j)&&ok_rail(i,j))
                {
                    cont[i]++;
                    cont[j]++;
                }
            }
            visit[i]=1;
        }
        for(i=1;i<=city;i++)
        {
            if(i!=1)printf(" ");
            printf("%d",cont[i]);
        }
        printf("\n");
    }
}

