    cin >> n >> k >> l;
    UnionFind a(n), b(n);

    vector<int> p(k), q(k);
    for(int i = 0; i < k; ++i){
        cin >> p[i] >> q[i];
        p[i] -= 1;
        q[i] -= 1;
        a.unite(p[i], q[i]);
    }

