int set1[2000005], set2[2000005], ans[2000005];

int find(int x, int *set)
{
	int s, temp;
	for (s=x; set[s]>=0; s=set[s]) ;
	while (s != x) {
		temp = set[x];
		set[x] = s;
		x = temp;
	}
	return s;
}
void union_set(int x, int y, int * set)
{
	int temp = set[x] + set[y];
	if (set[x] > set[y]) {
		set[x] = y;
		set[y] = temp;
	}
	else {
		set[y] = x;
		set[x] = temp;
	}
}
