class UF{
private:
    vector<int> par,rank,elmNum;
    vector<set<int>> elmList;
public:
    int groups;

    UF(int __size):par(__size) , rank(__size,0) , elmNum(__size,1), elmList(__size) , groups(__size){
        rep(i,__size)elmList[i].insert(i);
        for(int i=0;i<__size;i++)par[i]=i;
    }

    int getElementsNum(int n){ return elmNum[find(n)]; }
    set<int> getElementsList(int n){ return elmList[find(n)]; }

    int find(int x){
        if(par[x]==x) {
            return x;
        }else{
            return par[x]=find(par[x]);
        }
    }

    void unite(int x,int y){
        x=find(x);
        y=find(y);
        if(x==y) return;

        groups--;
        if(rank[x]<rank[y]){
            par[x]=y;
            elmNum[y]+=elmNum[x];
            for(auto &e:elmList[x])elmList[y].insert(e);

        }else{
            par[y]=x;
            elmNum[x]+=elmNum[y];
            for(auto &e:elmList[y])elmList[x].insert(e);
            if(rank[x]==rank[y])rank[x]++;
        }
    }

    bool isSame(int x,int y){
        return find(x)==find(y);
    }
};

int main(){
