        set<int> B = y.getElementsList(i);
        if(A>B)swap(A,B);
        int ans = 0;
        for(auto elm:A){
            if(B.count(elm))ans++;
        }
        if(i)cout<<" ";
        cout<<ans;
    }
    cout<<endl;
}

