	int par[301000];
	int rank[301000];

	void init(int n){
		for (int i = 0; i < n; i++){
			par[i] = i;
			rank[i] = 1;
		}
	}

	int find(int x){
		if (par[x] == x) return x;
		return par[x] = find(par[x]);
	}

	void unite(int x, int y){
		x = find(x);
