struct UF {
	vector<int> par, rank, cnt; //root, tree, count
	UF() {}
	UF(int n){ init(n); }
	void init(int n) {
		par.assign(n+4,0); rank.assign(n+4,0); cnt.assign(n+4,1);
		for(int i = 0; i<n; i++) par[i] = i;
	}
	int find(int x){if(par[x] == x) return x; else return par[x] =find(par[x]);}
	void unite(int x, int y) { //unite, (add)
		x = find(x); y = find(y);
		if(x == y) return;
		if(rank[x] < rank[y]){ par[x] = y; cnt[y] +=cnt[x]; }
		else{ par[y] = x;  cnt[x] +=cnt[y]; if(rank[x] == rank[y]) rank[x]++;}
	}
	bool same(int x, int y) { return find(x) == find(y); }
	int count(int x){return cnt[find(x)];}
};



