class UFT {

public:
	ll size;
	ll mode;
	vll root;
	vll rank;
	UFT(ll sizeget, ll modeget = 0){
		size = sizeget;
		mode = modeget;
		root.res(size, 0);
		if (!mode) rank.res(size, 0);
		IOTA(root, 0);
	}
	ll find(ll x) {
		return root[x] == x ? x : root[x] = find(root[x]);
	}
	bool same(ll x, ll y) {
		return find(x) == find(y);
	}
	void unite(ll x, ll y) {
		x = find(x);
		y = find(y);
		if (x == y) return;
		if (mode) root[y] = x;
		else {
			if (rank[x] < rank[y]) {
				root[x] = y;
			}
			else {
				root[y] = x;
				if (rank[x] == rank[y]) rank[x]++;
			}
		}
	}
};

template <typename valtype> class SegT {

public:

	ll size;
	vector<valtype> v;

	valtype initv;
	function<valtype(valtype x, valtype y)> calc;

	SegT(ll sizeget, ll modeget = 0) {
		sizeset(sizeget);
		modeset(modeget);
		init();
	}
	SegT(vector<valtype> cpyvec, ll modeget = 0) {
		sizeset(cpyvec.sz);
		modeset(modeget);
		init();
		copy(cpyvec);
	}
	SegT(ll sizeget, valtype initvget, function<valtype(valtype x, valtype y)> calcget) {
		sizeset(sizeget);
		initv = initvget;
		calc = calcget;
		init();
	}
	SegT(vector<valtype> cpyvec, valtype initvget, function<valtype(valtype x, valtype y)> calcget) {
		sizeset(cpyvec.sz);
		initv = initvget;
		calc = calcget;
		init();
		copy(cpyvec);
	}
	void sizeset(ll rsize) {
		size = DigN2(rsize);
		if (rsize == Pow2(size - 1)) size--;
		return;
	}
	void modeset(ll mode) {
		switch (mode) {
		case 0:
			initv = 0;
			calc = [](valtype x, valtype y) {return x + y; };
			break;
		case 1:
			initv = INF;
			calc = [](valtype x, valtype y) {return min(x, y); };
			break;
		case 2:
			initv = -INF;
			calc = [](valtype x, valtype y) {return max(x, y); };
			break;
		}
		return;
	}
	void init() {
		v.asn(Pow2(size + 1) - 1, initv);
	}
	void copy(vector<valtype> cpyvec) {
		REP(i, min(cpyvec.sz, Pow2(size))) set(i, cpyvec[i]);
	}
	ll i2v(ll i) const{
		if (i < 0 || i >= Pow2(size)) return -1;
		return Pow2(size) + i - 1;
	}
	ll top(ll i) const{
		if (i == 0) return -1;
		return (i - 1) / 2;
	}
	pl4 bot(ll i) const{
		if (i + 1 >= Pow2(size)) return mp(-1, -1);
		return mp(2 * i + 1, 2 * i + 2);
	}
	void set(ll i, valtype x) {
		i = i2v(i);
		v[i] = x;
		while (i > 0) {
			i = top(i);
			v[i] = calc(v[bot(i).fi], v[bot(i).se]);
		}
		return;
	}
	void add(ll i, valtype x) {
		set(i, v[i2v(i)] + x);
		return;
	}
	valtype operator[](const ll &i) const {
		return v[i2v(i)];
	}
//	valtype que(ll a = 0, ll b = Pow2(size) - 1) {
	valtype que(ll a, ll b) {
		if (a == b) return v[i2v(a)];
		if (a > b) swap(a, b);
		valtype ans = initv;
		ll ai = i2v(a);
		ll bi = i2v(b);
		FOR(i, 1, size + 1) {
			if (a > b) break;
			if (a%Pow2(i)) {
				ans = calc(ans, v[ai]);
				a += Pow2(i - 1);
				ai = top(ai) + 1;
			}
			else {
				ai = top(ai);
			}
			if (a > b) break;
			if ((b + 1) % Pow2(i)) {
				ans = calc(ans, v[bi]);
				b -= Pow2(i - 1);
				bi = top(bi) - 1;
			}
			else {
				bi = top(bi);
			}
			if (a > b) break;
		}
		return ans;
	}


};

template <typename lentype> class Graph {

public:

	ll mode;

	ll size;
	vector<vector<lentype>> Edge;
	vector<vector<lentype>> Path;
	vector<vector<lentype>> Prev;
	vll VtxData;
	vvll EdgeData;
	vector<set<ll>> Adj;

	Graph(ll sizeGet = 0, ll modeget = 0) {
		size = sizeGet;
		mode = modeget;
		init();
	}
	void init() {
		VtxInit();
		PathInit();
		PrevInit();
		return;
	}
	void VtxInit() {
		VtxData.res(size + 1, 0);
		Edge.res(size + 1, vector<lentype>(size, 0));
		EdgeData.res(size + 1, vll(size, 0));
		Edge[size].asn(size, 0);
		EdgeData[size].asn(size, 0);
		Adj.res(size, set<ll>());
		REP(i, size) {
			Edge[i].res(size, 0);
			EdgeData[i].res(size, 0);
		}
		return;
	}
	void PathInit() {
		Path.res(size + 1, vector<lentype>(size, 0));
		Path[size].asn(size, 0);
		REP(i, size) {
			Path[i].res(size, 0);
		}
		return;
	}
	void PrevInit() {
		Prev.res(size + 1, vector<lentype>(size, 0));
		Prev[size].asn(size, 0);
		REP(i, size) {
			Prev[i].res(size, 0);
		}
		return;
	}
	bool chk(ll x) {
		return (x < 0 || x >= size);
	}
/*	ll addV(ll x) {
		size += x;
//		init();
		return size - x;
	}*/
	ll setEData(ll x, ll y, ll i, ll m = -1) {
		if (chk(x) || chk(y)) return -1;
		if (m != -1) {
			switch (mode) {
			case 0:
				EdgeData[x][y] = Bset(EdgeData[x][y], Pow2(i), m);
				EdgeData[y][x] = Bset(EdgeData[y][x], Pow2(i), m);
				break;
			case 1:
				EdgeData[x][y] = Bset(EdgeData[x][y], Pow2(i), m);
				break;
			}
		}
		return Dig2(EdgeData[x][y], i);
	}
	void setE(ll x, ll y, lentype c) {
		if (chk(x) || chk(y)) return;
		switch (mode) {
		case 0:
			Edge[x][y] = c;
			Edge[y][x] = c;
			conE(x, y, 1);
			conE(y, x, 1);
			Adj[x].ins(y);
			Adj[y].ins(x);
			break;
		case 1:
			Edge[x][y] = c;
			conE(x, y, 1);
			Adj[x].ins(y);
			break;
		}
	}
	ll slpV(ll x, ll m = -1) {
		if (chk(x)) return -1;
		if (m != -1) VtxData[x] = m;
		return VtxData[x];
	}
	ll conE(ll x, ll y, ll m = -1) {
		if (chk(x) || chk(y)) return -1;
		if (m == 0) {
			switch (mode) {
			case 0:
				Adj[x].ers(y);
				Adj[y].ers(x);
				break;
			case 1:
				Adj[x].ers(y);
				break;
			}
		}
		return setEData(x, y, 0, m);
	}
	ll slpE(ll x, ll y, ll m = -1) {
		return setEData(x, y, 1, m);
	}
	ll canP(ll x, ll y, ll m = -1) {
		if (x < 0 || x >= (size + 1)) return -1;
		if (chk(y)) return -1;
		if (m != -1) {
