  dsu (int _n = 0) : n(_n) {
    root[0].resize(n+1);
    root[1].resize(n+1);
    for (int t = 0; t < 2; ++t)
    for (int u = 1; u <= n; ++u) {
      root[t][u] = u;
    }
  }
