class UnionFind {
public:
  //"UnionFind uni;"のように宣言
  // 0-indexed
  //親を格納する,根の場合は-(大きさ)を格納
  vector<long> Parent;

  //-1で初期化,nが要素数
  // uni.init(n)
  void init(long n){
    Parent = vector<long>(n,-1);
  }

  //根を求める、子を根につなぎなおす
  // uni.root(a)
  long root(long a){
    if(Parent[a]<0)return a;
    return Parent[a] = root(Parent[a]);
  }

  //根には(-大きさ)が格納されている
  long size(long a){
    return -(Parent[root(a)]);
  }

  //新しくつなぐ、すでにつながっているならfalseを返す
  bool connect(long a,long b){
    //aの根とbの根で考える
    a = root(a);
    b = root(b);
    //既に繋がっているならfalase
    if(a==b){
      return false;
    }
    //大きい木に小さい木をくっつける
    if(size(a)<size(b))swap(a,b);
    //木の大きさの更新
    Parent[a]+=Parent[b];
    //bの親をaにする
    Parent[b]=a;
    return true;
  }

  //同じ木に属しているかどうかtrueなら属している
  bool same(long a,long b){
    return (root(a)==root(b));
  }

};

