int uft_check_parent(int mode,int uft_x){
	if(uft_parent[mode][uft_x]!=-1)return uft_check_parent(mode,uft_parent[mode][uft_x]);
	int uft_a;
	while(!uft_q1.empty()){
		uft_a=uft_q1.front(),uft_q1.pop();
