struct UnionFind{
	vector<int> par;
	vector<int> rank;

	UnionFind(int n){
		par.resize(n);
		rank.resize(n);
		rep(i,n) par.at(i) = i;
	}

	int find(int x){
		if(par.at(x) == x) return x;
		else return par.at(x) = find(par.at(x));
	}

	bool unite(int x, int y){
		x = find(x);
		y = find(y);
		if(x == y) return false;
		else{
			par.at(y) = x;
			if(rank.at(x) == rank.at(y)) rank.at(x)++;
		}
		return true;
	}
};


