  if(f[x]==x)return x;
  else return f[x]=findf(f[x]);
}
void unitep(int x,int y){
  x=findp(x);
  y=findp(y);
  if(x==y)return ;
  if(prnk[x]<prnk[y])p[x]=y;
  else{
    p[y]=x;
    if(prnk[x]==prnk[y])prnk[x]++;
  }
}

void unitef(int x,int y){
  x=findf(x);
  y=findf(y);
  if(x==y)return ;
  if(frnk[x]<frnk[y])f[x]=y;
  else{
    f[y]=x;
    if(frnk[x]==frnk[y])frnk[x]++;
  }
}
bool samep(int x,int y){
  return findp(x)==findp(y);
}
bool samef(int x,int y){
  return findf(x)==findf(y);
}


