        Scd2(a,b);
        a--,b--;
        er[a].push_back(b);
        er[b].push_back(a);
    }

    Rep(i,L){
        Scd2(a,b);
        a--,b--;
        et[a].push_back(b);
        et[b].push_back(a);
    }

    stack<int> s;

    Rep(h,N){
        if( head[h] == -1 ){
            s.push(h);
            while( !s.empty() ){
                int from = s.top();
                s.pop();
                head[from] = h;
                for( int to : er[from] ){
                    if( head[to] == -1 ){
                        s.push(to);
                    }
                }
            }
        }
    }

    vector<int> ans(N);

    Rep(h,N){
        int cnt = 0;
        if( head[h] >= 0 ){
            s.push(h);
            while( !s.empty() ){
                int from = s.top();
                s.pop();
                if( head[from] < 0 ) continue;
                cnt++;
                ans[from] = -h;
                for( int to : et[from] ){
                    if( head[to] == head[from] ){
                        s.push(to);
                    }
                }
                head[from] = -from-1;
            }
            ans[h] = cnt;
        }
    }

    Rep(i,N){
        if( ans[i] <= 0 ) ans[i] = ans[-ans[i]];
        printf ("%d%c", ans[i], i == N-1 ? '\n' : ' ' );
    }


    return 0;
}

