using namespace std;

struct UnionFind {
    vector<int> parent, size;

    UnionFind(int n) : parent(n), size(n, 1) {
        for (int i = 0; i < n; i++) {
            parent[i] = i;
        }
    }

    int operator[](int x) {
        if (parent[x] == x) return x;
        return parent[x] = operator[](parent[x]);
    }

    bool merge(int x, int y) {
        x = operator[](x);
        y = operator[](y);
        if (x == y) return false;
        if (size[x] < size[y]) swap(x, y);
        parent[y] = x;
        size[x] += size[y];
        return true;
    }

    int getSize(int u) {
        return size[operator[](u)];
    }
};

int main() {
    int n, K, L;
    cin >> n >> K >> L;

    UnionFind uf(n);

    for (int i = 0; i < K; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        u--; v--;
        uf.merge(u, v);
    }

    UnionFind uf2(n);

    for (int i = 0; i < L; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        u--; v--;
        if (uf[u] == uf[v]) {
            uf2.merge(u, v);
        }
    }

    for (int i = 0; i < n; i++) {
        printf("%d ", uf2.getSize(i));
    }
}

