	int num[200001];

	void init(int n) {
		for (int i = 0; i < n; i++) {
			num[i] = i;
		}
	}

	int root(int x) { if (num[x] == x) return x; return (num[x] = root(num[x])); }
	void marge(int x, int y) {
		x = root(x);
		y = root(y);
		if (x == y) return;
		num[x] = y;
	}

	int is_same(int x, int y) {
		return root(x) == root(y);
