using namespace std;

class UF {
private:
  vector<int> v;
public:
  UF (int n) {
    v.resize(n);
    REP (i, 0, n) v[i] = i;
  }

  int Find (int a) {
    if (v[a] == a) return a;
    else return v[a] = Find(v[a]);
  }  

  bool isSame (int a, int b) {
    return Find(a) == Find(b);
  }

  bool Union (int a, int b) {
    int pa = Find(a);
    int pb = Find(b);
    if (pa == pb) return false;
    v[pa] = pb;
    return true;
  }

};


int main(){
  int N, K, L;
  cin >> N >> K >> L;
  UF uf(N);
  vector<int> v(N, 1);
  REP (i, 0, K) {
