  REP(i, 0, L) {
    int r, s;
    cin >> r >> s;
    if (uf.isSame(r - 1, s - 1)) {
      v[r - 1]++;
      v[s - 1]++;
    }
  }
  REP (i, 0, v.size()) {
    cout << v[i] << ' ';
  }

  return 0;
}

