void bfs(int u,int nc)
{
    queue<int > q;
    vis[u]=1;
    q.push(u);
    while(!q.empty())
    {
        u= q.front();
        tocomp[u]=nc;
        nodes[nc].push_back(u);
        q.pop();
        for(int v : g[u])
        {
            if(vis[v]) continue;
            vis[v]=1;
            q.push(v);
        }
    }
}
void Bfs(int u,int nc)
{
    queue<int > q;
    Vis[u]=1;
    q.push(u);
    while(!q.empty())
    {
        u= q.front();
        Tocomp[u]=nc;
        Nodes[nc].push_back(u);
        q.pop();
        for(int v : G[u])
        {
            if(Vis[v]) continue;
            Vis[v]=1;
            q.push(v);
        }
    }
}
map<pair<int,int >  ,int > ans;

void sol(int n)
{
    for(int i=1;i<=n;i++)
    {
        if(vis[i]) continue;
        bfs(i,++nc);
    }
    for(int i=1;i<=n;i++)
    {
        if(Vis[i]) continue;
        Bfs(i,++Nc);
    }
    for(int i=1;i<=nc;i++)
    {
        map<int ,int > dat;
        for(int u : nodes[i])
        {
            dat[Tocomp[u]]++;
        }
        for(auto x : dat)
        {
            ans[{i,x.first}]=x.second;
        }
    }
}
