struct DisjointSets
{
    vector<int> representatives, sizes;

    DisjointSets(const int N) : representatives(N), sizes(N, 1)
    {
        iota(begin(representatives), end(representatives), 0);
    }

    int find(const int x)
    {
        if (representatives[x] != x)
            representatives[x] = find(representatives[x]);
        return representatives[x];
    }

    void merge(int x, int y)
    {
        x = find(x);
        y = find(y);
        if (x != y)
        {
            representatives[x] = y;
            sizes[y] += sizes[x];
        }
    }

    int size(const int x) { return sizes[find(x)]; }
};

int main()
{
    ios::sync_with_stdio(false);

    int N, K, L; cin >> N >> K >> L;

    auto road_components = DisjointSets(N);
    for (auto i = 0; i < K; i++)
    {
        int p, q; cin >> p >> q;
        p--; q--;
        road_components.merge(p, q);
    }

    auto intersection_components = DisjointSets(N);
    for (auto i = 0; i < L; i++)
    {
        int r, s; cin >> r >> s;
        r--; s--;

        if (road_components.find(r) == road_components.find(s))
            intersection_components.merge(r, s);
    }

    for (auto i = 0; i < N; i++)
        cout << intersection_components.size(i) << " ";
    cout << endl;
}

