void make_intersection(set<ll> *intersections[],
                       set<ll> *road_set_list[],
                       set<ll> *rail_set_list[],
                       ll n)
{
    set<ll> *checked[n+1];
    memset(checked, 0, sizeof(checked));

    rep (i0, n) {
        ll i = i0 + 1LL;

        if (checked[i]) {
            intersections[i] = checked[i];
