	}

	std::map<PAIR, int> map;

	REP(i, n) {
		++map[PAIR(uf1.find(i), uf2.find(i))];
	}

	REP(i, n) {
		OUT(map[PAIR(uf1.find(i), uf2.find(i))])SPBR(i, n);
	}

	return 0;
}

