typedef vector< int > Edges;

void dfs (int node, int label, VI & dp, vector<Edges> & edges){
    if (dp[node] != 0)
        return;
    dp[node] = label;
    for (auto & to: edges[node]){
        dfs(to, label, dp, edges);
    }
}

void traverse_all(VI & dp, vector<Edges> & edges){
    int n = dp.size();

    int label = 1;

    REP(i, n){
        if(dp[i] == 0) {
            dfs(i, label, dp, edges);
            label ++;
        }
    }
}

void output(VI &dpa, VI &dpb) {
    int n = dpa.size();
    map<PII, int> m;

    REP(i, n){
        m[PII(dpa[i], dpb[i])] ++;
    }

    REP(i, n){
        cout << m[PII(dpa[i], dpb[i])]  << " ";
    }
    cout << endl;
}


