class DisjointSets {
    private:
        vector<int> f, h, sz;
    public:
        DisjointSets(int n = 0) {
            f.assign(n + 1, 0);
            h.assign(n + 1, 1);
            sz.assign(n + 1, 1);
            for (int i = 1; i <= n; ++ i) {
                f[i] = i;
            }
        }
        int size(int x) {
            return sz[father(x)];
        }
        int father(int x) {
            return x == f[x] ? x : (f[x] = father(f[x]));
        }
        void unite(int x, int y) {
            x = father(x);
            y = father(y);
            if (x == y) {
                return;
            }
            if (h[x] == h[y]) {
                h[x] += 1;
                sz[x] += sz[y];
                f[y] = x;
            } else if (h[x] > h[y]) {
                sz[x] += sz[y];
                f[y] = x;
            } else {
                sz[y] += sz[x];
                f[x] = y;
            }
        }
};

int main() {
    int n, m, k;
    cin >> n >> m >> k;
    DisjointSets s1(n), s2(n);
    for (int i = 1; i <= m; ++ i) {
        int x, y;
        cin >> x >> y;
        s1.unite(x, y);
    }
    for (int i = 1; i <= k; ++ i) {
        int x, y;
        cin >> x >> y;
        if (s1.father(x) == s1.father(y)) {
            s2.unite(x, y);
        }
    }
    for (int i = 1; i <= n; ++ i) {
        cout << s2.size(i) << (i == n ? "\n" : " ");
    }
    return 0;
}

