void init(){
  cin >> N >> K >> L;
  P = Q = vi( K );
  for( int i = 0; i < K; ++i )
    cin >> P[ i ] >> Q[ i ], --P[ i ], --Q[ i ];
  R = S = vi( L );
  for( int i = 0; i < L; ++i )
    cin >> R[ i ] >> S[ i ], --R[ i ], --S[ i ];
}

vvi G1, G2;
vi cc1_id, cc2_id;

void dfs( const vvi &g, int u, vi &cc_id ){
  for( int v : g[ u ] )
    if( cc_id[ v ] == -1 )
      cc_id[ v ] = cc_id[ u ],
      dfs( g, v, cc_id );
}

void preprocess(){
  G1 = vvi( N );
  for( int i = 0; i < K; ++i )
    G1[ P[ i ] ].emplace_back( Q[ i ] ),
    G1[ Q[ i ] ].emplace_back( P[ i ] );
  G2 = vvi( N );
  for( int i = 0; i < L; ++i )
    G2[ R[ i ] ].emplace_back( S[ i ] ),
    G2[ S[ i ] ].emplace_back( R[ i ] );
  cc1_id = vi( N, -1 );
  int cc_cnt = -1;
  for( int i = 0; i < N; ++i )
    if( cc1_id[ i ] == -1 )
      cc1_id[ i ] = ++cc_cnt,
      dfs( G1, i, cc1_id );
  cc2_id = vi( N, -1 );
  cc_cnt = -1;
  for( int i = 0; i < N; ++i )
    if( cc2_id[ i ] == -1 )
      cc2_id[ i ] = ++cc_cnt,
      dfs( G2, i, cc2_id );
}

void solve(){
  map< pii, int > cnt;
  map< pii, vi > node;
  for( int i = 0; i < N; ++i )
    ++cnt[ make_pair( cc1_id[ i ], cc2_id[ i ] ) ],
    node[ make_pair( cc1_id[ i ], cc2_id[ i ] ) ].emplace_back( i );
  vi ans( N );
  for( auto it = cnt.begin(); it != cnt.end(); ++it )
    for( auto v : node[ it->first ] )
      ans[ v ] = it->second;
  for( int i = 0; i < N; ++i )
    cout << ans[ i ] << " \n"[ i + 1 == N ];
}

signed main(){
  ios::sync_with_stdio( 0 );
  init();
  preprocess();
  solve();
  return 0;
}

