		S.merge(a, b);
	}
	REP(i, L){
		int a, b;
		cin >> a >> b;
		--a;
		--b;
		if(!S.is_brother(a, b))continue;
		T.merge(a, b);
	}
	bool flag = false;
	REP(i, N){
		if(flag)cout << " ";
		flag = true;
		cout << T.get_union_size(i);
	}
}

