    unite (u, a, b);
  }
  union_find *v = new_union_find (n + 1);
  while (l--) {
    i32 a, b;
    scanf ("%" SCNi32 "%" SCNi32, &a, &b);
    unite (v, a, b);
  }
  node *p = ALLOC (n, node);
  for (i32 i = 1; i <= n; ++i) {
    p[i - 1] = (node) {root (u, i), root (v, i), i - 1};
  }
  SORT (p, n, cmp_node);
  i32 *ans = ALLOC (n, i32);
  for (i32 i = 0; i < n;) {
    i32 j = i + 1;
    while (j < n && cmp_node (p + i, p + j) == 0) ++j;
    i32 d = j - i;
    for (; i < j; ++i) {
      ans[p[i].k] = d;
    }
  }
  for (i32 i = 0; i < n; ++i) {
    printf ("%" PRIi32, ans[i]);
    putchar (i == n - 1 ? '\n' : ' ');
  }
}

