		scanf("%d %d", &p, &q);
		graph[(p-1)*n+(q-1)] = 1;
		graph[(q-1)*n+(p-1)] = 1;
		//printf("conncted %d and %d with path.\n", p ,q);
	}
	//printf("checking connect with path\n");
	check_connect(graph, ar, n, 1);

	for(i=0; i<l; i++){
		scanf("%d %d", &p, &q);
		graph[(p-1)*n+(q-1)] += 2;
		graph[(q-1)*n+(p-1)] += 2;
		//printf("connected %d and %d with train.\n", p, q);
	}

	hashtable = (hnode *)malloc(sizeof(hnode)*Q);
	for(i=0; i<Q; i++){
		(hashtable+i)->next = NULL;
		(hashtable+i)->a = -1;
		(hashtable+i)->b = -1;
	}

	//printf("checking connect with train\n");
	check_connect(graph, br, n, 2);

	//printf("start counting\n");
	for(i=0; i<n; i++){
		counting(ar[i], br[i], hashtable);
	}
	//printf("start print result\n");
	for(i=0; i<n; i++){
		ans = hash_search(ar[i], br[i], hashtable);
		printf("%d ", ans);
	}
	printf("\n");

	return 0;
}

int hash_search(int a, int b, hnode *ht){
	int h;
	hnode *p;

	h = hash(a, b);
	p = ht+h;
	while(p != NULL){
		if(p->a == a && p->b == b) return p->n;
		p = p->next;
	}

	return -1;
}

int counting(int a, int b, hnode *ht){
	int h;
	hnode *p, *new;

	h = hash(a, b);
	p = ht + h;
	while(p->next != NULL){
		if(p->a == a && p->b == b){
			p->n++;
			return 0;
		}
		p = p->next;
	}
	if(p->a == a && p->b == b){
			p->n++;
	}else{
		new = (hnode *)malloc(sizeof(hnode));
		new->a = a;
		new->b = b;
		new->n = 1;
		new->next = NULL;
		p->next = new;
	}
	return 0;
}

int hash(int a, int b){
	int h;

	h = (a*a+b)%Q;
	//printf("%d %d %d\n", a, b, h);

	return h;
}




