int hash_search(int a, int b, hnode *ht){
	int h;
	hnode *p;

	h = hash(a, b);
	p = ht+h;
	while(p != NULL){
		if(p->a == a && p->b == b) return p->n;
		p = p->next;
	}

	return -1;
}

int counting(int a, int b, hnode *ht){
	int h;
	hnode *p, *new;

	h = hash(a, b);
	p = ht + h;
	while(p->next != NULL){
		if(p->a == a && p->b == b){
			p->n++;
			return 0;
		}
		p = p->next;
	}
	if(p->a == a && p->b == b){
			p->n++;
	}else{
		new = (hnode *)malloc(sizeof(hnode));
		new->a = a;
		new->b = b;
		new->n = 1;
		new->next = NULL;
		p->next = new;
	}
	return 0;
}

int hash(int a, int b){
	int h;

	h = (a*a+b)%Q;
	//printf("%d %d %d\n", a, b, h);

	return h;
}




