	int n;

	if(empty(q) == EMPTY) return 0;
	np = q->next;
	q->next = q->next->next;
	n = np->n;
	free(np);

	return n;
}

void enqueue(node *q, int n){
	node *np;

	np = (node*)malloc(sizeof(node));
	np->n = n;
	np->next = NULL;
	while(q->next != NULL) q = q->next;
	q->next = np;
}

