int flags[MAX_NODE] = {0}, ans[MAX_NODE] = {0};

void add(Vector *v, int to){
	if(++(v->len) >= v->alloced){
		v->alloced = (v->alloced ? v->alloced*2 : 2);
		v->to = (int*)realloc(v->to, sizeof(int)*v->alloced);
	}
	v->to[v->len-1] = to;
}
void setParent(int p, int n){
	Vector *v = &road[n];
	int i, len = v->len, next;
	for(i=0;i<len;i++){
		next = v->to[i];
		if(parent[next]!=next || p==next){ continue; }
		parent[next] = p;
		setParent(p, next);
	}
}
void setSize(int n){
	Vector *v = &train[n];
	int i, len = v->len, next;
	flags[n] = 1;
	sizes[parent[n]]++;
	for(i=0;i<len;i++){
		next = v->to[i];
		if(flags[next]){ continue; }
		setSize(next);
	}
}
void getSize(int n){
	Vector *v = &train[n];
	int i, len = v->len, next;
	ans[n] = sizes[parent[n]];
	for(i=0;i<len;i++){
		next = v->to[i];
		if(ans[next]){ continue; }
		getSize(next);
	}
}
void resetSize(int n){
	Vector *v = &train[n];
	int i, len = v->len, next;
	flags[n] = 0;
	sizes[parent[n]] = 0;
	for(i=0;i<len;i++){
		next = v->to[i];
		if(!flags[next]){ continue; }
		resetSize(next);
	}
}

