		int c;
		int n;
};

int compare_intnm(const void *a,const void *b){
		struct nm A=*(struct nm*)a,B=*(struct nm*)b;
		if(A.ca>B.ca)return 1;
		else{
				if(A.ca<B.ca)return -1;
				return A.dn-B.dn;
		}
}
int compare_intnma(const void *a,const void *b){
		struct nm A=*(struct nm*)a,B=*(struct nm*)b;
		return A.n-B.n;
}

struct nm hel[200001];
int par[200000];
int rank[200000];

void init(int n){
		for(int i=0;i<n;i++){
				par[i]=i;
				rank[i]=1;
		}
}

int find(int x){
		if(par[x]==x)return x;
		return par[x]=find(par[x]);
}

void unite(int x,int y){
		x=find(x);
		y=find(y);
		if(x==y)return;
		if(rank[x]<rank[y]){
				par[x]=y;
				rank[y]+=rank[x];
		}else{
				par[y]=x;
				rank[x]+=rank[y];
		}
}

int same(int x,int y){
		if(find(x)==find(y))return 1;
		return 0;
}

