}

ll   root(ll x, ll tree[])
{
    if (tree[x] < 0) {
        return x;
    }

    tree[x] = root(tree[x], tree);

    return tree[x];
}

void merge(ll a, ll b, ll tree[])
{
    a = root(a, tree);
    b = root(b, tree);

    if (a != b) {
        tree[a] += tree[b];
        tree[b] = a;
    }

    return;
}

