	Vector *v = &train[n];
	int i, len = v->len, next;
	flags[n] = 1;
	sizes[parent[n]]++;
	for(i=0;i<len;i++){
		next = v->to[i];
		if(flags[next]){ continue; }
		setSize(next);
	}
}
void getSize(int n){
	Vector *v = &train[n];
	int i, len = v->len, next;
	ans[n] = sizes[parent[n]];
	for(i=0;i<len;i++){
		next = v->to[i];
		if(ans[next]){ continue; }
		getSize(next);
	}
}
void resetSize(int n){
	Vector *v = &train[n];
	int i, len = v->len, next;
	flags[n] = 0;
	sizes[parent[n]] = 0;
	for(i=0;i<len;i++){
		next = v->to[i];
		if(!flags[next]){ continue; }
		resetSize(next);
	}
}

