#define MAX 400010
/* UNION-FIND library */
int id[MAX], size[MAX];
void init(int n) { int i; for (i = 0; i < n; i++)
	id[i] = i, size[i] = 1;
}
int root(int i) { while (i != id[i]) id[i] = id[id[i]], i = id[i]; return i; }
void unite(int p, int q) {
    int i = root(p), j = root(q); if (i == j) return;
    if (size[i] < size[j]) id[i] = j, size[j] += size[i]; else id[j] = i, size[i] += size[j];
}

int N;
typedef struct { int id; ll x; } T;
T g[200005]; int w;
int ans[200005];

void Usort(T *a, int n) {
	int i, k;
#define B 8
#define BMSK 255 // (1<<8)-1
	ll t1[1 << B], t2[1 << B];

	T *tmp = malloc(n * sizeof(T));	
	for (k = 0; k < 8; ++k) {
		memset(t1, 0, sizeof(t1)), memset(t2, 0, sizeof(t2));
		for (i = 0; i < n; ++i)	t1[(a[i].x >> k*B) & BMSK]++;
		for (i = 0; i < BMSK; ++i) t1[i+1] += t1[i];
		i = n; while (i--) tmp[--t1[(a[i].x >> k*B) & BMSK]] = a[i];
		k++;
		for (i = 0; i < n; ++i) t2[(tmp[i].x >> k*B) & BMSK]++;
		for (i = 0; i < BMSK; ++i) t2[i+1] += t2[i];
		i = n; while (i--) a[--t2[(tmp[i].x >> k*B) & BMSK]] = tmp[i];
	}
	free(tmp);
//for (i = 0; i < n; ++i) printf("[%d] %lld,%d\n", i, a[i].x, a[i].id);
}

int main()
{
	int i, j, k, K, L, a, b;

	N = in(), K = in(), L = in();
	init((N << 1) + 2);
	while (K--) {
		a = in() << 1, b = in() << 1;
		unite(a, b);
	}
	while (L--) {
		a = (in() << 1) + 1, b = (in() << 1) + 1;
		unite(a, b);
	}

	for (i = 1; i <= N; ++i) {
		g[w].id = i, g[w++].x = ((ll)root(i<<1) << 19) | root((i<<1)+1);
	}
	Usort(g, w);

	j = 0; while (j < w) {
		k = j++; while (j < w && g[k].x == g[j].x) j++;
		for (i = k; i < j; ++i) ans[g[i].id] = j-k;
	}
//	for (i = 1; i <= N; ++i) printf("[%d] %d\n", i, ans[i]);
	for (i = 1; i <= N; ++i) out(ans[i]);
	return 0;
}

