typedef struct {
	int len;
	int *list;
} conn;

void add(conn *c, int to) {
	c->len += 1;
	c->list = realloc(c->list, c->len * sizeof(int));
	*(c->list + c->len - 1) = to;
}

int has_val(int *vals, int len, int val) {
	for(int i = 0; i < len; i++) {
		if(*(vals + i) == val) {
			return 1;
		}
	}

	return 0;
}

void merge(conn *c1, conn c2) {
	for(int i = 0; i < c2.len; i++) {
		if(!has_val(c1->list, c1->len, *(c2.list + i))) {
			add(c1, *(c2.list + i));
		}
	}
}

void calc(conn *road, int target, char *flg, char mark) {
	conn check = {0};

	merge(&check, road[target]);

	for(int j = 0; j < check.len; j++) {
		if((flg[*(check.list + j)] & mark) == 0) {
			flg[*(check.list + j)] |= mark;
			merge(&check, road[*(check.list + j)]);
		}
	}

	free(check.list);
}

