		roadParent[i] = subwayParent[i] = i;
	}
	return n;
}

ull uf_find (ull x, ull parents[]) {
	if (parents[x] == x) return x;
	return parents[x] = uf_find(parents[x], parents);
}

ull uf_union (ull a, ull b, ull parents[], ull ranks[]) {
	ull ap = uf_find(a, parents);
	ull bp = uf_find(b, parents);
	if (ap == bp) return ap;

	if (ranks[ap] > ranks[bp]) {
		parents[bp] = ap;
	} else {
		parents[ap] = bp;
		if (ranks[ap] == ranks[bp]) {
			ranks[bp]++;
		}
	}
	return ap;
}

