	class UnionFindTree {
		int[] parent;
		int[] size;

		public UnionFindTree(int n) {
			parent = new int[n];
			size = new int[n];
			init();
		}

		public void init() {
			for (int i = 0; i < parent.length; i++) {
				parent[i] = i;
				size[i] = 1;
			}
		}

		public int find(int x) {
			if (parent[x] == x) return x;
			return parent[x] = find(parent[x]);
		}

		public boolean same(int x, int y) {
			return find(x) == find(y);
		}

		public void unite(int x, int y) {
			int xx = find(x), yy = find(y);
			if (xx == yy) return;
			parent[xx] = yy;
			size[yy] += size[xx];
		}

		public int getSize(int x) {
			return size[find(x)];
		}

		public String toString() {
			String res = "";
			res += Arrays.toString(parent) + "\n";
			res += Arrays.toString(size);
			return res;
		}
	}

	public void solve() {
		int N = in.nextInt(), K = in.nextInt(), L = in.nextInt();
		UnionFindTree road = new UnionFindTree(N);
		UnionFindTree rail = new UnionFindTree(N);
		for (int i = 0; i < K; i++) {
			int p = in.nextInt() - 1, q = in.nextInt() - 1;
			road.unite(p, q);
		}
		for (int i = 0; i < L; i++) {
			int r = in.nextInt() - 1, s = in.nextInt() - 1;
			rail.unite(r, s);
		}
		for (int i = 0; i < N; i++) {
			road.find(i);
			rail.find(i);
		}
		HashMap<String, Integer> map = new HashMap<>();
		for (int i = 0; i < N; i++) {
			int idx1 = road.parent[i];
			int idx2 = rail.parent[i];
			String key = toKey(idx1, idx2);
			if (map.containsKey(key))
				map.put(key, map.get(key) + 1);
			else
				map.put(key, 1);
		}
		for (int i = 0; i < N; i++) {
			int idx1 = road.parent[i];
			int idx2 = rail.parent[i];
			out.print(map.get(toKey(idx1, idx2)) + " ");
		}
		out.println();
		out.close();
	}

