			r[i] = sc.nextInt() - 1;
			s[i] = sc.nextInt() - 1;

			rail.unite(r[i], s[i]);
		}

		int[] ret = new int[n];
		List<Integer> ans = new ArrayList<>();
		for (int i = 0; i < n; i++) {
			if (ret[i] == 0) {
				Set<Integer> roadtmp = road.getList(i);
				Set<Integer> railtmp = rail.getList(i);

				ans.clear();
				if (roadtmp.size() < railtmp.size()) {
					for (int e : roadtmp) {
						if (railtmp.contains(e)) {
							ans.add(e);
						}
					}
				} else {
					for (int e : railtmp) {
						if (roadtmp.contains(e)) {
							ans.add(e);
						}
					}
				}

				for (int e : ans) {
					ret[e] = ans.size();
				}
			}
		}

		for (int i = 0; i < n; i++) {
			if (i > 0) {
				pr.print(" ");
			}
			pr.print(ret[i]);
		}
		pr.println();
	}

	@SuppressWarnings("unused")
	private static class UnionFindList {
		int n;
		// cnt : 異なる集合の数
		int cnt;

		// i2g : i番目の要素が属するグループ
		List<Integer> i2g;
		// g2i : そのグループに属する要素のリスト
		List<Set<Integer>> g2i;

		// 「データ構造をマージする一般的なテク」に基づくUnionFind
		// 指定した要素に属する集合を得られる。
		// Quick Find Weightedと呼ばれ、uniteがならしO(log n)、sameはO(1)
		UnionFindList(int n) {
			this.n = n;
			cnt = n;
			i2g = new ArrayList<>(n);
			g2i = new ArrayList<>(n);
			for (int i = 0; i < n; i++) {
				i2g.add(i);
				Set<Integer> tmp = new HashSet<>();
				tmp.add(i);
				g2i.add(tmp);
			}
		}

		// xのrootを求める
		int find(int x) {
			return i2g.get(x);
		}

		// xとyが同じ集合に属するのか
		boolean same(int x, int y) {
			return find(x) == find(y);
		}

		// xとyの属する集合を併合する
		void unite(int x, int y) {
			x = find(x);
			y = find(y);
			if (x == y) {
				return;
			}

			cnt--;
			// 要素数が大きい集合にmergeする(Quick Find Weighted?)
			if (g2i.get(x).size() > g2i.get(y).size()) {
				g2i.get(x).addAll(g2i.get(y));
				for (int e : g2i.get(y)) {
					i2g.set(e, x);
				}
				g2i.set(y, null);
			} else {
				g2i.get(y).addAll(g2i.get(x));
				for (int e : g2i.get(x)) {
					i2g.set(e, y);
				}
				g2i.set(x, null);
			}

			return;
		}

		// 要素xを含む集合のリスト
		public Set<Integer> getList(int x) {
			return g2i.get(find(x));
		}

		// 要素xを含む集合の要素数
		int count(int x) {
			return g2i.get(find(x)).size();
		}

		// 異なる集合の数
		int count() {
			return cnt;
		}
	}

