public class Main {


    public static void main(String[] args) {    	                 
            Scanner  sc = new Scanner(System.in);        

            int N = sc.nextInt();

            int K = sc.nextInt();
            int L = sc.nextInt();

            UnionFind road    = new UnionFind(N);
            UnionFind railway = new UnionFind(N);

            for(int i = 0;i < K;i++){
                int p = sc.nextInt() - 1;
                int q = sc.nextInt() - 1;
                road.union(p,q);
            }            

            for(int i = 0;i < L;i++){
                int r = sc.nextInt() - 1;
                int s = sc.nextInt() - 1;
                railway.union(r,s);                
            }

            Map<Long,Integer> count = new HashMap<>();

            for(int i = 0;i < N;i++){
                  long key = (long) road.find(i)*N + railway.find(i);
                  if(count.containsKey(key))
                      count.put(key,count.get(key) + 1);  
                  else
                      count.put(key,1);
            }

            StringBuilder sb = new StringBuilder();
            for(int i = 0;i < N;i++){
                 long key = (long) road.find(i)*N + railway.find(i);
                 sb.append(count.get(key)).append(" ");                                                  
            }            

            System.out.println(sb);
    }

    static class UnionFind{
        int parent[];
        int rank[];

        UnionFind(int n){
            parent = new int[n];
            rank   = new int[n];            
            for(int i = 0;i < n;i++){
                parent[i] = i;
                  rank[i] = 0;
            }            
        }

        public int find(int x){
           if(x == find(x))
              return parent[x] = x;
           else
              return parent[x] = find(parent[x]);
        }                

        boolean same(int x,int y){
            return find(x) == find(y);
        }                                        

        public void union(int x,int y){
            x = find(x);
            y = find(y);

            if(x != y){
                if(rank[x] > rank[y]){
                     parent[y] = x;                    
                }else{                                        
                     parent[x] = y;
                    if(rank[x] == rank[y]){
                        rank[y]++;                        
                    }                    
                }                                                              
            }

            return;
        }        

        public int count(){
            int count = 0;
            for(int i = 0;i < parent.length;i++){                
                if(i == parent[i]){
                    count++;
                }
            }            

            return count;
        }                                        
    }        
}

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;
import java.util.StringJoiner;

public class Main {
    static class Node {
        int index;
        Node parent;
        List<Node> children = new ArrayList<>();

        Node(int index) {
            this.index = index;
        }

        public void union(Node other) {
            Node parent1 = this.findParent();
            Node parent2 = other.findParent();
            if (parent1.equals(parent2)) {
                return;
            }
            if (parent1.index > parent2.index) {
                parent2.parent = parent1;
                parent2.children.forEach(node -> {
                    node.parent = parent1;
                });
                parent1.children.addAll(parent2.children);
            } else {
                parent1.parent = parent2;
                parent1.children.forEach(node -> {
                    node.parent = parent2;
                });
                parent2.children.addAll(parent1.children);
            }

        }

        Node findParent() {
            if (this.parent == null) {
                return this;
            }
            return parent.findParent();
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) { return true; }
            if (o == null || getClass() != o.getClass()) { return false; }

            Node node = (Node) o;

            return index == node.index;
        }

        @Override
        public int hashCode() {
            return index;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();

        int k = scanner.nextInt();
        int l = scanner.nextInt();

        List<Node> nodes = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            nodes.add(new Node(i));
        }

        for (int i = 0; i < k; i++) {
            int pi = scanner.nextInt();
            int qi = scanner.nextInt();
            Node n1 = nodes.get(pi - 1);
            Node n2 = nodes.get(qi - 1);
            n1.union(n2);
        }
        int[] roads = new int[n];
        for (int i = 0; i < n; i++) {
            roads[i] = nodes.get(i).findParent().index;
        }

        nodes = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            nodes.add(new Node(i));
        }
        for (int i = 0; i < l; i++) {
            int ri = scanner.nextInt();
            int si = scanner.nextInt();
            Node n1 = nodes.get(ri - 1);
            Node n2 = nodes.get(si - 1);
            n1.union(n2);
        }
        int[] rails = new int[n];
        for (int i = 0; i < n; i++) {
            rails[i] = nodes.get(i).findParent().index;
        }

        Map<String, Integer> all = new HashMap<>();
        for (int i = 0; i < n; i++) {
            all.compute(roads[i] + "," + rails[i], (s, integer) -> {
                if (integer == null) {
                    return 1;
                } else {
                    return integer + 1;
                }
            });
        }

        StringJoiner joiner = new StringJoiner(" ");
        for (int i = 0; i < n; i++) {
            joiner.add(all.get(roads[i] + "," + rails[i]) + "");
        }
        System.out.println(joiner);
    }
}

import java.util.*;

public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int K = sc.nextInt();
		int L = sc.nextInt();
		DJSet ds1 = new DJSet(N);
		DJSet ds2 = new DJSet(N);
		for (int i = 0; i < K; ++i) {
			int p = sc.nextInt() - 1;
			int q = sc.nextInt() - 1;
			ds1.setUnion(p, q);
		}
		for (int i = 0; i < L; ++i) {
			int r = sc.nextInt() - 1;
			int s = sc.nextInt() - 1;
			ds2.setUnion(r, s);
		}
		HashMap<List<Integer>, Integer> count = new HashMap<>();
		for (int i = 0; i < N; ++i) {
			int v1 = ds1.root(i);
			int v2 = ds2.root(i);
			List<Integer> pair = Arrays.asList(v1, v2);
			if (count.containsKey(pair)) {
				count.put(pair, count.get(pair) + 1);
			} else {
				count.put(pair, 1);
			}
		}
		for (int i = 0; i < N; ++i) {
			int v1 = ds1.root(i);
			int v2 = ds2.root(i);
			System.out.print(count.get(Arrays.asList(v1, v2)));
			if (i + 1 < N)
				System.out.print(" ");
			else
				System.out.println();
		}

	}

	static class DJSet {
		int n;
		int[] upper;

		public DJSet(int n) {
			this.n = n;
			upper = new int[n];
			Arrays.fill(upper, -1);
		}

		boolean equiv(int x, int y) {
			return root(x) == root(y);
		}

		int root(int x) {
			return (upper[x] < 0 ? x : root(upper[x]));
		}

		boolean setUnion(int x, int y) {
			x = root(x);
			y = root(y);
			if (x != y) {
				if (upper[x] > upper[y]) {
					int d = x;
					x = y;
					y = d;
				}

				upper[x] += upper[y];
				upper[y] = x;

			}
			return x != y;
		}
	}
}

