public class Main {
  private static class Task {
    void solve(FastScanner in, PrintWriter out) throws Exception {
      int N = in.nextInt();
      int K = in.nextInt();
      int L = in.nextInt();
      UnionFind train = new UnionFind(N);
      UnionFind road = new UnionFind(N);

      int[][] edgeT = new int[K][2];
      for (int i = 0; i < K; i++) {
        edgeT[i][0] = in.nextInt() - 1;
        edgeT[i][1] = in.nextInt() - 1;
        train.unite(edgeT[i][0], edgeT[i][1]);
      }

      int[][] edgeR = new int[L][2];
      for (int i = 0; i < L; i++) {
        edgeR[i][0] = in.nextInt() - 1;
        edgeR[i][1] = in.nextInt() - 1;
        road.unite(edgeR[i][0], edgeR[i][1]);
      }

      UnionFind uf = new UnionFind(N);
      for (int[] e : edgeR) {
        int r = e[0];
        int s = e[1];
        if (road.isSame(r, s) && train.isSame(r, s)) uf.unite(r, s);
      }
      for (int[] e : edgeT) {
        int r = e[0];
        int s = e[1];
        if (road.isSame(r, s) && train.isSame(r, s)) uf.unite(r, s);
      }

      for (int i = 0; i < N; i++) {
        if (i > 0) out.print(" ");
        int x = uf.partialSizeOf(i);
        if (x <= 0) throw new Exception();
        out.print(x);
      }
      out.println();

    }

    class UnionFind {
      // par[i]：データiが属する木の親の番号。i == par[i]のとき、データiは木の根ノードである
      private int[] par;
      // sizes[i]：根ノードiの木に含まれるデータの数。iが根ノードでない場合は無意味な値となる
      private int[] sizes;

      // 木の数
      private int size;

      UnionFind(int n) {
        par = new int[n];
        sizes = new int[n];
        size = n;
        Arrays.fill(sizes, 1);
        // 最初は全てのデータiがグループiに存在するものとして初期化
        for (int i = 0; i < n; i++) par[i] = i;
      }

      /**
       * データxが属する木の根を得る
       *
       * @param x
       * @return
       */
      int find(int x) {
        if (x == par[x]) return x;
        return par[x] = find(par[x]);  // 根を張り替えながら再帰的に根ノードを探す
      }

      /**
       * 2つのデータx, yが属する木をマージする。
       * マージが必要なら true を返す
       *
       * @param x
       * @param y
       * @return
       */
      boolean unite(int x, int y) {
        // データの根ノードを得る
        x = find(x);
        y = find(y);

        // 既に同じ木に属しているならマージしない
        if (x == y) return false;

        // xの木がyの木より大きくなるようにする
        if (sizes[x] < sizes[y]) {
          int tx = x;
          x = y;
          y = tx;
        }

        // xがyの親になるように連結する
        par[y] = x;
        sizes[x] += sizes[y];
        sizes[y] = 0;  // sizes[y]は無意味な値となるので0を入れておいてもよい

        size--;
        return true;
      }

      /**
       * 2つのデータx, yが属する木が同じならtrueを返す
       *
       * @param x
       * @param y
       * @return
       */
      boolean isSame(int x, int y) {
        return find(x) == find(y);
      }

      /**
       * データxが含まれる木の大きさを返す
       *
       * @param x
       * @return
       */
      int partialSizeOf(int x) {
        return sizes[find(x)];
      }

      /**
       * 木の数を返す
       *
       * @return
       */
      int size() {
        return size;
      }
    }
  }

