		int[] rank;

		UnionFindTree(int N){
			root = new int[N];
			rank = new int[N];
			for(int i=0;i<N;i++){
				root[i] = i;
			}
		}

		public int find(int x){
			if(root[x]==x){
				return x;
			}else{
				return find(root[x]);
			}
		}

		public void unite(int x,int y){
			x = find(x);
			y = find(y);
			if(x==y){
				return;
