public class Main {
  private static class Task {
    void solve(FastScanner in, PrintWriter out) throws Exception {
      int N = in.nextInt();
      int K = in.nextInt();
      int L = in.nextInt();
      UnionFind train = new UnionFind(N);
      UnionFind road = new UnionFind(N);

      int[][] edgeT = new int[K][2];
      for (int i = 0; i < K; i++) {
        edgeT[i][0] = in.nextInt() - 1;
        edgeT[i][1] = in.nextInt() - 1;
        train.unite(edgeT[i][0], edgeT[i][1]);
      }

      int[][] edgeR = new int[L][2];
      for (int i = 0; i < L; i++) {
        edgeR[i][0] = in.nextInt() - 1;
        edgeR[i][1] = in.nextInt() - 1;
        road.unite(edgeR[i][0], edgeR[i][1]);
      }

      UnionFind uf = new UnionFind(N);
      for (int[] e : edgeR) {
        int r = e[0];
        int s = e[1];
        if (road.isSame(r, s) && train.isSame(r, s)) uf.unite(r, s);
      }
      for (int[] e : edgeT) {
        int r = e[0];
        int s = e[1];
        if (road.isSame(r, s) && train.isSame(r, s)) uf.unite(r, s);
      }

      for (int i = 0; i < N; i++) {
        if (i > 0) out.print(" ");
        out.print(uf.partialSizeOf(i));
      }
      out.println();

    }

    class UnionFind {
      // par[i]：データiが属する木の親の番号。i == par[i]のとき、データiは木の根ノードである
      private int[] par;
      // sizes[i]：根ノードiの木に含まれるデータの数。iが根ノードでない場合は無意味な値となる
      private int[] sizes;

      // 木の数
      private int size;

      UnionFind(int n) {
        par = new int[n];
        sizes = new int[n];
        size = n;
        Arrays.fill(sizes, 1);
        // 最初は全てのデータiがグループiに存在するものとして初期化
        for (int i = 0; i < n; i++) par[i] = i;
      }

      /**
       * データxが属する木の根を得る
       *
       * @param x
       * @return
       */
      int find(int x) {
        if (x == par[x]) return x;
        return par[x] = find(par[x]);  // 根を張り替えながら再帰的に根ノードを探す
      }

      /**
       * 2つのデータx, yが属する木をマージする。
       * マージが必要なら true を返す
       *
       * @param x
       * @param y
       * @return
       */
      boolean unite(int x, int y) {
        // データの根ノードを得る
        x = find(x);
        y = find(y);

        // 既に同じ木に属しているならマージしない
        if (x == y) return false;

        // xの木がyの木より大きくなるようにする
        if (sizes[x] < sizes[y]) {
          int tx = x;
          x = y;
          y = tx;
        }

        // xがyの親になるように連結する
        par[y] = x;
        sizes[x] += sizes[y];
        sizes[y] = 0;  // sizes[y]は無意味な値となるので0を入れておいてもよい

        size--;
        return true;
      }

      /**
       * 2つのデータx, yが属する木が同じならtrueを返す
       *
       * @param x
       * @param y
       * @return
       */
      boolean isSame(int x, int y) {
        return find(x) == find(y);
      }

      /**
       * データxが含まれる木の大きさを返す
       *
       * @param x
       * @return
       */
      int partialSizeOf(int x) {
        return sizes[find(x)];
      }

      /**
       * 木の数を返す
       *
       * @return
       */
      int size() {
        return size;
      }
    }
  }

  /**
   * ここから下はテンプレートです。
   */
  public static void main(String[] args) throws Exception {
    OutputStream outputStream = System.out;
    FastScanner in = new FastScanner();
    PrintWriter out = new PrintWriter(outputStream);
    Task solver = new Task();
    solver.solve(in, out);
    out.close();
  }
  private static class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int bufferLength = 0;

    private boolean hasNextByte() {
      if (ptr < bufferLength) {
        return true;
      } else {
        ptr = 0;
        try {
          bufferLength = in.read(buffer);
        } catch (IOException e) {
          e.printStackTrace();
        }
        if (bufferLength <= 0) {
          return false;
        }
      }
      return true;
    }

    private int readByte() {
      if (hasNextByte()) return buffer[ptr++];
      else return -1;
    }

    private static boolean isPrintableChar(int c) {
      return 33 <= c && c <= 126;
    }

    private void skipUnprintable() {
      while (hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;
    }

    boolean hasNext() {
      skipUnprintable();
      return hasNextByte();
    }

    public String next() {
      if (!hasNext()) throw new NoSuchElementException();
      StringBuilder sb = new StringBuilder();
      int b = readByte();
      while (isPrintableChar(b)) {
        sb.appendCodePoint(b);
        b = readByte();
      }
      return sb.toString();
    }

    long nextLong() {
      if (!hasNext()) throw new NoSuchElementException();
      long n = 0;
      boolean minus = false;
      int b = readByte();
      if (b == '-') {
        minus = true;
        b = readByte();
      }
      if (b < '0' || '9' < b) {
        throw new NumberFormatException();
      }
      while (true) {
        if ('0' <= b && b <= '9') {
          n *= 10;
          n += b - '0';
        } else if (b == -1 || !isPrintableChar(b)) {
          return minus ? -n : n;
        } else {
          throw new NumberFormatException();
        }
        b = readByte();
      }
    }

    double nextDouble() {
      return Double.parseDouble(next());
    }

    double[] nextDoubleArray(int n) {
      double[] array = new double[n];
      for (int i = 0; i < n; i++) {
        array[i] = nextDouble();
      }
      return array;
    }

    double[][] nextDoubleMap(int n, int m) {
      double[][] map = new double[n][];
      for (int i = 0; i < n; i++) {
        map[i] = nextDoubleArray(m);
      }
      return map;
    }

    public int nextInt() {
      return (int) nextLong();
    }

    public int[] nextIntArray(int n) {
      int[] array = new int[n];
      for (int i = 0; i < n; i++) array[i] = nextInt();
      return array;
    }

    public long[] nextLongArray(int n) {
      long[] array = new long[n];
      for (int i = 0; i < n; i++) array[i] = nextLong();
      return array;
    }

    public String[] nextStringArray(int n) {
      String[] array = new String[n];
      for (int i = 0; i < n; i++) array[i] = next();
      return array;
    }

    public char[][] nextCharMap(int n) {
      char[][] array = new char[n][];
      for (int i = 0; i < n; i++) array[i] = next().toCharArray();
      return array;
    }

    public int[][] nextIntMap(int n, int m) {
      int[][] map = new int[n][];
      for (int i = 0; i < n; i++) {
        map[i] = nextIntArray(m);
      }
      return map;
    }
  }
}

import java.util.*;

public class Main {


    public static void main(String[] args) {    	                 
            Scanner  sc = new Scanner(System.in);        

            int N = sc.nextInt();

            int K = sc.nextInt();
            int L = sc.nextInt();

            UnionFind road    = new UnionFind(N);
            UnionFind railway = new UnionFind(N);

            for(int i = 0;i < K;i++){
                road.union(sc.nextInt()-1 ,sc.nextInt() - 1);
            }            

            for(int i = 0;i < L;i++){
                railway.union(sc.nextInt() - 1,sc.nextInt() - 1);                
            }

            Map<Long,Integer> count = new HashMap<>();

            for(int i = 0;i < N;i++){
                  long key = (long) road.find(i)*N + railway.find(i);
                  if(count.containsKey(key))
                      count.put(key,count.get(key) + 1);  
                  else
                      count.put(key,1);
            }

            StringBuilder sb = new StringBuilder();
            for(int i = 0;i < N;i++){
                 long key = (long) road.find(i)*N + railway.find(i);
                 sb.append(count.get(key)).append(" ");                                                  
            }            

            System.out.println(sb);
    }

    static class UnionFind{
        int parent[];
        int rank[];

        UnionFind(int n){
            parent = new int[n];
            rank   = new int[n];            
            for(int i = 0;i < n;i++){
                parent[i] = i;
                  rank[i] = 0;
            }            
        }

        public int find(int x){
           if(parent[x] == x)
              return x;
           else
              return parent[x] = find(parent[x]);
        }                

        boolean same(int x,int y){
            return find(x) == find(y);
        }                                        

        public void union(int x,int y){
            x = find(x);
            y = find(y);

            if(x != y){
                if(rank[x] > rank[y]){
                     parent[y] = x;                    
                }else{                                        
                     parent[x] = y;
                    if(rank[x] == rank[y]){
                        rank[y]++;                        
                    }                    
                }                                                              
            }

            return;
        }        

        public int count(){
            int count = 0;
            for(int i = 0;i < parent.length;i++){                
                if(i == parent[i]){
                    count++;
                }
            }                       
            return count;
        }          

    }     

}

