			int t=sc.nextInt()-1;
			UnionFind.unite(f,t);
		}
		for(int i=0; i<N; i++) {
			den[i]=UnionFind.find(i);
		}
		UnionFind.init(N);
		int[] dou=new int[N];
		for(int i=0;i<K; i++) {
			int f=sc.nextInt()-1;
			int t=sc.nextInt()-1;
			UnionFind.unite(f,t);
		}
		for(int i=0; i<N; i++) {
			dou[i]=UnionFind.find(i);
		}
		HashMap<Long,Integer> num = new HashMap<Long,Integer>();
		long[] id=new long[N];
		for(int i=0; i<N; i++) {
			id[i]=((long)(den[i])*((long) N)+((long)(dou[i])));
			if(num.containsKey(id[i])) {
				num.put(id[i], num.get(id[i])+1);
			}
			else {
				num.put(id[i], 1);
			}
		}
		for(int i=0; i<N; i++) {
			if(i<N-1) {
				p(num.get(id[i])+" ");
			}
			else {
				p(num.get(id[i]));
			}
		}
		pl();
	}
	static class UnionFind {
		static int N;			//頂点数
		static int par[];		//親ノード
		static int rank[];		//ランク　UnionFind木の高さがrankみたい
		public static void init(int n) {		//初期化
			N = n;
			par = new int[N];
			rank = new int[N];
			for(int i = 0; i < N; i++) {		//0処理
				par[i] = i;
				rank[i] = 0;
			}
		}
		public static int find(int x) {		//木の根を求める
			if(par[x] == x) {
				return x;
			} else {
				return par[x] = find(par[x]);
			}
		}
		public static void unite(int x, int y) {		//xとyの属する集合を併合	xにyをという意味合いが強そう		集合に含めるときに unite(114,514);のようにするみたい
			x = find(x);
			y = find(y);
			if(x == y) return;
			if(rank[x] < rank[y]) {
				par[x] = y;
			} else {
				par[y] = x;
				if(rank[x] == rank[y]) rank[x]++;
			}
		}
		public static boolean same(int x, int y) {		//x,yが同じ集合に属するか否か
			return find(x) == find(y);
		}
	}
	static class SC {
