    int[] irt = new int[N];
    int[] num = new int[N];
    Arrays.fill(rt, -1);
    for (int i = 0; i < N; i ++) {
      int root = a.find(i);
      if (rt[root] < 0) {
        rt[root] = count;
        irt[count] = root;
        count ++;
      }
      num[root] ++;
     }
    int[][] set = new int[count][];
    for (int i = 0; i < count; i ++) {
      set[i] = new int[num[irt[i]]];
    }

    int[] rptr = new int[count];
    for (int i = 0; i < N; i ++) {
      int root = a.find(i);
      set[rt[root]][rptr[rt[root]] ++] = i;
    }

    int[] ret = new int[N];
    for (int i = 0; i < N; i ++) {
      int rootA = a.find(i);
