class Pair<K,V> {
    public final K first;
    public final V second;
    Pair(K first,V second){
        this.first = first;
        this.second = second;
    }

    @Override
    public boolean equals(Object obj){

        if(!(obj instanceof Pair)){
            return false;
        }else{
            Pair<?,?> p = (Pair<?,?>)obj;
            return this.first == p.first && this.second == p.second;
        }
    }
    @Override
    public int hashCode(){
        return first.hashCode()^second.hashCode();
    }
}

