public class Main {
  private static class Task {
    void solve(FastScanner in, PrintWriter out) throws Exception {
      int N = in.nextInt();
      int K = in.nextInt();
      int L = in.nextInt();
      UnionFind train = new UnionFind(N);
      UnionFind road = new UnionFind(N);

      int[][] edgeT = new int[K][2];
      for (int i = 0; i < K; i++) {
        edgeT[i][0] = in.nextInt() - 1;
        edgeT[i][1] = in.nextInt() - 1;
        train.unite(edgeT[i][0], edgeT[i][1]);
      }

      int[][] edgeR = new int[L][2];
      for (int i = 0; i < L; i++) {
        edgeR[i][0] = in.nextInt() - 1;
        edgeR[i][1] = in.nextInt() - 1;
        road.unite(edgeR[i][0], edgeR[i][1]);
      }

      UnionFind uf = new UnionFind(N);
      TreeMap<Integer, ArrayList<Integer>> roadTree = new TreeMap<>();
      for (int i = 0; i < N; i++) {
        int p = road.find(i);
        ArrayList<Integer> list = roadTree.get(p);
        if (list == null) roadTree.put(p, list = new ArrayList<>());
        list.add(i);
      }
      for (Map.Entry<Integer, ArrayList<Integer>> entry : roadTree.entrySet()) {
        Collections.sort(entry.getValue());
      }

      TreeMap<Integer, ArrayList<Integer>> trainTree = new TreeMap<>();
      for (int i = 0; i < N; i++) {
        int p = train.find(i);
        ArrayList<Integer> list = trainTree.get(p);
        if (list == null) trainTree.put(p, list = new ArrayList<>());
        list.add(i);
      }
      for (Map.Entry<Integer, ArrayList<Integer>> entry : trainTree.entrySet()) {
        Collections.sort(entry.getValue());
      }

      int[] ans = new int[N];
      ArrayDeque<Integer> deque = new ArrayDeque<>();
      for (int i = 0; i < N; i++) {
        if (ans[i] != 0) continue;
        ArrayList<Integer> R = roadTree.get(road.find(i));
        ArrayList<Integer> T = trainTree.get(train.find(i));
        int r = 0;
        int t = 0;
        for (; r < R.size() && t < T.size(); ) {
          if (R.get(r) == T.get(t)) {
            deque.add(R.get(r));
            r++;
            t++;
          } else if (R.get(r) > T.get(t)) {
            t++;
          } else {
            r++;
          }
        }
        int s = deque.size();
        while (!deque.isEmpty()) {
          ans[deque.poll()] = s;
        }
      }

      for (int i = 0; i < N; i++) {
        if (i > 0) out.print(" ");
        out.print(ans[i]);
      }
      out.println();

    }

    class UnionFind {
      // par[i]：データiが属する木の親の番号。i == par[i]のとき、データiは木の根ノードである
      private int[] par;
      // sizes[i]：根ノードiの木に含まれるデータの数。iが根ノードでない場合は無意味な値となる
      private int[] sizes;

      // 木の数
      private int size;

      UnionFind(int n) {
        par = new int[n];
        sizes = new int[n];
        size = n;
        Arrays.fill(sizes, 1);
        // 最初は全てのデータiがグループiに存在するものとして初期化
        for (int i = 0; i < n; i++) par[i] = i;
      }

      /**
       * データxが属する木の根を得る
       *
       * @param x
       * @return
       */
      int find(int x) {
        if (x == par[x]) return x;
        return par[x] = find(par[x]);  // 根を張り替えながら再帰的に根ノードを探す
      }

      /**
       * 2つのデータx, yが属する木をマージする。
       * マージが必要なら true を返す
       *
       * @param x
       * @param y
       * @return
       */
      boolean unite(int x, int y) {
        // データの根ノードを得る
        x = find(x);
        y = find(y);

        // 既に同じ木に属しているならマージしない
        if (x == y) return false;

        // xの木がyの木より大きくなるようにする
        if (sizes[x] < sizes[y]) {
          int tx = x;
          x = y;
          y = tx;
        }

        // xがyの親になるように連結する
        par[y] = x;
        sizes[x] += sizes[y];
        sizes[y] = 0;  // sizes[y]は無意味な値となるので0を入れておいてもよい

        size--;
        return true;
      }

      /**
       * 2つのデータx, yが属する木が同じならtrueを返す
       *
       * @param x
       * @param y
       * @return
       */
      boolean isSame(int x, int y) {
        return find(x) == find(y);
      }

      /**
       * データxが含まれる木の大きさを返す
       *
       * @param x
       * @return
       */
      int partialSizeOf(int x) {
        return sizes[find(x)];
      }

      /**
       * 木の数を返す
       *
       * @return
       */
      int size() {
        return size;
      }
    }
  }

