        r = in.nextInt();
        s = in.nextInt();
        graph[1][r].add(s);
        graph[1][s].add(r);
      }
      comp = new int[2][n + 1];
      int[] ans = new int[n + 1];
      Arrays.fill(ans, 1);
      for (int j = 1; j <= n; ++j) {
        if (comp[0][j] == 0) {
          Set<Integer>[] set = (TreeSet<Integer>[]) new TreeSet[2];
          set[0] = new TreeSet<Integer>();
          ptr = j;
          dfs(graph[0], j, comp[0], set[0]);
          for (int k : set[0]) {
            if (comp[1][k] == 0) {
              ptr = k;
              set[1] = new TreeSet<Integer>();
              dfs(graph[1], k, comp[1], set[1]);
              if (set[1] != null) {
        //~ System.err.println(k);
        //~ System.err.println(set[0]);
        //~ System.err.println(set[1]);
        //~ System.err.println();
                int cnt = 0;
                List<Integer> list = new ArrayList<Integer>();
                if (set[0].size() < set[1].size()) {
                  for (int kk : set[0])
                    if (set[1].contains(kk)) {
                      ++cnt;
                      list.add(kk);
                    }
                } else {
                  for (int kk : set[1])
                    if (set[0].contains(kk)) {
                      ++cnt;
                      list.add(kk);
                    }
                }
                for (int kk : list)
                  ans[kk] += cnt - 1;
              }
            }
          }
        }
      }
