import java.io.*;
import java.util.*;

public class Main {

	private static Scanner sc;
	private static Printer pr;

	private static void solve() {
		int n = sc.nextInt();
		int k = sc.nextInt();
		int l = sc.nextInt();

		UnionFindList road = new UnionFindList(n);
		UnionFindList rail = new UnionFindList(n);

		int[] p = new int[k];
		int[] q = new int[k];
		for (int i = 0; i < k; i++) {
			p[i] = sc.nextInt() - 1;
			q[i] = sc.nextInt() - 1;

			road.unite(p[i], q[i]);
		}

		int[] r = new int[l];
		int[] s = new int[l];
		for (int i = 0; i < l; i++) {
			r[i] = sc.nextInt() - 1;
			s[i] = sc.nextInt() - 1;

			rail.unite(r[i], s[i]);
		}

		int[] ret = new int[n];
		for (int i = 0; i < n; i++) {
			if (ret[i] == 0) {
				Set<Integer> roadtmp = new HashSet<>(road.getList(i));
				Set<Integer> railtmp = rail.getList(i);

				roadtmp.retainAll(railtmp);
				for (int e : roadtmp) {
					ret[e] = roadtmp.size();
				}
			}
		}

		for (int i = 0; i < n; i++) {
			if (i > 0) {
				pr.print(" ");
			}
			pr.print(ret[i]);
		}
		pr.println();
	}

	@SuppressWarnings("unused")
	private static class UnionFindList {
		int n;
		// cnt : 異なる集合の数
		int cnt;

		// i2g : i番目の要素が属するグループ
		List<Integer> i2g;
		// g2i : そのグループに属する要素のリスト
		List<Set<Integer>> g2i;

		// 「データ構造をマージする一般的なテク」に基づくUnionFind
		// 指定した要素に属する集合を得られる。
		// Quick Find Weightedと呼ばれ、uniteがならしO(log n)、sameはO(1)
		UnionFindList(int n) {
			this.n = n;
			cnt = n;
			i2g = new ArrayList<>(n);
			g2i = new ArrayList<>(n);
			for (int i = 0; i < n; i++) {
				i2g.add(i);
				Set<Integer> tmp = new HashSet<>();
				tmp.add(i);
				g2i.add(tmp);
			}
		}

		// xのrootを求める
		int find(int x) {
			return i2g.get(x);
		}

		// xとyが同じ集合に属するのか
		boolean same(int x, int y) {
			return find(x) == find(y);
		}

		// xとyの属する集合を併合する
		void unite(int x, int y) {
			x = find(x);
			y = find(y);
			if (x == y) {
				return;
			}

			cnt--;
			// 要素数が大きい集合にmergeする(Quick Find Weighted?)
			if (g2i.get(x).size() > g2i.get(y).size()) {
				g2i.get(x).addAll(g2i.get(y));
				for (int e : g2i.get(y)) {
					i2g.set(e, x);
				}
				g2i.set(y, null);
			} else {
				g2i.get(y).addAll(g2i.get(x));
				for (int e : g2i.get(x)) {
					i2g.set(e, y);
				}
				g2i.set(x, null);
			}

			return;
		}

		// 要素xを含む集合のリスト
		public Set<Integer> getList(int x) {
			return g2i.get(find(x));
		}

		// 要素xを含む集合の要素数
		int count(int x) {
			return g2i.get(find(x)).size();
		}

		// 異なる集合の数
		int count() {
			return cnt;
		}
	}

	// ---------------------------------------------------
	public static void main(String[] args) {
		sc = new Scanner(System.in);
		pr = new Printer(System.out);

		solve();

		pr.close();
		sc.close();
	}

	@SuppressWarnings("unused")
	private static class Scanner {
		BufferedReader br;

		Scanner (InputStream in) {
			br = new BufferedReader(new InputStreamReader(in));
		}

		private boolean isPrintable(int ch) {
			return ch >= '!' && ch <= '~';
		}

		private boolean isCRLF(int ch) {
			return ch == '\n' || ch == '\r' || ch == -1;
		}

		private int nextPrintable() {
			try {
				int ch;
				while (!isPrintable(ch = br.read())) {
					if (ch == -1) {
						throw new NoSuchElementException();
					}
				}

				return ch;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		String next() {
			try {
				int ch = nextPrintable();
				StringBuilder sb = new StringBuilder();
				do {
					sb.appendCodePoint(ch);
				} while (isPrintable(ch = br.read()));

				return sb.toString();
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		int nextInt() {
			try {
				// parseInt from Integer.parseInt()
				boolean negative = false;
				int res = 0;
				int limit = -Integer.MAX_VALUE;
				int radix = 10;

				int fc = nextPrintable();
				if (fc < '0') {
					if (fc == '-') {
						negative = true;
						limit = Integer.MIN_VALUE;
					} else if (fc != '+') {
						throw new NumberFormatException();
					}
					fc = br.read();
				}
				int multmin = limit / radix;

				int ch = fc;
				do {
					int digit = ch - '0';
					if (digit < 0 || digit >= radix) {
						throw new NumberFormatException();
					}
					if (res < multmin) {
						throw new NumberFormatException();
					}
					res *= radix;
					if (res < limit + digit) {
						throw new NumberFormatException();
					}
					res -= digit;

				} while (isPrintable(ch = br.read()));

				return negative ? res : -res;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		long nextLong() {
			try {
				// parseLong from Long.parseLong()
				boolean negative = false;
				long res = 0;
				long limit = -Long.MAX_VALUE;
				int radix = 10;

				int fc = nextPrintable();
				if (fc < '0') {
					if (fc == '-') {
						negative = true;
						limit = Long.MIN_VALUE;
					} else if (fc != '+') {
						throw new NumberFormatException();
					}
					fc = br.read();
				}
				long multmin = limit / radix;

				int ch = fc;
				do {
					int digit = ch - '0';
					if (digit < 0 || digit >= radix) {
						throw new NumberFormatException();
					}
					if (res < multmin) {
						throw new NumberFormatException();
					}
					res *= radix;
					if (res < limit + digit) {
						throw new NumberFormatException();
					}
					res -= digit;

				} while (isPrintable(ch = br.read()));

				return negative ? res : -res;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		float nextFloat() {
			return Float.parseFloat(next());
		}

		double nextDouble() {
			return Double.parseDouble(next());
		}

		String nextLine() {
			try {
				int ch;
				while (isCRLF(ch = br.read())) {
					if (ch == -1) {
						throw new NoSuchElementException();
					}
				}
				StringBuilder sb = new StringBuilder();
				do {
					sb.appendCodePoint(ch);
				} while (!isCRLF(ch = br.read()));

				return sb.toString();
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		void close() {
			try {
				br.close();
			} catch (IOException e) {
//				throw new NoSuchElementException();
			}
		}
	}

	private static class Printer extends PrintWriter {
		Printer(PrintStream out) {
			super(out);
		}
	}
}

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Scanner;
import java.util.Set;

public class Main {
    public static class UnionFindTree {
        // nodeNum 个数，下标 [1, nodeNum]
        int nodeNum;
        int [] parent;
        int [] height;

        public UnionFindTree(int nodeNum) {
            this.nodeNum = nodeNum;
            parent = new int[nodeNum + 1];
            height = new int[nodeNum + 1];
            for (int i = 1; i <= nodeNum; ++i) {
                parent[i] = i;
                height[i] = 0;
            }
        }

        int find(int x) {
            if (parent[x] == x) {
                return x;
            } else {
                return parent[x] = find(parent[x]);
            }
        }

        void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX == rootY) {
                return;
            }
            if (height[rootX] < height[rootY]) {
                parent[rootX] = rootY;
            } else {
                if (height[rootX] == height[rootY]) {
                    height[rootX]++;
                }
                parent[rootY] = rootX;
            }
        }

    }
    public static class Edge {
        public int a;
        public int b;

        public Edge(int a, int b) {
            this.a = a;
            this.b = b;
        }

    }
    public static void main(String [] args) {
        Scanner scanner = new Scanner(System.in);

        int n = scanner.nextInt();
        long k = scanner.nextLong();
        long l = scanner.nextLong();
        final Set<Edge> roads = new HashSet<>();
        final Set<Edge> railways = new HashSet<>();
        for (int i = 0; i < k; ++i) {
            int a = scanner.nextInt();
            int b = scanner.nextInt();
            Edge edge = new Edge(a, b);
            roads.add(edge);
        }

        for (int i = 0; i < l; ++i) {
            int a = scanner.nextInt();
            int b = scanner.nextInt();
            Edge edge = new Edge(a, b);
            railways.add(edge);
        }
        final UnionFindTree roadTree = new UnionFindTree(n);
        for (Edge road : roads) {
            int a = road.a;
            int b = road.b;
            roadTree.union(a, b);
        }

        final UnionFindTree railwayTree = new UnionFindTree(n);
        for (Edge railway : railways) {
            int a = railway.a;
            int b = railway.b;
            railwayTree.union(a, b);
        }
        UnionFindTree bothTree = new UnionFindTree(n);

        final Map<Integer, Integer> unionSizes = new HashMap<>();
        for (Edge railway : railways) {
            int a = railway.a;
            int b = railway.b;
            int rootAInRoad = roadTree.find(a);
            int rootBInRoad = roadTree.find(b);
            int rootAInRailway = railwayTree.find(a);
            int rootBInRailway = railwayTree.find(b);

            if (rootAInRoad == rootBInRoad && rootAInRailway == rootBInRailway) {
                bothTree.union(a, b);
            }
        }

        for (int i = 1; i <= n; ++i) {
            int root = bothTree.find(i);
            int unionSize = unionSizes.getOrDefault(root, 0);
            unionSizes.put(root, unionSize + 1);
        }

        for (int i = 1; i <= n; ++i) {
            int root = bothTree.find(i);
            System.out.print(unionSizes.getOrDefault(root, 0) + " ");
        }


    }
}

import java.util.*;
import java.util.stream.*;

public class Main {
    private class Train {
        int parent;
        int cnt;

        public Train(int parent) {
            this.parent = parent;
            cnt = 1;
        }
    }

    public void main(Scanner sc) {
        int n = sc.nextInt();
        int k = sc.nextInt();
        int l = sc.nextInt();

        int road[] = new int[n];
        init(n, road);
        for (int i = 0; i < k; i++) {
            link(sc.nextInt(), sc.nextInt(), road);
        }

        Train train[] = new Train[n];
        init(n, train);
        for (int i = 0; i < l; i++) {
            link(sc.nextInt(), sc.nextInt(), train, road);
        }

        System.out.println(Arrays.stream(train).map(t -> String.valueOf(train[t.parent - 1].cnt))
            .collect(Collectors.joining(" ")));
    }

    public void init(int n, int data[]) {
        for (int i = 0; i < n; i++) {
            data[i] = i + 1;
        }
    }

    public void link(int x, int y, int data[]) {
        data[root(x, data) - 1] = root(y, data);
    }

    public boolean isSame(int x, int y, int data[]) {
        return root(x, data) == root(y, data);
    }

    public int root(int p, int data[]) {
        return (data[p - 1] == p) ? p : (data[p - 1] = root(data[p - 1], data));
    }

    public void init(int n, Train data[]) {
        for (int i = 0; i < n; i++) {
            data[i] = new Train(i + 1);
        }
    }

    public void link(int x, int y, Train data[], int sub[]) {
        if (isSame(x, y, sub)) {
            int rootx = root(x, data);
            int rooty = root(y, data);
            data[rootx - 1].parent = rooty;
            data[rooty - 1].cnt += data[rootx - 1].cnt;
        }
    }

    public int root(int p, Train data[]) {
        return (data[p - 1].parent == p) ? p
            : (data[p - 1].parent = root(data[p - 1].parent, data));
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        new Main().main(sc);
        sc.close();
    }
}

import java.util.*;
