class UnionFind {
	int parent[];
	int size[];

	public UnionFind(int num) {
		parent = new int[num];
		size = new int[num];
		for(int i = 0; i < num; i ++) {
			initNode(i);
		}
	}

	public void initNode(int i) {
		parent[i] = i;
		size[i] = 1;
	}

	public void unite(int x, int y) {
		int xRoot = root(x);
		int yRoot = root(y);
		if(xRoot == yRoot) { return; }
		if(size[yRoot] > size[xRoot]) {
			parent[xRoot] = yRoot;
			size[yRoot] += size[xRoot];
		}else {
			parent[yRoot] = xRoot;
			size[xRoot] += size[yRoot];
		}
	}

	public int size(int i) {
		return size[root(i)];
	}

	public int root(int i) {
		if(i != parent[i]) {
			parent[i] = root(parent[i]);
		}
		return parent[i];
	}

	public boolean same(int x, int y) {
		return root(x) == root(y);
	}
}

	}
}

import java.util.*;

class Node {
  Node parent;
  int id;
  int rank;

  Node(int id) {
    this.parent = null;
    this.id = id;
    this.rank = 0;
  }

  public Node getRoot() {
    if (parent == null) {
      return this;
    }
    Node root = parent.getRoot();
    parent = root;
    return root;
  }

  public long getRootId() {
    return getRoot().id;
  }

  public static void merge(Node a, Node b) {
    Node aRoot = a.getRoot();
    Node bRoot = b.getRoot();

    if (aRoot.rank > bRoot.rank) {
      bRoot.parent = aRoot;
    } else if (aRoot.rank < bRoot.rank) {
      aRoot.parent = bRoot;
    } else if (aRoot != bRoot) {
      aRoot.parent = bRoot;
      bRoot.rank = bRoot.rank + 1;
    }
  }
}

