      } else {
        cityCounter.put(id, cityCounter.get(id) + 1);
      }
    }
    for (int i = 0; i < n; i++) {
      int id = getCityId(roadGroup[i], railGroup[i]);
      if (i > 0) {
        System.out.print(" ");
