        for (int i = 0; i < 2; ++i)
          if (comp[i][j] == 0) {
            ptr = j;
            dfs(graph[i], j, comp[i]);
          }
      }
      Map<Long, Integer> map = new TreeMap<Long, Integer>();
      for (int i = 1; i <= n; ++i) {
        long key = ((long) comp[0][i] << 32) | comp[1][i];
        if (!map.containsKey(key))
          map.put(key, 1);
        else
          map.put(key, map.get(key) + 1);
      }
      for (int i = 1; i <= n; ++i) {
