    void dfs(List<Integer>[] graph, int v, int[] comp) {
      comp[v] = ptr;
      for (int w : graph[v])
        if (comp[w] == 0)
          dfs(graph, w, comp);
    }

    int i(long x) {
      return (int) x;
    }

    <T> void heapSort(T[] a, int s, int e) {
      Queue<T> queue = new PriorityQueue<>();
      for (int i = s; i <= e; ++i)
        queue.add(a[i]);
      for (int i = s; i <= e; ++i)
        a[i] = queue.poll();
    }    

  }

