	static void solve(){
		int n = in.nextInt();
		int k = in.nextInt();
		int l = in.nextInt();

		DisjointSet clus = new DisjointSet(n);

		for (int i=0; i<k; i++) {
			int p = in.nextInt() - 1;
			int q = in.nextInt() - 1;
			clus.unite(p, q);
		}

		DisjointSet clus2 = new DisjointSet(n);

		HashMap<Integer,Integer> map = new HashMap<>();
		int p = 0;
		for (int i=0; i<n; i++) {
			if (map.containsKey(clus.find(i))) {
			} else {
				map.put(clus.find(i), p++);
			}
		}

		int m = p;

		int[] ss = new int[l];
		int[] tt = new int[l];
		for (int i=0; i<l; i++) {
			ss[i] = in.nextInt() - 1;
			tt[i] = in.nextInt() - 1;
			clus2.unite(ss[i], tt[i]);
		}

		HashMap<Integer,Integer> map2 = new HashMap<>();
		p = 0;
		for (int i=0; i<n; i++) {
			if (map2.containsKey(clus2.find(i))) {
			} else {
				map2.put(clus2.find(i), p++);
			}
		}
		int m2 = p;

		DisjointSet ans = new DisjointSet(n);
		HashMap<Long, ArrayList<Integer>> lists = new HashMap<>();

		for (int i=0; i<l; i++) {
			int s = ss[i];
			int t = tt[i];
			if (clus.same(s, t)) {
				ans.unite(s, t);
