		int rankA[] = new int[n + 1];
		int rankB[] = new int[n + 1];
		for(int i = 1;i <= n;i++){
			parentA[i] = i;
			parentB[i] = i;
		}
		for(int i = 1;i <= k;i++){
			st = new StringTokenizer(br.readLine());
			int a = Integer.parseInt(st.nextToken());
			int b = Integer.parseInt(st.nextToken());
			merge(a,b,parentA,rankA);
		}
		for(int i = 1;i <= l;i++){
			st = new StringTokenizer(br.readLine());
			int a = Integer.parseInt(st.nextToken());
			int b = Integer.parseInt(st.nextToken());
			merge(a,b,parentB,rankB);
		}
