			for(int i = 0; i < n; i++) {
				edges2[i] = new LinkedList<>();
			}
			rail = init(n);
			while(b-- > 0) {
				int x = readInt()-1;
				int y = readInt()-1;
				edges2[x].add(y);
				edges2[y].add(x);
				merge(rail, x, y);
			}
			int[] ret = new int[n];
			boolean[] seen = new boolean[n];
			for(int aa = 0; aa < n; aa++) {
				if(seen[aa]) continue;
				LinkedList<Integer> q = new LinkedList<>();
