public class Main {
    public static void main(String[] $) {
        Scanner sc=new Scanner(in);
        int n = sc.nextInt(), k = sc.nextInt(), l = sc.nextInt();
        road.Init(n + 1);
        rail.Init(n + 1);
        int[] ans = new int[n + 1];

        for (int i = 0; i < k; i++) {
            int a = sc.nextInt(), b = sc.nextInt();
            road.unite(a, b);
        }

        for (int i = 0; i < l; i++) {
            int a = sc.nextInt(), b = sc.nextInt();
            rail.unite(a, b);
        }

        int[] d1=new int[n+1];
        int[] d2=new int[n+1];
        HashMap<Point,ArrayDeque<Integer>> map=new HashMap<>();

        for (int i = 1; i < n + 1; i++) {
            d1[i]=road.find(i);
            d2[i]=rail.find(i);
            Point p=new Point(d1[i],d2[i]);
            if(map.get(p)==null){
                ArrayDeque<Integer> temp=new ArrayDeque<>();
                temp.add(i);
                map.put(p,temp);
            }else {
                ArrayDeque<Integer> temp=map.get(p);
                temp.add(i);
                map.put(p,temp);
            }
        }

        for (Point p:map.keySet()){
            ArrayDeque<Integer> temp=map.get(p);
            int size=temp.size();
            while (!temp.isEmpty()){
                ans[temp.poll()]=size;
            }
        }

        for (int i = 1; i < n + 1; i++) {
            out.print(ans[i]);
            if (i < n) out.print(" ");
        }
        out.println();
    }

    static class road {
        static int[] d;

        static void Init(int size) {
            d = new int[size];
            for (int i = 0; i < size; i++) {
                d[i] = -1;
            }
        }

        static boolean unite(int x, int y) {
            x = find(x);
            y = find(y);
            if (x == y) return false;
