public class Main {
  private static int[] solve(int n, int k, int l, int[] ps, int[] qs, int[] rs, int[] ss) {
    UnionFind roadUnionFind = new UnionFind(n + 1);
    for (int i = 0; i < k; i++) {
      roadUnionFind.merge(ps[i], qs[i]);
    }

    UnionFind railUnionFind = new UnionFind(n + 1);
    for (int i = 0; i < l; i++) {
      railUnionFind.merge(rs[i], ss[i]);
    }

    long[] rootPairs = new long[n + 1];
    Map<Long, Integer> counters = new HashMap<>();
    for (int i = 1; i <= n; i++) {
      long roadRoot = roadUnionFind.getRoot(i);
      long railRoot = railUnionFind.getRoot(i);
      rootPairs[i] = (roadRoot << 20) | railRoot;
      counters.put(rootPairs[i], counters.getOrDefault(rootPairs[i], 0) + 1);
    }

    int[] answers = new int[n];
    for (int i = 1; i <= n; i++) {
      answers[i - 1] = counters.get(rootPairs[i]);
    }
    return answers;
  }

  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
    int k = reader.nextInt();
    int l = reader.nextInt();
    int[] ps = new int[k];
    int[] qs = new int[k];
    for (int i= 0; i < k; i++) {
