    int[] ss = new int[l];
    for (int i = 0; i < l; i++) {
      rs[i] = reader.nextInt();
      ss[i] = reader.nextInt();
    }
    int[] answers = solve(n, k, l, ps, qs, rs, ss);
    out.print(answers[0]);
    for (int i = 1; i < n; i++) {
      out.print(" ");
      out.print(answers[i]);
    }
    out.println();
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    PrintWriter out = new PrintWriter(System.out);
    execute(reader, out);
    out.flush();
  }
