    static void Main(string[] args)
    {
        new Magatro().Solve();
    }
}

public class Magatro
{
    private int N, K, L;

    private int[] CPar; //道路
    private int[] TPar; //電車

    private int CRoot(int a)
    {
        if (CPar[a] == a) return a;
        else return CRoot(CPar[a]);
    }

    private void CUnion(int a, int b)
    {
        a = CRoot(a);
        b = CRoot(b);
        if (a == b) return;
        CPar[b] = a;
    }
    private int TRoot(int a)
    {
        if (TPar[a] == a) return a;
        else return TRoot(TPar[a]);
    }

    private void TUnion(int a, int b)
    {
        a = TRoot(a);
        b = TRoot(b);
        if (a == b) return;
        TPar[b] = a;
    }

    public void Solve()
    {
        string[] line = Console.ReadLine().Split(' ');
        N = int.Parse(line[0]);
        K = int.Parse(line[1]);
        L = int.Parse(line[2]);
        CPar = (new int[N]).Select((i, index) => index).ToArray();
        for (int i = 0; i < K; i++)
        {
            line = Console.ReadLine().Split(' ');
            int p = int.Parse(line[0]) - 1;
            int q = int.Parse(line[1]) - 1;
            CUnion(p, q);
        }
        TPar = (new int[N]).Select((i, index) => index).ToArray();
        for (int i = 0; i < L; i++)
        {
            line = Console.ReadLine().Split(' ');
            int r = int.Parse(line[0]) - 1;
            int s = int.Parse(line[1]) - 1;
            TUnion(r, s);
        }

        var map = new Dictionary<Pair, int>();
        var arr = new Pair[N];
        for (int i = 0; i < N; i++)
        {
            var p = new Pair(CRoot(i), TRoot(i));
            arr[i] = p;
            int t;
            if(map.TryGetValue(p,out t))
            {
                map[p] = t + 1;
            }
            else
            {
                map[p] = 1;
            }
        }
        Console.WriteLine(string.Join(" ", arr.Select(p => map[p]).ToArray()));
    }
}

