			setnum = new int[N];
			int[] numset = new int[N];
			for (int i = 0; i < N; i++)
			{
				int p = find(i);
				if (!par.Contains(p))
				{
					setnum[i] = par.Count;
					numset[p] = i;
					par.Add(p);
				}
				else
				{
					setnum[i] = setnum[numset[p]];
				}
			}
			set = new List<int>[par.Count];
			for (int i = 0; i < par.Count; i++)
			{
				set[i] = new List<int>();
			}
			for (int i = 0; i < N; i++)
			{
				set[setnum[i]].Add(i);
			}
		}

		public UnionFind(int N)
		{
			this.N = N;
			parent = new int[N];
			rank = new int[N];
			for (int i = 0; i < N; i++)
			{
				parent[i] = i;
			}
		}

		public int find(int x)
		{
			if (parent[x] == x)
			{
				return x;
			}
			else
			{
				return parent[x] = find(parent[x]);
			}
		}

		public void unite(int x, int y)
		{
			x = find(x);
			y = find(y);
			if (rank[x] < rank[y])
			{
				parent[x] = y;
			}
			else
			{
				parent[y] = x;
				if (rank[x] == rank[y]) rank[x]++;
			}
		}

		public bool same(int x, int y)
		{
			return find(x) == find(y);
		}
	}
