        string[] str = Console.ReadLine().Split(' ');
        int N = int.Parse(str[0]);
        int K = int.Parse(str[1]);
        int L = int.Parse(str[2]);
        int[] P1 = new int[K];
        int[] Q1 = new int[K];
        int[] P2 = new int[L];
        int[] Q2 = new int[L];
        UnionFind U1 = new UnionFind(N);
        for(int i=0;i<K;i++){
            str = Console.ReadLine().Split(' ');
            int p = int.Parse(str[0])-1;
            int q = int.Parse(str[1])-1;
            P1[i] = p;
            Q1[i] = q;
            U1.Union(p,q);
        }
        UnionFind U2 = new UnionFind(N);
        for(int i=0;i<L;i++){
            str = Console.ReadLine().Split(' ');
            int p = int.Parse(str[0])-1;
            int q = int.Parse(str[1])-1;
            P2[i] = p;
            Q2[i] = q;
            U2.Union(p,q);
        }
        UnionFind U3 = new UnionFind(N);
        for(int i=0;i<K;i++){
            if(U2.Same(P1[i],Q1[i])){
                U3.Union(P1[i],Q1[i]);
            }
        }
        for(int i=0;i<L;i++){
            if(U1.Same(P2[i],Q2[i])){
                U3.Union(P2[i],Q2[i]);
            }
