    class UnionFind
    {
        public int[] path;
        public int[] rail;
        public int[] count;
        public bool[] check;

        public UnionFind(int n)
        {
            path = new int[n];
            rail = new int[n];
            count = new int[n];
            check = new bool[n];
            for (int i = 0; i < n; i++)
            {
                path[i] = i;
                rail[i] = i;

            }


        }

        private int rootPath(int i)
        {
            while(i != path[i])
            {
                path[i] = path[path[i]];
                i = path[i];
            }
            return i;
        }

        private int rootRail(int i)
        {
            while(i != rail[i])
            {
                rail[i] = rail[rail[i]];
                i = rail[i];
            }
            return i;
        }

        public bool findPath(int p, int q)
        {
            return rootPath(p) == rootPath(q);
        }

        public bool findRail(int p, int q)
        {
            return rootRail(p) == rootRail(q);
        }






        public void Add(int p)
        {
            int a = rail[p];
            int b = p;

            if (findPath(a, b))
            {
                count[a]++;
                check[p] = true;
            }
            else count[p] = 1;

            //if (a == b) count[p]++;
            //else if (findPath(a, b))
            //{
            //    count[rail[p]]++;
            //    count[p]+=2;

            //}
            //else count[p] = 1;

        }

        public int Output(int i)
        {
            return check[i]? count[rail[i]] : count[i];
            //return count[i];
        }



        public void unitePath(int p , int q)
        {
            int i = rootPath(p);
            int j = rootPath(q);
            path[i] = j;
        }

        public void uniteRail(int p, int q)
        {
            int i = rootRail(p);
            int j = rootRail(q);
            rail[i] = j;
        }
    }
