    public class Program
    {
        public object Calc()
        {
            var N = consoleReader.Int;
            var K = consoleReader.Int;
            var L = consoleReader.Int;

            var ufRoad = new UnionFind(N);
            var ufRail = new UnionFind(N);
            foreach (var cr in consoleReader.Repeat(K))
                ufRoad.UnionSet(cr.Int - 1, cr.Int - 1);
            foreach (var cr in consoleReader.Repeat(L))
                ufRail.UnionSet(cr.Int - 1, cr.Int - 1);

            var roads = new List<int>[N];
            var rails = new List<int>[N];
            for (int i = 0; i < N; i++)
            {
                var roadRoot = ufRoad.Root(i);
                if (roads[roadRoot] == null)
                    roads[roadRoot] = new List<int>();
                roads[i] = roads[roadRoot];
                roads[roadRoot].Add(i);


                var railRoot = ufRail.Root(i);
                if (rails[railRoot] == null)
                    rails[railRoot] = new List<int>();
                rails[i] = rails[railRoot];
                rails[railRoot].Add(i);
            }

            var res = new int[N];

            for (int i = 0; i < N; i++)
            {
                if (res[i] > 0) continue;
                var h = roads[i].Intersect(rails[i]).ToArray();
                foreach (var j in h)
                {
                    res[j] = h.Count;
                }
            }

            return string.Join(" ", res);
        }
        class UnionFind
        {
            int[] data;
            public UnionFind(int size)
            {
                this.data = Enumerable.Repeat(-1, size).ToArray();
            }

            public int Root(int x)
            {
                if (data[x] < 0) return x;
                return data[x] = Root(data[x]);
            }
            public int Count(int x) => -data[Root(x)];
            public void UnionSet(int x, int y)
            {
                var xRoot = Root(x);
                var yRoot = Root(y);
                if (xRoot == yRoot) return;
                else if (data[yRoot] < data[xRoot])//y側の方が多い場合は逆にする
                {
                    var tmp = yRoot;
                    yRoot = xRoot;
                    xRoot = tmp;
                }
                data[xRoot] += data[yRoot];
                data[yRoot] = xRoot;
            }
            public bool IsSameSet(int x, int y) => Root(x) == Root(y);
        }

