					N.REP(j =>
					{
						cnt += ufK.IsSameGroup(i, j) && ufL.IsSameGroup(i, j) ? 1 : 0;
					});
					ans[i] = cnt;
				});
				ans.StringJoin(" ").WL();

				return;
			}
		}
	}





