        public UnionFind(int n)
        {
            path = new int[n];
            rail = new int[n];
            count = new int[n];
            for (int i = 0; i < n; i++)
            {
                path[i] = i;
                rail[i] = i;
                //count[i] = 1;
            }


        }

        private int rootPath(int i)
        {
            while(i != path[i])
            {
                path[i] = path[path[i]];
                i = path[i];
            }
            return i;
        }

        private int rootRail(int i)
        {
            while(i != rail[i])
            {
                rail[i] = rail[rail[i]];
                i = rail[i];
            }
            return i;
        }

