class Myon
{
    public Myon() { }
    public static int Main()
    {
        new Myon().calc();
        return 0;
    }


    Scanner cin;



    void calc()
    {
        cin = new Scanner();
        int N = cin.nextInt();
        int K = cin.nextInt();
        int L = cin.nextInt();
        long[] memo = new long[N];

        init(N);
        for (int i = 0; i < K; i++)
        {
            int a = cin.nextInt() - 1;
            int b = cin.nextInt() - 1;
            connect(a, b);
        }
        for (int i = 0; i < N; i++)
        {
            memo[i] += (long)root(i) * 300000;
        }


        init(N);
        for (int i = 0; i < L; i++)
        {
            int a = cin.nextInt() - 1;
            int b = cin.nextInt() - 1;
            connect(a, b);
        }
        Dictionary<long, int> dic = new Dictionary<long, int>();
        for (int i = 0; i < N; i++)
        {
            memo[i] += (long)root(i);
            if (!dic.ContainsKey(memo[i])) dic[memo[i]] = 0;
            dic[memo[i]]++;
        }
        int[] ans = new int[N];
        for (int i = 0; i < N; i++)
        {
            ans[i] = dic[memo[i]];
        }
        Console.WriteLine(string.Join(" ", ans));
    }

    int[] uni;
    void init(int N)
    {
        uni = new int[N];
        for (int i = 0; i < N; i++)
        {
            uni[i] = -1;
        }
    }

    int root(int a)
    {
        if (uni[a] < 0) return a;
        else return uni[a] = root(uni[a]);
    }

    bool connect(int a, int b)
    {
        a = root(a);
        b = root(b);
        if (a == b) return false;
        if (uni[a] > uni[b]) swap(ref a, ref b);
        uni[a] += uni[b];
        uni[b] = a;
        return true;
    }

    void swap<T>(ref T a, ref T b)
    {
        T c = a;
        a = b;
        b = c;
    }  
}


