namespace ARC065D{
    public class Program{
        public static void Main(string[] args){
            var sr = new StreamReader();
            var sw = new StreamWriter(Console.OpenStandardOutput()){AutoFlush = false};
            //---------------------------------
            var N = sr.Next<int>();
            var K = sr.Next<int>();
            var L = sr.Next<int>();

            var qf = new QuickFind[3];
            qf[0] = new QuickFind(N);
            qf[1] = new QuickFind(N);
            qf[2] = new QuickFind(N);

            for(var i = 0; i < K; i++){
                var p = sr.Next<int>() - 1;
                var q = sr.Next<int>() - 1;
                qf[0].Merge(p, q);
                qf[2].Merge(p, q);
            }

            for(var i = 0; i < L; i++){
                var r = sr.Next<int>() - 1;
                var s = sr.Next<int>() - 1;
                qf[1].Merge(r, s);
                qf[2].Merge(r, s);
            }

            for(var i = 0; i < N; i++){
                sw.Write(Math.Max(1, qf[0].SameGroupItems(i).Count + qf[1].SameGroupItems(i).Count - qf[2].SameGroupItems(i).Count) + " ");
            }
            sw.WriteLine();
            //---------------------------------
            sw.Flush();
        }
    }

    public class Ex{
        public static void Swap<T>(ref T left, ref T right){
            var tmp = left;
            left = right;
            right = tmp;
        }

        public static void Fill<T>(ref T[] src, T val){
            for(var i = 0; i < src.Length; i++){
                src[i] = val;
            }
        }
    }

    public class QuickFind{
        //データ構造をマージする一般的なテク
        private readonly int[] Group;
        private readonly List<int>[] Items;

        public QuickFind(int n){
            Group = new int[n];
            Items = new List<int>[n];
            for(var i = 0; i < n; i++){
                Group[i] = i;
                Items[i] = new List<int>{i};
            }
        }

        public void Merge(int x, int y){
            if(Items[Group[x]].Count < Items[Group[y]].Count) Ex.Swap(ref x, ref y);

            var gx = Group[x];
            var gy = Group[y];
            if(gx == gy) return;

            foreach(var iy in Items[gy]){
                Group[iy] = gx;
                Items[gx].Add(iy);
            }
        }

        public List<int> SameGroupItems(int x){
            return Items[Group[x]];
        }

        public bool IsSameGroup(int x, int y){
            return Group[x] == Group[y];
        }
    }

