	//using GeometryLong;
	class Problem : IDisposable
	{
		bool IsGCJ;
		int Repeat;
		Scanner sc;
		Printer pr;
		public Problem(bool isGCJ, Scanner scanner, Printer printer)
		{
			sc = scanner;
			pr = printer;
			IsGCJ = isGCJ;
			if (isGCJ) Repeat = sc.Get<int>();
			else Read();
		}
		public Problem(bool isGCJ) : this(isGCJ, new Scanner(), new Printer()) { }
		public Problem(bool isGCJ, Scanner scanner) : this(isGCJ, scanner, new Printer()) { }
		public Problem(bool isGCJ, Printer printer) : this(isGCJ, new Scanner(), printer) { }
		public void Solve()
		{
			if (IsGCJ) for (var i = 0; i < Repeat; i++) { Read(); pr.Write("Case #" + (i + 1) + ": "); SolveOne(); }
			else SolveOne();
		}
		public void Dispose()
		{
			sc.Dispose();
			pr.Dispose();
		}
		public int Size { get { return 1; } }
		public const long Mod = 1000000007;
		RandomSFMT rand = Program.rand;
		int N,K,L;
		Tuple<int,int>[] rs,ts;
		void Read()
		{
			sc.Read(out N, out K, out L);
			rs = sc.ReadManyLines<int,int>(K);
			ts = sc.ReadManyLines<int,int>(L);
		}
		void SolveOne()
		{
			var uf1 = new UnionFindTree(N);
			foreach (var r in rs) uf1.UniteCategory(r.Item1 - 1, r.Item2 - 1);
			var uf2 = new UnionFindTree(N);
			foreach (var r in ts) uf2.UniteCategory(r.Item1 - 1, r.Item2 - 1);
			var cnt = new Dictionary<long,int>();
			var ans = new int[N];
			var ls = new Dictionary<int, List<int>>();
			var rev = new int[N];
			for (var i = 0; i < N; i++)
			{
				var r1 = uf1.GetRootOf(i);
				var r2 = uf2.GetRootOf(i);
				var k = r1 * (long)N + r2;
				if (!cnt.ContainsKey(k)) cnt[k] = 0;
				cnt[k]++;
			}
			for (var i = 0; i < N; i++)
			{
				var r1 = uf1.GetRootOf(i);
				var r2 = uf2.GetRootOf(i);
				var k = r1 * (long)N + r2;
				pr.Write(cnt[k] + (i == N - 1 ? "" : " "));
			}
			pr.WriteLine();
		}
	}
