class RandomSFMT : Random
{
	int index, coin_bits, byte_pos, range, shift;
	uint coin_save, byte_save, bse;
	protected uint[] x = new uint[40];
	static uint[] ParityData = { 0x00000001U, 0x00000000U, 0x00000000U, 0x20000000U };
	public virtual void gen_rand_all()
	{
		int a = 0, b = 28, c = 32, d = 36; uint y; uint[] p = x;
		do
		{
			y = p[a + 3] ^ (p[a + 3] << 24) ^ (p[a + 2] >> 8) ^ ((p[b + 3] >> 5) & 0xb5ffff7fU);
			p[a + 3] = y ^ (p[c + 3] >> 8) ^ (p[d + 3] << 14);
			y = p[a + 2] ^ (p[a + 2] << 24) ^ (p[a + 1] >> 8) ^ ((p[b + 2] >> 5) & 0xaff3ef3fU);
			p[a + 2] = y ^ ((p[c + 2] >> 8) | (p[c + 3] << 24)) ^ (p[d + 2] << 14);
			y = p[a + 1] ^ (p[a + 1] << 24) ^ (p[a] >> 8) ^ ((p[b + 1] >> 5) & 0x7fefcfffU);
			p[a + 1] = y ^ ((p[c + 1] >> 8) | (p[c + 2] << 24)) ^ (p[d + 1] << 14);
			y = p[a] ^ (p[a] << 24) ^ ((p[b] >> 5) & 0xf7fefffdU);
			p[a] = y ^ ((p[c] >> 8) | (p[c + 1] << 24)) ^ (p[d] << 14);
			c = d; d = a; a += 4; b += 4;
			if (b == 40) b = 0;
		} while (a != 40);
	}
	void period_certification()
	{
		uint work, inner = 0; int i, j;
		index = 40; range = 0; coin_bits = 0; byte_pos = 0;
		for (i = 0; i < 4; i++) inner ^= x[i] & ParityData[i];
		for (i = 16; i > 0; i >>= 1) inner ^= inner >> i;
		inner &= 1;
		if (inner == 1) return;
		for (i = 0; i < 4; i++) for (j = 0, work = 1; j < 32; j++, work <<= 1) if ((work & ParityData[i]) != 0) { x[i] ^= work; return; }
	}
	public void InitMt(uint s)
	{
		unchecked
		{
			x[0] = s;
			for (uint p = 1; p < 40; p++) x[p] = s = 1812433253 * (s ^ (s >> 30)) + p;
			period_certification();
		}
	}
	public RandomSFMT(uint s) { InitMt(s); }
	public void InitMtEx(uint[] init_key)
	{
		uint r, i, j, c, key_len = (uint)init_key.Length;
		unchecked
		{
			for (i = 0; i < 40; i++) x[i] = 0x8b8b8b8b;
			if (key_len + 1 > 40) c = key_len + 1; else c = 40;
			r = x[0] ^ x[17] ^ x[39]; r = (r ^ (r >> 27)) * 1664525;
			x[17] += r; r += key_len; x[22] += r; x[0] = r; c--;
			for (i = 1, j = 0; j < c && j < key_len; j++)
			{
				r = x[i] ^ x[(i + 17) % 40] ^ x[(i + 39) % 40];
				r = (r ^ (r >> 27)) * 1664525; x[(i + 17) % 40] += r;
				r += init_key[j] + i; x[(i + 22) % 40] += r;
				x[i] = r; i = (i + 1) % 40;
			}
			for (; j < c; j++)
			{
				r = x[i] ^ x[(i + 17) % 40] ^ x[(i + 39) % 40];
				r = (r ^ (r >> 27)) * 1664525; x[(i + 17) % 40] += r; r += i;
				x[(i + 22) % 40] += r; x[i] = r; i = (i + 1) % 40;
			}
			for (j = 0; j < 40; j++)
			{
				r = x[i] + x[(i + 17) % 40] + x[(i + 39) % 40];
				r = (r ^ (r >> 27)) * 1566083941; x[(i + 17) % 40] ^= r;
				r -= i; x[(i + 22) % 40] ^= r; x[i] = r; i = (i + 1) % 40;
			}
			period_certification();
		}
	}
	public RandomSFMT(uint[] init_key) { InitMtEx(init_key); }
	public RandomSFMT() : this((uint)(DateTime.Now.Ticks & 0xffffffff)) { }
	public uint NextMt() { if (index == 40) { gen_rand_all(); index = 0; } return x[index++]; }
	public int NextInt(int n) => (int)(n * (1.0 / 4294967296.0) * NextMt());
	public double NextUnif() { uint z = NextMt() >> 11, y = NextMt(); return (y * 2097152.0 + z) * (1.0 / 9007199254740992.0); }
	public int NextBit() { if (--coin_bits == -1) { coin_bits = 31; return (int)(coin_save = NextMt()) & 1; } else return (int)(coin_save >>= 1) & 1; }
	public int NextByte() { if (--byte_pos == -1) { byte_pos = 3; return (int)(byte_save = NextMt()) & 255; } else return (int)(byte_save >>= 8) & 255; }
	public override int Next(int maxValue) => Next(0, maxValue);
	protected override double Sample() => NextUnif();
	public override double NextDouble() => NextUnif();
	public override int Next() => 1 + NextIntEx(int.MaxValue);
	public override void NextBytes(byte[] buffer) { for (var i = 0; i < buffer.Length; i++) buffer[i] = (byte)NextByte(); }
	public override int Next(int min, int max) => min + NextIntEx(max - min);
	public int NextIntEx(int range_)
	{
		uint y_, base_, remain_; int shift_;
		if (range_ <= 0) return 0;
		if (range_ != range)
		{
			bse = (uint)(range = range_);
			for (shift = 0; bse <= (1UL << 30); shift++) bse <<= 1;
		}
		while (true)
		{
			y_ = NextMt() >> 1;
			if (y_ < bse) return (int)(y_ >> shift);
			base_ = bse; shift_ = shift; y_ -= base_;
			remain_ = (1U << 31) - base_;
			for (; remain_ >= (uint)range_; remain_ -= base_)
			{
				for (; base_ > remain_; base_ >>= 1) shift_--;
				if (y_ < base_) return (int)(y_ >> shift_);
				else y_ -= base_;
			}
		}
	}
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

namespace AtCoder
{
    class Program
    {
        private const int MODULO = 1000000007;
        private static string Read() { return Console.ReadLine(); }
        private static int ReadInt() { return int.Parse(Read()); }
        private static long ReadLong() { return long.Parse(Read()); }
        private static double ReadDouble() { return double.Parse(Read()); }
        private static int[] ReadInts() { return Array.ConvertAll(Read().Split(), int.Parse); }
        private static long[] ReadLongs() { return Array.ConvertAll(Read().Split(), long.Parse); }
        private static double[] ReadDoubles() { return Array.ConvertAll(Read().Split(), double.Parse); }

        class Node<T>
        {
            private int m_height;
            private Node<T> m_parent;
            public T Item { get; private set; }
            public Node(T item)
            {
                m_height = 0;
                m_parent = this;
                Item = item;
            }
            public Node<T> Find()
            {
                if (m_parent == this) { return this; }

                Node<T> parent = m_parent.Find();
                m_parent = parent;
                return parent;
            }
            public static void Unite(Node<T> a, Node<T> b)
            {
                Node<T> p = a.Find();
                Node<T> q = b.Find();
                if (p.m_height < q.m_height)
                {
                    p.m_parent = q;
                    q.m_height = Math.Max(p.m_height + 1, q.m_height);
                }
                else
                {
                    q.m_parent = p;
                    p.m_height = Math.Max(q.m_height + 1, p.m_height);
                }
            }
        }

        static IEnumerable<int> Solve(int N, Node<int>[] nodes1, Node<int>[] nodes2)
        {
            var dict = new Dictionary<Tuple<int, int>, int>();
            for (int i = 0; i < N; ++i)
            {
                int a = nodes1[i].Find().Item;
                int b = nodes2[i].Find().Item;
                var key = new Tuple<int, int>(a, b);
                if (!dict.ContainsKey(key)) { dict[key] = 0; }
                ++dict[key];
            }
            int[] ans = new int[N];
            for (int i = 0; i < N; ++i)
            {
                int a = nodes1[i].Find().Item;
                int b = nodes2[i].Find().Item;
                var key = new Tuple<int, int>(a, b);
                ans[i] = dict[key];
            }
            return ans;
        }
        static void Main(string[] args)
        {
            int[] v1 = ReadInts();
            int N = v1[0];
            int K = v1[1];
            int L = v1[2];
            var nodes1 = new Node<int>[N];
            var nodes2 = new Node<int>[N];
            for (int i = 0; i < N; ++i)
            {
                nodes1[i] = new Node<int>(i);
                nodes2[i] = new Node<int>(i);
            }
            for (int i = 0; i < K; ++i)
            {
                int[] v2 = ReadInts();
                int p = v2[0] - 1;
                int q = v2[1] - 1;
                Node<int>.Unite(nodes1[p], nodes1[q]);
            }
            for (int i = 0; i < L; ++i)
            {
                int[] v2 = ReadInts();
                int r = v2[0] - 1;
                int s = v2[1] - 1;
                Node<int>.Unite(nodes2[r], nodes2[s]);
            }
            Console.WriteLine(string.Join(" ", Solve(N, nodes1, nodes2)));
        }
    }
}

using System;
using System.Linq;//リストの使用
using System.Collections.Generic;
class Program
{

static string[] input = Console.ReadLine().Split(' ');
static int n = int.Parse(input[0]);
static int k = int.Parse(input[1]);
static int l = int.Parse(input[2]);
static int[][] parents = new int[n][];//親、親、値、元の番号
static int[] answers = new int[n];

	static void Main()
	{
    for(int i = 0; i < n; i++)
    {
      parents[i] = new int[4];
      parents[i][0] = i;
      parents[i][1] = i;
      parents[i][3] = i;
    }

    for(int i = 0; i < k; i++)
    {
      int[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),int.Parse);
      if(whatParentA(nums[0]-1) != whatParentA(nums[1]-1))
        parents[whatParentA(nums[0]-1)][0] = whatParentA(nums[1]-1);//親を結合して統一。親が2人できることはない。
    }

    for(int i = 0; i < l; i++)
    {
      int[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),int.Parse);
      if(whatParentB(nums[0]-1) != whatParentB(nums[1]-1))
        parents[whatParentB(nums[0]-1)][1] = whatParentB(nums[1]-1);//親を結合して統一。親が2人できることはない。
    }

    for(int i = 0; i < n; i++)
    {
      parents[i][2] = whatParentA(i)*10000000+whatParentB(i);
    }

    Array.Sort(parents, (a, b) => a[2].CompareTo(b[2]));
    parents[0][0] = 0;
    int memo = 1;
    for(int i = 1; i < n; i++)
    {
      if(parents[i][2] == parents[i-1][2])
      {
        memo++;
        parents[i][0] = memo;
      }else
      {
        memo = 1;
        parents[i][0] = memo;
      }
    }
    for(int i = n-2; i >= 0; i--)
    {
      if(parents[(int)(i+1)][0] != 1) parents[(int)(i)][0] = parents[(int)(i+1)][0];
    }

    Array.Sort(parents, (a, b) => a[3].CompareTo(b[3]));//番号でソート
    for(int i = 0; i < n; i++)
    {
      answers[i] = parents[i][0];
    }
    Console.WriteLine(string.Join(" ", answers));
	}

  static int whatParentA(int child)
  {
    if(parents[child][0] == child) return child;
    else return parents[child][0] = whatParentA(parents[child][0]);
  }

  static int whatParentB(int child)
  {
    if(parents[child][1] == child) return child;
    else return parents[child][1] = whatParentB(parents[child][1]);
  }

}

