      if(whatParentA(nums[0]-1) != whatParentA(nums[1]-1))
        parents[whatParentA(nums[0]-1)][0] = whatParentA(nums[1]-1);//親を結合して統一。親が2人できることはない。
    }

    for(int i = 0; i < l; i++)
    {
      int[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),int.Parse);
      if(whatParentB(nums[0]-1) != whatParentB(nums[1]-1))
        parents[whatParentB(nums[0]-1)][1] = whatParentB(nums[1]-1);//親を結合して統一。親が2人できることはない。
    }

    for(int i = 0; i < n; i++)
    {
      parents[i][2] = whatParentA(i)*10000000+whatParentB(i);
    }

    Array.Sort(parents, (a, b) => a[2].CompareTo(b[2]));
    parents[0][0] = 1;
    int memo = 1;
    for(int i = 1; i < n; i++)
    {
      if(parents[i][2] == parents[i-1][2])
      {
        memo++;
        parents[i][0] = memo;
      }else
      {
        memo = 1;
        parents[i][0] = memo;
      }
    }
    parents[n-1][1] = parents[n-1][0];
    for(int i = n-2; i >= 0; i--)
    {
      if(parents[(int)(i+1)][0] != 1) parents[(int)(i)][1] = parents[(int)(i+1)][0];
      else parents[(int)(i)][1] = parents[i][0];
    }

    Array.Sort(parents, (a, b) => a[3].CompareTo(b[3]));//番号でソート
    for(int i = 0; i < n; i++)
    {
      answers[i] = parents[i][1];
    }
    Console.WriteLine(string.Join(" ", answers));
	}

  static int whatParentA(int child)
  {
    if(parents[child][0] == child) return child;
    else return parents[child][0] = whatParentA(parents[child][0]);
  }

  static int whatParentB(int child)
  {
    if(parents[child][1] == child) return child;
    else return parents[child][1] = whatParentB(parents[child][1]);
  }

}

