		Tuple<int,int>[] rs,ts;
		void Read()
		{
			sc.Read(out N, out K, out L);
			rs = sc.ReadManyLines<int,int>(K);
			ts = sc.ReadManyLines<int,int>(L);
		}
		void SolveOne()
		{
			var uf = new UnionFindTree(N);
			foreach (var r in rs) uf.UniteCategory(r.Item1 - 1, r.Item2 - 1);
			var ls = new Dictionary<int, List<int>>();
			for (var i = 0; i < N; i++)
			{
				var r = uf.GetRootOf(i);
				if (ls.ContainsKey(r)) ls[r].Add(i);
				else ls[r] = new List<int>{ i };
			}
			var rev = new Dictionary<int,Dictionary<int,int>>();
			var ufs = new Dictionary<int,UnionFindTree>();
			foreach (var t in ls)
			{
				rev[t.Key] = new Dictionary<int, int>();
				ufs[t.Key] = new UnionFindTree(t.Value.Count);
				for (var i = 0; i < t.Value.Count; i++) rev[t.Key][t.Value[i]] = i;
			}
			foreach (var r in ts)
			{
				var a = r.Item1 - 1;
				var b = r.Item2 - 1;
				var c = uf.GetRootOf(a);
				var d = uf.GetRootOf(b);
				if (c != d) continue;
				var i = rev[c][a];
				var j = rev[c][b];
				ufs[c].UniteCategory(i, j);
			}
			for (var i = 0 ; i < N;i++)
			{
				var r = uf.GetRootOf(i);
				pr.Write(ufs[r].GetSize(rev[r][i]) + (i == N - 1 ? "" : " "));
			}
			pr.WriteLine();
		}
	}
