    class UnionFind
    {
        public int[] path;
        public int[] rail;
        public int[] count;
        public bool[] check;

        public UnionFind(int n)
        {
            path = new int[n];
            rail = new int[n];
            count = new int[n];
            check = new bool[n];
            for (int i = 0; i < n; i++)
            {
                path[i] = i;
                rail[i] = i;

            }


        }

        private int rootPath(int i)
        {
            while(i != path[i])
            {
                path[i] = path[path[i]];
                i = path[i];
            }
            return i;
        }

        private int rootRail(int i)
        {
            while(i != rail[i])
            {
                rail[i] = rail[rail[i]];
                i = rail[i];
            }
            return i;
        }

        public bool findPath(int p, int q)
        {
            return rootPath(p) == rootPath(q);
        }

        public bool findRail(int p, int q)
        {
            return rootRail(p) == rootRail(q);
        }






