{
	a=find(a);
	b=find(b);
	if(a==b)return 0;
	if(parent[a]>parent[b])
	{
		parent[b]+=parent[a];
		parent[a]=b;
	}
	else
	{
		parent[a]+=parent[b];
		parent[b]=a;
	}
	return 1;
}
