def root(a, x)
  a[x] < 0 ? x : a[x] = root(a, a[x])
end

def unite(a, x, y)
  x, y = root(a, x), root(a, y)
  if x != y
    x, y = y, x if a[y] < a[x]
    a[x] += a[y]
    a[y] = x
  end
end

def group(a, i)
  (1 .. N).select{|j| root(a, i) == root(a, j)}
end

