//Union-Find
type UnionFind struct {
	par []int
}

func (u *UnionFind) uniInit(n int)  {
	u.par = make([]int,n)
	for i:=0;i<n;i++{
		u.par[i] = -1
	}
}

//aがどのグループに属しているか
func (u *UnionFind) root (a int) int {
	if u.par[a] < 0{
		return a
	}
	u.par[a] = u.root(u.par[a])
	return u.par[a]
}

//自分のグループの頂点数
func (u *UnionFind) size (a int) int {
	return -u.par[u.root(a)]
}

//つなげる
func (u *UnionFind) connect(a,b int) bool {
	a = u.root(a)
	b = u.root(b)
	if a == b {
		return false
	}
	if u.size(a) < u.size(b) {a,b = b,a}
	u.par[a] += u.par[b]
	u.par[b] = a
	return true
}

