struct UnionFind {
  int n;
  int[] table;

  this (int N) {
    n = N;
    table = new int[](n);
    foreach (i; 0..n)
      table[i] = -1;
  }

  void unite(int x, int y) {
    x = find(x);
    y = find(y);
    if (x == y) return;
    if (table[x] < table[y]) swap(x, y);
    table[y] += table[x];
    table[x] = y;
  }

  int find(int x) {
    if (table[x] < 0)
      return x;
    return table[x] = find(table[x]);
  }
}

