class UnionFind{
  int[] root;
  this(int n){
    root.length=n;
    foreach(i; 0..n) root[i]=i;
  }
  int find(int x){
    if(x==root[x]) return x;
    else return root[x]=find(root[x]);
  }
  void merge(int x, int y){
    x=find(x); y=find(y);
    if(x==y) return;
    root[x]=y;
  }
}

