auto parse( Range )( Range input )
if( isInputRange!Range && is( ElementType!Range == string ) )
{
	auto nkl = input.front.split.to!( long[] );
	auto pqs = new long[ 2 ][ nkl[ 1 ] ];
	foreach( ref pq; pqs )
	{
		input.popFront;
		pq = input.front.split.to!( long[] );
		pq[] -= 1;
	}
	auto rss = new long[ 2 ][ nkl[ 2 ] ];
	foreach( ref rs; rss )
	{
		input.popFront;
		rs = input.front.split.to!( long[] );
		rs[] -= 1;
	}
	return tuple( nkl[ 0 ], pqs, rss );
}

auto solve( long n, long[ 2 ][] pqs, long[ 2 ][] rss )
{
	// 道路グループを判定
	auto uft_a = UnionFindTree( n );
	foreach( pq; pqs )
	{
		uft_a.unite( pq[ 0 ], pq[ 1 ] );
	}

	// 鉄道グループを判定
	auto uft_b = UnionFindTree( n );
	foreach( rs; rss )
	{
		uft_b.unite( rs[ 0 ], rs[ 1 ] );
	}

	// 道路グループの根と鉄道グループの根のペアを作成して同じペアをカウント（＝道路と鉄道の両方で接続されている都市の数）
	auto ps = new long[ 2 ][ n ];
	long[ long[ 2 ] ] cs;
	foreach( i, ref p; ps )
	{
		p = [ uft_a.root( i ), uft_b.root( i ) ];
		cs[ p ]++;
	}
	auto anss = new long[ n ];
	foreach( ref ans, p; lockstep( anss, ps ) )
	{
		ans = cs[ p ];
	}
	return anss.to!( string[] ).join( " " );
}

// UnionFind木
struct UnionFindTree
{
	private long[] ps;
	private long[] rs;

	public this( long n )
	{
		ps.length = n;
		ps[] = -1;
		rs.length = n;
	}

	public long root( long i )
	{
		if( ps[ i ] < 0 ) return i;
		else              return ps[ i ] = root( ps[ i ] );
	}

	public bool same( long i, long j )
	{
		return root( i ) == root( j );
	}

	public void unite( long i, long j )
	{
		i = root( i );
		j = root( j );
		if( i == j ) return;
		if( rs[ i ] < rs[ j ] )
		{
			ps[ j ] += ps[ i ];
			ps[ i ] = j;
		}
		else
		{
			ps[ i ] += ps[ j ];
			ps[ j ] = i;
			if( rs[ i ] == rs[ j ] ) rs[ i ]++;
		}
	}
}

