class Dsu:
	def __init__(self, n):
		self.n = n
		self.par = [i for i in range(n)]
	def root(self, x):
		path = []
		while self.par[x] != x:
			path.append(x)
			x = self.par[x]
		for i in path:
			self.par[i] = x
		return x
	def join(self, x, y):
		x = self.root(x)
		y = self.root(y)
		if x != y:
			self.par[x] = self.par[y]

