def bellman_ford(num, start, adj):
    dist = [float("inf") for i in range(num)]
    dist[start] = 0
    while 1:
        update = False
        for i,j,k in adj:
            if dist[j] > dist[i] + k:
                dist[j] = dist[i] + k
                update = True
            if dist[i] > dist[j] + k:
                dist[i] = dist[j] + k
                update = True
        if not update:
            break
    return dist
