class UnionFind3:
    def __init__(self, size):
        self.table = [-1 for _ in range(size)]

    def find(self, x):
        while self.table[x] >= 0: x = self.table[x]
        return x

    def union(self, x, y):
        s1 = self.find(x)
        s2 = self.find(y)
        if s1 != s2:
            if self.table[s1] <= self.table[s2]:
                self.table[s1] += self.table[s2]
                self.table[s2] = s1
            else:
                self.table[s2] += self.table[s1]
                self.table[s1] = s2

    def compress(self):
        return [i if v < 0 else self.find(self.table[i]) for i, v in enumerate(self.table)]

    @staticmethod
    def join(a, b):
        return [i + j * n for i, j in zip(a.compress(), b.compress())]


