N, K, L = map(int, input().split())

G = [[[] for j in range(N)] for i in range(2)]
check = [[0 for l in range(N)] for k in range(2)]


def bfs(s, cnt, mode):
    q = deque()
    q.append(s)
    check[mode][s] = cnt

    while len(q) != 0:
        u = q.popleft()
        for i in G[mode][u]:
            if check[mode][i] == 0:
                q.append(i)
                check[mode][i] = cnt


def main():
    for i in range(K):
        p, q = map(int, input().split())
        G[0][p-1].append(q-1)
        G[0][q-1].append(p-1)
    for i in range(L):
        r, s = map(int, input().split())
        G[1][r-1].append(s-1)
        G[1][s-1].append(r-1)

    cnt = 1
    for i in range(N):
        if check[0][i] == 0:
            bfs(i, cnt, 0)
            cnt += 1

    cnt = 1
    for i in range(N):
        if check[1][i] == 0:
            bfs(i, cnt, 1)
            cnt += 1

    groups = {}
    for i in range(N):
        a, b = check[0][i], check[1][i]
        groups[(a, b)] = groups.get((a, b), 0) + 1

    nums = []
