fn solve() {
    input!{
        N:usize,K:usize,L:usize,
        PQ:[(usize,usize);K],
        RS:[(usize,usize);L]
    }
    let mut roadUF=UnionFind::new(N);
    for (p,q) in PQ {
        roadUF.merge(p-1, q-1);
    }
    let mut railUF=UnionFind::new(N);
    for (r,s) in RS {
        railUF.merge(r-1, s-1);
    }

    // 2つのi,jについて、
    // (roadUF[i],railUF[i]) == (roadUF[j],railUF[j])
    // の時、2つのノードは道路と鉄道の両方で接続されている
    let mut ty = vec![];
    let mut h = HashMap::new();
    for i in 0..N {
        let t = (roadUF.root(i), railUF.root(i));
        ty.push(t);
        *h.entry(t).or_insert(0) += 1;
    }
    let mut ans = vec![];
    for i in 0..N {
        let t = ty[i];
        ans.push(*h.get(&t).unwrap());
    }

    println!("{}", ans.iter().map(|&x| x.to_string()).collect::<Vec<String>>().connect(" "));
}
pub struct UnionFind {
    par: Vec<usize>,
    rank: Vec<usize>,
}
impl UnionFind {
    pub fn new(n: usize) -> UnionFind {
        UnionFind {
            par: (0..n).collect::<Vec<usize>>(),
            rank: vec![0; n],
        }
    }
    pub fn same(&mut self, x: usize, y: usize) -> bool {
        self.root(x) == self.root(y)
    }
    pub fn root(&mut self, x: usize) -> usize {
        if self.par[x] == x {
            return x;
        } else {
            let y = self.par[x];
            let z = self.root(y);
            self.par[x] = z;
            return z;
        }
    }
    pub fn merge(&mut self, x: usize, y: usize) -> bool {
        let mut a = self.root(x);
        let mut b = self.root(y);
        if a == b {
            return false;
        }
        if self.rank[a] < self.rank[b] {
            std::mem::swap(&mut a, &mut b);
        }
        assert!(self.rank[a] >= self.rank[b]);
        if self.rank[a] == self.rank[b] {
            self.rank[a] += 1;
        }
        self.par[b] = a;
        return true;
    }
}

