struct G {
    N: usize,
    A: Vec<Vec<usize>>,
    P: Vec<usize>,
}

impl G {
    fn decomp(&mut self) {
        for v in 0..self.N {
            self.dfs(v, v);
        }
    }

    fn dfs(&mut self, v: usize, p: usize) {
        debug!((v, p, self.P[v]));
        if self.P[v] != self.N {
            return;
        }

        self.P[v] = p;

        for i in 0..self.A[v].len() {
            let w = self.A[v][i];
            self.dfs(w, p);
        }
    }
}

fn main() {
    let (N, K, L) = read!(usize, usize, usize);

    // subway instead of rails
    let mut R = vec![vec![]; N];
    let mut S = vec![vec![]; N];

    for _ in 0..K {
        let (u, v) = read!(usize, usize);
        R[u - 1].push(v - 1);
        R[v - 1].push(u - 1);
    }

    for _ in 0..L {
        let (u, v) = read!(usize, usize);
        S[u - 1].push(v - 1);
        S[v - 1].push(u - 1);
    }

    let mut rg = G {
        N: N,
        A: R,
        P: vec![N; N],
    };
    rg.decomp();

    let mut sg = G {
        N: N,
        A: S,
        P: vec![N; N],
    };
    sg.decomp();

    let mut m = BTreeMap::new();
    for v in 0..N {
        *m.entry((rg.P[v], sg.P[v])).or_insert(0) += 1;
    }

    let mut ns = vec![];
    for v in 0..N {
        ns.push(m[&(rg.P[v], sg.P[v])]);
    }

    debug!(sg.A, rg.A, m);

    println!("{}", ns.into_iter().map(|n| n.to_string()).vec().join(" "))
}

