    let mut walk = UnionFind::new(n);
    let mut rail = UnionFind::new(n);

    for i in 0..k {
        let (a, b): (usize, usize) = read();
        walk.unite(a-1, b-1);
    }
    for i in 0..l {
        let (a, b): (usize, usize) = read();
        rail.unite(a-1, b-1);
    }

    let mut map = HashMap::new();
    for i in 0..n {
        let id = (walk.find(i), rail.find(i));
        let next = *map.get(&id).unwrap_or(&0);
        map.insert(id, next+1);
    }

    for i in 0..n {
