fn dfs(s: usize, p: usize, g: &Vec<Vec<usize>>, mut uf: &mut Vec<usize>) {
  if uf[s] != 0 {return}
  uf[s] = p;
  for next in g[s].clone() {dfs(next, p, &g, &mut uf)}
}

