    }

    let mut ufroad = UnionFind::new(n + 2);
    let mut ufrail = UnionFind::new(n + 2);

    for &(from, to) in &road {
        ufroad.join(from as i32, to as i32);
    }

    for &(from, to) in &rail {
        ufrail.join(from as i32, to as i32);
    }

    //let mut sum = HashMap::new();
    let mut sum = vec![0; n];
    for i in 0..n {
        for j in i..n {
