pub fn main() {
    let i = stdin();
    let mut o = Vec::new();
    run(i.lock(), &mut o);
    stdout().write_all(&o).unwrap();
}

fn run<R: BufRead, W: Write>(i: R, o: &mut W) {
    let mut i = CpReader::new(i);
    let (n, k, l) = i.read3::<usize, usize, usize>();
    let mut pqs = Vec::new();
    for _ in 0..k {
        let (p, q) = i.read2::<usize, usize>();
        pqs.push((p - 1, q - 1));
    }
    let mut rss = Vec::new();
    for _ in 0..l {
        let (r, s) = i.read2::<usize, usize>();
        rss.push((r - 1, s - 1));
    }

    let r = solve(n, &pqs, &rss);
    for i in 0..r.len() {
        if i != 0 {
            write!(o, " ").unwrap();
        }
        write!(o, "{}", r[i]).unwrap();
    }
    writeln!(o, "").unwrap();
}
fn solve(n: usize, pqs: &[(usize, usize)], rss: &[(usize, usize)]) -> Vec<usize> {
    let g1 = grouping(n, pqs);
    let g2 = grouping(n, rss);

    let mut gs = HashMap::new();
    for i in 0..n {
        *gs.entry((g1[i], g2[i])).or_insert(0) += 1;
    }
    let mut rs = vec![0; n];
    for i in 0..n {
        rs[i] = gs[&(g1[i], g2[i])];
    }
    rs
}

// 各駅のグループIDを返す
fn grouping(n: usize, edges: &[(usize, usize)]) -> Vec<usize> {
    let mut r = vec![0; n];
    let mut t = vec![Vec::new(); n];
    let mut v = vec![false; n];
    for &e in edges {
        t[e.0].push(e.1);
        t[e.1].push(e.0);
    }

    let mut q = Vec::new();
    let mut gid = 0;
    for i in 0..n {
        if v[i] {
            continue;
        }
        v[i] = true;
        q.clear();
        q.push(i);
        let mut qi = 0;
        while qi < q.len() {
            for &j in &t[q[qi]] {
                if v[j] {
                    continue;
                }
                v[j] = true;
                q.push(j);
            }
            qi += 1;
        }
        for qi in 0..q.len() {
            r[q[qi]] = gid;
        }
        gid += 1;
    }
    r
}

