struct UnionFind {
      n: usize,
      parent: Vec<usize>,
      count: Vec<usize>
}

impl UnionFind {
     fn new(n: usize) -> Self {
           let mut p = vec![0; n];
           for i in 0..n {
                 p[i] = i;
           }
           UnionFind { n: n, parent: p, count: vec![1; n] }
     }

     fn find(&mut self, a: usize) -> usize {
           if self.parent[a] == a {
                 return a;
           }
           let par = self.parent[a];
           self.parent[a] = self.find(par);
           self.parent[a]
     }

     fn unite(&mut self, a: usize, b: usize) {
           let a = self.find(a);
           let b = self.find(b);
           if a == b {
                 return;
           }
           let ca = self.count[a];
           let cb = self.count[b];
           let total = ca + cb;
           self.count[b] = total;
           self.count[a] = total;
           if ca < cb {
                 self.parent[a] = b;
           } else {
                 self.parent[b] = a;
           }
     }

     fn same(&mut self, a: usize, b: usize) -> bool {
           self.find(a) == self.find(b)
     }

     fn count(&mut self, a: usize) -> usize {
           let a = self.find(a);
           self.count[a]
     }
}

fn main() {
    input! {
        n: usize, k: usize, l: usize,
        roads: [(usize1, usize1); k],
        rails: [(usize1, usize1); l],
    };

    let mut uf1 = UnionFind::new(n);
    let mut uf2 = UnionFind::new(n);
    for (a, b) in roads {
        uf1.unite(a, b);
    }
    for (a, b) in rails {
        uf2.unite(a, b);
    }
    let mut vec = vec![vec![]; n];
    for i in 0..n {
        vec[uf1.find(i)].push(i);
    }

    let mut count = vec![0; n];
    for list in vec {
        let mut gn = vec![];
        for &l in &list {
            gn.push((uf2.find(l), l));
        }
        gn.sort();
        let n = gn.len();
        let mut fr = 0;
        while fr < n {
            let mut to = fr;
            while to < n && gn[fr].0 == gn[to].0 {
                to += 1;
            }
            for i in fr..to {
                count[gn[i].1] = to-fr;
            }
            fr = to;
        }
    }
    println!("{}", join!(count, " "));
}

