struct UnionFind {
    par: Vec<usize>,
    rank: Vec<usize>,
}

impl UnionFind {
    fn new(n: usize) -> Self {
        UnionFind {
            par: (0..n).collect(),
            rank: vec![0; n],
        }
    }

    fn unite(&mut self, a: usize, b: usize) {
        use std::cmp;
        let x = self.find(a);
        let y = self.find(b);

        if x == y { return; }

        match self.rank[x].cmp(&self.rank[y]) {
            cmp::Ordering::Equal => {
                self.par[y] = x;
                self.rank[x] += 1;
            },
            cmp::Ordering::Less => {
                self.par[x] = y;
            },
            cmp::Ordering::Greater => {
                self.par[y] = x;
            }
        }
    }

    fn find(&mut self, a: usize) -> usize {
        if self.par[a] == a { a }
        else {
            let p = self.par[a];
            self.par[a] = self.find(p);
            self.par[a]
        }
    }
}


