// https://beta.atcoder.jp/contests/joi2008ho/tasks/joi2008ho_b

fn dfs(
    paths: &Vec<Vec<usize>>,
    cnct: &mut Vec<i32>,
    p: usize,
    num: i32
) {
    cnct[p] = num;
    for next in paths[p].iter() {
        if cnct[*next] == -1 {
            dfs(paths, cnct, *next, num);
        }
    }
}

fn main() {
    let cin = stdin(); let cin = cin.lock(); let mut sc = Scanner::new(cin);

    let (n, k, l): (usize, usize, usize) = (sc.read(), sc.read(), sc.read());
    let mut pqs: Vec<Vec<usize>> = vec![Vec::new(); n];
    for i in 0..k {
        let (p, q): (usize, usize) = (sc.read(), sc.read());
        pqs[p-1].push(q-1); pqs[q-1].push(p-1);
    }
    let mut rss: Vec<Vec<usize>> = vec![Vec::new(); n];
    for i in 0..l {
        let (r, s): (usize, usize) = (sc.read(), sc.read());
        rss[r-1].push(s-1); rss[s-1].push(r-1);
    }

    let mut c1: Vec<i32> = vec![-1; n];
    let mut cnt = 0;
    for i in 0..n {
        if c1[i] == -1 {
            cnt += 1;
            dfs(&pqs, &mut c1, i, cnt);
        }
    }
    cnt = 0;
    let mut c2: Vec<i32> = vec![-1; n];
    for i in 0..n {
        if c2[i] == -1 {
            cnt += 1;
            dfs(&rss, &mut c2, i, cnt);
        }
    }

    let mut cncts = HashMap::new();
    for i in 0..n {
        let num = cncts.entry((c1[i], c2[i])).or_insert(0);
        *num += 1;
    }
    for i in 0..n {
        if i < n-1 { print!("{} ", cncts.get(&(c1[i], c2[i])).unwrap()); }
        else { println!("{}", cncts.get(&(c1[i], c2[i])).unwrap()); }
    }
}

