    let v = read_vec::<usize>();
    let (n, k, l) = (v[0], v[1], v[2]);

    let mut roads = vec![];
    for _ in 0..k {
        let v = read_vec::<usize>();
        roads.push((v[0] - 1, v[1] - 1));
    }

    let mut trains = vec![];
    for _ in 0..l {
        let v = read_vec::<usize>();
        trains.push((v[0] - 1, v[1] - 1));
    }

    let mut road_uft = UnionFindTree::new(n);
    for &(p, q) in roads.iter() {
        road_uft.unite(p, q);
    }

    let mut train_uft = UnionFindTree::new(n);
    for &(p, q) in trains.iter() {
        train_uft.unite(p, q);
    }

    let mut road_dict = HashMap::new();
    for i in 0..n {
        road_dict
            .entry(road_uft.find(i))
            .or_insert(Vec::new())
            .push(i);
    }
    let mut answers = vec![0; n];
    for v in road_dict.values() {
        let mut count_dict = HashMap::new();
        for i in v {
            let root = train_uft.find(*i);
            *count_dict.entry(root).or_insert(0) += 1;
        }
        for i in v {
            let root = train_uft.find(*i);
            answers[*i] = count_dict[&root];
        }
    }

    print_array(&answers);
}

