    }
}

struct UFT {
    pub par: Vec<usize>,
    pub rank: Vec<usize>,
}

impl UFT {
    fn new(n: usize) -> Self {
        UFT {
            par: (0..n).collect(),
            rank: vec![0; n],
        }
    }

    fn find(&mut self, x: usize) -> usize {
        if self.par[x] == x {
            x
        } else {
            let p = self.par[x];
            let pp = self.find(p);
            self.par[x] = pp;
            pp
        }
    }

    fn unite(&mut self, x: usize, y: usize) {
        let x = self.find(x);
        let y = self.find(y);
        if x == y {
            return;
        }

        if self.rank[x] < self.rank[y] {
            self.par[x] = y;
        } else {
            self.par[y] = x;
            if self.rank[x] == self.rank[y] {
                self.rank[x] += 1;
            }
        }
    }
}

fn main() {
    let (n, k, l) = get!(usize, usize, usize);
    let road = get!(usize, usize; k);
    let train = get!(usize, usize; l);

    let mut uft_road = UFT::new(n);
    let mut uft_train = UFT::new(n);

    for &(a, b) in &road {
        uft_road.unite(a - 1, b - 1);
    }

    for &(a, b) in &train {
        uft_train.unite(a - 1, b - 1);
    }

    let mut counts = HashMap::new();

    for i in 0..n {
        *counts
            .entry((uft_road.find(i), uft_train.find(i)))
            .or_insert(0) += 1;
    }

    println!(
        "{}",
        (0..n)
            .map(|i| {
                counts.get(&(uft_road.find(i), uft_train.find(i))).unwrap()
            })
            .map(|n| n.to_string())
            .collect::<Vec<_>>()
            .join(" ")
    );
}
